// gen_audio.py 가 자동 생성합니다.
window.N1_AUDIO = {"d001": {"大手飲料メーカーが今月発売した低糖質の炭酸飲料が、予想を上回る売れ行きを見せている。発売日の朝、各地の量販店では開店するや否や客が売り場に殺到し、昼過ぎには在庫が底をついた店舗も少なくなかった。同社は当初、年間の販売目標を控えめに設定していたが、需要の急増を受けて増産体制の構築を急ぐ方針だ。ただ、原材料価格の高騰が続く中、生産を拡大すれば収益を圧迫しかねないとの懸念もある。専門家は「話題性による一時的な需要にすぎない可能性もあり、在庫を過剰に抱えるリスクを慎重に見極める必要がある」と指摘している。": [0.0, 47.11], "駅前のドラッグストア、新しい炭酸水が入荷するや否や売り切れたんだって。": [47.51, 6.0], "え、そんなに？在庫、全然なかったの？": [53.91, 4.335], "うん。店員さんの話だと、需要に生産が追いつかないみたい。": [58.645, 5.255], "じゃあ、しばらくは手に入らないかもね。": [64.3, 3.36], "彼は席に着くや否や、パソコンを開いて仕事を始めた。": [68.06, 4.825], "その法案が可決されるや否や、市場では株価が急落した。": [73.285, 5.16], "開演のベルが鳴るや否や、会場は水を打ったように静まり返った。": [78.845, 5.155], "限定モデルの予約が始まるや否や注文が殺到し、在庫はわずか一時間でなくなった。": [84.4, 7.035], "社長が会議室に入るや否や、全員が一斉に立ち上がった。": [91.835, 4.985], "ドアを開けたとたん、猫が外に飛び出していった。": [97.22, 3.805], "需要": [101.425, 1.09], "在庫": [102.915, 1.15], "高騰": [104.465, 1.2], "収益": [106.065, 1.22], "圧迫": [107.685, 1.175], "増産": [109.26, 1.11], "懸念": [110.77, 0.98], "過剰": [112.15, 1.105]}, "d002": {"私の祖父は小さな青果店を営んでいた。毎朝、市場から仕入れた野菜が店先に並ぶが早いか、近所の主婦たちが我先にと手に取っていったものだ。祖父は値段の交渉にも気さくに応じ、常連客との何気ない会話を何より大切にしていた。しかし、郊外に大型スーパーが進出してからは客足が次第に遠のき、売り上げは年々減少していった。祖父は採算が取れなくなったことを理由に、七十歳を前に店を畳んだ。効率や価格だけでは測れない価値が、あの店先には確かにあったのだと、今になって思う。": [0.0, 40.515], "うちの子、学校から帰ってくるが早いか、ゲームを始めるんだよ。": [40.915, 5.515], "うちも同じ。宿題をめぐる交渉が毎日大変で。": [46.83, 4.515], "効率よく終わらせたら遊んでいいって言ってるんだけどね。": [51.745, 4.005], "それ、なかなか効き目がないのよね。": [56.15, 3.125], "給料が振り込まれるが早いか、彼は全額を使ってしまった。": [59.675, 5.005], "ドアが開くが早いか、乗客は先を争って車内に乗り込んだ。": [65.08, 5.23], "店主はシャッターを下ろすが早いか、裏口から飛び出していった。": [70.71, 4.775], "パン屋が店を開けるが早いか、常連客が次々と焼きたてのパンを買っていった。": [75.885, 6.13], "チャイムが鳴るが早いか、子どもたちは校庭へ駆け出した。": [82.415, 4.525], "合格発表を見るや否や、彼女は母親に電話をかけた。": [87.34, 4.875], "交渉": [92.615, 1.215], "進出": [94.23, 1.21], "採算": [95.84, 1.17], "効率": [97.41, 1.165], "減少": [98.975, 1.16], "常連": [100.535, 1.055], "客足": [101.99, 1.255], "郊外": [103.645, 1.125]}, "d003": {"先日、取引先の部長が会議室に入ってくるなり、「この資料では話にならない」と言い放った。事前に何度も打ち合わせを重ね、先方の要望を反映させたつもりだっただけに、担当者の落胆は大きかった。後で分かったことだが、部長は直前に社内で予算削減の方針を聞かされ、計画の見直しを迫られていたらしい。立場が変われば、同じ資料でも評価は一変する。交渉の場では、相手の発言の裏にある事情を推し量る想像力が欠かせない。それは、どれほど業務の効率化が進んでも、人にしか担えない役割ではないだろうか。": [0.0, 43.495], "課長、今朝出社するなり不機嫌そうだったけど、何かあったの？": [43.895, 5.345], "取引先から予算の削減を言い渡されたらしいよ。": [49.64, 4.07], "そうなんだ。じゃあ、来月の企画も見直しかな。": [54.11, 4.505], "たぶんね。午後に今後の方針を説明するって。": [59.015, 4.095], "息子は帰宅するなり、自分の部屋に閉じこもってしまった。": [63.51, 4.49], "彼女は受話器を取るなり、大声で泣き出した。": [68.4, 3.735], "部長は報告書に目を通すなり、担当者を呼びつけた。": [72.535, 4.575], "先方の担当者は席に着くなり、取引の条件を変更したいと切り出した。": [77.51, 6.175], "父は玄関に入るなり、「腹が減った」と言った。": [84.085, 4.44], "幕が上がるや否や、客席から大きな拍手が起こった。": [88.925, 4.565], "取引": [93.89, 1.145], "削減": [95.435, 1.215], "方針": [97.05, 1.105], "反映": [98.555, 1.145], "予算": [100.1, 1.03], "業務": [101.53, 1.01], "担当": [102.94, 1.18], "先方": [104.52, 1.28]}, "d004": {"家計簿をつけ始めて三年になる。食費や光熱費を細かく記録し、無駄な支出を削ろうと努めてきたが、物価の上昇はそうした努力をあざ笑うかのようだ。節約したそばから、値上げのニュースが飛び込んでくる。給与はほとんど横ばいなのに、生活必需品の価格だけが上がり続けているのだから、家計が苦しくなるのも当然である。政府は企業に賃上げを促しているものの、体力の乏しい中小企業にとって人件費の増加は死活問題だ。景気の回復を実感できる日は、果たしていつ来るのだろうか。": [0.0, 38.86], "部屋を片付けるそばから、子どもたちが散らかすのよ。": [39.26, 4.37], "うちも同じだよ。注意したそばから忘れるしね。": [44.03, 4.06], "まあ、元気な証拠だと思うしかないわね。": [48.49, 3.57], "そうだね。でも、たまには静かに過ごしたいよ。": [52.46, 4.215], "新しい単語を覚えるそばから忘れてしまう。": [57.075, 3.595], "彼は稼いだそばから使ってしまうので、貯金がまったくない。": [61.07, 5.03], "雪かきをするそばから雪が積もり、きりがなかった。": [66.5, 4.29], "支出を減らしたそばから物価が上がるので、生活は少しも楽にならない。": [71.19, 5.955], "注意したそばから、また同じミスをする。": [77.545, 3.525], "試合終了の笛が鳴るや否や、選手たちは抱き合った。": [81.47, 4.42], "支出": [86.29, 1.135], "物価": [87.825, 1.07], "給与": [89.295, 1.065], "横ばい": [90.76, 1.205], "賃上げ": [92.365, 1.195], "人件費": [93.96, 1.16], "景気": [95.52, 1.075], "必需品": [96.995, 1.14]}, "d005": {"東京の広告会社を辞め、瀬戸内の小さな島に移り住んでからというもの、木村さんの暮らしは一変した。島は高齢化と過疎化という深刻な課題を抱えているが、木村さんは空き家を改装してカフェを開き、島の特産品であるレモンを使った菓子を開発してきた。当初は地元の住民から警戒されることもあったというが、地道な取り組みが実を結び、今では島を訪れる観光客も増えつつある。「都会では得られなかった、人と人とのつながりを実感しています」と木村さんは語る。地方の活性化には、こうした個人の挑戦を支える仕組みづくりが欠かせない。": [0.0, 43.775], "田中さん、犬を飼い始めてからというもの、毎朝五時に起きてるんだって。": [44.175, 5.845], "へえ、あの朝が苦手な田中さんが？": [50.42, 3.365], "うん。散歩のおかげで、体調もすごくいいらしいよ。": [54.185, 4.555], "生活がすっかり変わったんだね。": [59.14, 2.675], "娘が生まれてからというもの、夫は毎日早く帰宅するようになった。": [62.215, 5.57], "禁煙してからというもの、食事がおいしく感じられる。": [68.185, 4.255], "あの事故があってからというもの、彼は車の運転を避けている。": [72.84, 4.89], "地方に移住してからというもの、近所の住民と野菜を分け合うのが日課になった。": [78.13, 6.055], "留学してからというもの、彼の考え方は大きく変わった。": [84.585, 4.88], "手を洗ってから食事をしてください。": [89.865, 2.755], "過疎": [93.02, 1.085], "高齢化": [94.505, 1.24], "特産品": [96.145, 1.2], "開発": [97.745, 1.21], "活性化": [99.355, 1.24], "移住": [100.995, 1.015], "住民": [102.41, 1.08], "課題": [103.89, 1.03]}, "d006": {"老舗の和菓子メーカー「松風堂」は、来春のシンガポール出店を皮切りに、アジア各国へ販路を広げる計画を明らかにした。国内市場が少子化で縮小に向かう中、同社は数年前から海外の展示会に積極的に出品し、現地の嗜好に関する調査を重ねてきた。甘さを控えた商品や、日持ちのする個包装の菓子は特に評判がよく、すでに複数の現地企業と提携に向けた協議を進めているという。社長は「伝統の味を守りつつ、時代に合わせて変わることを恐れない」と意欲を示す。円安が追い風となる一方、為替の変動や物流コストの上昇といったリスクにどう対処するかが今後の焦点となる。": [0.0, 49.645], "来月の大阪公演を皮切りに、全国ツアーが始まるんだって。": [50.045, 5.195], "え、本当？チケット、もう発売されてる？": [55.64, 4.56], "まだだけど、ファンクラブの先行予約が今週末からだよ。": [60.6, 4.74], "絶対申し込まなきゃ。": [65.74, 1.915], "東京を皮切りに、全国十都市で展覧会が開催される。": [68.055, 5.035], "彼の発言を皮切りに、会議では反対意見が相次いだ。": [73.49, 4.735], "新宿店の開業を皮切りとして、同社は首都圏での出店を加速させた。": [78.625, 6.105], "同社は台湾企業との提携を皮切りに、東南アジアへの販路拡大を目指している。": [85.13, 6.29], "デビュー作を皮切りに、彼女は次々とヒット作を発表した。": [91.82, 5.11], "日本をはじめ、アジアの多くの国で少子化が進んでいる。": [97.33, 4.695], "販路": [102.425, 1.07], "縮小": [103.895, 1.325], "提携": [105.62, 1.205], "協議": [107.225, 1.03], "為替": [108.655, 1.175], "物流": [110.23, 1.125], "老舗": [111.755, 1.25], "円安": [113.405, 1.06]}, "d008": {"閉店のお知らせ\n平素より格別のご愛顧を賜り、誠にありがとうございます。さて、当店は誠に勝手ながら、本年十二月二十八日の営業を限りに閉店させていただくこととなりました。昭和五十年の創業以来、半世紀近くにわたり地域の皆様に支えられてまいりましたが、建物の老朽化に加え、後継者の確保が困難となったため、苦渋の決断に至りました。なお、閉店に先立ち、十二月一日より店内全品を対象とした感謝セールを実施いたします。お預かりしているポイントは、閉店日までにご利用くださいますようお願い申し上げます。長年のご厚情に、従業員一同、心より御礼申し上げます。": [0.0, 50.06], "このお店、今月末を限りに閉店するんですって？": [50.46, 4.6], "はい。建物の老朽化で、やむを得ず……。": [55.46, 3.87], "寂しくなりますね。三十年も通ったのに。": [59.73, 3.865], "長い間ご愛顧いただき、本当にありがとうございました。": [63.995, 4.68], "今日を限りに、タバコはきっぱりやめることにした。": [69.075, 3.99], "彼は今大会を限りに、現役を引退すると発表した。": [73.465, 4.84], "遭難者たちは声を限りに助けを求めた。": [78.705, 3.55], "創業以来四十年続いた当食堂は、三月末日の営業を限りに閉店いたします。": [82.655, 7.175], "今月を限りに、このブログの更新を終了します。": [90.23, 4.395], "本日をもちまして、受付を締め切らせていただきます。": [95.025, 4.42], "創業": [99.845, 1.245], "老朽化": [101.49, 1.24], "後継者": [103.13, 1.26], "確保": [104.79, 1.15], "営業": [106.34, 1.145], "従業員": [107.885, 1.11], "実施": [109.395, 1.04], "対象": [110.835, 1.18]}, "d009": {"件名：退職のご挨拶\n株式会社青葉商事 営業部 佐藤様\nいつも大変お世話になっております。山本工業の中村でございます。私事で恐縮ですが、このたび一身上の都合により、三月三十一日をもって退職することとなりました。在職中は、新規のお取引の開始から納期の調整まで、佐藤様には多大なるご支援を賜り、心より感謝申し上げます。後任は同じ部署の小林が務めます。小林は誠実な人柄と確かな実務能力をもって、これまで以上に貴社のご期待にお応えできるものと確信しております。本来であれば直接お伺いすべきところ、メールでのご挨拶となりましたことをお詫び申し上げます。貴社のますますのご発展をお祈りいたします。": [0.0, 53.065], "本日をもって、このプロジェクトチームは解散とします。": [53.465, 4.46], "皆さん、半年間お疲れさまでした。": [58.325, 3.385], "部長、新しい部署への異動の件はどうなりましたか。": [62.11, 4.5], "来週の会議で、正式に発表するよ。": [67.01, 3.73], "本日をもって、当サービスの提供を終了いたします。": [71.14, 4.52], "審査の結果は、後日書面をもってお知らせします。": [76.06, 4.25], "彼は持ち前の粘り強さをもって、難しい交渉をまとめ上げた。": [80.71, 5.29], "私儀、九月三十日をもって退職いたします。後任の田中を今後ともよろしくお願い申し上げます。": [86.4, 8.47], "以上をもちまして、本日の式典を終了いたします。": [95.27, 4.435], "台風によって、多くの便が欠航した。": [100.105, 3.5], "退職": [104.005, 1.19], "後任": [105.595, 1.065], "納期": [107.06, 1.05], "新規": [108.51, 1.165], "部署": [110.075, 1.035], "実務": [111.51, 1.085], "貴社": [112.995, 1.085], "異動": [114.48, 1.05]}, "d010": {"企業の不祥事が後を絶たない。問題なのは、多くの場合、社内で早くから異変に気づいていた社員がいたにもかかわらず、その声が経営陣に届かなかったことだ。ある食品会社では、品質データの不正な書き換えが十年以上続き、取引先からの指摘で発覚するに至って、ようやく社長が謝罪会見を開いた。別の企業に至っては、内部告発をした社員を地方の支社に左遷していたことまで明らかになっている。不正を防ぐには、規則を厳しくするだけでは不十分である。異論を口にした者が不利益を被らない組織風土をいかに築くか。経営者の本気度が問われている。": [0.0, 44.19], "駅前の再開発、反対運動が起きるに至って、ようやく市が説明会を開くんだって。": [44.59, 7.355], "遅すぎるよね。住民の声、ずっと無視してたのに。": [52.345, 4.655], "商店街の人たちに至っては、計画すら知らされてなかったらしいよ。": [57.4, 5.735], "それはひどい。説明会、私も行ってみようかな。": [63.535, 4.86], "被害が全国に広がるに至って、政府はようやく対策に乗り出した。": [68.795, 5.55], "この案には誰も賛成しなかった。部長に至っては、会議の途中で席を立ってしまった。": [74.745, 7.16], "事ここに至っては、もはや事実を隠し通すことはできない。": [82.305, 4.945], "不正が報道で発覚するに至って、会社はようやく公式に謝罪した。": [87.65, 5.645], "兄は勉強が苦手だ。弟に至っては、教科書を開いたことすらない。": [93.695, 6.09], "食器からタオルに至るまで、すべて手作りの品だ。": [100.185, 4.285], "不祥事": [104.87, 1.145], "経営陣": [106.415, 1.13], "発覚": [107.945, 1.23], "内部告発": [109.575, 1.535], "左遷": [111.51, 1.11], "不正": [113.02, 1.09], "組織": [114.51, 1.145], "謝罪": [116.055, 1.13]}, "d011": {"岐阜県のある町は、古くから刃物の産地として知られている。包丁やはさみはもちろん、医療用のメスから工業用の精密な刃に至るまで、この町で生産される製品は実に幅広い。かつては分業制が主流で、鍛造、研磨、柄の取り付けといった工程をそれぞれ別の職人が担っていた。しかし近年は担い手不足が深刻化し、一つの工房が複数の工程を兼ねるケースが増えている。その一方で、海外の料理人からの注文は年々増加しており、輸出額は過去最高を更新した。伝統の技術をいかに次世代へ継承していくか、産地全体で模索が続いている。": [0.0, 45.87], "このホテル、タオルからスリッパに至るまで、全部地元の製品なんだって。": [46.27, 6.08], "へえ、ずいぶんこだわってるね。": [52.75, 2.66], "地元の産業を応援したいっていうオーナーの方針らしいよ。": [55.81, 4.355], "そういう話を聞くと、また泊まりたくなるな。": [60.565, 3.905], "この辞書は、古語から最新の若者言葉に至るまで収録している。": [64.87, 5.615], "彼の小説は、子どもから高齢者に至るまで幅広い読者に愛されている。": [70.885, 6.225], "社長は、社員の服装に至るまで細かく口を出す。": [77.51, 4.74], "この地域は眼鏡の一大産地で、フレームから精密なネジに至るまで、すべて地元で作られている。": [82.65, 8.195], "細部に至るまで丁寧に作り込まれた模型だ。": [91.245, 3.725], "駅から家まで歩いて十分ほどだ。": [95.37, 2.735], "産地": [98.505, 1.145], "分業": [100.05, 1.145], "工程": [101.595, 1.2], "輸出": [103.195, 1.085], "継承": [104.68, 1.215], "主流": [106.295, 1.08], "精密": [107.775, 1.255], "模索": [109.43, 1.13]}, "d012": {"長引く不況にあって、多くの中小企業が苦境に立たされている。そうした中、従業員五十人ほどの部品メーカーが、独自の技術を生かして医療機器の分野に参入し、業績を大きく伸ばしたことが注目を集めている。同社の社長は「主要な取引先からの受注が激減したとき、下請けのままでは生き残れないと痛感した」と振り返る。危機にあってこそ、経営者の決断力が試される。もちろん、新たな分野への挑戦には多額の投資と失敗のリスクが伴う。それでも、現状にとどまり続けることこそが最大のリスクだという認識が、いま多くの経営者に求められているのではないか。": [0.0, 45.935], "経済の先行きが不透明なこの時代にあって、企業に求められるものは何でしょうか。": [46.335, 6.6], "変化を恐れず、新しい分野に挑戦する姿勢だと思います。": [53.335, 5.09], "具体的には、どのような取り組みでしょうか。": [58.825, 3.605], "たとえば、自社の技術をほかの業界に応用することですね。": [62.83, 5.06], "首相という立場にあって、軽率な発言は許されない。": [68.29, 4.73], "彼はどんな逆境にあっても、決して希望を失わなかった。": [73.42, 4.73], "情報があふれる現代にあっては、真偽を見極める力が欠かせない。": [78.55, 5.44], "この不況にあっても、同社は堅実な経営で三期連続の増益を達成した。": [84.39, 6.235], "戦時下にあって、人々は互いに助け合って暮らした。": [91.025, 4.52], "会議は第一会議室において行われる。": [95.945, 3.19], "不況": [99.535, 1.095], "苦境": [101.03, 1.095], "参入": [102.525, 1.185], "業績": [104.11, 1.205], "受注": [105.715, 1.065], "下請け": [107.18, 1.295], "投資": [108.875, 1.055], "危機": [110.33, 1.0]}, "d013": {"新幹線の延伸区間が開業して初めての週末とあって、沿線の観光地は大勢の人出でにぎわった。ある恐竜博物館では、開館前から入場を待つ家族連れの長い列ができ、周辺の駐車場も早朝から満車となった。地元の商店街では、開業に合わせて限定商品を販売する店も多く、ある菓子店の店主は「例年の三倍近い売り上げだ」と顔をほころばせた。一方で、交通渋滞や飲食店の混雑に対する苦情も寄せられており、県は観光客の分散に向けた対策を検討している。開業効果を一時的なものに終わらせないための工夫が問われる。": [0.0, 44.64], "今日の駅前、すごい人だったね。": [45.04, 3.105], "年に一度の花火大会とあって、朝から場所取りをしてる人もいたよ。": [48.545, 5.465], "道路も渋滞してたし、電車で来て正解だったね。": [54.41, 4.35], "帰りはもっと混むだろうから、少し早めに出よう。": [59.16, 4.05], "人気歌手が来日するとあって、空港には多くのファンが詰めかけた。": [63.61, 5.405], "久しぶりの晴天とあって、公園は家族連れでにぎわっている。": [69.415, 4.89], "恩師の頼みとあっては、断るわけにはいかない。": [74.705, 3.985], "三年ぶりに開かれた祭りとあって、会場周辺は大変な人出となり、道路も渋滞した。": [79.09, 7.365], "連休初日とあって、高速道路は朝から大渋滞だ。": [86.855, 4.63], "さすがプロの料理人だけあって、味付けが絶妙だ。": [91.885, 4.395], "延伸": [96.68, 1.0], "沿線": [98.08, 1.0], "人出": [99.48, 1.085], "渋滞": [100.965, 1.15], "苦情": [102.515, 1.09], "分散": [104.005, 1.03], "例年": [105.435, 1.04], "開業": [106.875, 1.18]}, "d015": {"入社して十年、今年の春から課長を務めている。一般の社員だった頃は、目の前の仕事を片付けることだけを考えていればよかった。だが、管理職ともなると、そうはいかない。部下の業務量を把握し、評価をつけ、時には人事上の難しい判断も下さなければならない。予算の配分や他部署との調整にも追われ、自分の仕事に集中できる時間はごくわずかだ。それでも、部下が大きな契約を取ってきたときの喜びは、自分の手柄とはまた違った格別なものがある。責任の重さと引き換えに得られるやりがいを、ようやく実感し始めている。": [0.0, 43.485], "来週はもう十二月か。年末ともなると、どこも忙しいね。": [43.885, 5.5], "うちの会社も、決算前で毎日残業だよ。": [49.785, 4.08], "大変だね。忘年会もあるんでしょう？": [54.265, 3.265], "うん。今年は幹事を任されちゃって、店の予約や会費の調整で頭が痛いよ。": [57.93, 6.915], "大学生ともなれば、自分の行動に責任を持つべきだ。": [65.245, 4.745], "一流のシェフともなると、包丁一本にもこだわりがあるものだ。": [70.39, 4.885], "真夏ともなると、この盆地の気温は四十度近くまで上がる。": [75.675, 4.94], "管理職ともなると、自分の成果だけでなく、部下の業務まで把握しておかなければならない。": [81.015, 7.19], "社長ともなると、休日でも気が休まらないだろう。": [88.605, 4.325], "明日出発となると、今夜中に荷物をまとめなければならない。": [93.33, 5.055], "管理職": [98.785, 1.21], "把握": [100.395, 1.075], "評価": [101.87, 1.145], "人事": [103.415, 1.04], "配分": [104.855, 1.07], "調整": [106.325, 1.245], "契約": [107.97, 1.185], "手柄": [109.555, 0.97]}, "d016": {"件名：工場見学のお礼\n東和精機株式会社 製造部 井上様\n先日はお忙しいところを、弊社の新入社員十名のために工場をご案内いただき、誠にありがとうございました。最新の自動化設備はもちろん、品質管理の徹底ぶりを間近で拝見し、参加者一同、大いに刺激を受けた様子でございました。特に、不良品の発生率を限りなくゼロに近づけるための工夫についてのご説明は、研修の報告会でも大きな話題となりました。本来であれば直接お礼に伺うべきところを、略儀ながらメールにてご挨拶申し上げます。今後とも末永いお付き合いのほど、何卒よろしくお願い申し上げます。": [0.0, 47.455], "お休みのところを申し訳ありません。少しよろしいでしょうか。": [47.855, 4.98], "ええ、大丈夫ですよ。どうしました？": [53.235, 3.33], "明日の研修の資料に、一か所誤りが見つかりまして。": [56.965, 4.565], "そうですか。じゃあ、修正したものを今日中に送ってください。": [61.93, 5.215], "お休みのところを、お邪魔して申し訳ありません。": [67.545, 4.01], "本来なら罰金を払うところを、今回は注意だけで済ませてもらった。": [71.955, 5.52], "授業中に居眠りしているところを、先生に見つかってしまった。": [77.875, 4.98], "お忙しいところを、弊社の研修で講演していただき、誠にありがとうございました。": [83.255, 6.96], "お急ぎのところを、お引き止めして申し訳ございません。": [90.615, 4.37], "何度も約束したのに、彼は結局来なかった。": [95.385, 4.205], "設備": [99.99, 1.185], "品質": [101.575, 1.135], "徹底": [103.11, 1.16], "不良品": [104.67, 1.06], "研修": [106.13, 1.135], "弊社": [107.665, 1.145], "発生": [109.21, 1.17], "自動化": [110.78, 1.17]}, "d017": {"定年を迎えた父が、長年の夢だった古民家カフェの開業準備に取りかかったのは、三年前の春のことだ。改装工事の契約を済ませ、いよいよ着工しようとした矢先に、父は軽い脳梗塞で倒れた。幸い後遺症はほとんど残らなかったが、家族の誰もが、計画は白紙に戻るものと思っていた。ところが父は、リハビリに励みながら資金計画を練り直し、規模を縮小して開業にこぎ着けた。今では地域の高齢者が集う憩いの場になっている。「挫折を経験したからこそ、身の丈に合った経営の大切さに気づけた」と、父は笑う。": [0.0, 43.575], "引っ越そうと思っていた矢先に、大家さんから家賃を下げるって言われてさ。": [43.975, 5.635], "え、それで引っ越すのをやめたの？": [50.01, 2.875], "うん、急に迷っちゃって。結局、今の部屋にもう少し住むことにしたよ。": [53.285, 6.285], "まあ、それも何かの縁だよね。": [59.97, 2.87], "出かけようとした矢先に、激しい雨が降り出した。": [63.24, 4.085], "新しい事業が軌道に乗り始めた矢先の事故だった。": [67.725, 4.185], "家を買った矢先に、地方への転勤を命じられた。": [72.31, 4.145], "店を開こうとした矢先に資金の援助が打ち切られ、計画は白紙に戻った。": [76.855, 6.045], "退院した矢先に、また体調を崩してしまった。": [83.3, 4.01], "出かけようとしているところへ、友人が訪ねてきた。": [87.71, 4.15], "定年": [92.26, 1.03], "着工": [93.69, 1.245], "資金": [95.335, 1.1], "規模": [96.835, 1.005], "経営": [98.24, 1.13], "改装": [99.77, 1.215], "挫折": [101.385, 1.15], "白紙": [102.935, 1.145]}, "d018": {"会計事務所で税理士として働くかたわら、週末は地元の子ども食堂の運営に携わっている鈴木さん。活動を始めたきっかけは、顧客である飲食店の経営者から、経済的な事情で十分な食事をとれない子どもが少なくないと聞いたことだった。現在は約二十人のボランティアとともに、月に二回、温かい食事を無償で提供している。運営費の多くは地域の企業や個人からの寄付で賄われているが、食材費の値上がりが続き、やりくりは決して楽ではない。それでも鈴木さんは「専門知識を生かして会計の透明性を高め、支援の輪を広げたい」と前を向く。": [0.0, 44.565], "先生は大学で教えるかたわら、小説も書いていらっしゃるんですよね。": [44.965, 5.73], "ええ、もう二十年近くになりますね。": [51.095, 3.385], "両立するのは大変じゃありませんか。": [54.88, 2.95], "時間のやりくりは大変ですが、どちらも私には欠かせないものなんですよ。": [58.23, 5.73], "彼女は会社勤めのかたわら、夜間の大学院に通っている。": [64.36, 4.975], "父は農業を営むかたわら、地元の歴史を研究している。": [69.735, 5.115], "祖母は家事のかたわら、近所の子どもたちに書道を教えていた。": [75.25, 5.065], "兄は銀行に勤めるかたわら、留学生の生活を支援するNPOの運営にも関わっている。": [80.715, 7.39], "彼は医師として働くかたわら、作家としても活躍している。": [88.505, 5.105], "音楽を聴きながら、宿題をする。": [94.01, 3.08], "税理士": [97.49, 1.21], "顧客": [99.1, 1.18], "運営": [100.68, 1.065], "無償": [102.145, 1.12], "寄付": [103.665, 0.98], "賄う": [105.045, 1.18], "透明性": [106.625, 1.28], "支援": [108.305, 0.995]}, "d019": {"休日の朝は、散歩がてら近所の商店街を歩くのが習慣になっている。最近はシャッターを下ろしたままの店が目立つ一方で、空いた店舗を活用した新しい店も少しずつ増えてきた。先週は、古い呉服店を改装した雑貨店をのぞいてみた。店主は三十代の女性で、地元の職人が作った器や布製品を扱っているという。「大型店やネット通販には、価格ではとても太刀打ちできない。だからこそ、作り手の顔が見える商品で勝負したい」と語る姿が印象的だった。消費の形が変わりつつある今、商店街が生き残る道は、価格競争とは別のところにあるのかもしれない。": [0.0, 46.555], "駅前まで買い物がてら、ちょっと散歩しない？": [46.955, 3.89], "いいね。ついでに郵便局にも寄りたいんだけど。": [51.245, 3.99], "じゃあ、先に郵便局に行こうか。": [55.635, 3.25], "うん。帰りにあの新しいパン屋ものぞいてみようよ。": [59.285, 4.05], "散歩がてら、駅前の本屋に寄ってみた。": [63.735, 3.665], "友人の見舞いがてら、久しぶりに故郷を訪れた。": [67.8, 4.315], "駅まで送りがてら、近くのカフェでお茶を飲んだ。": [72.515, 4.055], "散歩がてら、駅前に新しくできた雑貨の店舗をのぞいてきた。": [76.97, 5.235], "花見がてら、川沿いの道を散策した。": [82.605, 3.685], "郵便局に行ったついでに、銀行にも寄った。": [86.69, 3.81], "店舗": [90.9, 1.07], "活用": [92.37, 1.24], "通販": [94.01, 1.11], "消費": [95.52, 1.115], "競争": [97.035, 1.215], "呉服": [98.65, 1.06], "太刀打ち": [100.11, 1.185], "雑貨": [101.695, 1.115]}, "d020": {"拝啓　木々の緑が深まる季節となりましたが、先生にはお変わりなくお過ごしのことと存じます。さて、私事ではございますが、このたび十年勤めた商社を退職し、郷里で家業の醸造所を継ぐことになりました。在学中、先生から「経済は数字だけでなく、人の営みで動いている」と教わったことが、今も私の指針となっております。来月上京の折には、ご報告かたがたご挨拶に伺いたく存じますが、ご都合はいかがでしょうか。地方の酒蔵の存続は容易ではありませんが、伝統を守りつつ、海外市場の開拓にも挑戦する所存です。末筆ながら、先生のますますのご健勝をお祈り申し上げます。敬具": [0.0, 51.32], "来週、先方へお詫びかたがた、新しい担当者の紹介に伺おうと思うんだ。": [51.72, 6.81], "では、手土産を用意しておきます。": [58.93, 2.765], "ありがとう。先方のご都合も確認しておいてくれるかな。": [62.095, 4.725], "承知しました。午前中にメールでお伺いしてみます。": [67.22, 4.315], "先日のお礼かたがた、近況をご報告申し上げます。": [71.935, 4.725], "退院のご報告かたがた、お世話になった方々にご挨拶に伺った。": [77.06, 5.64], "転勤のご挨拶かたがた、新しい名刺をお持ちしました。": [83.1, 4.775], "郷里に戻って家業を継ぐことになりましたので、ご報告かたがたご挨拶に伺います。": [88.275, 6.64], "昇進のご挨拶かたがた、恩師のお宅を訪ねた。": [95.315, 4.43], "散歩がてら、パンを買ってきた。": [100.145, 2.88], "家業": [103.425, 1.095], "醸造": [104.92, 1.2], "指針": [106.52, 1.055], "存続": [107.975, 1.29], "開拓": [109.665, 1.215], "商社": [111.28, 1.22], "郷里": [112.9, 1.01], "市場": [114.31, 1.165]}, "d022": {"かつての日本の産業界では、大企業と取引先の中小企業が持ちつ持たれつの関係を築いてきた。大企業は安定した発注を約束し、中小企業はそれに応えて品質と納期を守る。こうした長期的な信頼関係こそが、日本のものづくりを支えてきたといえる。しかし、経済のグローバル化に伴い、大企業は部品の調達先を世界中から選ぶようになり、価格の引き下げを迫られた中小企業は疲弊している。両者の関係を対等なものに改めなければ、優れた技術を持つ町工場は次々と姿を消していくだろう。発注する側の企業にこそ、取引の在り方を見直す責任がある。": [0.0, 46.775], "さっきのレース、すごかったね。最後まで抜きつ抜かれつでさ。": [47.175, 5.415], "本当。ゴールの直前まで、どっちが勝つか分からなかった。": [52.99, 5.215], "あの二人、ライバルだけど、普段は一緒に練習してるらしいよ。": [58.605, 5.185], "へえ、持ちつ持たれつの関係なんだね。": [64.19, 3.53], "彼は駅の前を行きつ戻りつしながら、彼女を待っていた。": [68.12, 4.565], "両チームは抜きつ抜かれつの接戦を繰り広げた。": [73.085, 3.67], "小舟は波間に浮きつ沈みつしながら、沖へ流されていった。": [77.155, 4.82], "あの二社は対等な立場で信頼関係を築き、持ちつ持たれつでやってきた。": [82.375, 5.975], "答えが出せず、彼は部屋の中を行きつ戻りつした。": [88.75, 4.39], "休日は本を読んだり映画を見たりして過ごす。": [93.54, 3.5], "発注": [97.44, 1.175], "調達": [99.015, 1.235], "疲弊": [100.65, 1.145], "対等": [102.195, 0.99], "産業": [103.585, 1.26], "信頼": [105.245, 1.195], "引き下げ": [106.84, 1.285], "町工場": [108.525, 1.3]}, "d023": {"【相談】三十代の会社員です。今の職場は給料こそ悪くないものの、仕事にやりがいを感じられません。転職を考えていますが、家族には反対されています。\n【回答】やりがいを感じられないまま働き続けるのは、確かにつらいことでしょう。ただ、いきなり退職するのは得策とは言えません。まずは転職サイトに登録するなり、業界に詳しい知人に話を聞くなりして、ご自分の市場での評価を客観的に知ることから始めてはいかがでしょうか。そのうえで、ご家族に収入の見通しや将来の計画を具体的に説明すれば、理解を得られる可能性も高まるはずです。転職はあくまで手段であって、目的ではありません。何を実現したいのかを明確にすることが先決です。": [0.0, 52.905], "レポートのテーマがなかなか決まらなくて困ってるんだ。": [53.305, 3.78], "先生に相談するなり、図書館で資料を探すなりしてみたら？": [57.485, 5.115], "そうだね。締め切りまで、あと一週間しかないし。": [63.0, 4.435], "うん、早めに動いたほうがいいよ。": [67.835, 2.825], "分からないことがあれば、電話するなりメールするなりして連絡してください。": [71.06, 5.535], "そんなに疲れているなら、休むなり早退するなりしたらどうですか。": [76.995, 5.22], "必要な書類は、郵送なり持参なりで提出してください。": [82.615, 4.825], "転職するかどうか迷っているなら、専門家に相談するなり求人情報を調べるなりして、まず将来の見通しを立てたらどう？": [87.84, 9.59], "困ったときは、先生なり先輩なりに相談しなさい。": [97.83, 4.65], "週末は掃除をしたり洗濯をしたりした。": [102.88, 3.335], "転職": [106.615, 1.165], "得策": [108.18, 1.245], "客観的": [109.825, 1.34], "収入": [111.565, 1.18], "見通し": [113.145, 1.195], "手段": [114.74, 1.035], "実現": [116.175, 1.105], "先決": [117.68, 1.325]}, "d024": {"正社員であれ非正規社員であれ、同じ仕事をしている以上、待遇に不合理な差があってはならない。これが「同一労働同一賃金」の基本的な考え方である。制度の導入から数年がたち、一部の企業では手当や休暇の格差の是正が進んだ。しかし、基本給の差は依然として大きく、非正規で働く人の多くが将来への不安を抱えている。企業側からは、人件費の負担増を懸念する声も根強い。だが、雇用形態にかかわらず能力を正当に評価する仕組みは、働く人の意欲を高め、結果として企業の競争力の向上にもつながるはずだ。": [0.0, 44.78], "来月の社内イベント、参加は自由なんですよね？": [45.18, 4.33], "うん。でも部長が、新人であれベテランであれ、できるだけ顔を出してほしいって。": [49.91, 6.565], "そうですか。じゃあ、私も参加します。": [56.875, 3.87], "助かるよ。人数が多いほうが盛り上がるからね。": [61.145, 3.845], "晴れであれ雨であれ、試合は予定どおり行われる。": [65.39, 4.065], "大人であれ子どもであれ、ルールは守らなければならない。": [69.855, 4.29], "理由が何であれ、暴力は決して許されない。": [74.545, 3.85], "若者であれ高齢者であれ、同じ成果を上げた人には同じ賃金が支払われるべきだ。": [78.795, 6.605], "国内であれ海外であれ、出張の手続きは同じだ。": [85.8, 4.575], "行くにしろ行かないにしろ、早めに連絡してください。": [90.775, 4.355], "待遇": [95.53, 1.09], "不合理": [97.02, 1.115], "賃金": [98.535, 1.12], "格差": [100.055, 1.2], "是正": [101.655, 1.15], "依然": [103.205, 0.965], "雇用": [104.57, 1.085], "手当": [106.055, 1.055]}, "d025": {"先日、出張で泊まった地方都市のビジネスホテルは、予想外に快適だった。客室の清潔さといい、スタッフの細やかな対応といい、この料金を考えれば申し分ない。聞けば、数年前に経営が地元企業に移ったのを機に、接客の研修を一から見直したのだという。宿泊業界では人手不足が深刻で、自動チェックイン機の導入など省力化が進んでいる。もちろん効率化は重要だが、利用客の満足度を最終的に左右するのは、人の温かさではないだろうか。価格競争に陥りがちな業界にあって、サービスの質で差をつけようとする同ホテルの姿勢は、ほかの事業者にとっても参考になるだろう。": [0.0, 48.98], "昨日行ったレストラン、どうだった？": [49.38, 2.705], "よかったよ。味といい雰囲気といい、文句なしだね。": [52.485, 4.515], "でも、料金は高かったんじゃない？": [57.4, 3.01], "それが、ランチなら千五百円なんだ。今度一緒に行こうよ。": [60.81, 5.055], "この服は、色といいデザインといい、私の好みにぴったりだ。": [66.265, 5.26], "彼は態度といい言葉遣いといい、社会人としての常識に欠けている。": [71.925, 5.735], "今年の夏は、暑さといい雨の少なさといい、例年とは明らかに違う。": [78.06, 6.19], "あの旅館は、料理といい接客といい、料金以上の価値があった。": [84.65, 5.49], "この部屋は、広さといい日当たりといい、申し分ない。": [90.54, 4.56], "壁といわず床といわず、部屋じゅう落書きだらけだ。": [95.5, 4.135], "宿泊": [100.035, 1.33], "人手不足": [101.765, 1.475], "省力化": [103.64, 1.31], "満足度": [105.35, 1.215], "左右": [106.965, 1.095], "事業者": [108.46, 1.16], "接客": [110.02, 1.295], "料金": [111.715, 1.105]}, "d026": {"人気観光地の京都では、桜の季節を迎え、平日といわず週末といわず、主要な寺社や繁華街が国内外からの観光客であふれている。市内を走るバスは朝から満員の状態が続き、通勤や通学に利用する住民からは「乗りたくても乗れない」との不満が噴出している。観光客の増加は地域経済に大きな恩恵をもたらす一方で、ごみの放置や私有地への無断の立ち入りといった問題も深刻化している。市は今年度から、観光客向けの急行バスの運行や宿泊税の引き上げなどの対策を打ち出したが、効果は限定的との見方もある。観光と市民生活の両立に向けた模索が続いている。": [0.0, 47.96], "昨日の大雨で、家の中がひどいことになってさ。": [48.36, 4.165], "え、雨漏り？": [52.925, 1.645], "うん。床といわず壁といわず、あちこち濡れちゃって。": [54.97, 4.5], "大変だったね。修理はいつ来てもらえるの？": [59.87, 3.67], "業者が混んでて、来週になるらしいんだ。": [63.94, 3.585], "子どもたちは、顔といわず手といわず、泥だらけになって遊んでいた。": [67.925, 5.455], "彼は昼といわず夜といわず、研究室にこもって実験を続けた。": [73.78, 5.365], "部屋の中は、机の上といわず床といわず、本が山積みになっている。": [79.545, 5.78], "祭りの翌朝、繁華街は歩道といわず車道といわず、ごみが放置されたままだった。": [85.725, 6.745], "休日といわず平日といわず、彼は毎日ジムに通っている。": [92.87, 4.96], "兄も姉も医者だ。": [98.23, 1.66], "繁華街": [100.29, 1.19], "噴出": [101.88, 1.135], "恩恵": [103.415, 1.175], "放置": [104.99, 1.065], "私有地": [106.455, 1.235], "運行": [108.09, 1.175], "引き上げ": [109.665, 1.18], "限定的": [111.245, 1.295]}, "d027": {"「自分が投票しようがしまいが、結果は変わらない」。若い世代から、こうした声をよく耳にする。確かに、一票の重みを実感するのは難しい。しかし、若者の投票率が低い状態が続けば、政治家は投票所に足を運ぶ高齢者の意向を優先せざるを得なくなる。年金や医療の制度が高齢層に手厚い一方で、子育てや教育への予算が後回しにされがちなのは、その表れだという指摘もある。関心を持とうが持つまいが、政治の決定は私たちの暮らしに確実に影響を及ぼす。だからこそ、一人ひとりが自らの意思を示すことに意味があるのではないか。": [0.0, 44.84], "明日のバーベキュー、雨が降ったらどうする？": [45.24, 3.5], "雨が降ろうが降るまいが、屋根のある場所だから大丈夫だよ。": [49.14, 4.595], "よかった。じゃあ、食材は予定どおり買っておくね。": [54.135, 4.58], "うん、頼むよ。飲み物は僕が用意するから。": [59.115, 4.14], "君が賛成しようがしまいが、計画は予定どおり進める。": [63.655, 4.855], "人に笑われようが笑われまいが、自分の信じた道を進むつもりだ。": [68.91, 5.5], "売れようが売れまいが、作家は書き続けるしかない。": [74.81, 4.005], "周りに理解されようがされまいが、私は家族との時間を何より優先したい。": [79.215, 5.99], "彼が来ようが来るまいが、会議は時間どおりに始める。": [85.605, 4.38], "この薬は、飲んでも飲まなくても効果はあまり変わらない。": [90.385, 4.575], "投票率": [95.36, 1.215], "意向": [96.975, 1.1], "優先": [98.475, 1.1], "年金": [99.975, 1.11], "医療": [101.485, 1.04], "世代": [102.925, 1.095], "意思": [104.42, 0.945], "後回し": [105.765, 1.32]}, "d029": {"政府は少子化対策の一環として、子育て世帯への給付金の拡充を打ち出した。だが、一時的に現金を配ったところで、出生率が劇的に改善するとは考えにくい。若い世代が結婚や出産をためらう背景には、不安定な雇用や長時間労働、住居費の高さなど、複数の要因が複雑に絡み合っているからだ。本当に必要なのは、安心して働き続けられる職場環境や、子育てを社会全体で支える仕組みの整備だろう。財源には限りがある。目先の人気取りに終わらせることなく、長期的な視点に立った政策が求められている。": [0.0, 43.44], "今から急いだところで、もう終電には間に合わないよ。": [43.84, 4.285], "そっか……。じゃあ、タクシーで帰るしかないね。": [48.525, 3.955], "方向が同じだから、二人で乗れば料金も半分で済むよ。": [52.88, 4.86], "そうだね。駅前で拾おう。": [58.14, 2.585], "今さら謝ったところで、彼女は許してくれないだろう。": [61.125, 4.495], "いくら説明したところで、分かってもらえるとは思えない。": [66.02, 4.475], "多少値上げしたところで、利益はたかが知れている。": [70.895, 4.095], "財源の裏付けがないまま新しい政策を打ち出したところで、長続きはしないだろう。": [75.39, 6.6], "今から勉強したところで、合格は難しいだろう。": [82.39, 4.44], "雨が降っても、試合は予定どおり行われる。": [87.23, 3.79], "給付金": [91.42, 1.05], "拡充": [92.87, 1.215], "出生率": [94.485, 1.31], "世帯": [96.195, 1.135], "要因": [97.73, 1.015], "財源": [99.145, 1.075], "政策": [100.62, 1.29], "整備": [102.31, 1.095]}, "d031": {"職場で困りごとを一人で抱え込む若手社員が増えているという。先日も、ある新人が締め切り前夜まで資料の不備に気づかず、徹夜で修正する羽目になった。上司は「一言相談してくれれば、すぐに手を貸したものを」と嘆いたそうだ。だが、あながち本人だけを責めるわけにもいかない。忙しそうな先輩に声をかけるのは、新人にとって想像以上に勇気がいる。周囲がしきりに「何でも聞いて」と言っても、実際に尋ねやすい雰囲気がなければ、その言葉は空回りするだけだ。相談を待つのではなく、上司の側からあえて声をかける。そうした小さな工夫こそが、結果的に組織全体の損失を防ぐのではないだろうか。": [0.0, 50.005], "昨日の会議、資料が間に合わなかったんだって？": [50.405, 3.915], "うん、かろうじて最初の部分だけは出せたんだけど。": [54.72, 4.065], "言ってくれれば手伝ったものを。": [59.185, 2.32], "忙しそうだったから、あえて頼まなかったんだよ。": [61.905, 4.0], "早く病院に行けば軽く済んだものを、彼は我慢し続けた。": [66.305, 4.845], "黙っていればいいものを、彼はまた余計な一言を言ってしまった。": [71.55, 5.035], "素直に謝れば許してもらえたものを、意地を張ったせいで関係がこじれた。": [76.985, 5.7], "もう少し早く家を出ていれば電車に間に合ったものを、あえて遠回りをしてしまった。": [83.085, 5.945], "知らせてくれれば駅まで迎えに行ったものを。": [89.43, 3.325], "春なのに、まだ雪が降っている。": [93.155, 2.915], "あながち": [96.47, 1.18], "しきりに": [98.05, 1.19], "敢えて": [99.64, 1.055], "些か": [101.095, 1.315], "辛うじて": [102.81, 1.29], "案の定": [104.5, 1.225], "いっそ": [106.125, 1.045], "一概に": [107.57, 1.235]}, "d032": {"ある地方自治体が今春から試験的に導入した週休三日制について、半年間の検証結果が公表された。職員へのアンケートでは「生活に余裕が生まれた」との回答がおおむね七割に達し、とりわけ子育て世代からの評価が高かった。一方、窓口の待ち時間はさほど変わらなかったものの、一部の部署では残業がかえって増えたという。制度として一定の成果を上げたとはいえ、課題がすべて解消されたわけではない。担当者は「全庁に一挙に広げるのではなく、部署ごとの事情を踏まえて段階的に進めたい」と話しており、依然として慎重な姿勢を崩していない。": [0.0, 45.12], "新しいシステム、だいぶ慣れてきた？": [45.52, 3.195], "うん。慣れてきたとはいえ、まだ時々戸惑うよ。": [49.115, 4.27], "前のと比べて、操作はさほど変わらないはずなんだけどね。": [53.785, 4.785], "画面の配置がとりわけ違うから、そこがね。": [58.97, 3.84], "春とはいえ、朝晩はまだ冷え込む。": [63.21, 3.255], "経験者とはいえ、初めての現場では誰でも緊張するものだ。": [66.865, 5.12], "景気が回復しつつあるとはいえ、家計の負担は依然として重い。": [72.385, 5.225], "日本語に自信がついてきたとはいえ、敬語はいまだに難しいと感じる。": [78.01, 5.69], "休日とはいえ、仕事のことが頭から離れない。": [84.1, 4.285], "旅行といっても、近所の温泉に一泊するだけだ。": [88.785, 4.16], "依然として": [93.345, 1.435], "概ね": [95.18, 1.165], "一挙に": [96.745, 1.035], "未だに": [98.18, 1.135], "総じて": [99.715, 1.255], "さほど": [101.37, 1.22], "とりわけ": [102.99, 1.225], "極めて": [104.615, 1.215]}, "d033": {"名医といえども、誤診とまったく無縁ではいられない。医学の知識がいかに豊富でも、人間である以上、思い込みや疲労から判断を誤ることはしばしばある。問題は、誤りそのものよりも、それを認めない態度のほうだ。ある医師は若い頃、自分の診断に固執し、同僚の指摘にも一向に耳を貸さなかったという。その結果、患者の回復が遅れ、深く後悔したと振り返る。以来、彼は「自分は断じて間違えない」という考えを一切捨て、迷ったときには必ず他の医師の意見を求めるようにしている。どれほどの専門家といえども、謙虚さを失った瞬間に、その知識は危うさに変わるのかもしれない。": [0.0, 48.63], "今回の件は、新人だからといって見過ごすわけにはいかないね。": [49.03, 5.19], "はい。新人といえども、お客様との約束は守らなければなりません。": [54.62, 6.035], "本人は終始反省している様子だったけどね。": [61.055, 3.595], "ええ、事の重大さはよくわかっているようです。": [65.05, 3.91], "子どもといえども、一人の人間として尊重されるべきだ。": [69.36, 4.565], "一円といえども、公金を無駄にすることは許されない。": [74.325, 4.4], "いかに優れた技術といえども、使い方を誤れば危険なものになる。": [79.125, 5.285], "いかに経験豊富なベテランといえども、安全確認を怠ることは断じて許されない。": [84.81, 6.585], "たとえ社長といえども、会社の規則には従わなければならない。": [91.795, 5.06], "社長になったとはいえ、彼の生活は以前とほとんど変わらない。": [97.255, 5.29], "如何にも": [102.945, 1.225], "悉く": [104.57, 1.39], "断じて": [106.36, 1.16], "到底": [107.92, 1.165], "一向に": [109.485, 1.2], "屡々": [111.085, 1.345], "終始": [112.83, 1.15], "一切": [114.38, 1.06]}, "d034": {"創業六十年を迎えた駅前の喫茶店が、先月から休業している。店主が高齢であることもあり、常連客の多くはてっきり店をたたむものと思っていた。ところが、閉店かと思いきや、店主の孫にあたる二十代の女性が店を継ぐことになったという。昔ながらの固いプリンや手書きのメニューはそのまま残し、支払い方法だけはキャッシュレスに対応させる予定だ。この知らせはSNSでたちまち広まり、再開を待ち望む声が相次いでいる。女性は「祖父の味を守るのは責任重大ですが、まんざら不安ばかりでもありません」と笑顔を見せた。営業はほどなく、来月上旬に再開される予定だ。": [0.0, 46.62], "今日の試合、うちのチームが勝つと思いきや、最後に逆転されちゃった。": [47.02, 5.95], "本当？てっきり楽勝だと思ってたのに。": [53.37, 3.66], "相手のエースが途中から急に調子を上げてね。": [57.43, 3.62], "野球って、最後まで分からないもんだね。": [61.45, 3.455], "簡単な試験だと思いきや、最後の問題でつまずいた。": [65.305, 4.645], "雨がやんだと思いきや、今度は雷が鳴り出した。": [70.35, 4.21], "厳しい人かと思いきや、話してみると意外に気さくだった。": [74.96, 4.785], "てっきり満席だと思いきや、店に入るとすんなり席に案内された。": [80.145, 5.44], "晴れると思いきや、午後から大雨になった。": [85.985, 3.56], "子どもが静かになったと思ったら、もう寝ていた。": [89.945, 3.86], "てっきり": [94.205, 1.125], "あっさり": [95.73, 1.06], "忽ち": [97.19, 1.225], "俄かに": [98.815, 1.195], "程なく": [100.41, 1.215], "ひょっとすると": [102.025, 1.32], "満更": [103.745, 1.175], "すんなり": [105.32, 1.185]}, "d036": {"電車がほんの数分遅れただけで、駅員に詰め寄る乗客を見かけることがある。急いでいる事情があるにしたって、怒鳴ったところで電車が早く来るわけではない。私たちはとかく、他人には完璧を求めがちだ。だが、自分にしたって、毎日ミスなく働けているかと問われれば、胸を張れる人はせいぜい一握りだろう。疲れてろくに眠れなかった日もあれば、うっかり約束を忘れた日もある。他人の小さな失敗をむやみに責める前に、自分も同じ立場になりうると想像してみる。誰もが余裕を失いがちな時代だからこそ、なおさらそうした寛容さが求められているのではないか。": [0.0, 43.805], "来週のレポート、もう書き始めた？": [44.205, 3.235], "まだ。今週はバイトでろくに寝てなくてさ。": [47.84, 3.745], "忙しいにしたって、少しは手をつけておかないと間に合わないよ。": [51.985, 5.115], "わかってるよ。そっちにしたって、まだ半分ぐらいでしょ？": [57.5, 4.645], "ばれたか。": [62.545, 1.15], "冗談にしたって、言っていいことと悪いことがある。": [64.095, 4.045], "社長にしたって、この不況を予測できたわけではない。": [68.54, 4.38], "いくら安いにしたって、こんなに質が悪くては買う気にならない。": [73.32, 4.92], "遅れるにしたって、連絡ぐらいくれればいいのに。とかく君は時間にルーズだね。": [78.64, 6.175], "忙しいにしたって、電話一本くらいできるだろう。": [85.215, 4.045], "たとえ失敗したとしても、挑戦したことは後悔しない。": [89.66, 4.62], "兎角": [94.68, 1.145], "碌に": [96.225, 0.97], "やけに": [97.595, 1.115], "無闇に": [99.11, 1.025], "精々": [100.535, 1.26], "尚更": [102.195, 1.19], "ともすると": [103.785, 1.345], "甚だ": [105.53, 1.26]}, "d037": {"社員各位\n情報セキュリティ強化に関するお願い\n先月、取引先を装った不審なメールにより、他社で大規模な情報流出が発生しました。当社でも同様の手口のメールが複数確認されています。お客様の個人情報は、一件たりとも外部に漏らすことがあってはなりません。つきましては、以下の点を徹底してください。不審なメールの添付ファイルは開かず、直ちに情報システム部へ報告すること。社外へ資料を送付する際は、極力パスワードを設定すること。なお、最新の注意事項は社内サイトで随時お知らせします。くれぐれも「自分は大丈夫」と思わず、一人ひとりが当事者意識を持って対応してください。\n情報システム部": [0.0, 49.715], "来週の監査、準備は進んでる？": [50.115, 3.205], "はい、書類は一枚たりとも漏れがないよう、逐一確認しています。": [53.72, 5.755], "助かるよ。不明な点があったら、至急知らせてね。": [59.875, 4.5], "承知しました。": [64.775, 1.46], "試験中は一秒たりとも気を抜けない。": [66.635, 3.13], "両親が苦労して貯めたお金は、一円たりとも無駄にはできない。": [70.165, 5.015], "祖父は五十年間、一日たりとも日記を欠かさなかった。": [75.58, 4.85], "締め切りだけは一日たりとも遅らせないと決めて、絶えずスケジュールを確認している。": [80.83, 6.3], "工事中は一瞬たりとも目を離してはいけない。": [87.53, 3.535], "昨日は一分も勉強しなかった。": [91.465, 2.67], "くれぐれも": [94.535, 1.3], "直ちに": [96.235, 1.185], "絶えず": [97.82, 1.01], "随時": [99.23, 1.045], "逐一": [100.675, 1.175], "極力": [102.25, 1.255], "至急": [103.905, 1.1], "即座に": [105.405, 1.185]}, "d038": {"大地震はいずれ必ず起きると言われて久しい。行政はハザードマップの配布や避難所の整備を進めているが、それだけで命が守れるわけではない。現に、過去の災害では、近所の人に声をかけられて避難し、助かった高齢者が少なくなかった。日頃の住民同士のつながりなくしては、いざという時の迅速な避難は望めない。万一に備えて、避難経路をあらかじめ家族で確認しておくことはもちろん大切だ。しかし、何より重要なのは、隣に誰が住んでいるかを知っていることではないだろうか。地域の防災力は、ひとえに住民一人ひとりの関わりにかかっている。": [0.0, 44.25], "今回の受賞、おめでとうございます。": [44.65, 3.385], "ありがとうございます。スタッフの支えなくしては、この作品は完成しませんでした。": [48.435, 6.81], "制作にはどのくらいかかったんですか。": [55.645, 3.02], "構想から数えると、かれこれ三年近くになります。": [59.065, 4.555], "努力なくして成功はありえない。": [64.02, 2.57], "地元の方々の協力なくしては、この祭りは続けられなかった。": [66.99, 5.42], "信頼関係なくしては、本当のチームワークは生まれない。": [72.81, 4.685], "家族の理解なくしては、留学という決断はできませんでした。今の私があるのは、ひとえに家族のおかげです。": [77.895, 8.985], "皆様のご支援なくしては、今日の当社はありません。": [87.28, 4.185], "この施設は、予約なしには利用できません。": [91.865, 3.89], "偏に": [96.155, 1.12], "予め": [97.675, 1.365], "万一": [99.44, 1.125], "何れ": [100.965, 1.075], "現に": [102.44, 0.985], "予て": [103.825, 1.12], "自ずから": [105.345, 1.34], "かれこれ": [107.085, 1.255]}, "d039": {"株式会社ミナト工業　営業部　佐藤様\nいつもお世話になっております。北山商事の田中でございます。先日納品いただいた部品について、事前のご連絡なしに仕様が変更されていたことが判明いたしました。弊社では、この部品を使用した製品の検査をすべてやり直すことになり、出荷にも遅れが生じております。仕様を変更される際はご一報いただくよう、以前から再三お願いしておりましただけに、大変遺憾に存じます。つきましては、変更に至った経緯と今後の再発防止策について、早急にご回答いただけますでしょうか。何卒よろしくお願い申し上げます。": [0.0, 43.97], "申し訳ございません。こちらの展示は、予約なしにはご入場いただけないんです。": [44.37, 6.415], "え、そうなんですか。当日券もないんですか。": [51.185, 4.155], "あいにく本日分は完売しておりまして。": [55.74, 3.115], "そうですか…。じゃあ、来週の分を予約していきます。": [59.255, 4.47], "彼は一言の断りもなしに会社を辞めてしまった。": [64.125, 4.195], "専門家の協力なしには、この調査は進められない。": [68.72, 4.71], "職人たちは休むことなしに、朝から晩まで作業を続けた。": [73.83, 5.285], "事前のご説明なしに料金が変更されたため、困惑しております。早急にご説明いただけますと幸いです。": [79.515, 8.98], "彼は何の連絡もなしに会議を欠席した。": [88.895, 3.58], "今朝は朝ご飯を食べずに家を出た。": [92.875, 2.92], "再三": [96.195, 1.17], "早急に": [97.765, 1.215], "追って": [99.38, 1.03], "何卒": [100.81, 1.24], "生憎": [102.45, 1.15], "一律に": [104.0, 1.175], "予々": [105.575, 1.23], "重ねて": [107.205, 1.145]}, "d040": {"ある人気アニメの放送十周年を記念した限定グッズが、先週末、都内の一店舗だけで販売された。発売当日は早朝から長い列ができ、中には地方からはるばる夜行バスでやって来たファンもいたという。好きな作品のためとあれば、時間も費用も惜しまないのが、いわゆる「推し活」だ。ある女性は「この日のためにひたすら節約してきた。とことん楽しみたい」と話した。関連商品の市場は拡大を続けており、企業もこぞって参入している。一方で、転売目的の購入が後を絶たず、本当に欲しい人の手に届かないという課題も指摘されている。": [0.0, 44.78], "部長、来月の出張、僕が代わりに行きましょうか。": [45.18, 4.935], "いいのかい？遠いし、週末にかかるけど。": [50.515, 4.135], "部長のご指示とあれば、どこへでも行きますよ。": [55.05, 3.71], "頼もしいね。じゃあ、詳細はあとでメールするよ。": [59.16, 4.455], "子どものためとあれば、親はどんな苦労もいとわない。": [64.015, 4.055], "社長の命令とあれば、従わないわけにはいかない。": [68.47, 4.305], "必要とあれば、いつでもご説明に伺います。": [73.175, 3.955], "大切な友人のためとあれば、わざわざ遠くまで出向くことも苦にならない。": [77.53, 5.655], "君の頼みとあれば、断るわけにはいかない。": [83.585, 3.805], "三連休とあって、観光地はどこも混雑していた。": [87.79, 4.525], "挙って": [92.715, 1.21], "わざわざ": [94.325, 1.24], "遥々": [95.965, 1.14], "ひたすら": [97.505, 1.245], "とことん": [99.15, 1.16], "ふんだんに": [100.71, 1.21], "存分に": [102.32, 1.125], "いとも": [103.845, 1.08]}, "d041": {"今の時代、有名人がSNSで不用意な発言をしようものなら、数時間のうちに批判が殺到する。ひとたび拡散した投稿は完全に消すことができず、何年も後になって掘り返されることさえある。そのため、多くの人が本音をおちおち書き込めなくなったと感じている。もちろん、他人を傷つける発言を軽々しく許してよいわけではない。しかし、ややもすれば、たった一度の失言だけで人格まで否定されてしまう風潮には、危うさを覚える。言葉の重みを意識しつつも、互いの過ちにもう少し寛容になれないものだろうか。": [0.0, 41.42], "明日の授業、遅刻しないようにしなきゃ。": [41.82, 3.55], "田中先生の授業でしょ？一分でも遅れようものなら、教室に入れてもらえないよ。": [45.77, 6.54], "うかうかしていられないな。目覚ましを三つかけておこう。": [52.71, 4.345], "それがいいよ。": [57.455, 1.345], "父の前で弱音を吐こうものなら、「甘えるな」と叱られる。": [59.2, 5.04], "この山道で足を滑らせようものなら、大けがは避けられない。": [64.64, 4.965], "姉に年齢を聞こうものなら、一週間は口をきいてもらえないだろう。": [70.005, 5.115], "母の作った料理をうっかり残そうものなら、その日は一日中機嫌が悪い。": [75.52, 6.005], "試験中に私語をしようものなら、即座に退室を命じられる。": [81.925, 4.87], "戻れるものなら、学生時代に戻りたい。": [87.195, 3.64], "一度": [91.235, 1.18], "ややもすれば": [92.815, 1.45], "みすみす": [94.665, 1.265], "おちおち": [96.33, 1.155], "うかうか": [97.885, 1.26], "容易く": [99.545, 1.2], "軽々しく": [101.145, 1.445], "うっかり": [102.99, 1.105]}, "d043": {"在宅勤務が広がって以来、運動不足を感じる人がめっきり増えた。通勤がなくなっただけで、一日の歩数が半分以下になったという調査もある。とはいえ、忙しい社会人が毎日ジムに通うのは現実的ではない。そこで専門家が勧めるのが「ついで運動」だ。毎日一時間とは言わないまでも、せめて十分程度、家の周りを歩くだけでも、体への効果はぐっと高まるという。また、一時間に一度は立ち上がって体を伸ばすなど、こまめに動く習慣をつけることも大切だ。まずは無理のない範囲から、ひとまず始めてみてはどうだろうか。": [0.0, 43.185], "検査の結果ですが、数値はいたって正常ですよ。": [43.585, 4.34], "よかった。最近疲れやすいので心配してたんです。": [48.325, 4.255], "毎日とは言わないまでも、週に何回か軽い運動をしてみてください。": [52.98, 5.43], "わかりました。さしあたり、駅まで歩くことから始めてみます。": [58.81, 5.33], "満点は取れないまでも、平均点ぐらいは取りたい。": [64.54, 4.12], "毎日とは言わないまでも、週に一度は実家に電話している。": [69.06, 4.755], "謝罪はしないまでも、せめて事情ぐらいは説明すべきだ。": [74.215, 4.85], "一日一時間とは言わないまでも、せめて三十分は日本語のニュースを聞くようにしたい。": [79.465, 6.67], "プロとは言わないまでも、彼の料理の腕はかなりのものだ。": [86.535, 4.415], "会に参加しないにしても、返事ぐらいはするべきだ。": [91.35, 4.26], "せめて": [96.01, 1.195], "ひとまず": [97.605, 1.17], "めっきり": [99.175, 1.03], "ぐっと": [100.605, 1.055], "至って": [102.06, 1.04], "こまめに": [103.5, 1.065], "差し当たり": [104.965, 1.36], "ゆくゆく": [106.725, 1.25]}, "d044": {"先日、新入社員から届いたメールに驚いた。件名もなく、本文は「明日休みます」の一行だけだったのだ。学生同士のやり取りならいざ知らず、いやしくも社会人として働く以上、最低限の礼儀は必要だろう。まして相手は上司である。ただ、本人に悪気はなく、そうした書き方をまるっきり知らなかったようだ。考えてみれば、今の若者はメールよりもチャットに慣れた世代で、改まった文章を書く機会はてんでなかったのかもしれない。いまさら嘆いても始まらない。ことさら責めるのではなく、職場で一から丁寧に教えていくことこそ、私たち上の世代の役目なのだと思う。（会社員・五十二歳）": [0.0, 48.775], "この資料、明日までに全部翻訳してもらえる？": [49.175, 4.035], "え、全部ですか。数ページならいざ知らず、百ページもあるんですよ。": [53.61, 5.885], "そうよね…。じゃあ、とりあえず前半だけでいいわ。": [59.895, 4.29], "それなら何とかやってみます。": [64.585, 2.295], "子どもならいざ知らず、大人がそんなことで泣くなんて。": [67.28, 4.245], "初心者ならいざ知らず、十年もやっていてこのミスはないだろう。": [71.925, 5.0], "昔ならいざ知らず、今は誰でもネットで情報を調べられる。": [77.325, 4.935], "小さな子どもならいざ知らず、まして大人が電車の中で大声で騒ぐのはどうかと思う。": [82.66, 6.545], "新人ならいざ知らず、課長がこんな初歩的なミスをするとは。": [89.605, 5.115], "一日ならともかく、一週間も休むのは無理だよ。": [95.12, 4.385], "苟も": [99.905, 1.33], "況して": [101.635, 1.08], "今更": [103.115, 1.235], "よもや": [104.75, 1.11], "さも": [106.26, 1.075], "てんで": [107.735, 1.04], "まるっきり": [109.175, 1.225], "殊更": [110.8, 1.295]}, "d045": {"高校時代の部活動の監督は、とにかく厳しい人だった。練習中に少しでも気を抜けば怒鳴られ、部員は皆ほとほと疲れ果てていた。当時の私は、監督は自分たちを嫌っているのだと心底思っていた。ところが卒業式の日、監督は部員一人ひとりに手紙を手渡してくれた。そこには、私の長所や伸ばすべき点が細かく書かれていた。厳しくしたのは、皆の可能性を信じていればこそだったのだと、そのとき初めて気づいた。今では私も後輩を指導する立場になり、相手を思えばこそ言わなければならないことがあると、つくづく感じている。あの手紙は、今もって私の宝物だ。": [0.0, 46.675], "先生、どうして私の作文にだけこんなに赤が多いんですか。": [47.075, 5.265], "君には力があると思えばこそ、細かく直したんだよ。": [52.74, 4.56], "そうだったんですね。てっきり嫌われているのかと…。": [57.7, 3.98], "まさか。次の作文も楽しみにしているよ。": [62.08, 3.845], "健康であればこそ、好きな仕事も続けられるのだ。": [66.325, 4.315], "子どもの将来を思えばこそ、親は厳しく叱るのだ。": [71.04, 4.35], "君を信頼していればこそ、この仕事を任せたのだ。": [75.79, 4.35], "友人が耳の痛いことを言ってくれたのは、私を大切に思えばこそだったのだと、今になってつくづく思う。": [80.54, 8.29], "相手を大切に思えばこそ、あえて厳しいことを言うのだ。": [89.23, 4.565], "毎日練習したからこそ、本番で落ち着いていられた。": [94.195, 4.435], "ひたむきに": [99.03, 1.18], "心底": [100.61, 1.345], "つくづく": [102.355, 1.205], "しみじみ": [103.96, 1.26], "ほとほと": [105.62, 1.315], "尚も": [107.335, 1.06], "今以て": [108.795, 1.215], "夙に": [110.41, 1.05]}, "d046": {"最近、大学の入学式や企業の説明会に保護者が付き添う姿は珍しくなくなった。中には、就職先の条件について人事担当者にいちいち質問する親もいるという。子どもではあるまいし、二十歳を過ぎた大人の進路に親がそこまで口を出すのはいかがなものか。もちろん、なにかと不安の多い時代に、我が子を心配する気持ちは理解できる。しかし、先回りしてやたらに手を貸すことが、かえって本人の自立を妨げることもある。親にできるのは、あたかも何も知らないかのように見守りつつ、困ったときにはそれとなく支えることではないだろうか。": [0.0, 42.93], "明日の会議の資料、コピーはどうする？僕がやっておこうか？": [43.33, 5.32], "いいよ、自分でやるから。新人じゃあるまいし、それぐらいできるって。": [49.05, 5.875], "そうだよね。ごめん、余計なお世話だった。": [55.325, 3.765], "ううん、気にかけてくれてありがとう。": [59.49, 3.0], "小学生ではあるまいし、自分の部屋ぐらい自分で片付けなさい。": [62.89, 5.155], "永遠の別れじゃあるまいし、そんなに泣かないでよ。": [68.445, 3.96], "一生会えないわけではあるまいし、また来年会いましょう。": [72.805, 4.185], "初めての海外旅行じゃあるまいし、いちいち心配しなくても大丈夫だよ。": [77.39, 5.675], "子どもじゃあるまいし、一人で病院くらい行けるよ。": [83.465, 3.815], "急いでいるわけではないから、ゆっくりでいいですよ。": [87.68, 3.91], "いちいち": [91.99, 1.155], "何かと": [93.545, 1.275], "やたらに": [95.22, 1.035], "さながら": [96.655, 1.275], "恰も": [98.33, 1.26], "それとなく": [99.99, 1.4], "却って": [101.79, 1.155], "銘々": [103.345, 1.16]}, "d047": {"祖父母は結婚して六十年になる。二人の会話は驚くほど少ないが、祖母が台所に立つと、祖父は言われずとも黙々と皿を並べ始める。祖父が新聞から顔を上げてふと窓の外を見れば、祖母はさりげなく上着を差し出す。散歩に出かける合図なのだという。言葉にせずとも通じ合える関係は、長い年月の積み重ねがあってこそだろう。一方、私たちは何でもメッセージで伝え合い、相手の気持ちを確かめないと不安になる。もちろん、若い私たちに同じことができるはずもない。ただ、言葉の量ではなく、相手を見つめる時間の長さが信頼を育てるのだと、二人の姿は静かに教えてくれている。": [0.0, 47.36], "例の報告書だけど、急がずとも今週中に出してくれればいいよ。": [47.76, 5.26], "ありがとうございます。でも、明日には出せると思います。": [53.42, 4.795], "助かるよ。それから、先方にはじかに説明してもらえるかな。": [58.615, 5.485], "承知しました。午後に電話してみます。": [64.5, 3.315], "言わずとも、彼の気持ちはよくわかっている。": [68.215, 3.64], "そんなに急がずとも、電車にはまだ間に合う。": [72.255, 3.645], "辞書を引かずとも、文脈から意味はおおよそ推測できる。": [76.3, 4.55], "高い教材を買わずとも、ネットのニュースで十分に読解の練習ができる。": [81.25, 5.775], "わざわざ来ずとも、電話で済む話だ。": [87.425, 3.475], "明日は来なくてもいいですよ。": [91.3, 2.24], "黙々と": [93.94, 1.39], "淡々と": [95.73, 1.18], "直に": [97.31, 1.095], "ずばり": [98.805, 1.045], "ふと": [100.25, 0.965], "何気なく": [101.615, 1.315], "さりげなく": [103.33, 1.3], "しんみり": [105.03, 1.205]}, "d048": {"冬になると、我が家ではこたつを出す。これが厄介だ。いったん足を入れたが最後、二度と出たくなくなる。テレビを見ながらみかんを食べているうちに、ついついうたた寝をしてしまう。気がつけば夕方で、片付けるつもりだった書類は手つかずのままだ。スマートフォンのゲームも同じで、寝る前に少しだけと始めたら最後、延々とやめられない。人間は、楽なほうへとずるずる流されていく生き物なのだろう。だからこそ、私は最近、こたつのそばにスマートフォンを置かないことにした。誘惑そのものを遠ざけるのが、意志の弱い私にできる精一杯の工夫である。": [0.0, 42.84], "部長に資料のミスのこと、もう話した？": [43.24, 3.475], "まだ。あの人、一度怒らせたら最後、一週間は口をきいてくれないからさ。": [47.115, 6.855], "でも黙っていたら、あとでもっと大変なことになるよ。": [54.37, 4.21], "そうだよね…。いよいよ覚悟を決めて話してくるよ。": [58.98, 4.045], "この森は、一度迷い込んだが最後、二度と出られないと言われている。": [63.425, 5.55], "彼は話し始めたら最後、一時間は止まらない。": [69.375, 4.21], "この秘密を知られたが最後、私たちの計画はすべて台無しになる。": [73.985, 5.725], "動画サイトを開いたら最後、ついつい明け方まで見続けてしまう。": [80.11, 5.31], "妹は漫画を読み始めたが最後、呼んでも返事をしない。": [85.82, 4.81], "外に出たとたん、急に雨が降り出した。": [91.03, 3.47], "一旦": [94.9, 1.03], "延々と": [96.33, 1.095], "ついつい": [97.825, 1.19], "二度と": [99.415, 1.09], "愈々": [100.905, 1.155], "ずるずる": [102.46, 1.16], "片時も": [104.02, 1.35], "止め処なく": [105.77, 1.305]}, "d050": {"隣接する二つの町の合併協議が、目下、大詰めを迎えている。人口減少が進む中、行政の効率化を目指すA町に対し、B町は町名が消えることを理由に、頑として合併に反対してきた。ところが今月に入り、B町の町長は記者会見で「新しい市の名称に地域の歴史が反映されるのであれば、協議に応じないものでもない」と述べ、これまでの姿勢から一転して柔軟な態度を示した。ただし、住民の間では依然として慎重論も根強く、おいそれと合意に至るとは考えにくい。当面は、新市の名称案をめぐる議論が焦点となりそうだ。": [0.0, 45.555], "週末の引っ越し、手伝ってくれない？": [45.955, 3.47], "えー、週末は予定があるんだけど…。": [49.825, 3.32], "お昼ごちそうするからさ。": [53.545, 2.075], "まあ、半日だけなら手伝わないものでもないけど。": [56.02, 4.145], "助かる！ありがとう。": [60.565, 2.185], "今から急げば、最終電車に間に合わないものでもない。": [63.15, 4.51], "頼み方次第では、引き受けないものでもない。": [68.06, 3.755], "多少高くても、品質がよければ買わないものでもない。": [72.215, 4.45], "締め切りを一週間延ばしてもらえるなら、その仕事を引き受けないものでもない。": [77.065, 5.66], "説得の仕方によっては、彼も参加しないものでもない。": [83.125, 4.68], "辛い料理も食べないこともないが、あまり好きではない。": [88.205, 4.205], "目下": [92.81, 1.085], "当面": [94.295, 1.04], "一転して": [95.735, 1.185], "おいそれと": [97.32, 1.3], "早々に": [99.02, 1.21], "断固として": [100.63, 1.315], "頑として": [102.345, 1.3], "頑なに": [104.045, 1.205]}, "d051": {"大手食品メーカーが、商品の産地を長年にわたって偽って表示していたことが明らかになった。同社は記者会見で謝罪し、該当商品を速やかに回収すると発表した。しかし、問題は一部の社員による不正にとどまらず、品質管理の担当部署も事実上これを黙認していた疑いがある。消費者の信頼を裏切った以上、謝罪だけではすまないだろう。経営陣も責任を問われずにはすまない状況だ。行政も調査に乗り出しており、厳正な処分が下される見通しだ。同社には、第三者委員会による徹底的な調査と、再発を未然に防ぐ仕組みづくりが求められる。": [0.0, 44.54], "昨日、会社の車をぶつけちゃったんだ。": [44.94, 3.5], "ええっ、けがはなかった？": [48.84, 2.145], "うん、私は大丈夫。でも相手の車にも傷をつけちゃったから、上司に報告せずにはすまないよね。": [51.385, 8.395], "そうだね。正直に話したほうがいいよ。改めて相手の方に謝りに行くことになるかもしれないけど。": [60.18, 8.185], "大事な書類をなくしたのだから、課長に報告せずにはすまない。": [68.765, 5.045], "これだけ大きな事故を起こしたら、謝罪だけではすまないだろう。": [74.21, 4.825], "恩師の退職祝いの会となれば、出席せずにはすまない。": [79.435, 4.765], "約束の期限を守れなかったのだから、改めて先方に直接お詫びに行かずにはすまない。": [84.6, 7.045], "迷惑をかけた以上、直接謝りに行かずにはすまない。": [92.045, 4.81], "あの映画のラストシーンは、何度見ても泣かずにはいられない。": [97.255, 4.545], "速やかに": [102.2, 1.255], "厳正に": [103.855, 1.08], "全面的に": [105.335, 1.435], "徹底的に": [107.17, 1.37], "事実上": [108.94, 1.265], "公然と": [110.605, 1.195], "改めて": [112.2, 1.325], "未然に": [113.925, 1.02]}, "d052": {"戦時中に離ればなれになった姉妹の半生を描いた映画『遠い灯』が公開された。原作は、妹が晩年に書き残した手記である。監督は、二人が実際に交わした手紙をもとに、当時の暮らしを克明に再現した。中でも、病に倒れた姉が妹に宛てて書いた最後の手紙の場面では、家族を思う気持ちが切々とつづられ、観客は涙を禁じ得ないだろう。派手な戦闘場面はほとんどないが、そのぶん、何気ない日常を奪われていく恐ろしさがひしひしと伝わってくる。戦争を知らない世代にこそ、ぜひ見てほしい一作だ。": [0.0, 42.105], "今回の地震で被害を受けた方々について、一言お願いします。": [42.505, 5.525], "被災された皆様に、心からお見舞い申し上げます。報道を見て、同情を禁じ得ませんでした。": [48.43, 8.035], "早速、支援活動も始められたそうですね。": [56.865, 4.155], "ええ、少しでもお役に立てればと思いまして。": [61.42, 3.99], "被害者の証言を聞き、加害者への怒りを禁じ得なかった。": [65.81, 4.695], "長年の努力が報われた彼女の姿に、感動を禁じ得なかった。": [70.905, 5.37], "突然の方針転換には、戸惑いを禁じ得ない。": [76.675, 4.125], "被災地で懸命に働くボランティアの姿から、助け合いの大切さがひしひしと伝わり、感動を禁じ得なかった。": [81.2, 8.88], "彼の無責任な発言には、憤りを禁じ得ない。": [90.48, 4.235], "あまりにおかしくて、笑わずにはいられなかった。": [95.115, 3.74], "克明に": [99.255, 1.165], "赤裸々に": [100.82, 1.215], "ひしひしと": [102.435, 1.225], "切々と": [104.06, 1.335], "思わず": [105.795, 1.03], "深々と": [107.225, 1.265], "ありありと": [108.89, 1.135], "まざまざと": [110.425, 1.255]}, "d053": {"大型の台風十五号の接近に伴い、関東地方の鉄道各社は昨日、計画運休を実施した。首都圏の在来線は午後から軒並み運転を見合わせ、多くの通勤客が早めの帰宅を余儀なくされた。羽田空港を発着する国内線も相次いで欠航し、約三万人に影響が出た。また、都内で予定されていたイベントやコンサートも急遽中止が決まり、主催者側は払い戻しの対応に追われている。各社は今朝から、点検を終えた路線から順次運転を再開しているが、一部の区間では倒木の影響で終日運休となる見込みだ。": [0.0, 41.88], "駅前のパン屋さん、閉店しちゃったんだって。": [42.28, 3.6], "え、あの人気の店が？": [46.28, 2.355], "小麦の値段が大幅に上がって、閉店を余儀なくされたらしいよ。": [49.035, 5.03], "残念だなあ。あそこのクロワッサン、好きだったのに。": [54.465, 4.36], "資金不足のため、研究は中断を余儀なくされた。": [59.225, 4.45], "主力選手のけがは、チームに戦術の変更を余儀なくさせた。": [64.075, 5.155], "大雪の影響で、多くの住民が数日間の避難生活を余儀なくされた。": [69.63, 6.16], "飛行機の欠航により、私たちは旅行の日程変更を余儀なくされ、急遽ホテルを取り直した。": [76.19, 7.725], "業績の悪化により、工場は閉鎖を余儀なくされた。": [84.315, 4.39], "熱があるので、今日の練習は休まざるを得ない。": [89.105, 3.975], "急遽": [93.48, 1.115], "軒並み": [94.995, 1.19], "相次いで": [96.585, 1.13], "大幅に": [98.115, 1.1], "順次": [99.615, 1.04], "一時": [101.055, 1.065], "終日": [102.52, 1.225], "やむなく": [104.145, 1.225]}, "d054": {"人事部よりお知らせ\n当社ではこれまで、全社員の出社を前提に勤務制度を設計してきました。しかし、昨年から試験的に導入した在宅勤務では、業務効率が必ずしも低下しないことが確認されました。そこで来年四月より勤務制度を抜本的に見直し、職種に応じて出社と在宅勤務を柔軟に組み合わせられる制度へ移行します。ただし、顧客対応を伴う部署については、当分の間、原則として出社とします。新制度は段階的に導入する予定で、詳細は各部署の説明会でお伝えします。引き続き、ご理解とご協力をお願いいたします。": [0.0, 44.99], "例の新しいプロジェクト、もう始まるんですか。": [45.39, 3.885], "いや、まだだよ。来年度の予算が承認されることを前提に、準備だけ進めておいてくれ。": [49.675, 7.645], "わかりました。承認されなかった場合はどうしますか。": [57.72, 4.265], "そのときは規模を縮小して、試験的に始めるつもりだ。": [62.385, 4.84], "二人は結婚を前提に付き合っている。": [67.625, 3.005], "この計画は、国から補助金を受けることを前提としている。": [71.03, 4.905], "返却を前提とした貸し出しなので、汚さないように使ってください。": [76.335, 5.615], "来年日本で働くことを前提に、今から敬語を段階的に勉強している。": [82.35, 6.13], "全員参加を前提に、会場を予約した。": [88.88, 3.755], "この映画は、実際の事件をもとに作られた。": [93.035, 3.885], "原則として": [97.32, 1.41], "必ずしも": [99.13, 1.515], "抜本的に": [101.045, 1.42], "柔軟に": [102.865, 1.085], "試験的に": [104.35, 1.375], "当分": [106.125, 1.035], "段階的に": [107.56, 1.415], "引き続き": [109.375, 1.36]}, "d055": {"世界遺産に登録された山あいの集落で、観光客のマナー違反が問題となっている。住民の生活の場であるにもかかわらず、民家の敷地に無断で入り込んだり、庭先で平然と写真を撮ったりする人が後を絶たない。集落では立ち入り禁止の看板を設置したが、住民の困惑をよそに、週末になると観光バスがひっきりなしに訪れる。ある住民は「洗濯物を干すのもためらう」とため息をつく。村は今年度から入村料の導入を検討しているが、観光業者からは客足が遠のくとの反発もあり、議論はいまなお続いている。": [0.0, 42.06], "弟さん、大学受験はどうするって？": [42.46, 3.41], "それがね、親の心配をよそに、毎日ゲームばかりしてるんだ。": [46.27, 5.295], "相変わらずなんだね。": [51.965, 1.725], "本人は「本番に強いタイプだから大丈夫」って、平然としてるよ。": [54.09, 6.27], "周囲の反対をよそに、彼女は会社を辞めて世界一周の旅に出た。": [60.76, 5.6], "住民の不安をよそに、工事は予定どおり進められた。": [66.76, 4.46], "子どもたちは大人の心配をよそに、雪の中ではしゃいでいた。": [71.62, 4.94], "周囲の冷ややかな視線をよそに、彼は会議で堂々と自分の意見を述べた。": [76.96, 5.895], "家族の心配をよそに、彼は危険な冒険に出かけた。": [83.255, 4.675], "彼は足のけがをものともせず、最後まで走り抜いた。": [88.33, 4.54], "平然と": [93.27, 1.315], "堂々と": [94.985, 1.125], "次々と": [96.51, 1.29], "相変わらず": [98.2, 1.215], "ひっきりなしに": [99.815, 1.535], "今なお": [101.75, 1.105], "無断で": [103.255, 1.06], "とうとう": [104.715, 1.165]}, "d057": {"昨日行われた全国車いすマラソン大会で、初出場の高橋選手（二十四歳）が見事に優勝を果たした。高橋選手は三年前の交通事故で両足の自由を失ったが、絶望することなく、事故の半年後には競技用車いすでの練習を始めた。この日は朝から冷たい雨が降り続き、路面も滑りやすいという悪条件だったが、高橋選手は悪天候をものともせず、序盤から果敢に先頭集団に食らいついた。三十キロ地点でついにトップに立つと、粘り強く差を広げ、そのままゴールした。レース後、「支えてくれた家族に恩返しができた」と目に涙を浮かべた。": [0.0, 46.185], "昨日のニュース見た？八十歳の男性がエベレストに登ったんだって。": [46.585, 5.25], "見た見た。年齢をものともせず挑戦するなんて、すごいよね。": [52.235, 5.3], "何年もかけて、着実に体力をつけてきたらしいよ。": [57.935, 4.66], "私も見習わなきゃ。最近、階段だけで息が切れるもん。": [62.995, 5.165], "彼女は周囲の批判をものともせず、自分の信念を貫いた。": [68.56, 5.055], "救助隊は激しい吹雪をものともせずに、山小屋へ向かった。": [74.015, 4.87], "若い起業家は資金難をものともせず、事業を軌道に乗せた。": [79.285, 4.925], "母は病気をものともせず、毎朝笑顔で店を開け、懸命に私たちを育ててくれた。": [84.61, 7.255], "消防士は猛火をものともせず、子どもを救い出した。": [92.265, 4.375], "雨にもめげず、多くの人が集まった。": [97.04, 3.465], "果敢に": [100.905, 1.07], "見事に": [102.375, 1.055], "懸命に": [103.83, 1.115], "着実に": [105.345, 1.25], "粘り強く": [106.995, 1.43], "一心に": [108.825, 1.145], "敢然と": [110.37, 1.33], "遂に": [112.1, 1.045]}, "d058": {"若者の投票率の低さは、かねてから指摘されてきた課題である。各自治体は期日前投票所を大学に設けるなど工夫を重ねてきたにもかかわらず、前回の選挙でも二十代の投票率は三割台にとどまった。若者は政治に無関心だと言われることが多いが、調査によれば、社会問題への関心は概して高い。むしろ問題は、自分の一票で何かが変わるという実感を持てない点にある。選挙の争点が往々にして高齢者向けの政策に偏りがちなことも、その一因だろう。政治の側が若者の声にあまねく耳を傾けない限り、この状況は一段と深刻になりかねない。": [0.0, 45.13], "昨日の説明会、すごく人が多かったね。": [45.53, 3.97], "うん。平日の夜にもかかわらず、三百人以上来てたらしいよ。": [49.9, 5.555], "新しい制度への関心って、案外高いんだね。": [55.855, 4.17], "そうみたい。質問も前回より一段と多かったし。": [60.425, 4.49], "再三注意したにもかかわらず、彼は同じミスを繰り返した。": [65.315, 4.935], "悪天候にもかかわらず、大会は予定どおり開催された。": [70.65, 4.77], "彼は無実であるにもかかわらず、長い間疑いの目で見られた。": [75.82, 5.05], "十分に準備したにもかかわらず、本番では一段と緊張してしまい、実力を出し切れなかった。": [81.27, 7.63], "熱があるにもかかわらず、彼は出勤した。": [89.3, 3.725], "経験の有無にかかわらず、どなたでも応募できます。": [93.425, 4.145], "一段と": [97.97, 1.295], "殊の外": [99.665, 1.475], "案外": [101.54, 1.065], "往々にして": [103.005, 1.295], "概して": [104.7, 1.155], "存外": [106.255, 1.135], "心なしか": [107.79, 1.39], "遍く": [109.58, 1.195]}, "d059": {"市民講座「やさしい陶芸教室」受講者募集のご案内\n本講座は、陶芸経験のいかんを問わず、どなたでもご参加いただけます。全六回の講座で、器づくりの基本から焼き上げまでを体験していただきます。受講料は六回分を一括してお支払いください。なお、材料費として別途二千円を申し受けます。お申し込み後の受講料は、理由のいかんによらず返金いたしかねますので、あらかじめご了承ください。作業中は汚れてもよい服装でお越しいただき、エプロンは各自ご持参ください。ご不明な点がございましたら、何なりと事務局までお問い合わせください。": [0.0, 43.715], "すみません、このツアー、雨の場合はどうなりますか。": [44.115, 4.595], "こちらは天候のいかんにかかわらず、予定どおり実施いたします。": [49.11, 5.005], "そうなんですね。キャンセルはできますか。": [54.515, 3.285], "三日前までにご連絡いただければ、全額返金いたします。それ以降は、理由のいかんを問わず、返金いたしかねます。": [58.2, 9.79], "国籍のいかんを問わず、優秀な人材を採用する。": [68.39, 4.505], "試験の結果のいかんによらず、全員に修了証を発行します。": [73.295, 5.13], "事情のいかんにかかわらず、無断欠席は認めない。": [78.825, 4.345], "年齢や経験のいかんを問わず、意欲のある方を歓迎いたします。参加を希望される方は、事前にお申し込みください。": [83.57, 9.595], "理由のいかんを問わず、遅刻は減点とする。": [93.565, 3.825], "検査の結果いかんによっては、手術が必要になる。": [97.79, 4.35], "別途": [102.54, 1.035], "事前に": [103.975, 1.05], "適宜": [105.425, 1.095], "一括して": [106.92, 1.315], "何なりと": [108.635, 1.165], "前もって": [110.2, 1.26], "然るべく": [111.86, 1.27], "随意に": [113.53, 1.0]}, "d061": {"情報があふれる現代において、信頼に足る情報源を見極める力は、もはや一部の専門家だけのものではない。検索すれば数秒で答えらしきものが見つかるが、その多くは出典が曖昧で、根拠に乏しい。では、何をもって信頼に足ると判断すればよいのか。第一に、誰がどのような立場で書いたのかが明示されていること。第二に、主張を裏付けるデータが示され、第三者が検証できること。そして第三に、誤りが判明した際に訂正する仕組みがあることだ。こうした条件を満たす情報を綿密に選び取る姿勢こそ、健全な判断の土台となる。手間を惜しまず確かめる習慣が、結局は自分自身を守るのである。": [0.0, 49.105], "この調査報告、レポートに引用しても大丈夫かな。": [49.505, 4.57], "出典が国の統計だから、信頼に足る資料だと思うよ。": [54.475, 4.92], "でも、この部分の数字、ちょっと根拠が乏しくない？": [59.795, 4.69], "確かに。そこは別の資料で綿密に確かめたほうが妥当だね。": [64.885, 5.33], "彼女は、部下が信頼するに足るリーダーだ。": [70.615, 3.675], "その程度の失敗は、取るに足りないことだ。": [74.69, 3.725], "今回の実験結果だけでは、仮説を証明するに足る根拠とは言えない。": [78.815, 5.835], "私は、出典が明示され、データが綿密に示されている記事を信頼に足る情報だと考えている。逆に、根拠が曖昧なまま断定する記事は、どれほど話題になっていても鵜呑みにしないようにしている。": [85.05, 15.7], "これは十分に信頼するに足るデータだ。": [101.15, 3.135], "彼の粘り強い努力は称賛に値する。": [104.685, 3.385], "妥当": [108.47, 1.075], "綿密": [109.945, 1.155], "堅実": [111.5, 1.18], "健全": [113.08, 1.1], "乏しい": [114.58, 1.175], "曖昧": [116.155, 1.09], "著しい": [117.645, 1.41], "煩わしい": [119.455, 1.4]}, "d062": {"先日、市民劇団の定期公演を観た。正直なところ、アマチュアの舞台だからと期待はしていなかった。ところが幕が上がると、その思い込みはすぐに覆された。脚本は簡素ながら巧妙に組み立てられ、役者たちの演技にもぎこちなさがほとんどない。十分に鑑賞にたえる作品だったと言ってよい。一方、近ごろのテレビには、出演者をからかって笑いを取るだけの、見るにたえない番組も少なくない。予算や知名度が作品の質を決めるわけではないことを、この小さな舞台は改めて教えてくれた。終演後、劇団の代表は「足を運んでくださった皆様には感謝にたえません」と、何度も頭を下げていた。": [0.0, 48.32], "昨日の新人の発表、どうだった？": [48.72, 3.26], "資料は稚拙だったけど、内容は十分聞くにたえるものだったよ。": [52.38, 5.105], "へえ、それはよかった。前回はひどかったからね。": [57.885, 4.525], "うん、前回のは正直、聞くにたえなかった。今回はずいぶん準備したんだと思う。": [62.81, 6.84], "この論文は、専門家の厳しい批判にもたえる内容だ。": [70.05, 4.78], "事故現場は、見るにたえない惨状だった。": [75.23, 3.455], "皆様の温かいご支援には、感謝にたえません。": [79.085, 4.125], "先週読んだ小説は、筋書きこそ素朴だが、何度読み返しても鑑賞にたえる作品だった。登場人物の心理描写が巧妙で、最後まで飽きることがなかった。": [83.61, 12.995], "彼の言い訳は、聞くにたえないものだった。": [97.005, 3.425], "歯の痛みに耐えられず、夜中に救急病院へ行った。": [100.83, 4.175], "巧妙": [105.405, 1.185], "簡素": [106.99, 1.12], "ぎこちない": [108.51, 1.22], "稚拙": [110.13, 1.12], "見苦しい": [111.65, 1.285], "痛ましい": [113.335, 1.29], "素朴": [115.025, 1.175], "斬新": [116.6, 1.075]}, "d064": {"人口わずか三千人の町の図書館が、全国から注目を集めている。「人を貸し出す図書館」という試みが始まったのは五年前のことだ。利用者は本の代わりに地域の住民を「借りて」、三十分間、その人の経験に耳を傾ける。元漁師、パン職人、海外で長く暮らした主婦など、「本」となる住民の顔ぶれは多彩だ。当初は「図書館がやるべきことなのか」と疑問視する声もあったが、参加者の満足度は高く、世代を超えた交流が生まれたという。予算も人員も限られる中で、住民の知恵を資源に変えたこの取り組みは、大いに評価に値するだろう。他の自治体にとっても、一考に値する事例である。": [0.0, 50.195], "部長、新人の提案書、お読みになりましたか。": [50.595, 4.54], "ああ。荒削りだが、検討に値する内容だと思ったよ。": [55.535, 5.125], "発想が独創的ですよね。来月の会議で取り上げましょうか。": [61.06, 5.145], "そうしよう。有望な人材は早めに育てないとな。": [66.605, 4.44], "この本は、一度は読むに値する名著だ。": [71.445, 3.74], "彼女の地道な努力は、称賛に値する。": [75.585, 4.01], "根拠のない噂など、議論に値しない。": [79.995, 3.535], "近所の高校生たちが続けている清掃活動は、注目に値すると思う。毎週日曜の朝、誰に頼まれたわけでもなく公園を掃除する姿は、地道ながら有意義な取り組みだ。": [83.93, 14.63], "この企画は、十分に検討に値する。": [98.96, 3.72], "早起きして山に登った甲斐があって、見事な日の出が見られた。": [103.08, 4.87], "有意義": [108.35, 1.11], "有望": [109.86, 1.175], "画期的": [111.435, 1.32], "多彩": [113.155, 1.065], "有益": [114.62, 1.155], "地道": [116.175, 1.11], "意欲的": [117.685, 1.215], "独創的": [119.3, 1.3]}, "d065": {"（会社員・四十二歳）毎朝の通勤で、駅のホームを歩きながらスマートフォンの画面を見つめる人の多さに驚かされる。混雑したホームで前を見ずに歩くのは、危険極まりない行為だ。先日も、私の目の前で若い男性が白杖を持った方にぶつかり、謝りもせずに立ち去った。その態度は無礼極まるもので、見ていて情けなくなった。もちろん、急いでいる事情もあるだろう。しかし、ほんの数秒画面から目を離すことが、それほど面倒だろうか。鉄道会社による呼びかけも大切だが、結局は一人一人の意識にかかっている。自分だけは大丈夫だという思い込みこそ、事故の元なのだと思う。": [0.0, 47.28], "さっきの店員の態度、見た？": [47.68, 2.805], "うん、お客さんに向かってあの言い方はないよね。失礼極まりないよ。": [50.885, 5.695], "横柄っていうか、露骨に面倒くさそうだったし。": [56.98, 4.045], "本社のサイトから意見を送ってみようか。": [61.425, 3.26], "雪道をノーマルタイヤで走るなど、危険極まりない。": [65.085, 4.345], "約束に一時間も遅れて謝罪もないとは、無礼極まる。": [69.83, 4.765], "優勝が決まった瞬間、監督は感極まって涙を流した。": [74.995, 5.045], "夜道を無灯火で走る自転車は、危険極まりない。先日もぶつかりそうになったが、相手は謝るどころか冷淡な目でこちらをにらんで去っていった。": [80.44, 11.385], "彼の運転は乱暴極まりない。": [92.225, 2.64], "露天風呂付きの部屋で過ごす休日は、贅沢の極みだ。": [95.265, 4.615], "軽率": [100.28, 1.215], "無謀": [101.895, 1.07], "迂闊": [103.365, 1.105], "露骨": [104.87, 1.135], "横柄": [106.405, 1.115], "傲慢": [107.92, 1.055], "冷淡": [109.375, 1.065], "図々しい": [110.84, 1.385]}, "d066": {"本日は、このような栄誉ある賞をいただき、光栄の至りに存じます。四十年前、私が故郷の町で小さな陶芸工房を開いたとき、周囲からは「そんな無茶なことはやめておけ」と言われたものです。今振り返れば、勢いだけで飛び込んだのは若気の至りでした。それでも、素朴な土の器を愛してくださる方々に支えられ、なんとか今日まで続けることができました。決して私一人の力ではございません。本日ご列席の皆様、そして工房を手伝ってくれた弟子たちに、心より御礼申し上げます。お忙しい中、遠方からお越しくださった方も多く、恐縮の至りでございます。これからも初心を忘れず、土と向き合ってまいります。": [0.0, 51.75], "それでは、受賞者の山田様より一言お願いいたします。": [52.15, 4.77], "このような名誉ある賞をいただき、感激の至りです。": [57.32, 4.32], "若いころの数々の失敗も、今思えば若気の至りでした。": [62.04, 5.08], "輝かしいご経歴の裏に、そんなご苦労があったのですね。": [67.52, 4.875], "憧れの先生に作品を褒めていただき、感激の至りです。": [72.795, 5.065], "このような立派な席にお招きいただき、恐縮の至りでございます。": [78.26, 5.345], "学生時代に徹夜で騒いだのも、今となっては若気の至りだ。": [84.005, 5.185], "本日はこのような名誉ある賞をいただき、光栄の至りです。支えてくださった皆様のおかげであり、今後も謙虚な気持ちで努力を続けてまいります。": [89.59, 11.695], "大役を任せていただき、光栄の至りです。": [101.685, 3.84], "決勝で逆転負けしたことは、痛恨の極みだ。": [105.925, 4.245], "謙虚": [110.57, 1.145], "寛大": [112.115, 1.13], "誠実": [113.645, 1.23], "律儀": [115.275, 1.085], "厳か": [116.76, 1.31], "華々しい": [118.47, 1.44], "輝かしい": [120.31, 1.5], "名高い": [122.21, 1.185]}, "d067": {"仕事に追われる日々が続き、心身ともに疲労の極みに達していた私は、思い切って山あいの小さな旅館に二泊することにした。客室はわずか五つ。豪華な設備があるわけではないが、障子越しの柔らかな光、湯気の立つ檜の風呂、地元の野菜を使った質素な料理と、何もかもが穏やかで心地よい。何より印象に残ったのは、仲居さんの細やかな気配りである。こちらが頼む前に、さりげなく温かいお茶が用意されている。何もせずに川の音を聞いているだけの時間は、まさに贅沢の極みだった。帰りの電車の中で、本当の豊かさとは何かを考えずにはいられなかった。": [0.0, 46.305], "週末、温泉に行ってきたんだって？": [46.705, 3.315], "うん。部屋に露天風呂がついてて、まさに贅沢の極みだったよ。": [50.42, 5.355], "いいなあ。私なんて残業続きで、疲労の極みだよ。": [56.175, 4.97], "じゃあ、次の連休は閑静な宿でのんびりしてきたら？": [61.545, 4.49], "一流の職人が仕立てた着物は、まさに美の極みと言える。": [66.435, 4.785], "三日間ほとんど眠れず、疲労の極みに達していた。": [71.62, 4.235], "このような事故を起こしたことは、痛恨の極みです。": [76.255, 4.16], "仕事が一段落した週末、閑静な公園のベンチで好きな本を読んで過ごした。誰にも邪魔されないその時間は、私にとって贅沢の極みだった。": [80.815, 11.735], "一日中何もせず海を眺めるなんて、贅沢の極みだ。": [92.95, 4.895], "皆さんにお祝いしていただき、この上ない喜びです。": [98.245, 4.155], "豪華": [102.8, 1.125], "質素": [104.325, 1.175], "贅沢": [105.9, 1.22], "閑静": [107.52, 1.19], "殺風景": [109.11, 1.52], "穏やか": [111.03, 1.245], "細やか": [112.675, 1.295], "清々しい": [114.37, 1.525]}, "d068": {"まさか自分が五十を過ぎてから大学生になるとは、数年前には想像もしなかった。きっかけは、娘の何気ない一言だった。「お母さん、昔は歴史の先生になりたかったんでしょう」。子育てと仕事に追われるうちに、そんな夢があったことさえ忘れていた。入学してみると、教室の学生は娘と同じ年頃ばかりで、最初は気まずくて仕方がなかった。ところが、彼らは驚くほど気さくに話しかけてくれる。年齢の差を気にしていたのは私だけだったとは。レポートの締め切りに追われる日々は決して楽ではないが、学ぶことがこれほど楽しいとは、若いころには気づかなかった。": [0.0, 44.71], "聞いた？田中さん、来月で会社を辞めるらしいよ。": [45.11, 4.56], "え、本当？あんなに仕事一途だった人が辞めるとは。": [50.07, 4.92], "実家のパン屋を継ぐんだって。": [55.39, 2.265], "そうなんだ。無口だけど朗らかな人だから、お店でも人気が出そうだね。": [58.055, 6.05], "あの慎重な彼が、こんな初歩的なミスをするとは。": [64.505, 4.4], "たった一年で、町の景色がこれほど変わるとは思わなかった。": [69.305, 5.025], "子どもにまで嘘をつくとは、あきれて物も言えない。": [74.73, 4.02], "まさか、いつも無口な課長がカラオケであんなに陽気に歌うとは思わなかった。意外な一面を知って、少し親しみがわいた。": [79.15, 9.885], "彼がこの難関試験に一度で合格するとは。": [89.435, 3.735], "こんな簡単な問題を間違えるなんて、信じられない。": [93.57, 4.43], "気さく": [98.4, 1.1], "陽気": [99.9, 1.07], "陰気": [101.37, 1.01], "無口": [102.78, 1.08], "朗らか": [104.26, 1.28], "気まずい": [105.94, 1.165], "照れくさい": [107.505, 1.27], "一途": [109.175, 1.07]}, "d069": {"うちの猫ときたら、とにかく気まぐれで手に負えない。朝五時になると枕元で鳴き続け、ご飯を出すまで私を寝かせてくれない。それなのに、こちらが撫でようとすると、そっけなく顔を背けてどこかへ行ってしまう。高価なおもちゃを買ってきても見向きもせず、届いた段ボール箱のほうに夢中になる。家族に愚痴をこぼすと、「あなたこそ、猫のことになると甘すぎる」と笑われた。確かにそうかもしれない。仕事で疲れて帰った夜、何も言わずに膝の上で丸くなるあの温かさに、何度救われたことか。わがままで厄介な同居人だが、もう彼のいない暮らしは考えられない。": [0.0, 44.615], "うちの息子ときたら、休みの日はゲームばかりなんですよ。": [45.015, 4.58], "うちも同じです。外に出るのが億劫みたいで。": [49.995, 4.0], "宿題もなかなかやらないし、困ったものです。": [54.395, 3.875], "まあ、そういう年頃なんでしょうね。": [58.67, 3.025], "うちの夫ときたら、脱いだ服を床に置きっぱなしにする。": [62.095, 4.535], "このパソコンときたら、肝心なときに限って動かなくなる。": [67.03, 4.705], "最近の天気ときたら、晴れたかと思えば急に大雨が降る。": [72.135, 4.86], "うちの弟ときたら、気まぐれで約束をすぐに忘れる。昨日も一緒に買い物に行くはずだったのに、出かけるのが億劫だと言って寝ていた。": [77.395, 10.355], "隣の犬ときたら、夜中でもかまわず吠える。": [88.15, 3.85], "山頂から見た朝日の美しさといったらなかった。": [92.4, 3.995], "気まぐれ": [96.795, 1.205], "そっけない": [98.4, 1.33], "厄介": [100.13, 1.145], "億劫": [101.675, 1.105], "窮屈": [103.18, 1.175], "健気": [104.755, 1.11], "図太い": [106.265, 1.185], "愛おしい": [107.85, 1.235]}, "d071": {"部活動の指導者による暴言や体罰が、また明るみに出た。勝つためには厳格な指導も必要だという考え方は、今なお根強い。しかし、指導者たるもの、選手の心身の健康を何よりも優先しなければならない。恐怖で選手を支配するやり方は、一時的に成果を上げたとしても、競技を楽しむ心を奪い、才能の芽を摘んでしまう。一方で、指導者を一方的に責めるだけでは問題は解決しない。勝利を最優先する保護者や学校の姿勢、指導者自身が学び直す機会の不足など、背景には根深い構造がある。教育に携わる者たるもの、子どもを一人の人間として尊重する姿勢を忘れてはならない。社会全体で指導のあり方を見直すべき時である。": [0.0, 53.65], "先生、明日の試合、僕はベンチなんですか。": [54.05, 4.445], "ああ。最近、練習に遅刻することが多かっただろう。": [58.895, 4.85], "すみません。でも、キャプテンの僕が出ないのは……。": [64.145, 4.165], "キャプテンたるもの、まず自分が手本を示さなければならない。厳しいようだが、それが公正な判断だ。": [68.71, 8.2], "医師たるもの、患者の話に真摯に耳を傾けるべきだ。": [77.31, 4.82], "プロたるもの、どんな状況でも言い訳をしてはならない。": [82.53, 4.11], "一国の首相たる者は、発言の重みを自覚しなければならない。": [87.04, 5.285], "社会人たるもの、約束の時間は守らなければならない。また、自分の失敗を他人のせいにするような理不尽な態度は慎むべきだ。": [92.725, 10.7], "教師たるもの、生徒の前で人を見下すような発言をしてはならない。": [103.825, 5.43], "彼は高校の教師として二十年間働いてきた。": [109.655, 3.995], "厳格": [114.05, 1.24], "寛容": [115.69, 1.185], "根深い": [117.275, 1.195], "健やか": [118.87, 1.33], "頑な": [120.6, 1.32], "理不尽": [122.32, 1.105], "不当": [123.825, 1.075], "公正": [125.3, 1.215]}, "d072": {"深海は、宇宙よりも謎が多いと言われる。水深数千メートルの海底は太陽の光が届かず、水温は二度前後、水圧は地上の数百倍に達する。そこに生物が存在するなど、かつては誰も想像だにしなかった過酷な環境だ。ところが近年、無人探査機の発達により、多種多様な生物が暮らしていることがわかってきた。自ら光を放つ魚、熱水の噴き出す場所に群がるエビ、数百年生きるとされるサメ。その姿は奇抜で、まるで別の惑星の住人のようだ。もっとも、深海の生態系はきわめて脆弱で、海底資源の開発によって一度壊されれば、元に戻るまでに長い年月がかかる。人類の手が及ぶことで何が失われるのか、考えるだに恐ろしい。": [0.0, 54.875], "この前の地震、震源がすごく近かったんだって。": [55.275, 4.345], "もしあれが夜中だったらと思うと、考えるだに恐ろしいよ。": [60.02, 4.675], "被害が微々たるもので済んだのは、本当に運がよかったね。": [65.095, 4.635], "うん。防災グッズ、もう一度見直しておこう。": [70.13, 4.02], "戦争の悲惨さは、聞くだに胸が痛む。": [74.55, 3.595], "まさか自分が優勝するとは、想像だにしなかった。": [78.545, 4.405], "衛兵は、観光客に囲まれても微動だにしなかった。": [83.35, 4.595], "十年前の私は、自分が海外で働く日が来るとは想像だにしなかった。言葉も通じない土地で暮らすなど、当時は考えるだに恐ろしかったのだ。": [88.345, 11.775], "一人で夜の山道を歩くなんて、考えるだに恐ろしい。": [100.52, 4.65], "忙しすぎて、昼ご飯を食べる時間すらない。": [105.57, 4.03], "過酷": [110.0, 1.18], "奇抜": [111.58, 1.085], "脆弱": [113.065, 1.21], "膨大": [114.675, 1.075], "神秘的": [116.15, 1.275], "莫大": [117.825, 1.145], "微々たる": [119.37, 1.135], "希少": [120.905, 1.09]}, "d073": {"夜間中学に通う七十八歳の女性がいる。戦後の混乱期に家計を支えるため働きに出た彼女は、学校にほとんど通えず、つい数年前まで自分の名前すら満足に書けなかった。役所の窓口で書類を前にするたび、隣の人に代筆を頼む。その惨めさは言葉では言い表せないという。転機は、孫が持ち帰った夜間中学の案内だった。今では毎晩欠かさず教室に通い、ひらがなから漢字、分数の計算まで、一つひとつ学んでいる。「字が読めると、町の景色まで違って見えるんです」と、彼女は朗らかに笑う。学ぶ機会を奪われた人々が今も少なくないことを、私たちは忘れてはならない。": [0.0, 49.075], "最近忙しくて、新聞を読む時間すらないんだ。": [49.475, 4.295], "それは大変だね。でも、ニュースを知らないのは心細くない？": [54.17, 5.21], "うん。だから通勤中に、見出しだけはスマホで確認してる。": [59.78, 5.08], "見出しだけじゃ、もどかしいだろうけどね。": [65.26, 3.21], "そんな簡単なことは、小学生ですら知っている。": [68.87, 4.33], "疲れ果てて、立ち上がる気力すら残っていなかった。": [73.6, 4.25], "彼は親友にすら、病気のことを話さなかった。": [78.25, 4.105], "入社一年目は仕事に慣れるのに必死で、家族に電話する余裕すらなかった。今思えば、もっと周りに頼ればよかったと切実に感じる。": [82.755, 10.925], "当時は、電話をかけるお金すらなかった。": [94.08, 3.545], "天気さえよければ、山頂から富士山が見える。": [98.025, 3.955], "切実": [102.38, 1.3], "痛切": [104.08, 1.23], "惨め": [105.71, 1.1], "切ない": [107.21, 1.255], "もどかしい": [108.865, 1.355], "心細い": [110.62, 1.49], "心強い": [112.51, 1.445], "ひたむき": [114.355, 1.205]}, "d074": {"雪深い山あいの町・白川原で、今年も「かまくら祭り」が開かれます。町内の各所に作られた大小二百あまりのかまくらに明かりがともる光景は、雪国ならではの幻想的な美しさです。かまくらの中では、地元の方々が甘酒や焼き餅でお客様をもてなします。素朴ながらも温かいこの交流こそ、小さな町ならではの魅力と言えるでしょう。また、会場には郷土料理の屋台も並び、ここでしか味わえない山菜汁や川魚の塩焼きをお楽しみいただけます。なお、夜間は冷え込みが厳しく、気温が氷点下十度を下回ることもあります。防寒対策を万全にしてお越しください。": [0.0, 47.335], "この辺りで、何かおすすめの料理はありますか。": [47.735, 3.985], "でしたら、地元の山菜を使ったお鍋はいかがでしょう。この土地ならではの味ですよ。": [52.12, 6.715], "いいですね。寒い日に食べるお鍋は格別ですから。": [59.235, 4.32], "ありがとうございます。すぐにご用意いたします。": [63.955, 3.885], "この上品な味わいは、老舗ならではのものだ。": [68.24, 3.945], "手作りならではの温かみが、多くの客に愛されている。": [72.585, 4.615], "子どもならではの自由な発想に、大人たちは驚かされた。": [77.6, 4.83], "私の故郷は港町で、朝市には漁港ならではの新鮮な魚介が並びます。夕暮れ時、海に沈む鮮やかな夕日を眺めながら散歩するのは格別です。": [82.83, 12.76], "海辺の町ならではの新鮮な刺身を味わった。": [95.99, 3.67], "今日は春らしい暖かな一日だった。": [100.06, 3.115], "幻想的": [103.575, 1.27], "鮮やか": [105.245, 1.27], "壮大": [106.915, 1.18], "雄大": [108.495, 1.11], "のどか": [110.005, 1.055], "格別": [111.46, 1.265], "趣深い": [113.125, 1.51], "和やか": [115.035, 1.265]}, "d075": {"創業七十年を迎える町工場「森田精機」の社長が、今春で引退する。後継者に指名されたのは、入社二十年目の職人、佐藤健一さんだ。佐藤さんは百分の一ミリ単位の誤差も見逃さない緻密な腕で知られ、大手メーカーからの難しい注文も次々にこなしてきた。それでいて、職人にありがちな頑固さはなく、若手の話にも辛抱強く耳を傾ける。社長は「技術と人望を兼ね備えた人物は、彼をおいてほかにいない」と言い切る。一方、佐藤さん本人は「自分に務まるか心細い」と謙遜しつつも、「伝統を守るだけでなく、新しい分野にも挑みたい」と意欲を見せた。小さな工場の新たな挑戦が始まる。": [0.0, 53.655], "今回の海外プロジェクト、誰に任せましょうか。": [54.055, 4.17], "語学力と交渉力を考えると、鈴木さんをおいてほかにいないだろう。": [58.625, 5.445], "確かに、彼女の交渉は手堅いですからね。": [64.47, 3.84], "ああ。本人には、明日私から話してみるよ。": [68.71, 4.355], "この難しい役を演じられるのは、彼女をおいてほかにいない。": [73.465, 4.78], "町を立て直す道は、観光業の振興をおいてほかにないと考える。": [78.645, 5.635], "次の大会を開くなら、この会場をおいてほかにない。": [84.68, 4.445], "チームのリーダーを選ぶなら、山本さんをおいてほかにいない。仕事が緻密なうえに、どんな意見にも辛抱強く耳を傾けてくれるからだ。": [89.525, 10.57], "この研究を任せられるのは、田中先生をおいてほかにいない。": [100.495, 4.92], "冷蔵庫には牛乳以外に何も入っていなかった。": [105.815, 3.775], "緻密": [109.99, 1.12], "精巧": [111.51, 1.305], "精密": [113.215, 1.255], "頑固": [114.87, 1.13], "粗雑": [116.4, 1.18], "辛抱強い": [117.98, 1.545], "抜群": [119.925, 1.09], "手堅い": [121.415, 1.145]}, "d076": {"介護現場の人手不足が深刻だと言われて久しい。しかし、人が足りないのは介護業界に限ったことではない。物流、建設、飲食、さらには教育の現場でも、働き手の確保は年々難しくなっている。背景にあるのは少子高齢化による労働人口の減少だが、それだけでは説明がつかない。賃金に見合わない過重な労働や、旧態依然とした職場の慣習が、若い世代に敬遠されている面も否めないだろう。外国人労働者の受け入れや機械化も一つの手段ではある。だが、まず問われるべきは、働く人を大切にする職場をつくれるかどうかだ。待遇や働き方を見直さないかぎり、人手不足は解消されないのではないか。": [0.0, 50.395], "またうちの近くのコンビニが閉店するんだって。": [50.795, 3.725], "人手が足りないらしいね。でも、それはあの店に限ったことじゃないよ。": [54.92, 5.73], "どこも慢性的に人が足りないって聞くもんね。": [61.05, 3.535], "早急に手を打たないと、生活が不便になる一方だよ。": [64.985, 4.61], "彼が約束を破るのは、今回に限ったことではない。": [69.995, 4.61], "食品ロスの問題は、日本に限ったことではない。": [75.005, 4.36], "ネット上の誹謗中傷は有名人に限ったことではなく、誰もが被害者になり得る。": [79.765, 6.315], "若者の地方離れは、日本に限ったことではない。韓国でも地方の人口減少が顕著で、早急な対策が求められている。": [86.48, 10.455], "物価の上昇は、食料品に限ったことではない。": [97.335, 4.32], "この映画は、子どもに限らず大人も楽しめる。": [102.055, 3.995], "深刻": [106.45, 1.345], "顕著": [108.195, 1.135], "不可欠": [109.73, 1.28], "肝心": [111.41, 1.095], "肝要": [112.905, 1.185], "早急": [114.49, 1.225], "迅速": [116.115, 1.195], "慢性的": [117.71, 1.295]}, "d078": {"大手飲料メーカーの東邦飲料は、来年からすべてのペットボトルを再生素材に切り替えると発表した。同社はこれまでも容器の軽量化に取り組んできたが、今回の決定は環境保護のみならず、企業の生き残りをかけた戦略でもある。近年、環境への配慮は消費者が商品を選ぶ際の重要な基準となっており、投資家の目も厳しさを増している。再生素材は従来の素材に比べて割高で、当面は利益を圧迫するとみられる。それでも同社の社長は「目先の利益にとらわれていては、十年後の市場で選ばれない」と語る。こうした動きは、同業他社のみならず、他業種にも波及する可能性がある。": [0.0, 46.82], "この店、レジ袋をやめて紙袋にしたんだね。": [47.22, 4.245], "うん。環境のためのみならず、お店のイメージアップにもなるらしいよ。": [51.865, 5.52], "でも、紙袋って割高じゃない？": [57.785, 2.995], "そうね。だから、マイバッグを持ってくる人が増えたみたい。": [61.18, 4.865], "この病気は高齢者のみならず、若者にも広がっている。": [66.445, 4.595], "彼は優秀であるのみならず、人柄も誠実だ。": [71.44, 4.12], "その発言は国内のみならず、海外からも批判を浴びた。": [75.96, 4.84], "社内のペーパーレス化は、経費の削減のみならず、業務の効率化にもつながった。今後は持続的な取り組みとして、全部署に広げていく予定である。": [81.2, 11.85], "この制度は企業のみならず、地域社会にも利益をもたらす。": [93.45, 4.925], "彼は謝らないばかりか、逆にこちらを責めてきた。": [98.775, 4.265], "持続的": [103.44, 1.25], "割高": [105.09, 1.245], "割安": [106.735, 1.205], "抜本的": [108.34, 1.32], "画一的": [110.06, 1.365], "恒久的": [111.825, 1.335], "慎重": [113.56, 1.32], "大胆": [115.28, 1.05]}, "d079": {"手術室の扉が閉まってから、もう三時間が過ぎようとしていた。廊下の長椅子に座った陽子は、膝の上で固く手を組んだまま、壁の時計を見つめていた。医師からは、難しい手術になるとあらかじめ説明を受けている。今の自分にできることは何もない。ただ祈るのみだった。窓の外では、いつの間にか雨が上がり、雲の切れ間から淡い光が差し込んでいる。ふと、家を出るときに夫が照れくさそうに言った「退院したら、また一緒に花見に行こう」という言葉がよみがえった。そのとき、扉の上の赤いランプが静かに消えた。陽子は息を詰めて立ち上がった。": [0.0, 43.85], "試験の結果、いつ出るの？": [44.25, 2.675], "来週の月曜日。やれることは全部やったから、あとはただ結果を待つのみだよ。": [47.325, 6.58], "そっか。落ち着いてるね。": [54.305, 2.32], "いや、内心は不安で、ゆうべもよく眠れなかったんだ。": [57.025, 4.735], "準備はすべて整った。あとは実行あるのみだ。": [62.16, 4.075], "被災地の惨状を前に、私はただ立ち尽くすのみだった。": [66.635, 4.88], "合格できるかどうかは、ただ本人の努力のみにかかっている。": [71.915, 4.875], "面接の練習は十分に重ねてきた。あとは自分を信じて、ただ全力を尽くすのみだ。": [77.19, 7.27], "やるべきことはやった。あとはただ天に祈るのみだ。": [84.86, 4.045], "宿題はあと一ページだけ残っている。": [89.305, 2.975], "淡い": [92.68, 0.985], "儚い": [94.065, 1.215], "虚しい": [95.68, 1.18], "痛々しい": [97.26, 1.39], "悲痛": [99.05, 1.045], "沈痛": [100.495, 1.22], "安らか": [102.115, 1.3], "静粛": [103.815, 1.205]}, "d080": {"過疎化が進む山あいの村で、七年前に開業した農産物直売所が思わぬ成功を収めている。当初は村の高齢農家が育てた野菜を並べるだけの小さな店だった。ところが、形や大きさが不ぞろいでも新鮮で安いと評判になり、今では週末になると県外からも客が訪れる。その影響は売り上げの増加にとどまらず、村全体に広がった。直売所の隣には農家レストランが開かれ、収穫体験のツアーも始まった。都会から移住してくる若者も現れ、廃校寸前だった小学校の児童数はわずかながら増えている。「生きがいができた」と話す農家の顔は、何より晴れやかだ。": [0.0, 46.24], "駅前の商店街、最近にぎやかになったね。": [46.64, 4.105], "学生たちが始めたイベントが、一回きりにとどまらず、毎月開かれるようになったんだって。": [51.145, 7.23], "へえ。前はシャッターばかりで閑散としてたのにね。": [58.775, 4.12], "目覚ましい変化だよね。": [63.295, 1.94], "その歌手の人気は、国内にとどまらず、アジア全域に広がった。": [65.635, 5.66], "彼は問題点を指摘するにとどまらず、具体的な解決策まで示した。": [71.695, 5.99], "台風の被害は農作物にとどまらず、交通網にも及んだ。": [78.085, 4.965], "大学のサークルで始めた古着の交換会は、学内にとどまらず、地域の住民も参加するイベントになった。服を手頃に手に入れられるだけでなく、世代を超えた交流の場にもなっている。": [83.45, 14.23], "彼の活動は、音楽にとどまらず、映画や文学にまで及んでいる。": [98.08, 5.695], "彼女は英語のみならず、中国語も話せる。": [104.175, 3.875], "晴れやか": [108.45, 1.27], "不ぞろい": [110.12, 1.14], "瑞々しい": [111.66, 1.46], "手頃": [113.52, 1.06], "閑散": [114.98, 1.08], "目覚ましい": [116.46, 1.325], "好ましい": [118.185, 1.33], "無難": [119.915, 0.94]}, "d081": {"学生時代の夏、北アルプスの山小屋で一か月間アルバイトをしたことがある。標高三千メートル近いその山小屋には、テレビはおろか、携帯電話の電波すら届かなかった。電気は自家発電で、夜九時には消灯。水は雨水をためて使うため、シャワーなど望むべくもない。初めの一週間は、不便さに苛立ってばかりいた。ところが、慣れてくると、そうした暮らしが不思議と心地よくなった。夜明け前に起きて雲海を眺め、日が沈めば満天の星の下で眠る。情報に追われない毎日は、驚くほど穏やかだった。下山して久しぶりにスマートフォンを手にしたとき、私は少しだけ、あの山の静けさが恋しくなった。": [0.0, 49.27], "田中さん、引っ越したんだって？": [49.67, 2.675], "うん。でも急だったから、家具はおろか、カーテンもまだないんだよ。": [52.745, 5.475], "それは不自由でしょう。": [58.62, 1.805], "まあね。でも、物が少ないのも案外心地いいよ。": [60.825, 4.605], "祖父は、スマートフォンはおろか、携帯電話も使ったことがない。": [65.83, 5.455], "骨折して、走ることはおろか、歩くことさえできない。": [71.685, 4.925], "その島には、ホテルはおろか、コンビニ一軒すらない。": [77.01, 4.79], "海外に着いた初日、言葉はおろか、切符の買い方さえわからず途方に暮れた。駅員さんが身振りで教えてくれたおかげで、なんとかホテルにたどり着けた。": [82.2, 11.985], "忙しくて、旅行はおろか、休日に外出する暇もない。": [94.585, 5.255], "雨は弱まるどころか、ますます強くなってきた。": [100.24, 4.0], "険しい": [104.64, 1.19], "心地よい": [106.23, 1.365], "煩雑": [107.995, 1.215], "簡便": [109.61, 1.085], "不自由": [111.095, 1.145], "物足りない": [112.64, 1.35], "侘しい": [114.39, 1.185], "悠長": [115.975, 1.225]}, "d082": {"駅から徒歩十五分、住宅街の一角にひっそりと店を構える蕎麦屋「やまぶき」。看板も小さく、うっかりすると通り過ぎてしまう。だが、一度訪れれば、ここが行列の絶えない店である理由がすぐにわかる。石臼で挽いた蕎麦は香り高く、喉ごしは実に滑らかだ。蕎麦の味もさることながら、私が感心したのは器である。地元の陶芸家に一つひとつ焼いてもらったという器は、どれも温かみがあり、料理を一層引き立てている。店主のさりげない心配りも心地よい。値段はやや張るが、それに見合う満足感は十分に得られる。静かに蕎麦を味わいたい人に、ぜひ勧めたい一軒だ。": [0.0, 47.66], "この前行ったイタリアン、どうだった？": [48.06, 2.85], "料理の味もさることながら、景色が最高だったよ。窓から海が一望できるんだ。": [51.31, 6.635], "へえ、いいね。サービスは？": [58.345, 2.99], "控えめだけど丁寧で、申し分なかったよ。": [61.735, 3.735], "この映画は、ストーリーもさることながら、音楽が素晴らしい。": [65.87, 5.21], "留学には、費用もさることながら、本人の強い意志が必要だ。": [71.48, 5.61], "彼女は、歌唱力もさることながら、表現力が群を抜いている。": [77.49, 5.55], "駅前のパン屋は、香ばしいクロワッサンもさることながら、店員さんの笑顔が魅力だ。値段も控えめで、つい毎朝立ち寄ってしまう。": [83.44, 10.295], "この旅館は、料理もさることながら、従業員のもてなしが素晴らしい。": [94.135, 5.835], "この店は、週末はもちろん平日も混んでいる。": [100.37, 4.18], "滑らか": [104.95, 1.26], "香ばしい": [106.61, 1.295], "芳しい": [108.305, 1.31], "濃厚": [110.015, 1.215], "淡白": [111.63, 1.2], "絶妙": [113.23, 1.25], "申し分ない": [114.88, 1.285], "控えめ": [116.565, 1.2]}, "d083": {"市の職員が住民の個人情報を不正に持ち出し、知人の業者に売り渡していたことが明らかになった。住民の暮らしを守るべき公務員にあるまじき行為であり、厳正な処分は避けられない。だが、問題は個人の資質だけではない。この職員は数年前から同様の行為を繰り返していたにもかかわらず、データの閲覧記録は一度も点検されていなかった。管理体制の杜撰さは明白である。市は「一職員の不祥事」として早々に幕引きを図ろうとしているが、そうした姿勢こそ行政にあるまじきものではないか。失われた信頼を取り戻すには、外部の専門家による徹底した調査と、再発防止策の公表が欠かせない。": [0.0, 47.77], "ニュース見た？病院の職員が、患者の情報をSNSに書き込んでたって。": [48.17, 6.23], "医療に携わる人間にあるまじき行為だね。": [54.8, 3.35], "本当。病院の管理も杜撰だったんじゃないかな。": [58.55, 4.125], "厳正に処分してほしいね。": [63.075, 2.185], "患者の秘密を漏らすなど、医師にあるまじき行為だ。": [65.66, 4.125], "部下に責任を押しつけるとは、管理職としてあるまじき態度だ。": [70.185, 4.88], "それは、人として決して言うまじき言葉だった。": [75.465, 3.88], "試合中に審判を侮辱した選手の態度は、プロにあるまじきものだ。リーグは厳正な処分を下し、再発防止に努めるべきだ。": [79.745, 10.25], "選手に暴力をふるうなど、指導者にあるまじき行為だ。": [90.395, 4.475], "人の陰口を言うべきではない。": [95.27, 2.5], "杜撰": [98.17, 1.04], "厳正": [99.61, 1.105], "明白": [101.115, 1.195], "歴然": [102.71, 1.13], "不審": [104.24, 0.98], "不穏": [105.62, 0.92], "物騒": [106.94, 1.12], "由々しい": [108.46, 1.195]}, "d085": {"子どもへの読み聞かせが大切であることは、今さら言うまでもない。語彙が豊かになる、想像力が育つ、といった効果は多くの研究で示されている。しかし、読み聞かせの価値は、そうした目に見える成果だけにあるのではない。忙しい一日の終わりに、親の膝の上で同じ物語に耳を傾ける。その穏やかなひとときこそが、子どもにとってかけがえのない安心感になるのだ。上手に読む必要はない。声色を変えたり、抑揚をつけたりするまでもなく、親の声そのものが子どもには心地よいのである。毎晩でなくても構わない。たとえ十分でも、絵本を開く時間を大切にしてほしい。": [0.0, 45.86], "明日の会議の資料、印刷しておいたほうがいいですか。": [46.26, 4.4], "三人だけの打ち合わせだから、わざわざ印刷するまでもないよ。画面で見ればいいから。": [51.06, 6.725], "わかりました。じゃあ、データだけ共有しておきます。": [58.185, 4.295], "うん、お願いね。": [62.88, 1.77], "この程度の傷なら、病院に行くまでもない。": [65.05, 3.65], "言うまでもなく、安全が何よりも優先される。": [69.1, 3.89], "結果は、見るまでもなく明らかだった。": [73.39, 3.31], "言うまでもなく、外国語の上達には毎日の積み重ねが欠かせない。とはいえ、完璧を目指して悩むまでもなく、まずは楽しく続けることが大切だと思う。": [77.1, 12.71], "こんな簡単な計算は、電卓を使うまでもない。": [90.21, 4.21], "わざわざお越しいただくには及びません。": [94.82, 2.945], "無邪気": [98.165, 1.095], "あどけない": [99.66, 1.28], "いじらしい": [101.34, 1.285], "微笑ましい": [103.025, 1.46], "頼もしい": [104.885, 1.295], "逞しい": [106.58, 1.345], "利発": [108.325, 1.115], "腕白": [109.84, 1.195]}, "d086": {"三十五歳で会社を辞め、念願だった小さなカフェを開いた。周囲からは無謀だと止められたが、迷いはなかった。駄目だったら、また会社勤めに戻るまでだ。そう腹をくくっていたからだ。ところが、現実は甘くなかった。開店から半年、客足は伸びず、貯金は見る見る減っていった。ある晩、片付けをしながら、私は原因を一から考え直した。答えは単純だった。自分が出したいメニューばかりで、客が求めるものを見ていなかったのだ。翌月、私はメニューを半分に絞り、近所の人の声を聞いて回った。特別なことをしたわけではない。当たり前のことを当たり前にしたまでのことだ。今、店は少しずつ常連客で埋まりつつある。": [0.0, 51.555], "部長に企画を反対されたら、どうするの？": [51.955, 3.72], "そのときは、データをそろえてもう一度説明するまでだよ。": [56.075, 4.705], "粘り強いね。私だったら、すぐ諦めちゃうかも。": [61.18, 4.7], "いや、悲観的になっても仕方ないからさ。": [66.28, 3.74], "電車が動かないなら、歩いて帰るまでだ。": [70.42, 3.51], "お礼なんていりません。当然のことをしたまでです。": [74.33, 3.8], "反対されても、自分の信じる道を進むまでのことだ。": [78.53, 4.745], "来年、N1に挑戦するつもりだ。もし不合格でも、半年後にまた受け直すまでのことだ。": [83.675, 7.715], "断られたら、ほかの会社を探すまでだ。": [91.79, 3.725], "終電を逃したので、タクシーで帰るしかない。": [95.915, 3.86], "潔い": [100.175, 1.235], "しぶとい": [101.81, 1.24], "粘り強い": [103.45, 1.36], "未練がましい": [105.21, 1.5], "臆病": [107.11, 1.195], "果敢": [108.705, 1.055], "楽観的": [110.16, 1.305], "悲観的": [111.865, 1.22]}, "d087": {"人間ドックを受診された皆様へ。先日はご受診いただき、誠にありがとうございました。検査結果を同封いたしましたので、ご確認ください。なお、結果票で「要経過観察」と記載された項目については、直ちに治療を要するものではございません。過度にご心配いただくには及びませんが、一年後の健診で改めて確認されることをお勧めいたします。一方、「要精密検査」の項目がある方は、早めに専門の医療機関を受診してください。紹介状が必要な場合は、当センターの窓口までお申し出ください。また、本書面へのご返信には及びません。ご不明な点がございましたら、お気軽にお問い合わせください。": [0.0, 50.58], "先生、再検査って、すぐに入院したほうがいいんでしょうか。": [50.98, 5.415], "いえ、軽微な異常ですから、ご心配には及びませんよ。": [56.795, 4.84], "よかった。じゃあ、普段どおりに生活していいんですね。": [62.035, 4.675], "ええ。ただ、適度な運動は続けてください。": [67.11, 4.26], "軽い風邪ですから、わざわざお見舞いに来ていただくには及びません。": [71.77, 4.955], "この件はこちらで処理しますので、ご心配には及びません。": [77.125, 4.83], "私の料理の腕は、まだまだ母には及ばない。": [82.355, 4.075], "資料は本日中にこちらからお送りいたしますので、わざわざお越しいただくには及びません。ご不明な点がございましたら、お気軽にご連絡ください。": [86.83, 11.125], "本書面へのご返信には及びません。": [98.355, 2.93], "明日は早く来なくてもいいよ。": [101.685, 2.375], "頑健": [104.46, 1.115], "虚弱": [105.975, 1.12], "軽微": [107.495, 1.03], "重篤": [108.925, 1.22], "良好": [110.545, 1.215], "安静": [112.16, 1.11], "過度": [113.67, 0.995], "適度": [115.065, 1.14]}, "d088": {"「睡眠は一日八時間とるに越したことはない」とよく言われる。しかし、最近の研究によれば、必要な睡眠時間には個人差があり、誰にとっても八時間が理想とは限らないそうだ。大切なのは、時間の長さよりも質である。寝る直前までスマートフォンの画面を見ていると、脳が興奮して眠りが浅くなる。休日に昼過ぎまで寝だめをするのも、体内時計を狂わせる原因になる。もちろん、十分に眠れるならそれに越したことはない。だが、忙しい現代人にとっては、決まった時刻に起きて朝日を浴びるといった小さな習慣を積み重ねるほうが現実的だろう。睡眠を削って頑張ることを美徳とする風潮も、そろそろ見直す時期に来ているのではないか。": [0.0, 51.05], "来週の出張、新幹線のチケットはもう取った？": [51.45, 4.455], "まだだけど、当日でも大丈夫じゃない？": [56.305, 3.34], "連休前だから、早めに予約しておくに越したことはないよ。": [60.045, 4.86], "それもそうだね。今夜のうちに取っておくよ。": [65.305, 3.71], "体調が悪いときは、無理をせず休むに越したことはない。": [69.415, 4.66], "家賃は安いに越したことはないが、駅からの距離も大事だ。": [74.475, 4.83], "旅行先では、用心するに越したことはない。": [79.705, 3.8], "もちろん毎日規則的に勉強できるに越したことはないが、忙しい日もある。そんな日は、単語を五つ覚えるだけでも続けることが大切だと思う。": [83.905, 11.52], "お金はあるに越したことはないが、それだけで幸せになれるわけではない。": [95.825, 5.525], "熱があるなら、今日は早く寝たほうがいいよ。": [101.75, 3.7], "規則的": [105.85, 1.25], "不規則": [107.5, 1.275], "理想的": [109.175, 1.235], "現実的": [110.81, 1.315], "怠惰": [112.525, 1.04], "勤勉": [113.965, 1.085], "有害": [115.45, 1.12], "健康的": [116.97, 1.335]}, "d089": {"先月、念願のヨーロッパ旅行に出かけた。ところが三日目、駅の雑踏で財布をすられてしまった。現金とクレジットカードが入っていたため、目の前が真っ暗になった。それでも、パスポートと予備のカードを別のバッグに分けて入れていたのは不幸中の幸いだった。すぐにカード会社に連絡して利用を止め、警察で盗難届を出した。慣れない英語での手続きは骨が折れたが、親切な駅員さんが付き添ってくれた。旅の予定は一日分狂ったものの、帰国できなくなるような事態にならなかっただけましだと思うことにした。今回痛感したのは、海外では「まさか」が起こりうるということだ。貴重品は分散して持つ。当たり前のことだが、それが私を救ってくれた。": [0.0, 51.6], "台風で旅行が中止になったんだって？残念だったね。": [52.0, 4.41], "うん。でも、キャンセル料がかからなかっただけましだよ。": [56.81, 4.595], "それはよかった。危うく全額払うところだったんだね。": [61.805, 4.45], "そう。次はもっと天気が安定した時期を選ぶよ。": [66.655, 4.23], "試合には負けたが、大けがをしなかっただけましだ。": [71.285, 4.24], "部屋は狭いが、駅に近いだけましだ。": [75.925, 3.425], "給料は少ないけれど、仕事が好きなだけましだと思っている。": [79.75, 4.895], "先週、雨の日に自転車で転んでしまった。服は泥だらけになったが、骨が折れなかっただけましだ。これからは雨の日は歩いて行こうと思う。": [85.045, 11.13], "電車は遅れたが、運休にならなかっただけましだ。": [96.575, 4.13], "古い自転車でも、歩くよりはましだ。": [101.105, 3.265], "心許ない": [104.77, 1.58], "用心深い": [106.75, 1.525], "無防備": [108.675, 1.125], "不用心": [110.2, 1.15], "あっけない": [111.75, 1.21], "際どい": [113.36, 1.115], "危うい": [114.875, 1.065], "気の毒": [116.34, 1.2]}, "d092": {"三月も半ばを過ぎると、朝の空気にもようやく春めいた柔らかさが感じられるようになる。先日、近所の古道具屋に立ち寄った際、店主が古い文箱の中から一通の手紙を取り出して見せてくれた。差出人の名はなく、文面には謎めいた言葉が並んでいるだけだという。店主はそれを読み解こうと何年も思い巡らしてきたが、いまだに手がかりは見出せていない。「案外、誰かの冗談かもしれませんがね」と店主は皮肉めいた笑みを浮かべたが、その目は少しも笑っていなかった。答えの出ない問いを抱え続けることも、ひとつの楽しみなのだろう。私は店を出たあとも、その手紙のことがしばらく頭から離れなかった。": [0.0, 47.535], "最近、日差しがすっかり春めいてきましたね。": [47.935, 3.97], "ええ。でも、今朝は冬に逆戻りしたみたいに寒かったですよ。": [52.305, 5.46], "週末、どこかに立ち寄ってお花見の下見でもしようかな。": [58.165, 4.75], "いいですね。桜のつぼみも、そろそろふくらみ始めているでしょうから。": [63.315, 5.765], "庭の梅がほころび始め、日差しもすっかり春めいてきた。": [69.48, 4.795], "彼は冗談めいた口調で、本音を漏らした。": [74.675, 3.7], "その女優は私生活を一切語らない謎めいた人物だ。": [78.775, 4.58], "朝晩の風が秋めいてきたので、帰りに公園に立ち寄って、色づき始めた木々を眺めた。": [83.755, 7.105], "風が少しずつ秋めいてきた。": [91.26, 2.465], "彼は怒りっぽい性格だ。": [94.125, 2.26], "立ち寄る": [96.785, 1.145], "取り出す": [98.33, 1.2], "読み解く": [99.93, 1.255], "思い巡らす": [101.585, 1.545], "見出す": [103.53, 1.185], "言い当てる": [105.115, 1.165], "見抜く": [106.68, 1.085], "書き残す": [108.165, 1.475]}, "d093": {"会議で自分の案が退けられた途端、黙り込んで資料を机に放り出す。そんな子供じみた振る舞いをする大人は、意外に少なくない。かく言う私も、若い頃はそうだった。先輩に企画の甘さを指摘されると、素直に聞き入れるどころか、言い訳がましい理屈をこねて食い下がったものだ。今思えば、あれは自信のなさの裏返しだったのだろう。年齢を重ねて分かったのは、反論すること自体が悪いのではなく、感情を相手に押し付けることが問題だということだ。意見がぶつかったら、まずは一呼吸置いて、相手の言葉を受け止める。説教じみた話になってしまったが、これは過去の自分への戒めでもある。": [0.0, 47.145], "田中さん、さっきの会議、ちょっと子供じみた態度だったんじゃない？": [47.545, 5.57], "すみません。案を退けられて、つい黙り込んでしまいました。": [53.515, 5.145], "悔しい気持ちは分かるけど、意見はちゃんと言葉で伝えないと。": [59.06, 5.025], "はい。次は指摘を受け止めたうえで、言い返すんじゃなくて提案します。": [64.485, 5.66], "いい年をして、そんな子供じみたいたずらはやめなさい。": [70.545, 4.46], "彼の謝罪はどこか芝居じみていて、誠意が感じられなかった。": [75.405, 5.105], "祖父の作業着は、長年の仕事で油じみていた。": [80.91, 4.35], "弟は負けるとすぐに黙り込むという子供じみた癖があるが、最近は少しずつ相手の意見を受け止められるようになった。": [85.66, 9.24], "彼の言い訳はどこか子供じみていた。": [95.3, 3.06], "日差しがすっかり春めいてきた。": [98.76, 2.505], "黙り込む": [101.665, 1.32], "放り出す": [103.385, 1.31], "聞き入れる": [105.095, 1.185], "食い下がる": [106.68, 1.25], "押し付ける": [108.33, 1.305], "受け止める": [110.035, 1.3], "言い返す": [111.735, 1.295], "思い返す": [113.43, 1.43]}, "d094": {"駅から徒歩三分、日当たり良好、家賃は相場より二割も安い。不動産サイトでそんないいことずくめの物件を見つけ、私はすぐさま問い合わせた。ところが、内見に行ってみると話は違った。窓の外には建設中のビルが立ちはだかり、日差しはほとんど入らない。担当者を問い詰めると、「工事の情報を掲載し忘れていました」と言い逃れるばかりだった。考えてみれば、条件が良すぎる話には必ず裏がある。広告の言葉をうのみにせず、自分の目で確かめることの大切さを思い知らされた一日だった。結局その物件は見送り、少し高くても納得できる部屋を探すことにした。": [0.0, 46.515], "見て、この部屋。駅近で家賃も安くて、いいことずくめなの。": [46.915, 5.785], "うーん、条件が良すぎるね。何か見落としてることがあるんじゃない？": [53.1, 5.22], "そうかな。じゃあ、不動産屋に問い合わせて、詳しく聞いてみる。": [58.72, 5.515], "うん、内見もしたほうがいいよ。写真だけじゃ見破れないこともあるから。": [64.635, 5.745], "犯人は黒ずくめの服装で現場に現れたという。": [70.78, 3.95], "今年は昇進に結婚と、めでたいことずくめの一年だった。": [75.13, 4.995], "その寮は規則ずくめで、学生たちは息が詰まりそうだった。": [80.525, 5.05], "先週はボーナスが出て、旧友にも再会できて、まさにいいことずくめの一週間だった。": [85.975, 7.065], "今日はいいことずくめの一日だった。": [93.44, 2.865], "この作文は間違いだらけだ。": [96.705, 2.45], "問い合わせる": [99.555, 1.305], "立ちはだかる": [101.26, 1.44], "問い詰める": [103.1, 1.225], "言い逃れる": [104.725, 1.3], "思い知る": [106.425, 1.255], "見送る": [108.08, 1.155], "見落とす": [109.635, 1.215], "見破る": [111.25, 1.135]}, "d095": {"先月、市内の小学校で田植え体験が行われた。裸足で田んぼに入った子どもたちは、初めは足を取られて悲鳴を上げていたが、すぐに慣れて夢中で苗を植え付けていった。終わる頃には誰もが泥まみれで、顔を見合わせては笑い転げていた。指導した農家の男性は「今の子は汚れることを嫌がると思い込んでいたが、とんでもない」と目を細める。一方、保護者の間では、衣服の汚れや安全面を気にする声も聞かれた。それでも学校側は、土に触れる体験は教室では得られないとして、秋の稲刈りまで活動を続けていく方針だ。": [0.0, 41.8], "お帰り。うわっ、泥まみれじゃない。どうしたの？": [42.2, 4.33], "学校で田植えをしたんだ。みんなで笑い転げながら苗を植え付けたよ。": [46.93, 5.015], "楽しかったみたいね。でも、その服、洗って落ちるかしら。": [52.345, 5.515], "先にシャワーで泥を洗い流してくるから、怒らないでよ。": [58.26, 4.415], "一日中工事現場で働いた彼は、汗とほこりまみれになって帰ってきた。": [63.075, 6.005], "事業に失敗した叔父は、借金まみれの生活を送っている。": [69.48, 4.985], "倉庫の奥から、油まみれの古い工具箱が出てきた。": [74.865, 4.54], "引っ越しの日、押し入れの奥まで掃除したら、髪も服もほこりまみれになってしまった。": [79.805, 6.695], "子どもたちは泥まみれになって遊んだ。": [86.9, 2.97], "このレポートは誤字だらけだ。": [90.27, 2.25], "植え付ける": [92.92, 1.225], "見合わせる": [94.545, 1.1], "笑い転げる": [96.045, 1.475], "思い込む": [97.92, 1.295], "刈り取る": [99.615, 1.155], "踏み入れる": [101.17, 1.205], "掘り起こす": [102.775, 1.38], "洗い流す": [104.555, 1.405]}, "d096": {"人は自分に都合のいい情報ばかりを集めるきらいがある。心理学では「確証バイアス」と呼ばれる現象だ。SNSの時代になって、この傾向はいっそう強まったように思われる。好みに合わせて表示される記事を読み続けるうちに、異なる意見を聞き流し、やがては頭から切り捨ててしまう。こうして凝り固まった考えを解きほぐすのは容易ではない。大切なのは、自分の判断を時々疑ってみることだろう。反対の立場の記事をあえて読み比べ、根拠を照らし合わせる。そうした小さな手間を惜しまないことが、偏りに気づく第一歩になるのではないだろうか。": [0.0, 42.925], "山本君は、データを自分に都合よく解釈するきらいがあるね。": [43.325, 5.09], "そうでしょうか。根拠はしっかり照らし合わせたつもりですが。": [48.815, 4.61], "反対のデータを聞き流していないか、もう一度確かめてごらん。": [53.825, 4.8], "分かりました。決めつけずに、別の資料とも読み比べてみます。": [59.025, 5.225], "彼は物事を悲観的に考えすぎるきらいがある。": [64.65, 3.905], "最近の若者は、失敗を恐れて挑戦しないきらいがあると言われる。": [68.955, 5.545], "この報告書は数字の羅列のきらいがあって、要点がつかみにくい。": [74.9, 5.325], "私は締め切り直前まで作業を先延ばしにするきらいがあるので、今月から毎朝三十分だけ先に取りかかることにした。": [80.625, 9.43], "彼は人の話を最後まで聞かないきらいがある。": [90.455, 3.65], "出生率は年々低下する傾向がある。": [94.505, 3.4], "聞き流す": [98.305, 1.35], "切り捨てる": [100.055, 1.24], "凝り固まる": [101.695, 1.455], "解きほぐす": [103.55, 1.38], "読み比べる": [105.33, 1.42], "照らし合わせる": [107.15, 1.47], "決めつける": [109.02, 1.29], "見過ごす": [110.71, 1.255]}, "d097": {"「光陰矢のごとし」とはよく言ったもので、退職してから早くも十年が過ぎた。現役の頃は、毎日が飛ぶがごとく過ぎていき、立ち止まって季節を感じる余裕などなかった。今は庭の草花を育てながら、ゆっくりと時間を味わっている。先日、かつての部下が訪ねてきて、「部長のごとき上司には、もう出会えません」と言ってくれた。私ごときにはもったいない言葉だが、素直にうれしかった。思えば、仕事に追われながらも、多くの人に支えられてここまで歩んできたのだ。残りの人生は、受けた恩を少しずつ返していきたいと思っている。": [0.0, 42.21], "定年してもう十年か。月日が過ぎ去るのは早いもんだね。": [42.61, 4.735], "本当に。光陰矢のごとし、ですね。": [47.745, 3.7], "若い頃は時間に追い立てられてばかりで、立ち止まる暇もなかったよ。": [51.845, 5.325], "今はゆっくり振り返る時間ができて、よかったじゃありませんか。": [57.57, 4.875], "前述のごとく、この制度には多くの課題がある。": [62.845, 4.215], "彼は水を得た魚のごとく、新しい職場で生き生きと働いている。": [67.46, 5.335], "私ごときがこのような賞をいただくのは恐縮です。": [73.195, 3.98], "山頂から見下ろすと、雲が海のごとく広がり、遠くの峰々が島のごとく浮かんでいた。": [77.575, 7.19], "彼ごときに負けるはずがない。": [85.165, 2.35], "夢のような一日だった。": [87.915, 2.145], "過ぎ去る": [90.46, 1.255], "立ち止まる": [92.115, 1.275], "追い立てる": [93.79, 1.23], "振り返る": [95.42, 1.26], "移り変わる": [97.08, 1.375], "生き抜く": [98.855, 1.2], "思い起こす": [100.455, 1.445], "使い果たす": [102.3, 1.515]}, "d099": {"ゴールまで残り一キロ。沿道を埋め尽くした観客から、割れんばかりの声援が送られた。先頭を走る高橋選手は、一度は後続に追い抜かれかけたものの、最後の力を振り絞って再び突き放し、そのままテープを切った。ゴールの瞬間、彼女は今にも泣き出さんばかりの表情で両手を突き上げた。三年前、故障で引退も覚悟したという彼女にとって、この優勝は特別な意味を持つ。「諦めかけたこともありましたが、支えてくれた人たちの顔が浮かんで、踏みとどまれました」。インタビューでそう語る声は、かすかに震えていた。": [0.0, 42.355], "高橋選手、優勝おめでとうございます。ゴールの瞬間は今にも泣き出さんばかりでしたね。": [42.755, 7.415], "はい。最後は本当に力を振り絞りました。": [50.57, 4.02], "一度は追い抜かれそうになりましたが、どんなお気持ちでしたか。": [54.99, 4.565], "苦しかったですが、割れんばかりの声援に背中を押されて、踏みとどまれました。": [59.955, 6.195], "優勝が決まると、スタジアムは割れんばかりの拍手に包まれた。": [66.55, 5.105], "彼女は目に涙をあふれんばかりにためて、別れを告げた。": [72.055, 4.57], "店員は土下座せんばかりの勢いで謝罪した。": [77.025, 3.405], "最後の曲が終わった瞬間、会場を埋め尽くした観客から、あふれんばかりの拍手が送られた。": [80.83, 7.54], "彼は今にも殴りかからんばかりに怒っていた。": [88.77, 3.55], "彼は何も知らないかのように振る舞った。": [92.72, 3.06], "埋め尽くす": [96.18, 1.255], "追い抜く": [97.835, 1.14], "振り絞る": [99.375, 1.26], "突き放す": [101.035, 1.42], "突き上げる": [102.855, 1.22], "泣き出す": [104.475, 1.105], "踏みとどまる": [105.98, 1.395], "追いすがる": [107.775, 1.21]}, "d100": {"我が家の猫は、言葉こそ話さないが、意思表示は実にはっきりしている。朝六時になると、「早くご飯をよこせ」とばかりに枕元で鳴き続け、寝ている私を叩き起こす。仕方なく起き上がって餌を出すと、当然だと言わんばかりの顔で食べ始める。来客があれば、ここは自分の縄張りだとばかりにソファーの真ん中に寝そべり、決して譲ろうとしない。そんな猫に振り回される毎日だが、不思議と腹は立たない。むしろ、気ままに生きる姿を見ていると、人間関係に気を遣いすぎる自分を見つめ直すきっかけをもらっている気さえする。": [0.0, 41.67], "うちの猫、私が帰ると、遅いとばかりにすぐ擦り寄ってくるの。": [42.07, 5.67], "かわいいじゃない。うちのはソファーに居座って、どいてくれないよ。": [48.14, 4.915], "猫って、人間を振り回すのが得意よね。": [53.455, 3.62], "本当だね。でも、つい言うことを聞いちゃうんだよなあ。": [57.475, 4.49], "母は「もう聞きたくない」とばかりに、テレビの音量を上げた。": [62.365, 5.405], "セールが始まると、客はここぞとばかりに売り場へ殺到した。": [68.17, 4.905], "相手のミスをチャンスとばかりに、彼は一気に攻め込んだ。": [73.475, 4.475], "散歩の時間になると、犬は「早く行こう」とばかりにリードをくわえて、玄関で私を待ちかねている。": [78.35, 8.69], "彼は「勝った」とばかりにガッツポーズをした。": [87.44, 4.01], "彼女は泣き出さんばかりの顔をしていた。": [91.85, 3.155], "叩き起こす": [95.405, 1.54], "起き上がる": [97.345, 1.21], "振り回す": [98.955, 1.335], "見つめ直す": [100.69, 1.335], "居座る": [102.425, 1.085], "寝そべる": [103.91, 1.175], "擦り寄る": [105.485, 1.18], "待ちかねる": [107.065, 1.265]}, "d101": {"帰りの電車で、聞くともなしに隣の席の会話を聞いていた。大学生らしい二人のうち一人は、大企業の内定を得ているのに、小さな出版社への未練を断ち切れずにいるという。「安定を取るか、好きなことを取るか」。どこにでもあるありふれた悩みだが、本人にとっては人生の岐路だ。私も二十年前、同じことで思い悩んだ。結局、親の勧めに押し切られる形で安定を選んだが、後悔はしていない。ただ、自分で決めたと胸を張れるかと問われれば、答えに詰まる。窓の外を見るともなく眺めながら、私は心の中で彼らにエールを送った。": [0.0, 43.205], "さっきの電車で、聞くともなく隣の人の話を聞いちゃったんだけど。": [43.605, 5.535], "うん、何の話？": [49.54, 1.935], "転職するかどうか思い悩んでるみたいで、なんだか他人事に思えなくて。": [51.875, 5.435], "それで話に聞き入って、駅を乗り過ごしたってわけ？": [57.71, 4.335], "そうなの。笑わないでよ。": [62.445, 2.405], "ラジオを聞くともなく聞いていたら、懐かしい曲が流れてきた。": [65.25, 4.915], "どこからともなく、金木犀の甘い香りが漂ってきた。": [70.565, 4.665], "誰からともなく拍手が起こり、やがて会場全体に広がった。": [75.63, 5.125], "カフェで雑誌をめくるともなくめくっていたら、昔の同級生がインタビューを受けている記事が目に入った。": [81.155, 7.435], "窓の外を見るともなく見ていた。": [88.99, 2.655], "社長ともなると、休日も忙しい。": [92.045, 3.545], "決めかねる": [95.99, 1.19], "断ち切る": [97.58, 1.16], "思い悩む": [99.14, 1.345], "押し切る": [100.885, 1.105], "聞き入る": [102.39, 1.1], "見入る": [103.89, 0.99], "行き交う": [105.28, 1.155], "乗り過ごす": [106.835, 1.36]}, "d102": {"町外れに、昔ながらの製法で包丁を作り続ける鍛冶屋がある。四代目の主人は、生まれながらにして鉄を打つ音を子守歌に育ったという。若い頃は家業を継ぐことに反発し、都会の会社に勤めたが、父が倒れたのを機に戻ってきた。「最初は父に何度も突き返されました。刃の角度がわずかに違うだけで、切れ味がまるで変わるんです」。今では全国から注文が舞い込み、一年待ちの状態だ。それでも彼は、機械化して量産する気はないと言い切る。「手間を惜しめば、代々受け継いできたものが途絶えてしまいますから」。彼は涙ながらに、亡き父の思い出を語った。": [0.0, 45.16], "この包丁、昔ながらの製法で作られてるんだって。": [45.56, 4.61], "へえ、だから一年待ちなのね。注文が次々と舞い込んでるらしいよ。": [50.57, 5.915], "職人さんは、お父さんに技を一から叩き込まれたそうだよ。": [56.885, 4.965], "そうやって受け継がれてきた技なんだね。": [62.25, 3.195], "インターネットのおかげで、家にいながらにして世界中の映画が見られる。": [65.845, 5.2], "彼女は涙ながらに、事故の様子を語った。": [71.445, 3.925], "この通りには、昔ながらの商店が今も軒を連ねている。": [75.77, 4.92], "祖母の家の近くには、昔ながらの製法を受け継ぐ豆腐屋があり、毎朝行列ができる。": [81.09, 7.5], "彼は生まれながらに音楽の才能があった。": [88.99, 3.305], "狭いながらも、居心地のいい部屋だ。": [92.695, 3.325], "突き返す": [96.42, 1.395], "舞い込む": [98.215, 1.18], "言い切る": [99.795, 1.135], "受け継ぐ": [101.33, 1.235], "打ち込む": [102.965, 1.155], "鍛え上げる": [104.52, 1.28], "研ぎ澄ます": [106.2, 1.37], "叩き込む": [107.97, 1.35]}, "d103": {"住宅街での空き巣被害が相次いだことを受け、ある町では町ぐるみの防犯活動が始まった。住民が交代で夜道を見回り、不審な車両を見かけたらすぐに警察へ通報する仕組みだ。当初は「素人に何ができる」と冷ややかな声もあったが、活動開始から半年で被害は大幅に減った。成功の鍵は、家族ぐるみで参加する世帯が多かったことにあるという。子どもたちが通学路の危険な場所を洗い出し、地図に書き込んだことで、大人たちも気づかなかった死角が浮かび上がったのだ。町内会長は「顔見知りが増えたことが一番の収穫だ」と話している。": [0.0, 43.775], "最近、町内会で夜の見回りを始めたんだって？": [44.175, 4.355], "うん。空き巣が相次いだから、町ぐるみで取り組むことになったの。": [48.93, 5.15], "うちも家族ぐるみで参加しようかな。": [54.48, 3.015], "ぜひ。子どもたちも危ない場所を洗い出してくれて、助かってるのよ。": [57.895, 5.525], "隣の家とは、もう二十年も家族ぐるみの付き合いをしている。": [63.82, 4.72], "調査の結果、会社ぐるみで不正が行われていたことが分かった。": [68.94, 5.36], "旅行先で強盗に遭い、身ぐるみはがされてしまった。": [74.7, 4.3], "私の地元では、毎年夏に町ぐるみで川の清掃活動を行い、住民に参加を呼び掛けている。": [79.4, 8.495], "地域ぐるみで子どもたちを見守る。": [88.295, 2.76], "魚を骨ごと食べる。": [91.455, 2.005], "相次ぐ": [93.86, 1.145], "見回る": [95.405, 1.13], "見かける": [96.935, 1.255], "洗い出す": [98.59, 1.275], "書き込む": [100.265, 1.245], "浮かび上がる": [101.91, 1.355], "呼び掛ける": [103.665, 1.4], "見張る": [105.465, 1.055]}, "d104": {"年明け恒例の初競りで、重さ二百キロからある本マグロが競り落とされた。落札額は一億円を超え、会場はどよめきに包まれた。競り落としたのは都内の寿司チェーンの社長で、「縁起物ですから」と笑顔を見せた。もっとも、これほどの高値が付くのは宣伝効果を見込んでのことだと冷ややかに見る向きもある。実際、一貫数千円からする高級寿司として売ったとしても、採算は到底取れない。それでも、ニュースで店名が繰り返し報じられることを思えば、決して高い買い物ではないのだろう。華やかな競りの裏には、したたかな計算が潜んでいる。": [0.0, 42.615], "見た？初競りのマグロ、二百キロからあったらしいよ。": [43.015, 4.59], "うん、一億円以上で競り落とされたんでしょう？すごいね。": [48.005, 4.735], "宣伝効果を見込んでるんだろうね。": [53.14, 2.82], "それにしても、一貫何千円からするお寿司なんて、私には縁がないなあ。": [56.36, 6.095], "この森には、高さ三十メートルからある巨木が立ち並んでいる。": [62.855, 5.22], "彼女は百万円からするバッグを、迷わず買ってしまった。": [68.475, 4.69], "その講演会には五千人からの聴衆が詰めかけた。": [73.565, 4.26], "先日の展示会では、一台三千万円からするスポーツカーが、まるで宝石のように並べられていた。": [78.225, 8.045], "十キロからある荷物を一人で運んだ。": [86.67, 3.07], "三時間もの間、彼は話し続けた。": [90.14, 3.48], "競り落とす": [94.02, 1.405], "見込む": [95.825, 1.1], "売り出す": [97.325, 1.2], "買い占める": [98.925, 1.255], "売り切れる": [100.58, 1.235], "買い叩く": [102.215, 1.345], "見積もる": [103.96, 1.16], "釣り上げる": [105.52, 1.23]}, "d106": {"豪雨で自宅を失い、避難所で暮らす人々の不安は察するにかたくない。体育館の床に段ボールを敷いただけの空間では、プライバシーも保てない。高齢者の中には、慣れない環境で体調を崩す人も出始めている。行政は仮設住宅の建設を急いでいるが、入居できるのは早くても二か月後になる見通しだ。被災地では、全国から駆けつけたボランティアが泥のかき出しなどに汗を流しているものの、人手はまだ足りていない。被害の大きさを思えば、復興までの道のりが長くなることは想像にかたくない。私たち一人ひとりが、遠く離れていても何ができるかを考え続けることが求められている。": [0.0, 45.925], "ニュース見た？避難所の生活、本当に大変そうだね。": [46.325, 4.99], "うん。家を失った人たちの気持ちは察するにかたくないよ。": [51.715, 4.8], "私たちにも、何か手を差し伸べられることはないかな。": [56.915, 4.505], "週末、ボランティアとして駆けつけようと思ってるんだ。一緒に行く？": [61.82, 5.435], "一人で子どもを育てながら働く彼女の苦労は、想像にかたくない。": [67.655, 5.68], "試験に落ちた息子の落胆ぶりは、察するにかたくない。": [73.735, 4.56], "この法案が成立すれば、中小企業が打撃を受けることは想像にかたくない。": [78.695, 6.265], "長年勤めた工場の閉鎖を知らされた従業員たちの戸惑いは、想像にかたくない。": [85.36, 6.76], "彼の悔しさは察するにかたくない。": [92.52, 2.88], "結果は言うまでもない。": [95.8, 1.84], "駆けつける": [98.04, 1.375], "かき出す": [99.815, 1.29], "立ち直る": [101.505, 1.245], "寄り添う": [103.15, 1.19], "差し伸べる": [104.74, 1.375], "持ちこたえる": [106.515, 1.38], "立ち退く": [108.295, 1.22], "打ちひしがれる": [109.915, 1.35]}, "d107": {"一つの新薬が患者のもとに届くまでには、長い道のりがある。まず研究室で数万種類もの候補物質がふるいにかけられ、有望なものだけが絞り込まれる。続いて動物実験で安全性を確かめ、その後、人を対象とした三段階の臨床試験を経て、ようやく国に承認を申請できる。ここまでに十年以上かかることも珍しくない。途中で深刻な副作用が見つかれば開発は打ち切られ、それまでの投資は水の泡となる。成功確率は数万分の一とも言われる。新薬の価格が高いことに不満を抱く人は多いが、こうした過程を知れば、その背景にも目を向ける必要があるだろう。": [0.0, 46.595], "この薬は、長い臨床試験を経て、去年ようやく承認されたんですよ。": [46.995, 6.02], "そうなんですか。開発には何年ぐらいかかるんですか。": [53.415, 4.38], "十年以上はかかりますね。途中で打ち切られる研究も多いんです。": [58.195, 5.15], "多くの壁を乗り越えて生まれた薬なんですね。": [63.745, 3.565], "厳しい審査を経て、彼の作品が最優秀賞に選ばれた。": [67.71, 5.135], "十年の歳月を経て、焼失した城がついに再建された。": [73.245, 5.1], "この列車は名古屋を経て大阪へ向かう。": [78.745, 3.09], "三回の面接と実技試験を経て、念願だった出版社から内定をもらうことができた。": [82.235, 6.76], "議会での審議を経て、法案が可決された。": [89.395, 3.92], "知人を通じて彼と知り合った。": [93.715, 2.485], "絞り込む": [96.6, 1.405], "打ち切る": [98.405, 1.13], "突き止める": [99.935, 1.31], "積み重ねる": [101.645, 1.51], "取り下げる": [103.555, 1.265], "乗り越える": [105.22, 1.26], "練り直す": [106.88, 1.295], "見極める": [108.575, 1.275]}, "d108": {"昨年の市民祭りでは、会場周辺の渋滞や、ゴミの散乱に対する苦情が多数寄せられました。実行委員会では、こうした反省をふまえて、今年度の運営方法を大幅に見直しました。まず、車での来場を控えていただくため、最寄り駅から無料のシャトルバスを運行します。また、ゴミ箱の設置場所を倍に増やし、分別の案内係を配置します。出店者との打ち合わせも重ね、使い捨て容器の使用を減らすよう申し合わせました。市民の皆様からいただいたご意見を一つひとつ受け止め、誰もが気持ちよく楽しめる祭りを作り上げていきたいと考えております。": [0.0, 43.885], "来年度の企画書だけど、今年のアンケート結果をふまえて練り直してくれる？": [44.285, 5.82], "はい。特にどの点を重視すればよろしいでしょうか。": [50.505, 4.19], "待ち時間への不満が多かったから、その改善策を盛り込んでほしいんだ。": [55.095, 5.57], "承知しました。来週の打ち合わせまでに取りまとめます。": [61.065, 4.455], "前回の調査結果をふまえて、新たな仮説を立てた。": [65.92, 4.615], "現場の意見をふまえた改善案を、来週までに提出してください。": [70.935, 5.27], "過去の失敗をふまえ、今回は慎重に計画を進めることにした。": [76.605, 5.705], "前回の模擬試験の結果をふまえて学習計画を見直し、今月は聴解の練習を毎日三十分増やすことにした。": [82.71, 9.19], "昨年の反省をふまえて、計画を見直した。": [92.3, 4.015], "この映画は実話に基づいて作られた。": [96.715, 3.13], "見直す": [100.245, 1.19], "打ち合わせる": [101.835, 1.205], "申し合わせる": [103.44, 1.455], "作り上げる": [105.295, 1.325], "取りまとめる": [107.02, 1.37], "練り上げる": [108.79, 1.2], "盛り込む": [110.39, 1.205], "立ち上げる": [111.995, 1.23]}, "d109": {"校則の見直しを進める学校が増えている。髪の色や下着の色まで細かく定めた規則は、時代に合わないばかりか、生徒の人権を損ないかねないと指摘されてきた。ある高校では、生徒会が中心となって校則を一つずつ洗い直し、実態に即して改める作業を行った。「なぜこの規則が必要なのか」を説明できないものは廃止し、残す規則についても理由を書き添えたという。教員の中には、規律が緩むのではないかと危ぶむ声もあった。しかし、自分たちで決めたルールだからこそ守ろうとする意識が芽生え、かえって違反は減ったそうだ。規則とは、上から押し付けるものではなく、皆で作り上げるものなのだろう。": [0.0, 49.005], "今年から、校則を実態に即して見直すことになりました。": [49.405, 4.945], "本当ですか。髪型の規則も変わるんですか。": [54.75, 4.075], "ええ。理由を説明できない規則は廃止して、残すものには理由を書き添えます。": [59.225, 6.61], "自分たちで取り決めたルールなら、みんな守ると思います。": [66.235, 4.45], "制度は、利用者の実態に即して柔軟に運用されるべきだ。": [71.085, 5.09], "この小説は史実に即して書かれているが、登場人物の一部は架空だ。": [76.575, 6.145], "現場の状況に即した対応が求められている。": [83.12, 3.725], "在宅勤務が増えた今、通勤手当の制度も働き方の実態に即して見直すべきだと思う。": [87.245, 7.55], "事実に即して報道する。": [95.195, 2.375], "マニュアルに沿って作業を進める。": [97.97, 2.545], "洗い直す": [100.915, 1.355], "書き添える": [102.67, 1.295], "取り締まる": [104.365, 1.25], "言い渡す": [106.015, 1.295], "守り抜く": [107.71, 1.32], "押し通す": [109.43, 1.245], "取り決める": [111.075, 1.26], "切り替える": [112.735, 1.26]}, "d110": {"近年、採用の書類選考にAIを導入する企業が増えている。大量の応募書類を短時間でふるい分けられるのは確かに魅力だ。だが、AIは過去の採用データを学習するため、かつての偏った判断をそのまま引き継いでしまうおそれがある。実際、海外では特定の性別の応募者を不当に低く評価していた例が明るみに出た。こうした仕組みが、雇用の機会均等を定めた法律に照らして問題がないのか、厳しく問い直す必要がある。技術の便利さに飛びつく前に、判断の根拠を人間が検証できるようにしておくこと。それが、AIを使いこなすための最低限の条件ではないだろうか。": [0.0, 45.66], "うちの会社も、書類選考にAIを使うことになったらしいよ。": [46.06, 5.14], "でも、それって法律に照らして問題ないのかな。": [51.6, 4.06], "判断の根拠は、人間が確認できるようにするって。": [56.06, 4.435], "便利だからって、すぐ飛びつくのは危ないよね。": [60.895, 3.9], "過去の判例に照らして、今回の判決は妥当だと言える。": [65.195, 4.795], "私の経験に照らせば、この計画は少し楽観的すぎる。": [70.39, 5.305], "社内規定に照らして、彼の行為は懲戒処分に当たる。": [76.095, 4.72], "一般常識に照らして考えれば、深夜に大音量で音楽を流すのは、明らかに近所迷惑だ。": [81.215, 7.815], "法に照らして処分を決める。": [89.43, 2.205], "現状に即して計画を修正する。": [92.035, 3.125], "ふるい分ける": [95.56, 1.36], "引き継ぐ": [97.32, 1.23], "問い直す": [98.95, 1.25], "飛びつく": [100.6, 1.245], "使いこなす": [102.245, 1.505], "割り出す": [104.15, 1.215], "読み取る": [105.765, 1.18], "振り分ける": [107.345, 1.285]}, "d111": {"相撲は単なる格闘技ではない。土俵に上がる前の塩まき、四股、仕切りといった所作の一つひとつが、古来のしきたりにのっとって行われる神事でもある。だからこそ、伝統を守ることに強いこだわりを持つ関係者は多い。一方で、女性が土俵に上がれない慣習などをめぐっては、時代にそぐわないとの批判も根強い。伝統を守り続けるべきか、社会の変化に合わせて改めるべきか。どちらか一方を切り捨てて済む問題ではないだろう。大切なのは、なぜその決まりが生まれたのかを掘り下げて考え、残すべき核心と、見直してよい部分とを見極めることではないだろうか。": [0.0, 44.095], "今日の取組、行司の所作がきれいだったね。": [44.495, 3.805], "全部しきたりにのっとって行われているんでしょう？": [48.7, 3.595], "そう。行司は土俵の上を取り仕切る大事な役目なんだ。": [52.695, 4.415], "伝統って、意味を掘り下げてみると面白いね。": [57.51, 3.875], "式典は、古くからの作法にのっとって厳かに執り行われた。": [61.785, 5.16], "選挙は法律にのっとって公正に実施されなければならない。": [67.345, 4.595], "スポーツマンシップにのっとり、正々堂々と戦うことを誓います。": [72.34, 5.42], "韓国の祭祀は、家ごとに受け継がれてきたしきたりにのっとって、料理の並べ方まで細かく決められている。": [78.16, 8.44], "伝統にのっとって儀式を行う。": [87.0, 2.665], "係員の指示に従ってください。": [90.065, 2.83], "掘り下げる": [93.295, 1.3], "踏み出す": [94.995, 1.24], "突っぱねる": [96.635, 1.295], "立ち返る": [98.33, 1.24], "押し出す": [99.97, 1.195], "投げ飛ばす": [101.565, 1.37], "組み合う": [103.335, 1.1], "取り仕切る": [104.835, 1.245]}, "d113": {"各位　来期の新規事業計画について、ご連絡いたします。先日の役員会では、試験販売の結果いかんで本格展開の可否を判断することが決まりました。期間は三か月、対象は首都圏の二十店舗です。売れ行きが目標を上回れば、全国展開に向けて予算を積み増しますが、結果いかんによっては計画そのものを白紙に戻すこともあり得ます。各部署には、販売データの集計方法を事前にすり合わせておくよう、お願いいたします。また、店頭での顧客の反応についても、数字だけでは読み取れない声を拾い上げていただきたく存じます。ご不明な点は企画部・森までお問い合わせください。": [0.0, 47.085], "試験販売の結果いかんでは、計画を見合わせることになるかもしれない。": [47.485, 5.67], "そうなんですか。目標を下回った場合ということですね。": [53.555, 4.535], "ああ。だから、各店の声もしっかり拾い上げてほしいんだ。": [58.49, 4.99], "分かりました。集計方法も事前にすり合わせておきます。": [63.88, 4.53], "今後の交渉のいかんで、契約内容が大きく変わる可能性がある。": [68.81, 5.455], "検査結果いかんによっては、手術が必要になるかもしれません。": [74.665, 5.11], "合格できるかどうかは、これからの努力いかんだ。": [80.175, 4.1], "来月の試験の結果いかんによっては、留学の時期を半年先に持ち越すことも考えている。": [84.675, 7.2], "審査の結果いかんで、補助金の額が決まる。": [92.275, 4.02], "天気次第で、明日の予定を決めよう。": [96.695, 3.35], "積み増す": [100.445, 1.285], "すり合わせる": [102.13, 1.415], "拾い上げる": [103.945, 1.275], "上回る": [105.62, 1.22], "下回る": [107.24, 1.3], "持ち越す": [108.94, 1.26], "立て直す": [110.6, 1.315], "取りやめる": [112.315, 1.23]}, "d114": {"山あいの小さな温泉町が、ここ数年、若い旅行者の間で人気を集めている。湯けむりが立ち込める石畳の街並みが、紅葉の美しさとあいまって、写真映えすると評判になったのだ。町では空き家を改装したカフェや雑貨店が相次いで開業し、歩いて巡る楽しみも増えた。円安による外国人客の増加もあいまって、週末には宿の予約が取りにくいほどだという。ただ、観光客の急増で、住民の生活道路が渋滞するなどの問題も持ち上がっている。町は今後、観光と暮らしをどう両立させるか、住民と話し合いながら方針を練り上げていく考えだ。": [0.0, 44.37], "この温泉町、紅葉と石畳の街並みがあいまって、本当にきれいね。": [44.77, 6.235], "うん、思わず見とれちゃうよ。最近、若い人が押し寄せてるらしいね。": [51.405, 5.935], "空き家がカフェに生まれ変わったりして、町も盛り上がってるんだって。": [57.74, 4.82], "でも、住んでいる人たちにとっては、大変なこともあるんだろうな。": [62.96, 5.45], "彼女の歌声は、幻想的な照明とあいまって、観客を魅了した。": [68.81, 5.865], "疲労と寝不足があいまって、試験中に頭が働かなくなった。": [75.075, 5.235], "好天もあいまって、花火大会には例年以上の人出があった。": [80.71, 5.0], "この映画は、俳優の自然な演技と美しい映像があいまって、見終わったあとも思わず余韻に浸ってしまう。": [86.11, 8.02], "才能と努力があいまって、彼は成功を収めた。": [94.53, 4.28], "雨に加えて、風も強くなってきた。": [99.21, 3.425], "立ち込める": [103.035, 1.275], "持ち上がる": [104.71, 1.23], "見とれる": [106.34, 1.12], "呼び込む": [107.86, 1.245], "生まれ変わる": [109.505, 1.385], "盛り上がる": [111.29, 1.2], "押し寄せる": [112.89, 1.265], "移り住む": [114.555, 1.3]}, "d115": {"姉は昔から何事にも計画的だった。夏休みの宿題は七月中に片付け、受験勉強も早めに取りかかって、志望校に難なく合格した。それにひきかえ、私は締め切りが迫らないと動けない性分で、いつも最終日に泣きながら宿題をやり遂げていた。親戚が集まるたびに比べられ、肩身の狭い思いをしたものだ。ところが大人になって、意外なことを知った。姉は予定が狂うと途方に暮れてしまい、とっさの判断が苦手だというのだ。一方、追い詰められてから力を発揮してきた私は、急な変更にもうろたえない。長所と短所は表裏一体なのだと、今になって思い知らされている。": [0.0, 46.64], "お姉さんは、何でも早めに取りかかるタイプなのね。": [47.04, 4.175], "うん。それにひきかえ、僕はいつもぎりぎりなんだ。": [51.615, 4.375], "でも、追い詰められると力を発揮するんでしょう？": [56.39, 3.9], "まあね。昔は姉と張り合ってばかりいたけど、今はお互いの違いを認め合えるようになったよ。": [60.69, 7.29], "去年の猛暑にひきかえ、今年の夏は過ごしやすい。": [68.38, 4.57], "兄が社交的なのにひきかえ、弟は人見知りが激しい。": [73.35, 4.97], "隣の子は毎日勉強している。それにひきかえ、うちの息子はゲームばかりだ。": [78.72, 6.53], "料理上手な母にひきかえ、私は目玉焼きさえ焦がしてしまうので、今年こそ料理教室を最後までやり遂げたい。": [85.65, 8.965], "几帳面な兄にひきかえ、弟はだらしない。": [95.015, 3.92], "都市部の人口が増えたのに対して、農村部では減少した。": [99.335, 4.815], "取りかかる": [104.55, 1.345], "やり遂げる": [106.295, 1.27], "追い詰める": [107.965, 1.22], "出し抜く": [109.585, 1.205], "張り合う": [111.19, 1.095], "言い負かす": [112.685, 1.36], "見下す": [114.445, 1.255], "追い越す": [116.1, 1.235]}, "d116": {"新商品の名前を決める会議は、毎回のように紛糾する。先日も、若手が「味はさておき、まずは名前で目を引くべきだ」と言い出したのをきっかけに、議論が脱線してしまった。ベテラン社員は「中身が伴わなければ、客はすぐに見限る」と食ってかかり、場の空気は凍りついた。司会役の私は、慌てて「どちらが正しいかはさておき、両方の視点から案を出し合いましょう」と割って入った。結局、三時間話し合って決まったのは、候補を十に絞ることだけだった。それはさておき、会議のあとに皆で食べた試作品は、文句なしにおいしかった。名前など、案外どうでもいいのかもしれない。": [0.0, 48.45], "名前の話はさておき、まず価格を決めましょう。": [48.85, 4.21], "でも、名前が決まらないと、パッケージのデザインに入れません。": [53.46, 4.965], "分かった。じゃあ、各自が案を持ち寄って、明日もう一度出し合おう。": [58.825, 5.785], "はい。今日みたいに言い争いにならないといいんですが。": [65.01, 4.135], "冗談はさておき、そろそろ本題に入りましょう。": [69.545, 4.195], "費用の問題はさておき、まずは実現可能かどうかを検討すべきだ。": [74.14, 5.54], "何はさておき、無事に帰ってきてくれてよかった。": [80.08, 3.97], "細かい日程はさておき、まずは各自が行きたい場所の案を持ち寄って、行き先を決めよう。": [84.45, 6.925], "それはさておき、来週の予定はどうなっていますか。": [91.775, 4.21], "見た目はともかく、味は確かだ。": [96.385, 3.03], "言い出す": [99.815, 1.165], "見限る": [101.38, 1.185], "食ってかかる": [102.965, 1.39], "凍りつく": [104.755, 1.335], "割って入る": [106.49, 1.205], "出し合う": [108.095, 1.09], "持ち寄る": [109.585, 1.145], "言い争う": [111.13, 1.3]}, "d117": {"出張にかこつけて観光を楽しむ人は少なくないだろう。かく言う私も、地方出張の際には、仕事を早めに切り上げて名所に足を延ばすことがある。もっとも、最近は会社の目も厳しくなった。経費の使い道は細かく問いただされ、私用の移動費を紛れ込ませれば、すぐに見抜かれてしまう。それでも、「ワーケーション」という言葉が広まったことで、仕事と休暇を組み合わせる働き方は、むしろ推奨されるようになりつつある。大切なのは、何かにかこつけてこっそり楽しむのではなく、きちんと線を引いたうえで、堂々と両立させることなのかもしれない。": [0.0, 44.5], "部長、また視察にかこつけて温泉に行くらしいよ。": [44.9, 4.415], "えっ、本当？経費で落とすつもりかな。": [49.715, 3.78], "最近は経理に細かく問いただされるから、無理だと思うけど。": [53.895, 4.965], "そうだよね。仕事を早めに切り上げて、少し観光するくらいならいいけど。": [59.26, 6.16], "彼は体調不良にかこつけて、面倒な会議を欠席した。": [65.82, 4.935], "父は孫の誕生日にかこつけて、自分の欲しかったゲーム機を買ってきた。": [71.155, 5.885], "雨にかこつけて、今日もジョギングをさぼってしまった。": [77.44, 4.29], "大掃除にかこつけて古いアルバムを一日中眺めてしまい、結局部屋は少しも片付かなかった。": [82.13, 7.93], "取材にかこつけて、有名店を食べ歩いた。": [90.46, 3.91], "頭痛を口実に早退した。": [94.77, 2.36], "切り上げる": [97.53, 1.2], "問いただす": [99.13, 1.3], "紛れ込む": [100.83, 1.33], "組み合わせる": [102.56, 1.375], "抜け出す": [104.335, 1.275], "取り繕う": [106.01, 1.32], "繰り出す": [107.73, 1.215], "言いくるめる": [109.345, 1.335]}, "d118": {"郊外の農道沿いに、野菜の無人販売所がある。棚に並んだ野菜の横に料金箱が置かれているだけで、客の良心に任された仕組みだ。ところが最近、人目がないのをいいことに、代金を払わずに持ち去る者が後を絶たないという。持ち主の農家は、防犯カメラの設置に踏み切るべきか迷っている。「お客さんを疑ってかかるようで嫌なんですよ。きちんと払ってくれる大多数の人に申し訳ない」。性善説に立つ仕組みは、一部の心ない行為によってたやすく崩れ去る。誰も見ていないときにどう振る舞うか。そこにこそ、その人の本当の姿が表れるのだろう。": [0.0, 43.375], "弟が、親が留守なのをいいことに、毎晩夜更かししてるんだよ。": [43.775, 5.32], "あらら。注意しないの？": [49.495, 2.24], "しばらく見逃してたら、ますますひどくなってね。注意したら居直られたよ。": [52.135, 5.84], "人の甘さに付け込むのは感心しないね。": [58.375, 3.405], "先生が来ないのをいいことに、生徒たちは教室で騒ぎ始めた。": [62.18, 5.455], "彼は上司が寛大なのをいいことに、遅刻を繰り返している。": [68.035, 4.83], "監視の目が緩いのをいいことに、ゴミの不法投棄が続いていた。": [73.265, 5.01], "在宅勤務で上司の目が届かないのをいいことに昼過ぎまで寝ている同僚がいるが、いずれ成果に表れると思う。": [78.675, 8.18], "親の留守をいいことに、友達を呼んで騒いだ。": [87.255, 3.905], "留学をきっかけに、日本の文化に興味を持った。": [91.56, 4.12], "持ち去る": [96.08, 1.17], "踏み切る": [97.65, 1.205], "崩れ去る": [99.255, 1.165], "立ち去る": [100.82, 1.17], "盗み出す": [102.39, 1.375], "付け込む": [104.165, 1.26], "見逃す": [105.825, 1.24], "居直る": [107.465, 1.095]}, "d121": {"勝たんがためには手段を選ばない――そう言い切る指導者は今も少なくない。だが、記録を出さんがために睡眠を削り、くたくたになるまで走り込む練習が、本当に選手を強くするのだろうか。ある高校の陸上部の監督は、数年前から方針を大きく変えた。練習量を三割減らし、その代わりに選手には夜十時までに床に就くよう求めたのである。当初は保護者から「甘すぎる」という批判も出たが、ぐっすり眠れるようになった選手たちは、練習中にぐったりすることが減り、けがも目に見えて少なくなった。そして昨季、チームは創部以来初めて全国大会への出場を果たした。勝利を目指すこと自体は悪くない。問われるべきは、その目的のために何を犠牲にしているかである。": [0.0, 53.665], "最近、残業続きでへとへとだよ。": [54.065, 3.47], "それなのに、昇進試験に合格せんがため、毎晩遅くまで勉強してるんだって？": [57.935, 6.735], "うん。でも、電車でついうとうとしちゃって、全然頭に入らないの。": [65.07, 5.815], "それじゃ本末転倒だよ。まずはぐっすり寝たほうがいいって。": [71.285, 4.635], "真実を明らかにせんがため、記者は十年にわたって取材を続けた。": [76.32, 5.7], "生き残らんがために、企業は次々と新しい事業に手を広げている。": [82.42, 5.545], "彼は自分の主張を通さんがための嘘を重ねた。": [88.365, 3.855], "N1に合格せんがため、毎朝五時に起きて勉強している。くたくたになる日もあるが、その分、夜はぐっすり眠れる。": [92.62, 9.875], "優勝せんがため、彼らは一年間一日も休まず練習した。": [102.895, 5.305], "健康のために、毎朝三十分歩いている。": [108.6, 3.85], "うんざり": [112.85, 1.075], "げっそり": [114.325, 1.085], "ぐったり": [115.81, 1.11], "くたくた": [117.32, 1.285], "へとへと": [119.005, 1.315], "ぐっすり": [120.72, 1.085], "うとうと": [122.205, 1.165], "すやすや": [123.77, 1.32]}, "d122": {"人手不足を解消すべく、ある温泉町の老舗旅館が昨年から週休三日制を導入した。従業員の休みを増やせばサービスの質が落ちるのではないか、という懸念は当初からあった。ところが、実際にはその逆の結果が出ている。十分に休めるようになった従業員は、接客の際にもきびきびと動き、客の細かな要望にもてきぱきと応じるようになったという。宿泊客へのアンケートでも「スタッフの対応が気持ちよい」という声が目立って増えた。女将は「休みを取ることをぐずぐずと先延ばしにしてきたのは、むしろ経営する側でした」と振り返る。この試みを地域全体に広めるべく、町の観光協会は他の旅館にも見学を呼びかけている。": [0.0, 50.81], "新しいシステムを今月中に導入すべく、来週から研修を始めます。": [51.21, 5.96], "承知しました。ただ、現場はまだ準備にもたもたしていて……。": [57.57, 5.075], "だからこそ、てきぱき進めてほしいんだ。延期の要望が来ても、きっぱり断ってくれ。": [63.045, 7.345], "わかりました。各チームのリーダーに今日中に連絡します。": [70.79, 4.54], "被災地の復興を支援すべく、多くのボランティアが現地に駆けつけた。": [75.73, 5.49], "彼は長年の夢を実現すべく、会社を辞めて留学した。": [81.62, 4.88], "消費者の信頼を回復すべく、同社は全製品の点検に乗り出した。": [86.9, 5.725], "業務の効率を上げるべく、会議の時間を半分に減らした。その結果、社員がてきぱきと動くようになった。": [93.025, 8.645], "新記録を出すべく、彼は練習量を倍に増やした。": [102.07, 4.365], "後ろの席の人にも聞こえるように、大きな声で話した。": [106.835, 4.74], "きっぱり": [111.975, 1.16], "てきぱき": [113.535, 1.24], "はきはき": [115.175, 1.275], "きびきび": [116.85, 1.225], "のろのろ": [118.475, 1.17], "ぐずぐず": [120.045, 1.19], "もたもた": [121.635, 1.235], "せかせか": [123.27, 1.48]}, "d123": {"近所の古い寺の門前に、「境内にてみだりに火気を使用すべからず」と書かれた立て札がある。墨の色はすっかり薄れているが、その文言には不思議な威厳がある。現代の看板なら、さしずめ「火気厳禁」とでも書くところだろう。考えてみれば、「〜べからず」という言い回しは、禁止の命令でありながら、どこか読む者の良心に訴えかける響きを持っている。一方、「欠くべからざる」という形は、今でも論文や式典のあいさつで目にすることがある。言葉は時代とともに移り変わるが、こうした古い形が細々とでも生き残っているのは、頭ごなしの禁止とは違う、静かに人を戒める力を持っているからではないだろうか。": [0.0, 49.73], "先輩、この部室の張り紙、「無断で機材を持ち出すべからず」って書いてありますね。": [50.13, 7.25], "ああ、去年、勝手に持ち出して壊した人がいて、部長がかっとなって書いたの。": [57.78, 6.63], "実は昨日、少し借りちゃったんですけど……。なんだかひやひやしてきました。": [64.81, 5.71], "正直に言えば大丈夫だよ。そんなにびくびくしないで。": [70.92, 4.45], "芝生に立ち入るべからず。": [75.77, 2.135], "信頼は企業経営にとって欠くべからざる要素だ。": [78.305, 3.915], "公務員が賄賂を受け取るなど、許すべからざる行為である。": [82.62, 4.515], "夜十時以降、大声で騒ぐべからず。使った食器を流しに放置すべからず。家族の協力は、快適な生活に欠くべからざるものだ。": [87.535, 11.525], "関係者以外、立ち入るべからず。": [99.46, 2.91], "試験中に携帯電話を使ってはならない。": [102.77, 3.355], "ひやひや": [106.525, 1.245], "はらはら": [108.17, 1.235], "びくびく": [109.805, 1.23], "おどおど": [111.435, 1.15], "そわそわ": [112.985, 1.33], "いらいら": [114.715, 1.13], "むしゃくしゃ": [116.245, 1.33], "かっと": [117.975, 1.085]}, "d124": {"今年公開されたドキュメンタリー映画『海を渡る手紙』は、観る者の心を揺さぶらずにはおかない作品だ。戦後、離ればなれになった兄と妹が、半世紀以上にわたって交わした手紙をもとに構成されている。派手な演出は一切ない。ナレーションも最小限に抑えられ、手紙の文面と、年老いた妹の静かな語りだけで物語が進んでいく。それでも、兄の最後の手紙が読み上げられる場面では、客席のあちこちからすすり泣きが聞こえた。家族の絆とは何か、時代に翻弄されるとはどういうことか。監督はその答えをずばりと示すことはしない。だが、その問いは観終わった後も、観客の胸に重く残らずにはおかないだろう。": [0.0, 50.145], "部長、あの取引先、また支払いを遅らせておいて、しれっと追加注文してきたんですよ。": [50.545, 7.595], "ぬけぬけとよく言えたもんだな。今度ばかりは、きちんと説明させずにはおかないぞ。": [58.54, 6.635], "先方の担当者、ずけずけ物を言う人なので、少し心配です。": [65.575, 5.715], "心配いらない。私が直接話すから。": [71.69, 3.915], "彼の熱のこもった演説は、聴衆を感動させずにはおかなかった。": [76.005, 5.45], "今回の不祥事は、会社の将来に影響を与えずにはおかないだろう。": [81.855, 5.38], "事件の真相を明らかにしないではおかない、と刑事は誓った。": [87.635, 4.995], "この小説の結末は、読者を涙させずにはおかない。主人公の最後の一言が、ぐさっと胸に刺さった。": [93.03, 9.17], "その知らせは、人々を驚かせずにはおかない。": [102.6, 4.01], "その知らせを聞いて、驚かずにはいられなかった。": [107.01, 4.01], "ずけずけ": [111.42, 1.31], "ぬけぬけ": [113.13, 1.32], "しれっと": [114.85, 1.235], "ちゃっかり": [116.485, 1.19], "がらりと": [118.075, 1.065], "ずばり": [119.54, 1.045], "ぐさっと": [120.985, 1.09], "ぴしゃりと": [122.475, 1.055]}, "d125": {"卒業生の皆さん、ご卒業おめでとうございます。三年前、緊張した面持ちで入学式に臨んだ皆さんの姿を、昨日のことのように思い出します。この三年間、皆さんは感染症の流行という、誰も経験したことのない困難に直面しました。行事は次々と中止になり、友人と顔を合わせることさえままならない日々が続きました。それでも皆さんは、画面越しに励まし合い、できる形で学びを続けてきました。その姿に、私たち教職員こそ、人の強さをひしひしと感じさせられたのです。これから歩む道には、思いがけない壁もあるでしょう。しかし、この三年間を乗り越えた皆さんなら、きっと大丈夫です。皆さんの未来が希望に満ちたものであることを、心から願ってやみません。": [0.0, 56.355], "昨日の卒業式、校長先生のスピーチ、じんときたね。": [56.755, 5.36], "うん。「心から願ってやみません」ってところで、思わずほろりとしちゃった。": [62.515, 6.175], "三年間、いろいろあったもんな。つくづく、いい仲間に恵まれたと思うよ。": [69.09, 6.29], "ほんとだね。卒業しても、ときどき集まろうよ。": [75.78, 4.43], "私が尊敬してやまない恩師は、昨年九十歳を迎えた。": [80.61, 5.075], "両国の関係が、今後さらに発展することを期待してやみません。": [86.085, 5.39], "彼は生涯、故郷の海を愛してやまなかった。": [91.875, 3.975], "先生のご健康とますますのご活躍を、心よりお祈りしてやみません。": [96.25, 5.95], "皆様のご健康を、心よりお祈りしてやみません。": [102.6, 4.345], "明日の面接の結果が気になってならない。": [107.345, 3.33], "ほのぼの": [111.075, 1.225], "しみじみ": [112.7, 1.26], "うっとり": [114.36, 1.085], "しんみり": [115.845, 1.205], "じんと": [117.45, 1.1], "ほろりと": [118.95, 1.085], "つくづく": [120.435, 1.205], "ひしひし": [122.04, 1.275]}, "d127": {"「失敗の数なら誰にも負けない」――ベンチャー企業を率いる石田氏は、そう公言してはばからない。二十代で起こした最初の会社はわずか二年で倒産し、その後も手がけた事業の多くが軌道に乗らなかった。周囲からは陰でひそひそと噂され、面と向かって「もうやめたらどうか」とくどくど説教されたこともあるという。それでも氏は、失敗を隠そうとはしなかった。むしろ、何がうまくいかなかったのかを社員や投資家に包み隠さず語り、次の挑戦に生かしてきた。現在の会社は創業十年で従業員三百人を抱えるまでに成長した。失敗を恥じるより、失敗から学んだことを誇る。その姿勢こそが、氏の最大の強みなのかもしれない。": [0.0, 50.56], "隣の部署の山下さん、会議で「この企画は自分が一番よくわかってる」って言ってはばからないのよ。": [50.96, 8.425], "ああ、あの人ね。でも実際、資料を読むと説得力があるんだよな。": [59.785, 6.25], "それはそうなんだけど、言い方がね。若手がみんなぶつぶつ文句言ってるよ。": [66.435, 6.01], "実力はあるんだから、もう少し周りに配慮してくれたらいいのにね。": [72.845, 5.205], "彼は自分こそ次期社長にふさわしいと公言してはばからない。": [78.45, 4.795], "その評論家は、最近のドラマには見る価値がないと言ってはばからない。": [83.645, 5.47], "彼女は幼い頃から、世界一のシェフになると語ってはばからなかった。": [89.515, 5.815], "祖父は「若い者にはまだ負けない」と言ってはばからない。実際、毎朝五キロも歩いているのだから大したものだ。": [95.73, 9.22], "彼は自分が天才だと言ってはばからない。": [105.35, 3.225], "私は彼の才能を信じてやまない。": [108.975, 3.17], "ぺらぺら": [112.545, 1.175], "ぶつぶつ": [114.12, 1.21], "ぼそぼそ": [115.73, 1.3], "ひそひそ": [117.43, 1.345], "がやがや": [119.175, 1.2], "ざわざわ": [120.775, 1.235], "くどくど": [122.41, 1.26], "がみがみ": [124.07, 1.165]}, "d128": {"標高二千メートルを超える山の上に、その遺跡はあった。巨大な石を寸分の狂いもなく積み上げた城壁は、五百年以上の風雪に耐え、今なおその姿をとどめている。重機も鉄の道具もない時代に、人々はどうやってこれほどの石を運び上げたのか。案内人の説明を聞きながら、私は古代の人々の知恵と労力に、畏敬の念を禁じ得なかった。そのとき、ふと足元を見て、はっとした。崖の縁まで、あと数歩しかなかったのだ。ひやっとして後ずさりしながら、この険しい場所で暮らした人々の日常を想像した。自然を恐れ、敬い、それでも自然とともに生きる。その営みの重さを、石の一つ一つが静かに語っているようだった。": [0.0, 51.56], "ニュース見た？　あの火事で、小学生が隣の家のおばあさんを助け出したんだって。": [51.96, 6.425], "見た見た。まだ十歳なのにすごい勇気だよね。驚嘆の念を禁じ得ないって、ああいうときに使うんだろうね。": [58.785, 8.305], "僕なんて、煙を見ただけでぞっとしちゃうのに。": [67.49, 3.795], "二人ともけががなくて、本当にほっとしたよ。": [71.685, 3.875], "被害者の心情を思うと、同情の念を禁じ得ない。": [75.96, 4.275], "長年支えてくれた家族に、感謝の念を禁じ得ない。": [80.635, 4.51], "今回の判決には、疑問の念を禁じ得ない。": [85.545, 3.925], "災害の現場で働く人々の姿に、感謝の念を禁じ得ない。自分にも何かできることはないかと考えさせられた。": [89.87, 9.405], "彼の献身的な姿に、尊敬の念を禁じ得ない。": [99.675, 4.62], "彼の献身的な姿を見て、尊敬せずにはいられない。": [104.695, 4.82], "ぞっと": [109.915, 1.08], "ぎょっと": [111.395, 1.055], "はっと": [112.85, 1.085], "ぎくっと": [114.335, 1.095], "どきっと": [115.83, 1.075], "ひやっと": [117.305, 1.06], "ほっと": [118.765, 1.085], "すかっと": [120.25, 1.245]}, "d129": {"大学生の息子のことで相談したい。入学当初は真面目に授業に出ていたのだが、二年生の夏ごろから生活がだらだらと乱れ始めた。昼過ぎまで寝て、起きればごろごろしながらスマートフォンを眺めるばかり。注意しても「わかってる」と言うだけで、何も変わらない。そのうちアルバイトも無断で休むようになり、ついには必修科目の単位を落として、留年が決まるしまつだ。本人は「来年からは頑張る」と言うが、このままずるずると同じことを繰り返すのではないかと不安でならない。親としてどこまで口を出すべきなのか、それとも本人が自分で気づくまで待つべきなのか。同じような経験をされた方のご意見を伺いたい。": [0.0, 47.41], "弟がまた会社を辞めたって。今年に入ってもう三回目よ。": [47.81, 5.14], "え、またか。前の会社、半年ももたなかったよね。": [53.35, 5.195], "そうなの。しかも今度は次の仕事も決めずにぶらぶらしてて、挙げ句の果てに私にお金を借りに来るしまつ。": [58.945, 8.555], "それは困ったね。一度ちゃんと話したほうがいいんじゃない？": [67.9, 4.49], "彼は遅刻を繰り返し、とうとう大事な会議まですっぽかすしまつだ。": [72.79, 5.52], "隣の家の犬は一晩中ほえ続け、ついには近所から苦情が出るしまつだった。": [78.71, 6.21], "計画も立てずに旅に出た結果、帰りの電車賃までなくなるしまつだ。": [85.32, 5.725], "兄はダイエットを始めると言いながら毎晩お菓子を食べ、ついには夜中にラーメンまで作るしまつだ。": [91.445, 7.16], "彼は借金を重ね、ついには家まで手放すしまつだ。": [99.005, 4.635], "さんざん悩んだあげく、彼は家を手放すことにした。": [104.04, 4.225], "だらだら": [108.665, 1.145], "ごろごろ": [110.21, 1.175], "ずるずる": [111.785, 1.16], "ぶらぶら": [113.345, 1.155], "うろうろ": [114.9, 1.13], "ころころ": [116.43, 1.255], "ちょくちょく": [118.085, 1.33], "うかうか": [119.815, 1.26]}, "d130": {"企業の不祥事が明るみに出るたびに、深々と頭を下げる経営者の姿がテレビに映し出される。日本では、謝ることが誠意の証とされる傾向が強い。しかし最近、謝罪の中身の薄さが目につく。原因の説明も再発防止策もないまま、ただぺこぺこと頭を下げ、「誠に申し訳ございません」を繰り返すだけの会見も少なくない。あるコメンテーターは「形だけの謝罪にもほどがある」と厳しく批判した。謝罪とは本来、自らの過ちを認め、その責任をどう取るのかを示す行為のはずだ。頭を下げる角度や時間ばかりが注目される現状は、謝る側にとっても、謝られる側にとっても不幸なことではないだろうか。": [0.0, 50.46], "課長、また会議に三十分も遅れて来たのよ。しかもへらへら笑ってるの。": [50.86, 6.27], "遅刻するにもほどがあるよね。今月もう四回目だよ。": [57.53, 4.485], "それなのに、部長の前ではぺこぺこしてるんだから。": [62.415, 4.24], "まあ、陰でぐちぐち言っててもしょうがないし、一度はっきり伝えてみようか。": [67.055, 6.145], "冗談にもほどがある。人の気持ちを考えなさい。": [73.6, 4.215], "ビジネスホテルで一泊十万円だなんて、高いにもほどがある。": [78.215, 4.845], "約束を三回も忘れるなんて、いい加減にもほどがある。": [83.46, 4.63], "友達が二時間も遅れて来たのに、謝りもしなかった。マイペースにもほどがある。": [88.49, 6.365], "人をからかうにもほどがある。": [95.255, 2.235], "この料理は塩が多すぎる。": [97.89, 2.195], "べたべた": [100.485, 1.22], "ちやほや": [102.105, 1.275], "いちゃいちゃ": [103.78, 1.225], "ねちねち": [105.405, 1.225], "ぐちぐち": [107.03, 1.23], "へらへら": [108.66, 1.235], "ぺこぺこ": [110.295, 1.355], "めそめそ": [112.05, 1.315]}, "d131": {"先週末、友人に誘われて、山あいの小さな温泉宿に泊まった。駅から送迎バスで四十分、携帯の電波もろくに届かない場所である。正直なところ、到着するまでは不安だった。だが、宿に着いた途端、そんな不安は吹き飛んだ。まず、露天風呂からの眺めの美しさといったらない。目の前には紅葉に染まった渓谷が広がり、聞こえるのは川のせせらぎだけだ。湯はとろりとしていて、上がった後は肌がしっとりと潤った。夕食に出た山菜の天ぷらも、衣が軽く、塩だけでいくらでも食べられた。日頃の疲れがすっきり取れた二日間だった。帰りの電車の中で、気づけばもう次の予約のことを考えている自分がいた。": [0.0, 50.045], "すみません、このシャンプー、試してみてもいいですか。": [50.445, 4.57], "どうぞ。洗い上がりのさらさら感といったらないですよ。": [55.415, 4.235], "私、髪が傷んでいて、いつもざらざらなんです。": [60.05, 4.51], "でしたら、こちらのトリートメントと一緒にお使いいただくと、しっとりまとまりますよ。": [64.96, 6.52], "一人で夜道を歩いたときの心細さといったらなかった。": [71.88, 4.27], "初めて富士山の頂上から見た朝日の美しさといったらない。": [76.55, 4.705], "暖房が壊れたこの部屋の寒いことといったらない。": [81.655, 3.81], "運動のあとに飲んだ冷たい水のおいしさといったらなかった。汗をたっぷりかいて、気分もすっきりした。": [85.865, 7.67], "合格を知ったときの嬉しさといったらなかった。": [93.935, 3.55], "彼の態度は失礼極まりない。": [97.885, 2.62], "さっぱり": [100.905, 1.225], "すっきり": [102.53, 1.225], "しっとり": [104.155, 1.215], "さらさら": [105.77, 1.31], "つるつる": [107.48, 1.205], "ざらざら": [109.085, 1.215], "ねばねば": [110.7, 1.21], "べとべと": [112.31, 1.22]}, "d132": {"子どもの頃に通った駅前の商店街を、二十年ぶりに歩いた。かつては八百屋や魚屋がずらりと並び、夕方になると買い物客で歩くのもやっとだった通りである。ところが今は、シャッターを下ろした店ばかりで、通りはがらんとしている。昔よく通った駄菓子屋も、色あせた看板だけがぽつんと残っていた。寂しいかぎりだ。ただ、歩いているうちに、古い店舗を改装したカフェや雑貨店がちらほらと目に入ってきた。話を聞くと、都会から移り住んだ若者たちが、空き店舗を安く借りて開いた店だという。町の姿は変わっても、新しい芽が確かに育ち始めている。それを知って、何とも心強いかぎりであった。": [0.0, 48.285], "引っ越しの手伝いに来てくれて、本当にありがとう。助かったよ。": [48.685, 5.59], "いいのいいの。それにしても、本がぎっしり詰まった段ボール、二十箱もあったね。": [54.675, 6.745], "一人だったらどうなってたか。頼れる友達がいるのは、ありがたいかぎりだよ。": [61.82, 5.955], "じゃあ、今度ご飯おごってね。": [68.175, 2.67], "長年の研究がようやく認められ、うれしいかぎりです。": [71.245, 4.505], "知り合いが一人もいない土地での生活は、心細いかぎりだった。": [76.15, 5.125], "決勝戦を目前にしての主力選手のけがは、残念なかぎりだ。": [81.675, 5.17], "親友が遠くへ引っ越してしまい、寂しいかぎりだ。いつも二人で座った公園のベンチも、なんだかぽつんと見える。": [87.245, 9.015], "皆様に祝っていただき、うれしいかぎりです。": [96.66, 3.725], "喉が渇いてたまらない。": [100.785, 1.99], "ぽつんと": [103.175, 1.24], "がらんと": [104.815, 1.175], "ひっそり": [106.39, 1.115], "ぎっしり": [107.905, 1.085], "びっしり": [109.39, 1.065], "ずらりと": [110.855, 1.21], "どっさり": [112.465, 1.065], "ちらほら": [113.93, 1.25]}, "d134": {"十年前、旅先のパリの小さな古書店で、私は一冊の古い日本語の詩集を手に取った。ページを開くと、余白に鉛筆で書き込みがある。どこか見覚えのある筆跡だった。驚いて裏表紙を見ると、亡くなった祖父の名前が記されていた。祖父は若い頃、仕事でフランスに暮らしていたことがある。そのときに手放した本が、半世紀以上の時を経て、偶然ふらりと立ち寄った孫の手に戻ってきたのだ。これが運命でなくてなんだろう。店主に事情を話すと、彼は黙ってうなずき、代金を受け取ろうとしなかった。その詩集は今も私の書斎にある。ページをめくるたびに、写真でしか知らない若き日の祖父と、言葉を交わしている気がする。": [0.0, 49.865], "昨日、駅で高校の時の担任の先生にばったり会ったの。": [50.265, 4.95], "へえ、偶然だね。何年ぶり？": [55.615, 3.21], "十五年ぶり。しかも先生、私が卒業の時に書いた作文を、今も取っておいてくれたんだって。": [59.225, 8.495], "それこそ、教師の愛情でなくてなんだろう、って感じだね。": [68.12, 5.095], "命をかけて子を守る親の姿、これが愛でなくてなんだろう。": [73.615, 5.045], "千人に一人という難病から回復したのは、奇跡でなくてなんであろうか。": [79.06, 5.715], "弱い立場の人から搾取し続けることが、罪でなくてなんだろうか。": [85.175, 5.435], "道に迷ってひょいと入った店で、今の妻と出会った。これが運命でなくてなんだろう。": [91.01, 6.775], "二人が三十年ぶりに再会できたのは、運命でなくてなんだろう。": [98.185, 5.075], "今回の成功は、社員一人一人の努力にほかならない。": [103.66, 4.74], "ばったり": [108.8, 1.09], "ひょっこり": [110.29, 1.16], "ふらりと": [111.85, 1.07], "ひょいと": [113.32, 1.09], "ぱっと": [114.81, 1.05], "さっと": [116.26, 1.15], "すっと": [117.81, 1.15], "ぴたりと": [119.36, 1.04]}, "d135": {"八月三十一日。夏休みも今日で終わりだ。七月の初めには、計画表をびっしりと書いた。英単語を千個覚える、小説を五冊読む、祖母の家に一人で行く――。だが振り返ってみると、達成できたのは祖母の家に行くことくらいで、単語帳は最初の十ページで止まり、図書館で借りた小説も結局一冊も読まずじまいだった。毎日のほほんと過ごしているうちに、気がつけば八月も終わり。今になってあたふたしても、もう遅い。正直、自分にほとほと嫌気がさす。それでも、祖母と縁側で過ごした数日間は、今年の夏いちばんの思い出になった。来年こそは、計画を半分に減らしてでも、最後までやり遂げたい。": [0.0, 50.455], "先週の京都旅行、どうだった？": [50.855, 2.995], "それが、楽しみにしてた有名なお寺、行列がすごくて結局入れずじまいだったんだ。": [54.25, 7.065], "えー、それはがっかりだね。": [61.715, 2.495], "うん。うっかり予約するのを忘れてたんだよ。次はちゃんと調べてから行くよ。": [64.61, 5.995], "忙しさにかまけて、恩師にお礼の手紙を書かずじまいになってしまった。": [71.005, 5.695], "せっかく買った高い服も、一度も着ずじまいでサイズが合わなくなってしまった。": [77.1, 6.01], "彼が会社を辞めた本当の理由は、とうとう聞けずじまいだった。": [83.51, 5.005], "留学中に一度はオーロラを見たかったが、天気に恵まれず、結局見られずじまいだった。今思い出してもがっくりする。": [88.915, 9.225], "憧れの先輩に気持ちを伝えられずじまいで卒業した。": [98.54, 4.315], "電気をつけないまま寝てしまった。": [103.255, 2.475], "うっかり": [106.13, 1.105], "がっかり": [107.635, 1.13], "がっくり": [109.165, 1.13], "げんなり": [110.695, 1.09], "ほとほと": [112.185, 1.315], "まごまご": [113.9, 1.21], "あたふた": [115.51, 1.2], "のほほんと": [117.11, 1.39]}, "d136": {"十五日未明、市内の私立美術館から江戸時代の掛け軸二点が盗まれた事件で、警察は現場付近の防犯カメラの映像を公開した。映像には、午前二時ごろ、美術館の裏口付近をきょろきょろと見回しながら歩く、三十代とおぼしき男の姿が映っている。男は黒っぽい上着を着て帽子を目深にかぶり、細長い筒状の荷物を抱えていた。警察によると、裏口の鍵は特殊な工具でこじ開けられた形跡があり、館内の事情に詳しい者による犯行の可能性もあるとみて捜査を進めている。美術館は当面休館し、警備体制を全面的に見直すとしている。警察は、心当たりのある人は最寄りの警察署まで情報を寄せてほしいと呼びかけている。": [0.0, 51.91], "さっきから、あの人、こっちをちらちら見てない？": [52.31, 4.335], "え、どの人？　ああ、観光客とおぼしき人だね。地図を持ってきょろきょろしてる。": [57.045, 6.88], "道に迷ってるのかも。声をかけてみようか。": [64.325, 3.875], "そうだね。英語、通じるかな。": [68.6, 3.27], "現場には、犯人のものとおぼしき足跡が残されていた。": [72.27, 4.605], "会場には、大学生とおぼしき若者が大勢集まっていた。": [77.275, 4.93], "部屋の奥から、子どもが泣いているとおぼしき声が聞こえてきた。": [82.605, 4.72], "公園のベンチに会社員とおぼしき男性が座り、手にした古い写真をしげしげと眺めていた。": [87.725, 6.955], "四十代とおぼしき女性が、店に入ってきた。": [95.08, 3.975], "隣に引っ越してきたのは、四十代の女性らしい。": [99.455, 4.3], "ちらちら": [104.155, 1.26], "じろじろ": [105.815, 1.21], "きょろきょろ": [107.425, 1.255], "まじまじ": [109.08, 1.18], "しげしげ": [110.66, 1.345], "こそこそ": [112.405, 1.415], "こっそり": [114.22, 1.115], "ぬっと": [115.735, 1.05]}, "d137": {"国民の生活を守るべき大臣ともあろう者が、自らの政治資金の使い道について満足に説明できないとは、あきれるほかない。今回明らかになったのは、数年にわたり、後援会の飲食費として多額の資金が計上されていたという事実である。大臣は記者会見で「秘書に任せていたので知らなかった」と述べ、翌日にはけろりとした表情で国会に姿を見せた。政治家の言葉がこれほど軽く扱われるなら、国民の政治不信が深まるのも無理はない。説明責任とは、問われたときに答えることではなく、問われる前に自ら明らかにすることだ。政府はこの問題をうやむやにせず、第三者による調査を速やかに行うべきである。": [0.0, 49.655], "聞いたか。経理部の課長が、取引先との会食の帰りに大事な書類をなくしたらしい。": [50.055, 7.225], "えっ、あの課長ともあろう人が、ですか。": [57.68, 3.73], "ああ。しかも翌日、本人はけろりとしていたそうだ。おかげで部内がぴりぴりしてるよ。": [61.81, 7.15], "信じられません。私たちも気を引き締めないといけませんね。": [69.36, 4.8], "医者ともあろう者が、患者の前で煙草を吸うなんて。": [74.56, 4.195], "一流ホテルともあろうところが、こんな初歩的なミスをするとは信じられない。": [79.155, 5.815], "裁判官ともあろう人が、法を軽んじる発言をするべきではない。": [85.37, 5.235], "プロの料理人ともあろう者が、賞味期限の切れた材料を使っていたとは驚いた。その話が広まってから、店の雰囲気もぎすぎすしている。": [91.005, 10.975], "校長ともあろう人が、生徒の名前を何度も間違えるとは。": [102.38, 4.935], "校長ともなると、人前で話す機会がぐっと増える。": [107.715, 4.39], "ころっと": [112.505, 1.175], "けろりと": [114.08, 1.205], "しゃあしゃあと": [115.685, 1.27], "ぐらぐら": [117.355, 1.175], "ぴりぴり": [118.93, 1.105], "ぎすぎす": [120.435, 1.25], "ぎくしゃく": [122.085, 1.25], "もやもや": [123.735, 1.195]}, "d138": {"高齢化が進む中、介護の現場は深刻な人手不足に陥っている。その最大の原因の一つが、仕事の重さに見合わない賃金の低さだ。介護職員は、利用者の食事や入浴の手助けから、体調の小さな変化への気配りまで、毎日せっせと働いている。夜勤もあり、心身の負担は決して小さくない。それにもかかわらず、平均賃金は全産業の平均を大きく下回っている。社会を支える仕事に就く人々は、それにふさわしい報酬を受けてしかるべきだ。国は介護報酬の引き上げを検討しているというが、その効果が現場の職員の給与にまで確実に届く仕組みでなければ意味がない。人手不足はじわじわと進み、気づいたときには手遅れになりかねない。": [0.0, 52.6], "田中さん、入社三年目なのに、もう大きなプロジェクトを任されてるんだって。": [53.0, 6.06], "毎日こつこつ勉強して、実力をめきめき伸ばしてきたからね。評価されてしかるべきだよ。": [59.46, 7.3], "でも、給料はほかの同期と同じなんでしょ？": [67.16, 3.695], "そこなんだよ。成果に応じた待遇があってしかるべきだと思うんだけどな。": [71.255, 5.57], "被害を受けた住民には、十分な補償がなされてしかるべきだ。": [77.225, 4.97], "子どもの安全に関わることなのだから、もっと早く対策が取られてしかるべきだった。": [82.595, 6.32], "彼の長年の功績は、もっと高く評価されてしかるべきだ。": [89.315, 4.995], "子育て中の親が、もっと気軽に休みを取れる制度があってしかるべきだ。そうすれば、出生率もじわじわと回復するのではないか。": [94.71, 10.375], "努力した人は、正当に報われてしかるべきだ。": [105.485, 4.11], "約束は守るべきだ。": [109.995, 2.0], "こつこつ": [112.395, 1.26], "せっせと": [114.055, 1.26], "ばりばり": [115.715, 1.1], "めきめき": [117.215, 1.245], "ぐんぐん": [118.86, 1.06], "じわじわ": [120.32, 1.23], "ちまちま": [121.95, 1.305], "もりもり": [123.655, 1.115]}, "d139": {"市民交流センター利用規約（抜粋）\n第五条　施設の利用を希望する者は、利用日の一か月前から七日前までに、所定の申請書を提出するものとする。\n第六条　利用者は利用時間を厳守し、終了時刻までに室内を原状に復するものとする。\n第七条　利用者の責めに帰すべき事由により施設又は備品を損傷した場合、利用者はその損害を賠償するものとする。\n第八条　次の各号のいずれかに該当するとき、センターは利用の許可を取り消すことができる。\n一　申請の内容と実際の利用目的が異なるとき。\n二　他の利用者に著しい迷惑を及ぼすおそれがあるとき。\n第九条　前条の規定により利用の許可を取り消した場合、既に納付された使用料は返還しないものとする。": [0.0, 53.67], "来月、センターの会議室を借りたいんですが、申し込みは当日でも大丈夫ですか。": [54.07, 6.805], "申し訳ありません。規約で、利用日の七日前までに申請書を提出するものとする、と決まっておりまして。": [61.275, 8.62], "そうですか。じゃあ、ざっと日程を確認して、今週中に出します。": [70.295, 5.955], "はい。それから、終了時刻はきっちり守っていただくようお願いいたします。": [76.65, 6.235], "本契約の有効期間は一年とし、双方に異議がない場合は自動的に更新されるものとする。": [83.285, 7.925], "会員は、住所に変更があった場合、速やかに届け出るものとする。": [91.61, 5.89], "期限までに回答がない場合は、同意したものとする。": [97.9, 4.195], "共用スペースを使用した者は、使用後に元の状態に戻すものとする。ゴミは各自で分別して出すものとする。": [102.495, 8.96], "正当な理由なく欠席した者は、棄権したものとする。": [111.855, 4.61], "明日から毎朝三十分走ることにする。": [116.865, 3.47], "きっちり": [120.735, 1.175], "ぴったり": [122.31, 1.105], "ちぐはぐ": [123.815, 1.235], "ばらばら": [125.45, 1.155], "すんなり": [127.005, 1.185], "あっさり": [128.59, 1.06], "ざっと": [130.05, 1.08], "じっくり": [131.53, 1.155]}, "d141": {"胃の内視鏡検査を受けられる方へ\n検査前日の夕食は、午後九時までに軽めに済ませてください。それ以降は、水やお茶などの透明な飲み物であれば、飲んでもさしつかえありません。ただし、牛乳やジュース、アルコール類はお控えください。\n普段服用しているお薬については、検査当日の朝は原則として飲まないでください。ただし、血圧の薬など医師から指示があったものは、少量の水で服用してもさしつかえありません。\n検査後、喉に軽い違和感やひりひりとした痛みが残ることがありますが、通常は一日ほどで治まります。また、麻酔の影響でふらふらすることがありますので、当日の車の運転はお控えください。ご不明な点は、受付までお問い合わせください。": [0.0, 51.815], "熱は下がりましたね。まだ頭がずきずきしますか。": [52.215, 4.21], "いえ、もうほとんど治りました。明日から仕事に行ってもいいでしょうか。": [56.825, 5.53], "ええ、行ってもさしつかえありませんよ。ただ、無理はしないでください。": [62.755, 5.79], "わかりました。お風呂も入ってかまいませんか。": [68.945, 3.68], "長湯をしなければ大丈夫です。": [73.025, 2.36], "下書きは鉛筆で書いてもさしつかえありません。": [75.785, 3.58], "印鑑がない場合は、署名でもさしつかえありません。": [79.765, 4.115], "会場が多少狭くてもさしつかえないので、駅から近い所を探してください。": [84.28, 6.27], "当日は私服でお越しいただいてもさしつかえありません。開始時刻に間に合わない場合も、途中からご参加いただいてもさしつかえございません。": [90.95, 10.265], "本日の会議には、オンラインでご参加いただいてもさしつかえございません。": [101.615, 5.545], "この部屋、自由に使ってもかまわないよ。": [107.56, 3.62], "ちくちく": [111.58, 1.21], "ずきずき": [113.19, 1.225], "ひりひり": [114.815, 1.165], "がんがん": [116.38, 1.06], "むずむず": [117.84, 1.185], "ふらふら": [119.425, 1.22], "くらくら": [121.045, 1.24], "ぞくぞく": [122.685, 1.285]}, "d142": {"十年前、機械翻訳といえば、意味の通らない奇妙な訳文の代名詞だった。ところが近年、人工知能の技術はぐんと進歩し、ビジネス文書程度であれば、ほぼ違和感のない訳が瞬時に得られるようになった。ある研究者は「現在の技術をもってすれば、旅行や日常会話で言葉の壁を感じることはほとんどなくなるだろう」と語る。では、外国語を学ぶ意味は失われるのだろうか。答えは否だろう。言葉の背後には、その言語を話す人々の歴史や価値観がどっしりと根を張っている。冗談の間合いや、言葉にされない遠慮を感じ取る力は、機械に任せきりにはできない。翻訳技術が進めば進むほど、自ら学んだ言葉で人と向き合うことの価値は、むしろ増していくのかもしれない。": [0.0, 53.915], "今度の新製品の開発、期限まであと二か月しかないんだよね。": [54.315, 5.275], "大丈夫ですよ。うちのチームの技術力をもってすれば、きっと間に合います。": [59.99, 5.935], "心強いね。君がチームをぐいぐい引っ張ってくれて助かってるよ。": [66.325, 5.15], "いえ、みんながしっかり支えてくれているおかげです。": [71.875, 4.04], "彼の語学力をもってすれば、海外の大学院への進学も難しくないだろう。": [76.315, 6.22], "最新の医療技術をもってすれば、この病気も十分に治療が可能だ。": [82.935, 5.65], "あのチームの団結力をもってすれば、優勝も夢ではない。": [88.985, 4.775], "姉の行動力をもってすれば、一人で世界一周旅行をすることも不可能ではないだろう。": [94.16, 6.56], "彼の実力をもってすれば、合格は確実だ。": [101.12, 4.2], "彼の実力をもってしても、合格は難しかった。": [105.72, 4.34], "ぐいぐい": [110.46, 1.105], "ずんずん": [111.965, 1.1], "ぐんと": [113.465, 1.075], "がっちり": [114.94, 1.145], "がっしり": [116.485, 1.085], "どっしり": [117.97, 1.065], "ずしりと": [119.435, 1.11], "ぴんと": [120.945, 1.07]}, "d143": {"二百年前に描かれたとされる絵巻物が、ある旧家の蔵から見つかった。しかし、長年湿気の多い場所に置かれていたため、紙はぼろぼろに傷み、一部は虫に食われて大きな穴が開いていた。修復を担当したのは、この道四十年の職人である。彼は貼り合わされた和紙を一枚ずつ丁寧にはがし、欠けた部分には色を合わせた新しい紙を補っていった。作業は二年に及んだ。だが、その熟練の技術をもってしても、失われた場面を元通りに再現することはできなかった。「足りない部分を想像で描き足すのは、修復ではなく創作になってしまう」と職人は言う。完成した絵巻物には今も空白が残る。その空白こそが、作品が歩んできた時間の証なのだという。": [0.0, 52.875], "このかばん、母から譲り受けたものなんですけど、もうぼろぼろで。": [53.275, 5.24], "拝見します。……革がかなり傷んでいますね。正直、当店の技術をもってしても、完全に元通りにするのは難しいかと。": [58.915, 10.36], "そうですか。でも、少しでもきれいになれば。": [69.675, 4.135], "かしこまりました。できる限りつやつやに仕上げてみますね。": [74.21, 4.565], "世界最高水準の医療をもってしても、彼の命を救うことはできなかった。": [79.175, 6.02], "天才と呼ばれた彼の頭脳をもってしても、この問題は解けなかった。": [85.595, 5.38], "どんな言葉をもってしても、この悲しみを言い表すことはできない。": [91.375, 5.035], "どんなに高価なクリームをもってしても、年齢による肌の変化を完全に止めることはできない。それでも、肌がつやつやになると気分は上がる。": [96.81, 10.635], "最新の技術をもってしても、地震を正確に予知するのは難しい。": [107.845, 5.715], "専門家でさえ、地震を正確に予知するのは難しい。": [113.96, 4.88], "ぼろぼろ": [119.24, 1.155], "よれよれ": [120.795, 1.18], "くしゃくしゃ": [122.375, 1.3], "ぴかぴか": [124.075, 1.215], "つやつや": [125.69, 1.285], "てかてか": [127.375, 1.36], "ちかちか": [129.135, 1.365], "ぎらぎら": [130.9, 1.175]}, "d144": {"日本の夏はむしむしと蒸し暑く、冬は乾燥して冷え込む。こうした気候に即した家づくりの知恵が、かつての民家にはあふれていた。深い軒は夏のじりじりとした日差しを遮り、冬の低い日の光は部屋の奥まで届ける。土壁は湿気を吸ったり吐いたりして、室内をじめじめさせない。ところが戦後、全国どこでも同じ規格の住宅が大量に建てられるようになり、それぞれの土地の気候に照らした工夫は次第に忘れられていった。近年、省エネルギーへの関心の高まりから、こうした伝統の知恵が改めて見直されている。最新の技術と昔ながらの工夫を組み合わせる。それこそが、これからの時代に即した住まいのあり方ではないだろうか。": [0.0, 49.345], "新しい防災マニュアル、全国共通のものをそのまま使うのはやめようと思うんだ。": [49.745, 6.315], "そうですね。この地域は川も近いですし、地域の実情に即した内容にすべきだと思います。": [56.46, 7.815], "うん。過去の水害の教訓に照らした避難計画も盛り込みたい。": [64.675, 5.115], "では、まず市の資料を集めてみます。": [70.19, 3.19], "現場の実態に即した指導が求められている。": [73.78, 3.665], "感情に流されず、法律に照らした公正な判断を下すべきだ。": [77.845, 5.42], "学習者のレベルに即した教材を作るのは、簡単なことではない。": [83.665, 5.48], "社員の働き方に即した勤務制度を導入し、過去のデータに照らした評価基準を設けるべきだ。": [89.545, 7.58], "時代に即した教育制度が必要だ。": [97.525, 3.18], "校則に照らした処分が下された。": [101.105, 2.85], "ひんやり": [104.355, 1.13], "ぽかぽか": [105.885, 1.36], "じりじり": [107.645, 1.155], "かんかん": [109.2, 1.145], "からっと": [110.745, 1.175], "じめじめ": [112.32, 1.255], "むしむし": [113.975, 1.245], "しとしと": [115.62, 1.3]}, "d145": {"創業百二十年を迎えた老舗の和菓子店。五代目の店主は、店を継いだ当初、売り上げの低迷に悩み、新しい商品を次々と打ち出したという。洋風の材料を取り入れた菓子は一時的に話題になったが、長年の常連客からは「昔の味が変わってしまった」と厳しい声が寄せられた。そのとき店主ははっと気づいたそうだ。「店は、通い続けてくださるお客様あってのものなんです」。以来、看板商品の製法には一切手を加えず、その代わりに包装や販売方法を工夫するようになった。九十歳を過ぎた先代も、今もぴんぴんしていて、毎朝あんこを炊いている。伝統とは何も変えないことではなく、守るべきものを見極めることなのだと、店主は穏やかに語った。": [0.0, 53.085], "今日は、優勝したチームのキャプテンにお話を伺います。おめでとうございます。": [53.485, 6.3], "ありがとうございます。この優勝は、最後まで応援してくださったファンの皆さんあってのものです。": [60.185, 7.28], "決勝では、一時は大差をつけられていましたね。": [67.865, 4.005], "ええ。でも、監督の一言で、みんなしゃきっと気持ちを切り替えられました。": [72.27, 6.375], "健康あっての人生だ。仕事もほどほどにしなさい。": [79.045, 4.395], "国民あっての国家であることを、政治家は忘れてはならない。": [83.84, 4.865], "今日の成功は、仲間の支えあってのことだ。": [89.105, 3.9], "今回の受賞は、いつも支えてくれた家族あってのものです。これからも初心を忘れず、しゃんとした姿勢で仕事に向き合っていきます。": [93.405, 10.35], "お客様あっての商売です。": [104.155, 2.3], "お客様が来てくださるからこそ、商売が成り立つのです。": [106.855, 4.79], "ぴんぴん": [112.045, 1.07], "しゃきっと": [113.515, 1.34], "しゃんと": [115.255, 1.18], "ぴりっと": [116.835, 1.125], "つんと": [118.36, 1.135], "ぷんぷん": [119.895, 1.07], "むっと": [121.365, 1.05], "かちんと": [122.815, 1.125]}, "d146": {"二歳になる娘が、最近何でも自分でやりたがる。靴を履くのも、スプーンを使うのも、手を貸そうとすると「じぶんで！」と怒る。時間のない朝などは、正直つい手を出したくなる。だが、ある日、玄関でよちよちと靴を履こうとする娘をじっと待っていると、左右は逆だったものの、ちゃんと自分の力で履き終えた。そして、誇らしげに私の顔を見上げたのである。子どもは子どもなりに考え、悩み、挑戦しているのだ。大人の目から見れば不器用でも、そこには娘なりの工夫がある。完璧を求めるのではなく、その小さな努力を見守ること。それが、親としての私なりの答えになりつつある。": [0.0, 49.02], "先生、レポート、自分なりに一生懸命書いてみたんですが、見ていただけますか。": [49.42, 7.04], "もちろん。……うん、構成はしっかりしているね。ただ、結論が少し弱いかな。": [56.86, 6.76], "やっぱり。最後のほうは、締め切り前でばたばたして書いてしまって。": [64.02, 5.64], "君なりの意見を、もう少しはっきり書いてごらん。": [70.06, 3.835], "経験が浅いなりに、彼はよく頑張っている。": [74.295, 3.855], "子どもには子どもなりの悩みがあるものだ。": [78.55, 3.035], "給料は多くないが、少ないなりに工夫して暮らしている。": [81.985, 4.355], "日本語はまだ完璧ではないが、私なりに毎日少しずつ勉強を続けている。散歩のときも、てくてく歩きながら単語を覚えている。": [86.74, 10.6], "新人は新人なりに、自分にできることを探している。": [97.74, 4.5], "新人らしく、元気よくあいさつをした。": [102.64, 3.445], "よちよち": [106.485, 1.24], "とぼとぼ": [108.125, 1.22], "すたすた": [109.745, 1.29], "のそのそ": [111.435, 1.315], "てくてく": [113.15, 1.24], "ちょこちょこ": [114.79, 1.455], "ばたばた": [116.645, 1.22], "ぶらりと": [118.265, 1.165]}, "d148": {"ある美術館の片隅に、一枚の小さな肖像画が掛けられている。描かれているのは、名も知られていない若い女性だ。その口元には、笑みとも憂いともつかない表情がほんのりと浮かんでいる。正面から見ると穏やかに微笑んでいるようだが、少し離れて眺めると、どこか寂しげにも見える。私はその前で、気づけば三十分近くもぼうっと立ち尽くしていた。画家はこの女性に何を見たのだろうか。説明板には、制作年も画家の名も「不詳」とあるだけだった。わからないからこそ、見る者はそれぞれの物語をそこに重ね合わせる。答えのない問いを投げかけ続けること、それこそが優れた芸術の力なのかもしれない。": [0.0, 49.055], "ねえ、さっきの部長の「考えておくよ」って、オッケーってこと？": [49.455, 6.195], "さあね。賛成とも反対ともつかない返事だったからなあ。": [56.05, 4.91], "最後に、ぼそっと「予算がね」って言ってたのも気になる。": [61.36, 5.325], "うん。もう一度、具体的な数字を持って相談に行ったほうがいいかもね。": [67.085, 5.895], "彼は冗談とも本気ともつかない口調で、「会社を辞める」と言った。": [73.38, 5.75], "夕暮れの空は、赤とも紫ともつかない不思議な色に染まっていた。": [79.53, 5.52], "森の奥から、鳥とも獣ともつかない鳴き声が聞こえてきた。": [85.45, 5.02], "試験の結果を聞いた友人は、安心とも落胆ともつかない顔で、ぽつりと「まあまあかな」と言った。": [90.87, 8.69], "彼女は、喜びとも悲しみともつかない表情を浮かべた。": [99.96, 4.88], "窓の外を見るともなく見ていた。": [105.24, 2.655], "ぼんやり": [108.295, 1.08], "ぼうっと": [109.775, 1.115], "ぼそっと": [111.29, 1.205], "ぽつりと": [112.895, 1.135], "ほんのり": [114.43, 1.12], "うっすら": [115.95, 1.115], "にやりと": [117.465, 1.19], "にんまり": [119.055, 1.095]}, "d149": {"人気のラーメン店の前に、早朝から長い行列ができている。開店は十一時だが、先頭の客は朝六時から並んでいるという。中には、会社を早退までして駆けつけたという人もいた。そこまでして食べたいのかと驚く人もいるだろう。しかし、並んだ人たちに話を聞くと、その答えは意外にもさっぱりしている。「待つ時間も含めて楽しいんですよ」。確かに、一杯のラーメンをぺろりと平らげて店を出てくる人々の顔は、どこか満ち足りている。手間をかけずに何でもすぐ手に入る時代だからこそ、苦労して手に入れることそのものに価値を見いだす人が増えているのかもしれない。行列とは、現代人のささやかな冒険なのだろう。": [0.0, 48.45], "聞いた？　佐藤さん、コンサートのチケット代のために、借金までしたんだって。": [48.85, 6.535], "えっ、そこまでして行きたいの？": [55.785, 2.61], "一生に一度のチャンスだって言ってたよ。": [58.795, 3.01], "気持ちはわかるけど、借金までして行くのはちょっとね。": [62.205, 4.39], "彼は徹夜までして、締め切りに間に合わせた。": [66.995, 3.855], "整形手術までしてオーディションに臨んだが、結果は不合格だった。": [71.25, 5.24], "友人を裏切るようなことまでして、出世したいとは思わない。": [76.89, 4.735], "友人は人気のパンを買うために、早起きまでして店に並んだ。焼きたてのパンをぱくぱく食べる姿は、本当に幸せそうだった。": [82.025, 9.915], "借金までして家を買う必要はない。": [92.34, 2.99], "借金をしてまで家を買う必要はない。": [95.73, 3.045], "がつがつ": [99.175, 1.23], "ぱくぱく": [100.805, 1.24], "ちびちび": [102.445, 1.245], "ごくごく": [104.09, 1.25], "ぺろりと": [105.74, 1.05], "がぶがぶ": [107.19, 1.16], "むしゃむしゃ": [108.75, 1.315], "ほくほく": [110.465, 1.275]}, "d151": {"春の空ほど移り気なものはない。朝から晴れ渡っていたかと思うと、昼過ぎには急に雲が広がり、冷たい雨が降り出す。慌てて傘を買えば、今度はあっという間に日が差してくる。こうした気まぐれな天気に、私たちはつい頭を抱えてしまう。しかし考えてみれば、人の心もまた同じではないか。喜んでいたかと思うと、ささいな一言で落ち込む。固く決意したかと思えば、翌日にはもう迷っている。そうした揺れを欠点とみなすのではなく、季節の移ろいのように自然なものとして受け止められれば、少しは生きやすくなるだろう。春の天気に本気で腹を立てる人がいないように、自分の心の変化にも寛容でありたいものだ。": [0.0, 48.915], "部長、また会議の時間が変わったんですか。": [49.315, 3.795], "うん、先方が午前にするって言ったかと思えば、今度は夕方がいいって。": [53.51, 5.915], "それじゃ資料の準備が追いつきませんよ。正直、頭を抱えちゃいます。": [59.825, 5.9], "まあ、大事な取引先の顔を立てるためだから、ここは我慢してくれ。": [66.125, 5.905], "息子は帰ってきたかと思うと、すぐにまた遊びに出かけた。": [72.43, 4.81], "空がぴかっと光ったかと思えば、激しい雷鳴がとどろいた。": [77.64, 4.88], "新制度に賛成する社員がいるかと思えば、強く反発する社員もいる。": [82.92, 5.845], "うちの猫は甘えてきたかと思うと、急にそっぽを向いてしまう。気まぐれな態度に毎日頭を抱えている。": [89.165, 8.225], "妹は泣いていたかと思うと、もうけらけら笑っている。": [97.79, 4.375], "家を出たとたん、雨が降り出した。": [102.565, 2.83], "頭が上がらない": [105.795, 1.575], "頭が切れる": [107.77, 1.395], "頭を抱える": [109.565, 1.545], "頭を冷やす": [111.51, 1.435], "顔が広い": [113.345, 1.255], "顔を立てる": [115.0, 1.275], "腹が立つ": [116.675, 1.245], "目に余る": [118.32, 1.135]}, "d152": {"在宅勤務が定着して久しいが、その陰で失われたものもあるのではなかろうか。かつて職場では、休憩室での何気ない雑談から新しい企画が生まれることが少なくなかった。他部署の人の話に耳を傾けるうちに、自分の仕事の思わぬ欠点に気づくこともあった。画面越しの会議は効率的である反面、用件が済めばすぐに終わってしまい、そうした偶然の出会いが生まれにくい。もちろん、通勤の負担が減ったことの意義は大きい。だが、効率だけを物差しにして働き方を論じるのは、いささか早計ではなかろうか。週に一度でも職場に足を運び、顔を合わせて話す時間を設けることが、組織の活力を保つ鍵になるのではなかろうか。": [0.0, 50.185], "山田さん、例の企画書だけど、少し見直したほうがいいんじゃないかな。": [50.585, 5.79], "はい。実はお客様からも同じご指摘をいただいて、耳が痛いです。": [56.775, 5.81], "役員会でも、スケジュールに無理があるのではなかろうか、という声が出ていてね。": [62.985, 6.125], "わかりました。一度腰を据えて練り直します。": [69.51, 3.85], "このままでは、地方の公共交通は維持できなくなるのではなかろうか。": [73.76, 5.485], "彼が辞退した本当の理由は、健康問題ではなかろうか。": [79.645, 4.935], "子どもに必要なのは、立派な設備より安心できる居場所ではなかろうか。": [84.98, 5.66], "若者の政治離れが指摘されて久しい。しかし問題は若者の側ではなく、彼らの声に耳を傾けてこなかった社会の側にあるのではなかろうか。": [91.04, 11.65], "この判断は少し性急ではなかろうか。": [103.09, 3.245], "この判断は少し性急ではあるまいか。": [106.735, 3.185], "耳が痛い": [110.32, 1.28], "耳を傾ける": [112.0, 1.62], "口が堅い": [114.02, 1.385], "口を挟む": [115.805, 1.375], "肩を持つ": [117.58, 1.25], "腰を据える": [119.23, 1.3], "手を焼く": [120.93, 1.085], "足を運ぶ": [122.415, 1.35]}, "d153": {"昨冬、取材で訪れた山あいの村で、記録的な大雪に見舞われた。一夜にして道路は雪に埋もれ、村を出ようにも出られない。電話もつながらず、外部に連絡しようにも連絡のしようがなかった。窓の外の白一色の景色を見たときには、正直、血の気が引いた。それでも村の人々は少しも慌てなかった。蓄えてあった野菜や味噌で温かい鍋をこしらえ、よそ者の私までもてなしてくれたのである。三日後、遠くから除雪車の音が聞こえたときには、皆で胸をなで下ろした。便利さに慣れた都会の暮らしでは、どうにもならない状況に身を置くことはまずない。あの三日間は、自然と折り合いをつけて生きる知恵を、私に教えてくれた。": [0.0, 50.665], "昨日の停電、大丈夫だった？": [51.065, 2.775], "全然。エレベーターが途中で止まって、降りようにも降りられなくて。": [54.24, 5.255], "えっ、閉じ込められたの？　それは血の気が引いたでしょう。": [59.895, 4.475], "うん、三十分くらい。助けが来たときは、本当に胸をなで下ろしたよ。": [64.77, 6.28], "熱が高くて、起きようにも起きられなかった。": [71.45, 3.68], "相手の連絡先を知らないので、謝ろうにも謝れない。": [75.53, 4.555], "周りがうるさすぎて、集中しようにもできない。": [80.485, 3.945], "台風で飛行機が欠航し、帰ろうにも帰れなかった。首を長くして待っていた家族には本当に申し訳なかった。": [84.83, 8.965], "財布を落として、電車に乗ろうにも乗れなかった。": [94.195, 3.865], "住所がわからないので、連絡しようがない。": [98.46, 3.64], "手が出ない": [102.5, 1.165], "手を尽くす": [104.065, 1.285], "手に負えない": [105.75, 1.2], "足が棒になる": [107.35, 1.51], "首を長くする": [109.26, 1.52], "胸をなで下ろす": [111.18, 1.515], "息を呑む": [113.095, 1.12], "血の気が引く": [114.615, 1.37]}, "d155": {"人気のパン屋の前に、開店前から長い列ができている。中には始発電車に乗ってまで並ぶ人もいるという。甘いものに目がない私も一度は並んでみようかと思ったが、二時間待ちと聞いて二の足を踏んでしまった。そこまでして手に入れる価値があるのかと、首をかしげる人も多いだろう。しかし、列に並ぶ人々の表情は意外にも明るい。待つ時間そのものがちょっとした冒険であり、手に入れた後の満足感を高めているのかもしれない。一方で、睡眠を削ってまで行列に加わり、体調を崩しては元も子もない。楽しみと無理の境目を見極めることこそ、大人の分別というものだろう。": [0.0, 45.825], "先輩、このライブのチケット、徹夜で並んで買ったんですよ。": [46.225, 5.44], "徹夜してまで？　明日、試験じゃなかった？": [52.065, 3.945], "そうなんです。でも、喉から手が出るほど欲しかったので。": [56.41, 4.87], "気持ちはわかるけど、単位を犠牲にしてまで行く価値があるかなあ。": [61.68, 4.955], "健康を害してまで働く必要はない。": [67.035, 3.245], "友人を裏切ってまで、出世したいとは思わない。": [70.68, 3.95], "彼は会社を休んでまで、娘の発表会に駆けつけた。": [75.03, 4.94], "流行の服は好きだが、借金をしてまで買いたいとは思わない。値札を見るたびに二の足を踏んでしまう。": [80.37, 7.76], "嘘をついてまで勝ちたくはない。": [88.53, 2.44], "借金をしてでも、この店を守りたい。": [91.37, 3.5], "目がない": [95.27, 1.045], "舌鼓を打つ": [96.715, 1.615], "喉から手が出る": [98.73, 1.56], "二の足を踏む": [100.69, 1.39], "首をかしげる": [102.48, 1.45], "腹をくくる": [104.33, 1.295], "身を粉にする": [106.025, 1.31], "指をくわえる": [107.735, 1.365]}, "d156": {"電車内での通話は控えるのがマナーとされている。急病や事故の連絡ならまだしも、友人との世間話を大声で続けられては、周りの乗客が眉をひそめるのも無理はない。最近はイヤホンをしたまま話す人も多く、本人は小声のつもりでも周囲には会話が筒抜けである。一度や二度ならまだしも、毎朝同じ車両で繰り返されれば、我慢の限界を超える人も出てくるだろう。もっとも、マナーを守らない人を白い目で見るだけでは何も変わらない。なぜそれが迷惑なのかを、押しつけではなく共感を通して伝える工夫が、社会全体に求められているのではないか。": [0.0, 42.45], "新しく入ったバイトの子、また遅刻したんだって。": [42.85, 4.19], "一回ならまだしも、今月でもう三回目でしょう。": [47.44, 4.3], "店長も今までは目をつぶってきたけど、さすがに限界みたい。": [52.14, 5.09], "紹介したのは僕だからなあ。顔に泥を塗られた気分だよ。": [57.63, 4.76], "小学生ならまだしも、大人がこんな簡単な計算を間違えるとは。": [62.79, 5.7], "少し遅れるならまだしも、連絡もなしに休むのは困る。": [68.89, 4.965], "値段が高いだけならまだしも、味までひどいのだから話にならない。": [74.255, 5.36], "たまにならまだしも、毎晩夜中に掃除機をかけられては困る。これまでは目をつぶってきたが、管理会社に相談するつもりだ。": [80.015, 9.89], "一日ならまだしも、一週間も待たされるのは我慢できない。": [90.305, 4.885], "プロならともかく、素人にこの作業は無理だ。": [95.59, 4.01], "眉をひそめる": [100.0, 1.365], "白い目で見る": [101.765, 1.42], "目をつぶる": [103.585, 1.18], "鼻につく": [105.165, 1.34], "口が軽い": [106.905, 1.335], "顔に泥を塗る": [108.64, 1.475], "肩身が狭い": [110.515, 1.51], "背を向ける": [112.425, 1.295]}, "d157": {"近年、手軽な趣味として登山を始める人が増えている。それ自体は喜ばしいことだが、遭難事故の増加もまた見過ごせない。夏の低山ならともかく、天候が急変しやすい冬山に初心者だけで挑むのは無謀と言わざるを得ない。腕に覚えがある経験者でさえ、吹雪で道を見失い肝を冷やした例は少なくないのだ。また、下山の途中で膝が笑い、思うように歩けなくなる人も多い。登りで体力を使い果たさず、余力を残して引き返す勇気こそが大切である。山は逃げない。「無理をしない」という原則を肝に銘じ、自分の力量に見合った山選びを心がけてほしい。": [0.0, 44.955], "今度の週末、富士山に登ろうと思ってるんだ。": [45.355, 4.115], "え、もう十二月だよ。夏ならともかく、冬の富士山は上級者向けでしょう。": [49.87, 6.725], "大丈夫だよ。体力には自信があるし。": [56.995, 3.495], "体力の問題じゃないって。肝を冷やすような目に遭ってからじゃ遅いんだから。": [60.89, 5.54], "一人ならともかく、家族四人でこの部屋に住むのは狭すぎる。": [66.83, 5.07], "冗談ならともかく、本気でそう言っているなら許せない。": [72.3, 4.49], "知らなかったのならともかく、わかっていて黙っていたのは問題だ。": [77.19, 5.1], "週末ならともかく、平日の夜に三時間も練習するのは骨が折れる。それでも本番までは続けようと肝に銘じている。": [82.69, 9.61], "子どもならともかく、大人がそんな言い訳をするとは。": [92.7, 4.245], "味はともかく、この店は雰囲気が最高だ。": [97.345, 4.0], "腕に覚えがある": [101.745, 1.54], "肝を冷やす": [103.685, 1.345], "肝に銘じる": [105.43, 1.405], "膝が笑う": [107.235, 1.315], "腰が重い": [108.95, 1.33], "足を引っ張る": [110.68, 1.38], "息が合う": [112.46, 1.09], "骨が折れる": [113.95, 1.245]}, "d158": {"年末が近づくと、年賀状をどうするかで毎年迷う。祖父母の時代ならいざ知らず、今はメッセージアプリで一瞬にして新年の挨拶が送れる。実際、虚礼廃止を掲げて年賀状のやり取りをやめた会社も多い。仕事に追われて一枚一枚に心を込める余裕などない、という声もよく耳にする。それでも私が年賀状をやめられないのは、恩師から届く手書きの一枚があるからだ。毎年、教え子一人一人に向けた短い言葉が添えられていて、読むたびに頬が緩む。手間のかかる習慣だからこそ、受け取った側の胸を打つのだろう。効率では測れない価値が、あの小さな紙の中には詰まっている。": [0.0, 46.585], "今度の大阪旅行、夜行バスで行くって本当？": [46.985, 4.29], "うん、新幹線より一万円以上安いからね。": [51.675, 3.94], "学生ならいざ知らず、四十過ぎて夜行バスはきついんじゃない？": [56.015, 4.96], "わかってる。でも今月は懐が寒くて、ぜいたくは言えないのよ。": [61.375, 5.63], "昔はいざ知らず、今は女性の管理職も珍しくない。": [67.405, 4.875], "神様ならいざ知らず、人間に未来がわかるはずがない。": [72.68, 4.535], "初めてならいざ知らず、三度目でも同じ失敗をするとは情けない。": [77.615, 5.435], "昔はいざ知らず、今は地図を広げて道を探す人はほとんどいない。それでも、父が紙の地図を手に旅の計画を立てていた姿が目に浮かぶ。": [83.45, 11.645], "江戸時代ならいざ知らず、今どき手紙で連絡する人は少ない。": [95.495, 5.1], "五分ならまだしも、一時間の遅刻は許されない。": [100.995, 4.165], "手が込む": [105.56, 1.21], "手が回らない": [107.17, 1.385], "目を通す": [108.955, 1.185], "目に浮かぶ": [110.54, 1.21], "胸が痛む": [112.15, 1.285], "胸を打つ": [113.835, 1.14], "頬が緩む": [115.375, 1.3], "懐が寒い": [117.075, 1.58]}, "d159": {"先月の豪雨で被害を受けた川辺町では、今も多くの住民が避難生活を余儀なくされている。家屋に流れ込んだ泥のかき出しは人手が足りず、復旧は思うように進んでいない。そこで本会では、週末ごとにボランティアを現地へ派遣することにした。専門的な技術は必要ない。わずかなりとも力になりたいという気持ちさえあれば十分である。一日なりとも参加していただければ、被災された方々にとって大きな支えとなるだろう。また、現地に赴くことが難しい方には、物資や寄付による支援もお願いしたい。皆が足並みをそろえて一歩ずつ進めば、町に再び笑顔が戻る日は必ず来る。ご協力を心よりお願い申し上げる。": [0.0, 48.935], "先輩、引っ越しの片付け、まだ終わらないんですか。": [49.335, 4.79], "そうなの。レポートもあって、一人じゃ全然手が回らなくて。": [54.525, 5.015], "僕でよければ、少しなりとも手を貸しますよ。": [59.94, 4.0], "本当？　助かる！　お礼に晩ご飯は私が腕を振るうね。": [64.34, 5.295], "多少なりともお役に立てれば幸いです。": [70.035, 3.18], "一目なりとも、故郷の母に会いたい。": [73.615, 3.31], "ご不明な点があれば、何なりとお申し付けください。": [77.325, 4.235], "地域の清掃活動に、月に一度なりとも参加したいと思っている。皆で足並みをそろえれば、町はきっときれいになるはずだ。": [81.96, 9.98], "少しなりとも休んだほうがいい。": [92.34, 2.535], "一秒たりとも気を抜けない。": [95.275, 2.235], "手を貸す": [97.91, 1.16], "腕を振るう": [99.47, 1.2], "骨を折る": [101.07, 1.12], "肩の荷が下りる": [102.59, 1.535], "肩を落とす": [104.525, 1.38], "胸が躍る": [106.305, 1.23], "目頭が熱くなる": [107.935, 1.77], "足並みをそろえる": [110.105, 1.58]}, "d160": {"大臣の秘書が公金の不正流用に手を染めていたことが明らかになった。関係者は当初、口裏を合わせて疑惑を否定していたが、送金の記録から足がつき、ついに秘書が口を割った。大臣は「すべて秘書が独断でやったこと」と釈明しているが、それで国民が納得するとは思えない。たとえ大臣であろうと、法の前では一市民と何ら変わりはない。いかなる地位にある者であろうと、不正に対する責任は等しく問われるべきである。国民の信頼を裏切った以上、身から出た錆と言われても仕方がないだろう。政府には、相手が身内であろうと容赦しない、徹底した調査を求めたい。": [0.0, 45.21], "来月から、無断の遅刻が三回で減給という規則にするからね。": [45.61, 5.515], "えっ、管理職も対象ですか。": [51.525, 2.78], "もちろん。誰であろうと例外はなしだ。": [54.705, 3.24], "わかりました。後ろ指を指されないよう、私も気をつけます。": [58.345, 5.295], "どんな理由であろうと、暴力は許されない。": [64.04, 3.56], "たとえ親友であろうと、言ってはいけないことがある。": [68.0, 3.915], "仕事が単純であろうと複雑であろうと、手を抜くつもりはない。": [72.315, 4.84], "相手が誰であろうと、約束の時間は守るべきだ。小さな約束を破り続ければ、いずれ後ろ指を指されることになる。": [77.555, 9.6], "どんな結果であろうと、受け入れるしかない。": [87.555, 3.325], "どんな結果であれ、受け入れるしかない。": [91.28, 3.145], "手を染める": [94.825, 1.175], "口裏を合わせる": [96.4, 1.555], "足がつく": [98.355, 1.315], "口を割る": [100.07, 1.175], "身から出た錆": [101.645, 1.53], "後ろ指を指される": [103.575, 1.725], "腹が黒い": [105.7, 1.295], "首を切る": [107.395, 1.19]}, "d162": {"先日、知人に誘われて和太鼓の公演を見に行った。正直なところ、さほど期待はしていなかったのだが、幕が開いた瞬間にその考えは吹き飛んだ。最初の一打の音たるや、腹の底まで響き渡り、客席の空気を一変させるほどだった。十数人の奏者が一糸乱れず打ち鳴らす姿には目を見張るばかりで、観客は皆、息を殺して舞台を見つめていた。聞けば、奏者たちは十年以上も毎日欠かさず腕を磨いてきたのだという。その鍛錬の成果たるや、まさに圧巻の一言に尽きる。終演後もしばらく鳥肌が立ったままで、あの響きは今もはっきりと胸に刻まれている。": [0.0, 45.43], "昨日の新人歌手のコンサート、どうだった？": [45.83, 3.745], "いやあ、その歌唱力たるや、ベテランの評論家も舌を巻くほどだったよ。": [49.975, 5.98], "へえ、まだ十八歳でしょう？": [56.355, 2.695], "うん。最初の一声で、会場中が息を呑んだからね。": [59.45, 4.82], "優勝が決まった瞬間の観客の熱狂たるや、すさまじいものだった。": [64.67, 5.61], "その店のラーメンの辛さたるや、一口で汗が噴き出すほどだ。": [70.68, 5.055], "彼の練習量たるや、プロ選手も驚くほどだという。": [76.135, 4.325], "展望台から見た夜景の美しさたるや、言葉を失うほどだった。思わず鳥肌が立ち、しばらくその場を動けなかった。": [80.86, 9.655], "その建物の大きさたるや、想像をはるかに超えていた。": [90.915, 4.68], "教師たるもの、生徒の手本でなければならない。": [95.995, 3.91], "目を見張る": [100.305, 1.175], "息を殺す": [101.88, 1.34], "腕を磨く": [103.62, 1.31], "舌を巻く": [105.33, 1.27], "鳥肌が立つ": [107.0, 1.45], "胸に刻む": [108.85, 1.345], "耳を疑う": [110.595, 1.34], "目に留まる": [112.335, 1.18]}, "d163": {"子育てに悩む親から相談を受けるたびに、私はこう伝えている。「完璧な親などいない」と。保育士として三十年働いてきた私とて、わが子の夜泣きには途方に暮れ、何度も声を荒らげてしまった。手塩にかけて育てたつもりでも、子どもは親の思い通りにはならないものだ。どれほど育児書を読んだとて、目の前のわが子にそのまま当てはまるわけではない。だからこそ、時には手を抜くことも必要である。疲れ切った親が歯を食いしばって頑張り続けるより、周囲に頼り、笑顔でいられる時間を増やすほうが、子どもにとってもずっと幸せなはずだ。悩みながらも向き合っている自分に、もっと胸を張っていいのである。": [0.0, 46.74], "田中さん、今回のミスで相当落ち込んでいるみたいですね。": [47.14, 4.78], "気持ちはわかるよ。私とて、若いころは同じような失敗をしたからね。": [52.32, 5.935], "課長もですか。ちょっと意外です。": [58.655, 2.86], "今夜、一度腹を割って話してみるよ。失敗から学べば、それでいいんだから。": [61.915, 6.87], "医者とて人間だ。疲れれば判断を誤ることもある。": [69.185, 4.375], "今さら謝ったとて、彼の怒りは収まらないだろう。": [73.96, 4.35], "負けたからとて、これまでの努力が無駄になるわけではない。": [78.71, 4.595], "私とて、最初から上手に話せたわけではない。歯を食いしばって練習を続けたからこそ、今の自分があるのだ。": [83.705, 9.16], "私とて、好きでこの仕事を断るわけではない。": [93.265, 4.3], "専門家でさえ、この問題は解けなかった。": [97.965, 3.765], "頭が下がる": [102.13, 1.43], "手塩にかける": [103.96, 1.5], "目を細める": [105.86, 1.315], "目に入れても痛くない": [107.575, 1.87], "手を抜く": [109.845, 1.075], "歯を食いしばる": [111.32, 1.395], "腹を割る": [113.115, 1.14], "胸を張る": [114.655, 1.145]}, "d164": {"このたびは、当店のオンラインショップをご利用いただき、誠にありがとうございます。さて、先週末に実施いたしました開店十周年記念セールにおきまして、想定をはるかに上回るご注文をいただき、商品の発送に大幅な遅れが生じております。何分にも初めての試みであったこととて準備が行き届かず、お客様には多大なるご迷惑をおかけしましたことを、心よりお詫び申し上げます。現在、従業員一同、目が回るような忙しさの中ではございますが、一日も早くお届けできるよう全力で対応しております。なお、お届けまでに二週間以上かかる場合は、ご希望に応じてご注文の取り消しも承ります。今後はこのようなことのないよう、体制の見直しに努めてまいります。": [0.0, 53.79], "すみません、さっき注文したのと違う料理が来たんですが。": [54.19, 4.775], "大変申し訳ございません。新人がまだ慣れぬこととて、ご迷惑をおかけしました。": [59.365, 6.825], "いえいえ。誰にでも間違いはありますから。": [66.59, 3.485], "恐れ入ります。すぐにお取り替えいたします。": [70.475, 3.625], "子どものしたこととて、どうか大目に見てやってください。": [74.5, 4.385], "何分急なこととて、十分なおもてなしもできず失礼いたしました。": [79.285, 5.5], "不慣れなこととて、手続きに時間がかかってしまいました。": [85.185, 4.63], "何分不慣れなこととて、資料の送付が遅れましたことを深くお詫び申し上げます。皆様に合わせる顔がございませんが、今後は十分に注意いたします。": [90.215, 11.775], "初めてのこととて、不手際をお許しください。": [102.39, 3.9], "几帳面な彼のことだから、もう準備は終わっているだろう。": [106.69, 4.5], "合わせる顔がない": [111.59, 1.625], "顔から火が出る": [113.615, 1.555], "腰が低い": [115.57, 1.355], "耳をそろえる": [117.325, 1.37], "足が出る": [119.095, 1.165], "目が回る": [120.66, 1.16], "首が回らない": [122.22, 1.525], "尻ぬぐい": [124.145, 1.315]}, "d165": {"正月に親戚が集まった席で、つい口が滑って「今年こそ禁煙する」と宣言してしまった。言った手前、今さら撤回するわけにもいかない。何しろ、その場には小学生の甥まで同席していたのだ。子どもたちの手前、こっそり一本吸うことすらはばかられる。最初の一週間は地獄だった。口寂しさを紛らわそうとガムをかみ続け、あごが痛くなったほどだ。それでも一か月が過ぎるころには、朝の目覚めが軽くなり、階段を上っても息が切れなくなった。舌の根の乾かぬうちに挫折するだろうと笑っていた兄も、今では驚いている。見栄から始まった禁煙だったが、人前で宣言するというのも案外悪くない方法なのかもしれない。": [0.0, 50.34], "来月のマラソン大会、本当に出るの？": [50.74, 3.765], "うん。みんなの前で完走するって大口をたたいた手前、引くに引けなくてね。": [54.905, 6.045], "でも、ほとんど練習してないって言ってたじゃない。": [61.35, 3.74], "だから最近は毎朝走ってるんだよ。笑われたら腹の虫が治まらないからね。": [65.49, 6.115], "必ず行くと約束した手前、今さら断れない。": [72.005, 4.495], "部下の手前、上司の私が弱音を吐くわけにはいかない。": [76.9, 4.78], "ごちそうになった手前、彼の頼みは断りにくい。": [82.08, 4.33], "飲み会でつい口が滑って、料理が得意だと言ってしまった。言った手前、来週のパーティーでは何か作らなければならない。": [86.81, 9.43], "先生に褒められた手前、手を抜くわけにはいかない。": [96.64, 4.245], "引き受けた以上、最後までやり遂げるべきだ。": [101.285, 3.71], "口が滑る": [105.395, 1.335], "大口をたたく": [107.13, 1.605], "舌の根の乾かぬうちに": [109.135, 2.155], "鼻が高い": [111.69, 1.38], "鼻にかける": [113.47, 1.42], "口をそろえる": [115.29, 1.395], "顔を出す": [117.085, 1.23], "腹の虫が治まらない": [118.715, 2.01]}, "d166": {"外国語は、使ってこそ身につくものだ。学生時代、文法書を何冊も読み込み、試験では高得点を取っていた私だが、初めて留学した街では、パン一つ満足に注文できなかった。頭では理解していても、相手の速い話し言葉にまったくついていけなかったのである。そのとき、教科書の知識だけでは足りないことが身に染みてわかった。それからは、恥をかくのを恐れず、市場や食堂で地元の人に積極的に話しかけた。言い間違えて笑われることも多かったが、そうして実際に言葉を交わしてこそ、生きた表現が頭に残っていった。机に向かう学習を軽んじるつもりはない。だが、知識は使われてこそ初めて本当の力になるのだと思う。": [0.0, 51.78], "先生、毎日同じ基礎練習ばかりで、正直退屈なんですが。": [52.18, 5.89], "基本を繰り返してこそ、応用がきくようになるんだよ。": [58.47, 4.25], "それ、耳にたこができるほど聞きました。": [63.12, 3.535], "それだけ大事だってことさ。続けた人だけが、その意味を肌で感じられるんだ。": [67.055, 6.465], "互いに支え合ってこそ、本当の家族と言えるだろう。": [73.92, 4.325], "法律は守られてこそ意味がある。": [78.645, 2.735], "失敗を重ねてこその成功だから、喜びもひとしおだ。": [81.78, 4.89], "一人暮らしを始めて、親のありがたさが身に染みた。家事は自分でやってこそ、その大変さがわかるものだ。": [87.07, 8.645], "練習を続けてこそ、上達できる。": [96.115, 3.435], "病気になって初めて、健康のありがたさがわかった。": [99.95, 4.465], "肌で感じる": [104.815, 1.455], "身に染みる": [106.67, 1.195], "目から鱗が落ちる": [108.265, 1.785], "骨身を惜しまない": [110.45, 1.59], "頭が固い": [112.44, 1.465], "頭をひねる": [114.305, 1.34], "耳にたこができる": [116.045, 1.765], "口が重い": [118.21, 1.3]}, "d167": {"スマートフォンで撮った写真が、今や何千枚と端末に眠っている人も多いだろう。だが、端末を落として壊してしまえばそれまでだ。思い出の写真が一瞬で消えてしまう。クラウドに保存しているから安心だという人もいるが、そのサービスが終了してしまえばそれまでである。実際、無料の保存サービスが突然打ち切られ、目の色を変えてデータを移した人もいた。大切なのは、一か所に頼らず、複数の場所に分けて保存しておくことだ。失ってから手を打とうとしても遅い。尻に火がつく前に、今日にでも写真の整理を始めてみてはどうだろうか。お気に入りの数枚を紙に印刷しておくのも、意外に確実な方法である。": [0.0, 47.38], "この企画、すごくいいアイデアだと思うんだけど、部長は首をひねってたのよね。": [47.78, 6.23], "どんなにいいアイデアでも、予算が通らなければそれまでだからな。": [54.41, 4.74], "じゃあ、費用の面からもう一度説明してみる。": [59.55, 3.895], "うん。締め切りも迫ってるし、早めに手を打ったほうがいいよ。": [63.845, 4.945], "どんなに練習しても、本番で緊張してしまえばそれまでだ。": [69.19, 4.765], "命を落としたらそれまでなのだから、無理は禁物だ。": [74.355, 4.345], "運が悪かったと言ってしまえばそれまでだが、防ぐ手立てはあったはずだ。": [79.1, 5.34], "どんなに稼いでも、体を壊してしまえばそれまでだ。若いうちから健康のために手を打っておきたい。": [84.84, 7.48], "データが消えてしまえばそれまでだ。": [92.72, 2.495], "電車が動かないなら、歩いて行くまでだ。": [95.615, 3.365], "頭打ちになる": [99.38, 1.54], "手を打つ": [101.32, 1.025], "手を引く": [102.745, 1.03], "尻に火がつく": [104.175, 1.645], "目の色を変える": [106.22, 1.455], "首をひねる": [108.075, 1.245], "足元を見る": [109.72, 1.38], "二枚舌を使う": [111.5, 1.635]}, "d169": {"三年前から、自宅の裏にある猫の額ほどの土地で野菜を育てている。自給自足とまではいかないが、夏場はトマトやきゅうりをほとんど買わずに済むようになった。始めたころは失敗の連続で、せっかく芽が出た苗を虫にすっかり食べられてしまったこともある。それでも、近所の農家の方に教わりながら続けるうちに、少しずつ腕が上がってきた。手前味噌になるが、今年のトマトは店で売っているものより甘いと家族にも評判だ。何より、土に触れる時間は仕事の疲れを忘れさせてくれる格好の息抜きになっている。プロ並みとまではいかなくとも、自分の手で育てた野菜を食卓に並べる喜びは、何物にも代えがたい。": [0.0, 47.59], "最近、料理教室に通ってるんだって？": [47.99, 3.57], "うん。プロ並みとまではいかないけど、だいぶ腕が上がったと思う。": [51.96, 4.905], "へえ、今度ぜひ食べさせてよ。": [57.265, 2.845], "いいよ。口に合うかどうかわからないけどね。": [60.51, 3.55], "満点とまではいかないが、合格点は取れたと思う。": [64.46, 4.355], "毎日とまではいかなくても、週に一度は親に電話したい。": [69.215, 4.635], "完全に治ったとまではいかないが、だいぶ痛みは引いた。": [74.25, 4.375], "日本語で映画を楽しめるとまではいかないが、字幕があれば内容はほぼわかるようになった。週末の映画鑑賞は、勉強を兼ねたいい息抜きだ。": [79.025, 10.925], "優勝とまではいかないが、三位以内には入りたい。": [90.35, 4.15], "優勝できないまでも、三位以内には入りたい。": [94.9, 3.91], "猫の額": [99.21, 1.325], "腕が上がる": [100.935, 1.225], "手前味噌": [102.56, 1.375], "息抜き": [104.335, 1.205], "口に合う": [105.94, 1.165], "目が肥える": [107.505, 1.175], "手が届く": [109.08, 1.23], "骨休め": [110.71, 1.39]}, "d170": {"来月十日に、管理組合の臨時総会を開催いたします。議題は、駐車場利用料の改定および外壁修繕工事の実施についてです。ご都合により出席できない方は、同封の委任状を必ず期日までにご提出ください。期日までに委任状、議決権行使書のいずれも提出されなかった場合は、議長に一任されたものとして扱います。なお、修繕工事の費用については、昨年度の総会で修繕積立金を充てることがすでに承認されたものとして、本総会では工事業者の選定についてご審議いただきます。住民の皆様が膝を交えて意見を出し合える貴重な機会ですので、できる限りご出席くださいますようお願い申し上げます。": [0.0, 49.52], "明日の会議だけど、全員が資料に目を通してきたものとして進めるからね。": [49.92, 5.81], "えっ、資料の説明はなしですか。": [56.13, 3.04], "時間がないからね。質問があれば、遠慮せずに最初に口火を切ってくれていいよ。": [59.57, 6.505], "わかりました。今夜中に読んでおきます。": [66.475, 3.305], "連絡がない場合は、参加しないものとして準備を進めます。": [70.18, 4.935], "その金はもう戻ってこないものとして諦めることにした。": [75.515, 4.24], "全員が基礎知識を持っているものとして、授業を始めます。": [80.155, 4.67], "今月二十日までに返信がない場合は、欠席されるものとして扱います。久しぶりに膝を交えて語り合える場ですので、ぜひご参加ください。": [85.225, 11.14], "異議がないものとして、次の議題に移ります。": [96.765, 3.785], "会費は毎月末日までに納めるものとする。": [100.95, 3.655], "膝を交える": [105.005, 1.4], "口火を切る": [106.805, 1.305], "口を出す": [108.51, 1.265], "首を突っ込む": [110.175, 1.475], "首を縦に振る": [112.05, 1.6], "顔色をうかがう": [114.05, 1.56], "腹を決める": [116.01, 1.28], "耳を貸す": [117.69, 1.285]}, "d171": {"青葉県北部の山あいにある無住の寺で、平安時代後期に作られたものと思われる木造の仏像が見つかった。発見したのは、本堂の改修工事に携わっていた地元の大工である。天井裏の暗がりで仏像を目にしたときには、腰を抜かしそうになったという。県の調査によると、仏像は表面の傷みが激しいものの、全体の形はよく保たれている。台座に残された墨書から、戦乱の時代に何らかの事情で天井裏へ移されたものと思われる。地元の住民にとってはまさに寝耳に水の出来事で、「こんな宝が身近に眠っていたとは」と驚きを隠せない様子だ。県は今後、専門家による詳しい調査を進め、文化財指定も検討する方針である。": [0.0, 51.37], "今日の決勝戦、後半は手に汗を握る展開でしたね。": [51.77, 4.605], "ええ。両チームとも疲れから、終盤は足が止まっていたものと思われます。": [56.775, 6.12], "最後の決勝点については、どうご覧になりましたか。": [63.295, 4.445], "守備の一瞬の隙を、相手は見逃さなかったものと思われます。": [68.14, 4.96], "事故の原因は、運転手の居眠りであるものと思われる。": [73.5, 4.375], "この傾向は、今後もしばらく続くものと思われる。": [78.275, 4.295], "犯人は裏口から侵入したものと思われる。": [82.97, 3.475], "老舗百貨店の突然の閉店発表は、従業員にとって寝耳に水だった。売り上げの長期低迷が主な原因であるものと思われる。": [86.845, 10.035], "火災は配線の老朽化によるものと思われる。": [97.28, 3.55], "明日は雨が降ると思う。": [101.23, 2.04], "腰を抜かす": [103.67, 1.475], "寝耳に水": [105.545, 1.355], "手に汗を握る": [107.3, 1.48], "目を光らせる": [109.18, 1.4], "小耳に挟む": [110.98, 1.54], "血眼になる": [112.92, 1.495], "眉唾物": [114.815, 1.465], "息がかかる": [116.68, 1.37]}, "d172": {"八十を過ぎた祖母に言わせれば、今の若者は「我慢が足りない」らしい。少し気に入らないことがあるとすぐに仕事を辞め、何でも機械に頼ろうとする、というのである。歯に衣着せぬ祖母の物言いに、最初は私も頭に来たものだ。しかし、若い世代の私に言わせれば、合わない職場で無理を続けることこそ不健全であり、便利な道具は大いに使えばいい。もっとも、話をよく聞いてみると、祖母の言う「我慢」とは、ただ耐え忍ぶことではなく、物事をすぐに投げ出さず、長い目で見る姿勢のことだったようだ。互いの言葉尻をとらえて揚げ足を取るのではなく、その奥にある思いをくみ取ること。世代を超えた対話に必要なのは、案外そんなことなのかもしれない。": [0.0, 53.075], "新しく来た部長、どう思う？": [53.475, 2.83], "僕に言わせれば、口がうまいだけで中身がない人だね。": [56.705, 4.455], "でも、山田さんに言わせると、すごく面倒見がいいらしいよ。": [61.56, 5.06], "うーん。まあ、もう少し長い目で見てみるか。": [67.02, 4.11], "料理人の父に言わせれば、だしの取り方で味の九割が決まるそうだ。": [71.53, 5.585], "私に言わせれば、そんな計画は最初から無理だった。": [77.515, 4.585], "専門家に言わせると、この程度の揺れは珍しくないらしい。": [82.5, 4.785], "母に言わせれば、転職を繰り返すのは根気がない証拠だそうだ。だが私に言わせれば、長い目で見て自分に合う仕事を探すことのほうが大切だ。": [87.685, 11.415], "祖父に言わせれば、最近のドラマはどれもつまらない。": [99.5, 4.285], "天気予報によれば、明日は雪だそうだ。": [104.185, 3.535], "歯に衣着せぬ": [108.12, 1.49], "頭に来る": [110.01, 1.325], "揚げ足を取る": [111.735, 1.355], "長い目で見る": [113.49, 1.355], "口がうまい": [115.245, 1.3], "口が減らない": [116.945, 1.425], "鼻であしらう": [118.77, 1.39], "目くじらを立てる": [120.56, 1.52]}, "d173": {"駅前に新しくできたフレンチレストランに行ってみた。店構えからして高級感が漂い、期待は高まった。ところが、出てきた料理は見た目こそ華やかだが、肝心の味は平凡そのものだった。テレビで顔が売れたシェフの店だというが、この内容からいって、一皿五千円という値段は高すぎると言わざるを得ない。加えて、店員の態度からして、客を見下しているような印象を受けた。料理について説明を求めると、「お客様にはおわかりにならないかと」と返されたのだ。鼻持ちならないとはこのことだろう。名声に頼るのではなく、一皿一皿で客の心をつかむ努力をしてほしいものである。": [0.0, 45.32], "今度の新人、入社してまだ半年なのに、もう頭角を現してるらしいね。": [45.72, 6.25], "うん。企画書の書き方からして、ほかの新人とは違うのよ。": [52.37, 5.305], "このままだと、すぐに先輩たちと肩を並べそうだな。": [58.075, 4.505], "あの実力からいって、それも時間の問題ね。": [62.98, 3.97], "あの話し方からして、彼は相当怒っているようだ。": [67.35, 4.35], "この映画はタイトルからして暗いので、見る気がしない。": [72.1, 4.265], "彼の実力からいって、優勝は間違いないだろう。": [76.765, 4.18], "この店は店名からして気取っていて、少し鼻持ちならない感じがした。だが、料理の質からいって、値段はむしろ安いほうだ。": [81.345, 10.205], "社長からして遅刻するのだから、社員が守るはずがない。": [91.95, 4.725], "経験からいって、この方法が一番確実だ。": [97.075, 4.16], "鼻持ちならない": [101.635, 1.565], "鼻息が荒い": [103.6, 1.5], "鼻を折る": [105.5, 1.13], "鼻を明かす": [107.03, 1.395], "顔が売れる": [108.825, 1.23], "頭角を現す": [110.455, 1.66], "肩を並べる": [112.515, 1.415], "歯が立たない": [114.33, 1.34]}, "d174": {"来月一日の開館に先立ち、駅から目と鼻の先に建設された市立中央図書館で、市民向けの内覧会が開かれた。新図書館は、蔵書数約五十万冊と旧館の二倍の規模を誇る。旧館は老朽化が進み、駐車場も狭かったため、近年は利用者の足が遠のいていた。そこで市は数年前から再整備に本腰を入れ、設計に先立って市民アンケートを実施し、寄せられた要望を計画に反映させてきた。館内には、子ども連れでも気兼ねなく過ごせる専用スペースや、夜十時まで使える学習室が設けられている。内覧会に参加した親子連れは、司書の説明に膝を乗り出して聞き入っていた。開館の日を指折り数えて待つ市民も多いことだろう。": [0.0, 52.245], "新製品の発表に先立ちまして、開発部長よりご挨拶申し上げます。": [52.645, 6.0], "本日はお集まりいただき、ありがとうございます。三年かけた製品が、ようやく完成いたしました。": [59.045, 8.31], "開発ではご苦労も多かったと伺っておりますが。": [67.755, 3.83], "ええ。一時はどうなることかと思いましたが、ようやく目鼻がつきまして、今日は胸を張ってお見せできます。": [71.985, 8.295], "工事の開始に先立ち、近隣住民への説明会が開かれた。": [80.68, 5.39], "映画の公開に先立って、主演俳優の舞台挨拶が行われた。": [86.47, 5.335], "出発に先立つ準備として、全員の健康状態を確認した。": [92.205, 5.485], "文化祭の開催に先立ち、各クラスの代表者による打ち合わせを行います。生徒たちは当日を指折り数えて待っています。": [98.09, 9.735], "試合に先立ち、両国の国歌が演奏された。": [108.225, 4.195], "この会社は他社に先駆けて新技術を導入した。": [112.82, 3.96], "目と鼻の先": [117.18, 1.56], "足が遠のく": [119.14, 1.435], "本腰を入れる": [120.975, 1.465], "膝を乗り出す": [122.84, 1.48], "指折り数える": [124.72, 1.54], "目鼻がつく": [126.66, 1.445], "腕が鳴る": [128.505, 1.145], "胸がすく": [130.05, 1.195]}, "d176": {"都内の会社に四十年勤めた佐藤さんは、定年退職を機に、妻と共に瀬戸内海の小さな島へ移住した。若いころから釣りが趣味で、いつか海の近くで暮らしたいと考えていたという。とはいえ、知り合いが一人もいない土地での新生活に、最初は腰が引けていた。しかし島の人々は懐が深く、よそから来た夫婦を温かく迎え入れてくれた。今では地元の漁師に教わりながら漁を手伝い、週末には島の子どもたちに将棋を教えている。「会社を退いたのを機に、ようやく自分の人生を生きている気がします」と佐藤さんは笑う。この島に骨を埋めるつもりだと語るその顔は、都会にいたころよりずっと若々しく見えた。": [0.0, 49.14], "結婚を機に会社を辞めるって、本当？": [49.54, 3.625], "いや、辞めるんじゃなくて、地元の支店に移るんだ。": [53.565, 4.41], "そうなんだ。本社で十年も頑張ってきたのに、ちょっともったいない気もするけど。": [58.375, 6.265], "うん。でも、これを機に家族との時間を大事にしたいと思ってね。": [65.04, 5.22], "入院したのを機に、たばこをきっぱりやめた。": [70.66, 3.565], "創業五十周年を機に、社名を変更することになった。": [74.625, 4.785], "これを機に、両国の交流がさらに深まることを願っております。": [79.81, 5.09], "大学入学を機に、一人暮らしを始めた。最初は料理も洗濯も不安で腰が引けていたが、今ではすっかり慣れた。": [85.3, 9.525], "還暦を機に、地域のボランティア活動を始めた。": [95.225, 4.24], "友人に誘われたのをきっかけに、山登りにはまった。": [99.865, 4.455], "骨を埋める": [104.72, 1.37], "足を洗う": [106.49, 1.185], "身を引く": [108.075, 1.03], "腰が引ける": [109.505, 1.355], "尻込みする": [111.26, 1.35], "懐が深い": [113.01, 1.545], "手が離せない": [114.955, 1.42], "肩入れする": [116.775, 1.27]}, "d177": {"駅前の商店街を取り壊し、高層マンションを建設する再開発計画をめぐって、住民の意見が二分している。推進派は、人口減少に歯止めをかけるには若い世帯を呼び込む住宅が不可欠だと主張する。一方、反対派の商店主たちは、長年地域を支えてきた商店街の歴史を軽んじるものだと強く反発している。とりわけ反対派が腹に据えかねているのは、当初は商店街の存続を約束していた市長が、大手開発業者と手を組んだとたん、手のひらを返したように計画を推し進め始めたことだ。記者会見で真意を問われた市長の答えは歯切れが悪く、具体的な説明は避けた。計画をめぐる議論は、来月の市議会でさらに紛糾するものとみられる。": [0.0, 52.075], "来年度の予算配分をめぐって、また部長同士がもめてるらしいよ。": [52.475, 5.345], "ああ、聞いた。営業部と開発部でしょう？": [58.22, 3.94], "うん。会議でもお互いに腹を探り合ってばかりで、話が全然進まないんだって。": [62.56, 6.575], "私たちが口を出しても仕方ないし、しばらくは口をつぐんでおくのが一番ね。": [69.535, 6.19], "遺産の相続をめぐって、兄弟の間で争いが起きた。": [76.125, 4.595], "新空港の建設をめぐり、国と県の主張が対立している。": [81.12, 5.29], "安楽死をめぐる議論は、今も決着がついていない。": [86.81, 4.42], "少子化に歯止めをかける政策をめぐって、国会で議論が続いている。財源をどう確保するかをめぐり、与野党の意見は大きく分かれている。": [91.63, 11.005], "ダム建設をめぐって、住民が賛成派と反対派に分かれた。": [103.035, 5.035], "先生がダム建設の歴史について説明した。": [108.47, 3.905], "歯止めをかける": [112.775, 1.5], "手を組む": [114.675, 1.085], "手のひらを返す": [116.16, 1.535], "腹を探る": [118.095, 1.295], "腹に据えかねる": [119.79, 1.555], "歯切れが悪い": [121.745, 1.4], "口をつぐむ": [123.545, 1.355], "唇をかむ": [125.3, 1.43]}, "d178": {"大地震から十年が経ち、被災地以外では防災への関心が薄れつつある。喉元過ぎれば熱さを忘れるというが、次の災害は待ってはくれない。ある自治体では、過去の被害記録と最新の地盤調査に基づき、地区ごとの危険度を示した地図を作成した。避難所の配置も、勘や慣習ではなく、住民の年齢構成や移動にかかる時間のデータに依拠して見直したという。その結果、高齢者の多い地区では、徒歩五分圏内に一時避難場所が新設された。根拠に基づいた計画は、住民にとっても納得しやすい。「なぜここに逃げるのか」が明確であれば、いざというときの迷いも減るはずだ。防災こそ、感覚ではなく事実に依拠して進めるべき分野なのである。": [0.0, 52.17], "検査の結果に基づいて、今後の治療方針をご説明しますね。": [52.57, 5.475], "はい。正直、結果を聞くのが怖くて、背筋が寒くなる思いです。": [58.445, 6.3], "ご安心ください。早めに見つかったので、手術をせずに薬で治せる見込みです。": [65.145, 6.66], "そうですか。本当にほっとしました。": [72.205, 3.185], "法律に基づき、違反した業者に営業停止を命じた。": [75.79, 4.79], "この報告書は、三年間の調査データに依拠して書かれている。": [80.98, 5.11], "経験に基づいたアドバイスは、説得力がある。": [86.49, 4.245], "模擬試験の結果に基づいて、苦手な読解を重点的に勉強することにした。喉元過ぎれば熱さを忘れるというから、悪かった点数は手帳に書いておく。": [91.135, 12.16], "規則に基づいて、厳正に処分する。": [103.695, 3.54], "祖母の話をもとに、小説を書いた。": [107.635, 3.55], "喉元過ぎれば熱さを忘れる": [111.585, 2.57], "背筋が寒くなる": [114.555, 1.815], "眉一つ動かさない": [116.77, 1.93], "血も涙もない": [119.1, 1.63], "身につまされる": [121.13, 1.49], "肝が据わる": [123.02, 1.3], "心臓が強い": [124.72, 1.64], "爪の垢を煎じて飲む": [126.76, 2.115]}, "d179": {"【市民文化講座 受講規約（抜粋）】一、受講料は、申込時に全額をお支払いいただきます。お支払い後の受講料は、理由のいかんにかかわらず返金いたしません。ただし、講師の急病など主催者側の事情により講座が中止となった場合はこの限りではなく、全額を返金いたします。二、欠席された回の振替受講は、原則として認めておりません。三、講座の内容を無断で録音・録画することは、目的のいかんにかかわらず禁止します。四、受講態度が著しく不適切で、他の受講者の迷惑になると主催者が判断した場合には、受講を取り消すことがあります。その場合も、受講料は返金いたしません。なお、本規約の内容は、事前の告知により変更することがあります。": [0.0, 56.14], "来週の社内コンペ、結果のいかんにかかわらず、参加者全員に記念品が出るらしいよ。": [56.54, 7.225], "へえ、社長も太っ腹ね。それ、誰から聞いたの？": [64.165, 5.195], "総務の田中さんが、こっそり耳打ちしてくれたんだ。": [69.76, 4.225], "さすが、耳が早いわね。": [74.385, 2.57], "理由のいかんにかかわらず、無断欠勤は認められない。": [77.355, 4.485], "審査の結果のいかんにかかわらず、応募作品は返却いたしません。": [82.24, 5.515], "国籍のいかんを問わず、誰でも参加できる。": [88.155, 3.9], "会費は、出席回数のいかんにかかわらず、毎月同じ額を納めること。会長は太っ腹だが、この規則だけは譲らない。": [92.455, 10.405], "天候のいかんにかかわらず、大会は予定通り行う。": [103.26, 4.495], "天候のいかんによっては、大会を中止することもある。": [108.155, 4.365], "太っ腹": [112.92, 1.305], "耳打ちする": [114.625, 1.26], "耳が早い": [116.285, 1.29], "目が高い": [117.975, 1.24], "顔が利く": [119.615, 1.21], "顔を貸す": [121.225, 1.275], "肩透かしを食う": [122.9, 1.645], "脇が甘い": [124.945, 1.29]}, "d181": {"市立図書館の利用者調査によれば、来館者の六割が平日の夕方以降に訪れたいと答えている。ところが現在の閉館時刻は午後六時であり、仕事帰りの会社員や部活動を終えた高校生は、事実上利用の機会を奪われている。図書館が「誰にでも開かれた知の拠点」を掲げる以上、この状況は看過できない。もちろん、開館時間を延ばせば人件費はかさむ。しかし、利用の少ない平日午前の窓口を縮小し、その人員を夜間に振り向ければ、総額をほとんど変えずに済むという試算もある。費用と利便性の両立は十分に可能なのだ。したがって、市は従来の運営方式に固執するのではなく、時間帯ごとの需要に応じた柔軟な人員配置へと舵を切るべきである。図書館の価値は蔵書の数ではなく、それを手に取る人の数で測られるはずだ。": [0.0, 60.285], "来月から、窓口の受付時間が変わるそうですね。": [60.685, 4.5], "ええ、システムの更新があるんです。したがって、土曜日の受付は当面休止になります。": [65.585, 7.57], "そうですか。システムの問題なら、すぐには元に戻らないんでしょうね。": [73.555, 5.75], "ええ、一朝一夕に片づく問題ではないので、ご不便をおかけします。": [79.705, 5.825], "この地域は地盤が弱い。したがって、高層建築には特別な基準が設けられている。": [85.93, 7.3], "応募者が定員に満たなかった。したがって、二次募集を行うこととする。": [93.63, 5.99], "本製品は防水仕様ではありません。したがって、浴室でのご使用はお控えください。": [100.02, 6.95], "来月から新しい会計システムが導入されます。操作に慣れるのは一朝一夕にはいきません。したがって、今月中に全員研修を受けてください。": [107.37, 11.62], "需要が減少している。したがって、生産量を調整する必要がある。": [119.39, 6.105], "雨が降ってきた。だから、早く帰ろうよ。": [125.895, 3.97], "一石二鳥": [130.265, 1.555], "一朝一夕": [132.22, 1.445], "一長一短": [134.065, 1.35], "一喜一憂": [135.815, 1.425], "一進一退": [137.64, 1.43], "試行錯誤": [139.47, 1.58], "本末転倒": [141.45, 1.66], "首尾一貫": [143.51, 1.265]}, "d183": {"「AならばBである。Aである。ゆえにBである」。論理学の教科書に必ず登場するこの推論は、一目瞭然で反論の余地がないように見える。だが、日常の議論においては、前提そのものが疑わしい場合が少なくない。たとえば「有名な専門家が勧めている、ゆえにこの健康法は正しい」という主張は、形式こそ整っているものの、専門家の発言は常に正しいという隠れた前提に依存している。牽強付会な理屈ほど、「ゆえに」「したがって」といった硬い接続詞で武装し、もっともらしく響くものだ。読み手に求められるのは、結論に飛びつく前に、その手前にある前提を一つずつ点検する姿勢である。論理の形式が正しくても、出発点が誤っていれば、たどり着く結論もまた誤りなのだから。": [0.0, 57.31], "先生、この証明の最後にある「ゆえに」って、普通の会話でも使いますか。": [57.71, 7.38], "いや、話し言葉で使うと大げさに聞こえるね。論文や証明の言葉だと思っておくといいよ。": [65.49, 7.32], "なるほど。じゃあ、レポートなら使っても大丈夫ですか。": [73.21, 4.76], "使えるけど、前提と結論が理路整然とつながっていることが条件だね。": [78.37, 5.94], "我思う、ゆえに我あり。": [84.71, 2.43], "三角形の内角の和は百八十度である。ゆえに、残りの角は六十度となる。": [87.54, 6.86], "彼は正直であるがゆえに、損をすることも多い。": [94.8, 4.195], "値段が高い。ゆえに品質が良い。この推論は、高価なものは必ず良品だという隠れた前提に頼っており、牽強付会と言わざるを得ない。": [99.395, 11.435], "証拠は不十分である。ゆえに、被告人は無罪とする。": [111.23, 4.935], "参加者が増えた。したがって、会場を変更する。": [116.565, 4.675], "一目瞭然": [121.64, 1.56], "牽強付会": [123.6, 1.53], "我田引水": [125.53, 1.38], "理路整然": [127.31, 1.205], "支離滅裂": [128.915, 1.43], "半信半疑": [130.745, 1.435], "疑心暗鬼": [132.58, 1.39], "金科玉条": [134.37, 1.655]}, "d184": {"在宅勤務の導入から三年、当社の調査では社員の八割が「集中できる時間が増えた」と回答し、残業時間も平均で二割減少した。通勤の負担がなくなり、育児や介護と仕事を両立しやすくなったという声も多い。こうした数字を見る限り、在宅勤務はいいことずくめで、働き方改革の切り札とさえ言えそうだ。もっとも、すべてが順風満帆というわけではない。入社して間もない社員の中には、気軽に質問できる相手がおらず、孤立感を訴える者が少なくない。先輩の仕事ぶりを間近で見て学ぶ機会が失われたことは、数字には表れにくい損失である。制度の長所を生かしつつ、新人が置き去りにされない仕組みを整えること。それが次の三年間の課題となるだろう。": [0.0, 54.635], "新しいプロジェクト、順調みたいですね。": [55.035, 3.625], "ええ、おかげさまで。もっとも、最初の一か月は四苦八苦しましたけどね。": [59.06, 6.525], "そうだったんですか。全然そうは見えませんでしたよ。": [65.985, 4.095], "チームのみんなが二人三脚で支えてくれたおかげです。": [70.48, 4.045], "この店の料理はどれもおいしい。もっとも、値段は少々高めだが。": [74.925, 5.755], "明日は全員出席のこと。もっとも、体調不良の場合はこの限りではない。": [81.08, 6.205], "彼の言い分にも一理ある。もっとも、やり方が強引すぎたのは確かだ。": [87.685, 5.955], "駅前の新しいカフェは静かで、仕事をするには最適だ。もっとも、席の数が少ないので、週末は座れないこともあるが。": [94.04, 10.695], "彼は優秀だ。もっとも、少し気が短いところはあるが。": [105.135, 5.145], "入場無料。ただし、小学生以下は保護者同伴のこと。": [110.68, 5.325], "順風満帆": [116.405, 1.46], "千差万別": [118.265, 1.59], "十人十色": [120.255, 1.49], "適材適所": [122.145, 1.69], "臨機応変": [124.235, 1.31], "二人三脚": [125.945, 1.56], "孤軍奮闘": [127.905, 1.43], "四苦八苦": [129.735, 1.38]}, "d185": {"市民体育館 個人利用のご案内\n当館では、午前九時から午後九時まで、卓球・バドミントン・トレーニング室の個人利用を受け付けています。利用料金は一回二百円で、事前の予約は不要です。ただし、土日・祝日は団体利用を優先するため、個人利用は午後五時以降に限らせていただきます。\nトレーニング室を初めて利用される方は、安全講習(約三十分)を受講していただく必要があります。講習は毎週水曜日の午後七時から行っており、受講料は無料です。ただし、定員は十名ですので、窓口またはお電話でお早めにお申し込みください。\nなお、館内では運動に適した室内用の靴をご着用ください。器具の使用後は備え付けのタオルで汗を拭き取るなど、次の方が気持ちよく使えるようご協力をお願いいたします。": [0.0, 59.065], "すみません、体育館の個人利用って、予約が要りますか。": [59.465, 5.13], "いいえ、予約は要りません。ただし、トレーニング室は初回だけ講習を受けていただきます。": [64.995, 7.26], "講習はいつありますか。": [72.655, 1.985], "毎週水曜の夜七時からです。ただし、定員が十名なので、お早めにお申し込みください。": [75.04, 7.89], "試験中の辞書の使用を認める。ただし、電子辞書は不可とする。": [83.33, 5.755], "参加費は無料です。ただし、交通費は各自でご負担ください。": [89.485, 5.725], "返品は一週間以内なら可能です。ただし、開封済みの商品は除きます。": [95.61, 6.43], "毎週土曜の朝に日本語の勉強会を開きます。老若男女、どなたでも参加できます。ただし、初回は見学のみとさせていただきます。": [102.44, 11.48], "駐車場は無料です。ただし、二時間を超える場合は有料となります。": [114.32, 5.76], "説明会は十時からです。なお、当日は筆記用具をお持ちください。": [120.48, 5.955], "公明正大": [126.835, 1.555], "用意周到": [128.79, 1.4], "油断大敵": [130.59, 1.545], "無病息災": [132.535, 1.395], "老若男女": [134.33, 1.51], "千客万来": [136.24, 1.735], "和洋折衷": [138.375, 1.49], "単純明快": [140.265, 1.435]}, "d186": {"件名:本社移転に伴う業務についてのお知らせ\n社員各位\nすでにお知らせしているとおり、本社は来月十五日(月)に新社屋へ移転します。移転作業は十三日(土)から十四日(日)にかけて行うため、十二日(金)は午後三時までに各自の私物と書類を所定の段ボール箱に詰め、机の上に置いてください。箱には必ず部署名と氏名を記入すること。十五日は通常どおり午前九時から業務を開始します。新社屋は現在より駅から遠くなるため、通勤経路の変更届を今月末までに総務部へ提出してください。\nなお、旧社屋の会議室は十一日(木)で使用できなくなります。十二日に予定されている来客対応や打ち合わせについては、総務部が近隣の貸し会議室を手配しますので、早めにご相談ください。\n総務部": [0.0, 58.43], "移転の件、説明会では何て言ってた?": [58.83, 3.625], "金曜の三時までに荷物を箱に詰めておくこと。なお、会議室は木曜までしか使えないって。": [62.855, 7.62], "えっ、金曜にお客さんが来るんだけど。右往左往しそうだな。": [70.875, 5.0], "総務が貸し会議室を手配してくれるから、早めに相談すれば大丈夫だよ。": [76.275, 5.94], "会議は三時から第二会議室で行います。なお、資料は各自印刷してお持ちください。": [82.615, 7.355], "応募の締め切りは五月末日です。なお、結果は合格者にのみ通知します。": [90.37, 6.625], "本日の営業は終了しました。なお、明日は臨時休業となります。": [97.395, 5.705], "来週の土曜、六時から駅前の居酒屋で送別会を開きます。なお、会費は当日、幹事に直接お支払いください。": [103.5, 10.335], "申込書は窓口で配布します。なお、郵送での受け付けは行いません。": [114.235, 6.285], "この寺は八百年前に建てられた。ちなみに、隣の茶店も創業百年だそうだ。": [120.92, 7.085], "一部始終": [128.405, 1.405], "東奔西走": [130.21, 1.605], "心機一転": [132.215, 1.485], "前代未聞": [134.1, 1.4], "大同小異": [135.9, 1.375], "単刀直入": [137.675, 1.645], "異口同音": [139.72, 1.23], "右往左往": [141.35, 1.325]}, "d187": {"私の住む町には「鍛冶町」という地名が残っている。江戸時代、刀や農具をつくる職人がこの一帯に集まっていたことに由来するそうだ。今では鍛冶屋は一軒もなく、マンションとコンビニが立ち並ぶ、どこにでもある住宅街である。地名は、こうした失われた暮らしの記憶を伝える小さな歴史の証人だ。ところが近年、市町村合併や再開発に伴い、古い地名が「〇〇ヶ丘」「△△台」といった、どこにでもありそうな名前に置き換えられる例が後を絶たない。新しい名前は響きこそ美しいが、土地の来歴を何も語らない。温故知新という言葉があるが、古いものを知る手がかりそのものを手放してしまっては、新しいものを生み出す土台も危うくなるのではないか。ちなみに、私の家の前の坂は昔「狐坂」と呼ばれていたらしい。名前の由来を知る人は、もう近所にはいない。": [0.0, 63.935], "この町の名前って、昔は鍛冶屋が多かったからなんだって。": [64.335, 4.9], "へえ、知らなかった。ちなみに、隣の「馬場町」は?": [69.635, 5.96], "昔、武士が馬の訓練をした場所らしいよ。古今東西、地名には歴史が詰まってるね。": [75.995, 7.71], "温故知新か。今度、図書館で調べてみようかな。": [84.105, 4.72], "今日のランチはカレーだった。ちなみに、昨日もカレーだった。": [89.225, 4.9], "この映画は世界中で大ヒットした。ちなみに、監督はまだ三十代だそうだ。": [94.525, 6.57], "日本で一番高い山は富士山だ。ちなみに、二番目に高いのは北岳である。": [101.495, 6.435], "私の故郷は山紫水明の地として知られ、夏には多くの観光客が訪れる。ちなみに、名物のそばは江戸時代から作られているそうだ。": [108.33, 11.32], "この店のケーキは人気だ。ちなみに、一番人気はチーズケーキだ。": [120.05, 5.72], "試験、お疲れさま。ところで、夏休みはどこか行くの?": [126.17, 5.455], "温故知新": [132.025, 1.255], "古今東西": [133.68, 1.435], "栄枯盛衰": [135.515, 1.52], "森羅万象": [137.435, 1.58], "山紫水明": [139.415, 1.535], "天変地異": [141.35, 1.385], "奇想天外": [143.135, 1.465], "空前絶後": [145.0, 1.595]}, "d188": {"今年の夏は観測史上最も暑かったと、気象庁が発表した。三十五度を超える猛暑日が二十日連続を記録し、各地で熱中症による救急搬送が相次いだ。気候変動の影響を考えれば、こうした夏が今後「当たり前」になることは覚悟しなければならないのだろう。それにしても、と私は思う。わずか数十年前、夏休みの子どもたちは真昼の空き地で日が暮れるまで遊んでいたのではなかったか。今や学校は外遊びを控えるよう通知を出し、公園からは子どもの声が消えた。命を守るための措置であることは重々承知している。だが、汗まみれで無我夢中に虫を追いかけた記憶を持たない子どもたちが大人になったとき、彼らにとって夏とはどんな季節になるのだろう。暑さそのものよりも、季節の手触りが失われていくことのほうが、私にはよほど空恐ろしく感じられる。": [0.0, 60.84], "今日も三十八度だって。": [61.24, 2.245], "夏だから暑いのは仕方ないけど、それにしても限度があるよね。": [63.885, 4.965], "子どもたちも外で遊べないし、四六時中エアコンの部屋にこもってるよ。": [69.25, 5.575], "昔は無我夢中で虫取りしてたのにね。なんだか寂しいな。": [75.225, 4.845], "忙しいのは分かる。それにしても、連絡ぐらいはくれてもいいだろう。": [80.47, 5.67], "人気の店だとは聞いていたが、それにしてもすごい行列だ。": [86.54, 4.845], "それにしても、今日は本当に寒いですね。": [91.785, 3.725], "物価が上がっているのは知っていた。それにしても、野菜の値段が去年の倍になるとは思わなかった。": [95.91, 7.495], "雨が多い季節だが、それにしても今年は降りすぎだ。": [103.805, 4.495], "彼は初心者だと言っていた。それにしては上手すぎる。": [108.7, 4.37], "喜怒哀楽": [113.47, 1.36], "無我夢中": [115.23, 1.31], "一心不乱": [116.94, 1.135], "天真爛漫": [118.475, 1.435], "抱腹絶倒": [120.31, 1.635], "意気揚々": [122.345, 1.39], "意気消沈": [124.135, 1.22], "四六時中": [125.755, 1.505]}, "d190": {"機械翻訳の精度は、この十年で飛躍的に向上した。旅先の看板もメニューも、スマートフォンをかざせば瞬時に母語で読める。外国語を何年もかけて学ぶ必要はもはやない、と考える人が増えるのも無理はない。とはいうものの、言葉を学ぶ意義が翻訳の精度だけで測れるとは思えない。外国語を学ぶ過程では、母語では当たり前だった区別が相手の言語にはなかったり、逆に母語にない微妙な感情を表す語に出会ったりする。そうした発見の積み重ねこそが、世界の切り取り方は一つではないという実感をもたらすのだ。翻訳機は意味を運んではくれるが、その実感までは運んでくれない。便利な道具を使いこなしつつ、それでもなお自ら言葉を学ぶ。その姿勢は、異なる文化を持つ人々と向き合う上で、むしろこれからいっそう大切になるのではないだろうか。": [0.0, 59.43], "最近は翻訳アプリがあるから、英語の勉強、やめちゃった。": [59.83, 5.215], "確かに便利だよね。とはいうものの、相手の冗談まで訳してくれるかな。": [65.445, 5.88], "うーん、それは無理かも。": [71.725, 2.29], "だろう?語学は一朝一夕にはいかないけど、自分で学ぶ意味はあると思うよ。": [74.415, 6.245], "健康のために運動が大事だとは分かっている。とはいうものの、なかなか続かない。": [81.06, 6.54], "暦の上では春とはいうものの、まだ朝晩は冷え込む。": [88.0, 4.405], "給料は上がった。とはいうものの、物価の上昇には追いつかない。": [92.805, 5.215], "毎日少しずつ単語を覚えるのが一番の近道だ。とはいうものの、忙しい日が続くとつい後回しにしてしまう。": [98.42, 8.98], "退院した。とはいうものの、まだ無理はできない。": [107.8, 4.0], "子どもとはいえ、自分の行動には責任を持つべきだ。": [112.2, 4.44], "換骨奪胎": [117.04, 1.67], "千変万化": [119.11, 1.665], "博覧強記": [121.175, 1.6], "一念発起": [123.175, 1.44], "切磋琢磨": [125.015, 1.575], "大器晩成": [126.99, 1.41], "日進月歩": [128.8, 1.465], "不言実行": [130.665, 1.44]}, "d191": {"人口わずか八百人の山あいの村で、今年も秋祭りが開かれた。担い手の高齢化が進み、数年前には中止もやむを得ないと言われていた祭りである。にもかかわらず、今年の参加者は過去最多を記録した。立役者となったのは、都市部に住む村の出身者や、SNSで祭りを知った若者たちだ。彼らは一日だけの「助っ人」として神輿を担ぎ、屋台を手伝った。村の人々も当初は半信半疑だったという。よそ者に伝統の何が分かるのか、という声もあった。しかし、汗を流して神輿を担ぐ若者の姿に、長老たちの表情は次第に和らいでいった。もっとも、助っ人頼みの運営が長続きする保証はない。それでも、住民と外部の人々が力を合わせて伝統を守ろうとするこの試みは、過疎に悩む多くの地域にとって、一つの可能性を示していると言えるだろう。": [0.0, 63.275], "例の村の祭り、今年は中止になると思ってたよ。": [63.675, 4.575], "私も。にもかかわらず、参加者は過去最多だったんだって。": [68.65, 5.39], "まさに起死回生だね。何があったの?": [74.44, 3.34], "都会の若者が助っ人で来てくれたらしいよ。": [78.18, 3.615], "大雨だった。にもかかわらず、試合は予定どおり行われた。": [82.195, 5.135], "何度も注意された。にもかかわらず、彼は同じミスを繰り返した。": [87.73, 5.585], "平日であるにもかかわらず、会場は大勢の人でにぎわった。": [93.715, 4.925], "準備期間は一週間しかなかった。にもかかわらず、チーム全員が粉骨砕身したおかげで、発表会は大成功に終わった。": [99.04, 9.93], "十分な準備期間があった。にもかかわらず、計画は失敗に終わった。": [109.37, 5.94], "一生懸命勉強した。それなのに、また不合格だった。": [115.71, 4.985], "起死回生": [121.095, 1.46], "孤立無援": [122.955, 1.185], "危機一髪": [124.54, 1.46], "絶体絶命": [126.4, 1.67], "粉骨砕身": [128.47, 1.655], "堅忍不抜": [130.525, 1.475], "悪戦苦闘": [132.4, 1.565], "七転八起": [134.365, 1.58]}, "d192": {"旧市民球場の跡地をどう活用するか、市議会での議論は平行線をたどっている。新たな多目的スタジアムを建設して観光客を呼び込むべきだという意見がある一方で、緑地公園として整備し、住民の憩いの場にすべきだという声も根強い。前者は経済効果を、後者は維持費の安さと暮らしの質を重視しており、どちらの主張にも一理ある。いずれにせよ、確かなことが一つある。結論を先延ばしにするほど、跡地は雑草の生い茂る空き地のまま放置され、どちらの案の利点も享受できないということだ。跡地をめぐる議論はすでに三年に及び、市民の間には「結局何も決まらない」という諦めすら広がっている。優柔不断な議会に今必要なのは、完璧な答えを探し続けることではない。期限を区切って住民の意見を集約し、責任を持って決断を下すことである。": [0.0, 60.75], "新商品の発売、来月にするか再来月にするか、まだ決まらないのか。": [61.15, 6.42], "はい、営業部と開発部で侃々諤々の議論が続いておりまして。": [67.97, 5.64], "いずれにせよ、今週中に結論を出してくれ。時間が惜しい。": [74.01, 5.37], "承知しました。明日の会議で必ず決めます。": [79.78, 3.98], "参加するかどうかは自由だ。いずれにせよ、金曜までに返事をください。": [84.16, 6.05], "原因が人為的なものか自然現象かは不明だ。いずれにせよ、早急な対策が必要だ。": [90.61, 7.495], "電車で行くかバスで行くか、いずれにせよ一時間はかかる。": [98.505, 4.715], "大学院に進むか、就職するか、まだ迷っている。いずれにせよ、今のうちに専門分野の勉強をしっかりしておくつもりだ。": [103.62, 10.19], "晴れても雨でも、いずれにせよ試合は行われる。": [114.21, 3.955], "細かいことは後で考えよう。とにかく、今は急いで現場に向かおう。": [118.565, 6.025], "優柔不断": [124.99, 1.39], "朝令暮改": [126.78, 1.525], "是々非々": [128.705, 1.27], "侃々諤々": [130.375, 1.765], "喧々囂々": [132.54, 1.67], "満場一致": [134.61, 1.415], "大義名分": [136.425, 1.365], "時期尚早": [138.19, 1.345]}, "d193": {"会議が長い会社ほど生産性が低い、とはよく言われることだ。ある調査では、管理職は勤務時間の四割近くを会議に費やしているという。しかも、その多くは情報共有が目的で、何かを決めるわけではない。参加者は資料を読み上げる声を聞きながら、頭では別の仕事のことを考えている。これでは時間の無駄遣いと言われても仕方がない。では、なぜこうした会議がなくならないのか。理由の一つは、会議に出ること自体が「仕事をしている証拠」とみなされる風土にある。もう一つは、誰も責任を負いたくないために、全員で集まって決めたという形をつくりたがる心理だ。要するに、無駄な会議は時間管理の問題である以前に、組織の文化と責任のあり方の問題なのである。会議の時間を短縮するだけでは、問題の本質は解決しない。": [0.0, 59.245], "部長の話、長かったね。結局どういうこと?": [59.645, 4.675], "要するに、来月から会議は三十分以内にしろってことだよ。": [64.72, 5.165], "なるほど。でも時間だけ短くしても、有名無実になりそうだな。": [70.285, 5.645], "そうなの。中身が変わらなきゃ意味がないよね。": [76.33, 3.665], "彼は理由をあれこれ並べたが、要するにやりたくないのだ。": [80.395, 4.595], "費用もかかるし、時間も足りない。要するに、今の計画では無理だということだ。": [85.39, 6.95], "要するに、君は何が言いたいんだ。": [92.74, 3.045], "先生は練習方法についていろいろ説明してくださった。要するに、毎日欠かさず声に出して読むことが大切だということだ。": [96.185, 9.96], "説明は長かったが、要するに予算が足りないということだ。": [106.545, 4.86], "彼は私の父の弟、つまり叔父にあたる。": [111.805, 4.165], "枝葉末節": [116.37, 1.46], "有名無実": [118.23, 1.375], "羊頭狗肉": [120.005, 1.47], "竜頭蛇尾": [121.875, 1.325], "責任転嫁": [123.6, 1.605], "付和雷同": [125.605, 1.31], "面従腹背": [127.315, 1.615], "千篇一律": [129.33, 1.7]}, "d194": {"便利さは、常に善であるかのように語られる。だが、あえて不便さを残すことで生まれる価値もある。ある介護施設では、館内を完全なバリアフリーにはせず、わずかな段差や坂道を意図的に残している。利用者が日常の中で自然に足腰を使い、体の機能を保てるようにするためだ。導入当初は家族から苦情も寄せられたが、数年後には、利用者の歩行能力の低下が他の施設より緩やかだという結果が出た。便利な環境は、人から考える機会や体を動かす機会を奪いかねない。だとすれば、私たちが目指すべきは不便を一掃することではない。むしろ、どの不便を残し、どの不便を取り除くかを見極めることではないだろうか。何でも楽にすればよいという発想は、時として本末転倒の結果を招くのである。": [0.0, 56.44], "あの施設、わざと段差を残してるんですって。危なくないんですか。": [56.84, 5.555], "私も最初はそう思いました。でも、むしろそのほうが足腰が衰えにくいそうです。": [62.795, 6.82], "へえ、不便さにも意味があるんですね。": [70.015, 3.19], "ええ。一挙両得とまではいかなくても、何でも楽にすればいいわけじゃないんですね。": [73.605, 6.39], "彼は天才というより、むしろ努力の人だ。": [80.395, 3.815], "失敗は恥ずかしいことではない。むしろ、成長のチャンスだと考えるべきだ。": [84.61, 6.495], "こんなに道が混んでいるなら、むしろ歩いて行ったほうが早い。": [91.505, 4.67], "人見知りは短所だと思われがちだ。しかし、むしろ相手の話をじっくり聞けるという長所でもある。": [96.575, 7.78], "言い訳をするより、むしろ黙っていたほうがいい。": [104.755, 3.775], "薬を飲んだら、かえって具合が悪くなった。": [108.93, 3.63], "一挙両得": [112.96, 1.495], "自業自得": [114.855, 1.44], "自縄自縛": [116.695, 1.46], "自画自賛": [118.555, 1.2], "自問自答": [120.155, 1.435], "自給自足": [121.99, 1.5], "自暴自棄": [123.89, 1.3], "因果応報": [125.59, 1.42]}, "d195": {"子どもに勉強させようと、テストで良い点を取るたびにご褒美を与える親は多い。一見、合理的なやり方に思える。ところが心理学の研究では、こうした報酬がかえって学ぶ意欲を損なう場合があることが知られている。ある実験では、もともと絵を描くのが好きな子どもたちを二つに分け、一方のグループにだけ、描けばご褒美をあげると約束した。すると後日、ご褒美がない状況では、そのグループの子どもたちが自由時間に自分から絵を描くことは少なくなったのである。楽しいから描くという内側からの動機が、ご褒美のために描くという外側の動機に置き換わってしまったのだと考えられる。もちろん、報酬が常に悪いわけではない。だが、善意から出た工夫が子どもの好奇心の芽を摘んでいないか、時には立ち止まって考えてみる必要があるだろう。": [0.0, 56.925], "息子に、テストで百点取ったらゲームを買ってあげるって約束したの。": [57.325, 5.34], "それ、かえってやる気をなくすこともあるらしいよ。": [63.065, 3.935], "えっ、どうして?": [67.4, 1.645], "ご褒美のための勉強になっちゃうんだって。良かれと思ってしたことが裏目に出るんだね。": [69.445, 6.22], "親切のつもりで手伝ったが、かえって迷惑をかけてしまった。": [76.065, 5.045], "近道をしようとしたら、道に迷ってかえって時間がかかった。": [81.51, 4.96], "あまり細かく注意すると、かえって部下のやる気をそぐ。": [86.87, 4.37], "緊張をほぐそうと冗談を付け加えたら、かえって場の空気が重くなってしまった。まさに蛇足だった。": [91.64, 7.72], "急いで書いたら、かえって間違いが増えた。": [99.76, 3.5], "逆に考えれば、この失敗はチャンスでもある。": [103.66, 3.975], "過ぎたるは猶及ばざるが如し": [108.035, 2.575], "助長": [111.01, 1.15], "蛇足": [112.56, 1.115], "杞憂": [114.075, 1.015], "矛盾": [115.49, 0.97], "塞翁が馬": [116.86, 1.525], "怪我の功名": [118.785, 1.475], "角を矯めて牛を殺す": [120.66, 2.135]}, "d197": {"店を選ぶとき、インターネットの評価を参考にする人は多い。星の数が多ければ安心し、少なければ避ける。だが、評価の数字はあくまで投稿した人々の感想の平均にすぎない。満足した客の大半は何も書かずに帰り、不満を持った客ほど投稿したがる傾向があるとも言われる。さらに、評価を上げるための「やらせ」の投稿が紛れ込んでいる例も後を絶たない。つまり、星の数は店の実力を正確に映す鏡ではなく、さまざまな偏りを含んだ一つの目安なのだ。もちろん、評価を参考にすること自体が悪いのではない。問題は、数字を絶対的な基準とみなし、自分の舌や目で確かめる手間を省いてしまうことである。玉石混交の情報があふれる時代だからこそ、最後に判断を下すのは自分自身だという当たり前のことを、改めて心に留めておきたい。": [0.0, 61.78], "この店、評価が星二つだよ。やめておこうか。": [62.18, 4.65], "でも、それはあくまで何人かの感想でしょ。": [67.23, 3.815], "まあね。針小棒大に書く人もいるかもしれないし。": [71.445, 4.375], "そうそう。百聞は一見に如かず、自分で食べてみようよ。": [76.22, 5.17], "これはあくまで私個人の意見です。": [81.79, 2.87], "彼はあくまで自分の非を認めようとしなかった。": [85.06, 3.595], "この数字はあくまでも目安にすぎない。": [89.055, 3.05], "私は、朝型の生活のほうが勉強の効率が上がると思う。ただ、これはあくまで私の経験にもとづく感想にすぎない。": [92.505, 10.35], "これはあくまで仮の計画だ。": [103.255, 2.47], "青い空がどこまでも広がっている。": [106.125, 2.725], "玉石混交": [109.25, 1.8], "針小棒大": [111.45, 1.6], "美辞麗句": [113.45, 1.215], "大言壮語": [115.065, 1.45], "誇大妄想": [116.915, 1.535], "正真正銘": [118.85, 1.695], "虚心坦懐": [120.945, 1.6], "公平無私": [122.945, 1.33]}, "d198": {"かつて、どの町にも商店街があった。八百屋の主人は客の家族構成まで知っていて、「今日は息子さんの誕生日だろう」と果物をおまけしてくれる。子どもが一人で歩いていれば、誰かが声をかける。商店街は単に物を売り買いする場所ではなく、いわば地域全体を見守る大きな家のような存在だったのだ。大型店やネット通販の普及で、多くの商店街はシャッター通りと化した。買い物の利便性は格段に増したが、失われたのは店だけではない。顔の見える関係の中で自然に成り立っていた防犯や子育ての機能もまた、静かに姿を消したのである。近年、空き店舗を活用して子ども食堂や高齢者の集いの場を開く試みが各地で始まっている。こうした取り組みは、商店街が担っていた見えない役割を取り戻そうとする模索と言えるだろう。": [0.0, 57.23], "昔の商店街って、みんな顔見知りだったんでしょう。": [57.63, 4.415], "そうだよ。八百屋のおじさんなんか、いわば町内の見張り役だったな。": [62.445, 5.49], "いいなあ。言わなくても以心伝心で通じる関係ですね。": [68.335, 4.58], "うん。今は空き店舗で子ども食堂をやってるところもあるらしいよ。": [73.315, 4.955], "この町は、いわば日本社会の縮図だ。": [78.67, 3.525], "彼は私にとって、いわば兄のような存在だ。": [82.595, 4.14], "睡眠は、いわば脳の掃除の時間なのだ。": [87.135, 3.69], "祖母の家の縁側は、私にとっていわば心の避難所のような場所だ。悩みがあると、いつもそこでぼんやり庭を眺めていた。": [91.225, 9.69], "図書館は、いわば町の頭脳だ。": [101.315, 2.995], "彼はいわゆる「団塊の世代」に属する。": [104.71, 4.155], "以心伝心": [109.265, 1.37], "一期一会": [111.035, 1.44], "相互扶助": [112.875, 1.32], "共存共栄": [114.595, 1.49], "和気藹々": [116.485, 1.29], "一蓮托生": [118.175, 1.685], "管鮑の交わり": [120.26, 1.645], "水魚の交わり": [122.305, 1.575]}, "d199": {"新しい制度を導入するとき、私たちはしばしば「どうやるか」の議論に終始してしまう。例えば、ある市では小中学校へのタブレット端末の配布をめぐって、機種の選定や通信環境の整備、故障時の対応といった細部の検討に一年以上が費やされた。ところが、いざ配布してみると、授業で使われる場面はごくわずかだった。教員の多くが、端末を使って何を教えればよいのか分からなかったのである。そもそも端末を配る目的は何だったのか。子どもたちにどんな力を身につけてほしいのか。この最初の問いが曖昧なまま手段の議論ばかりが先行すれば、立派な道具も宝の持ち腐れになる。手段を磨くことは大切だが、それが目的化してしまっては本末転倒だ。行き詰まったときこそ、そもそもの出発点に立ち返る勇気が必要なのである。": [0.0, 59.255], "新しいシステム、結局ほとんど使われていないそうだね。": [59.655, 4.745], "はい。操作の研修はしたんですが……。": [64.8, 3.28], "そもそも、何のために入れたのかが現場に伝わっていなかったんじゃないか。": [68.48, 5.525], "おっしゃるとおりです。暗中模索の状態でした。目的の説明から、もう一度やり直します。": [74.405, 7.74], "そもそも、この計画は誰が言い出したのか。": [82.545, 3.935], "遅刻を責める前に、そもそも集合時間が早すぎたのではないか。": [86.88, 5.455], "けんかのそもそもの原因は、小さな誤解だった。": [92.735, 4.115], "クラスの雰囲気が悪いと先生は嘆いている。だが、そもそも生徒同士が話し合う機会が十分に設けられていたのだろうか。": [97.25, 9.625], "そもそも、なぜこの会議が必要なのか。": [107.275, 3.795], "彼はもともと無口な性格だ。": [111.47, 2.705], "暗中模索": [114.575, 1.53], "五里霧中": [116.505, 1.295], "紆余曲折": [118.2, 1.52], "初志貫徹": [120.12, 1.445], "原点回帰": [121.965, 1.455], "熟慮断行": [123.82, 1.435], "深謀遠慮": [125.655, 1.51], "一意専心": [127.565, 1.32]}, "d200": {"地元で採れた野菜を地元で食べる「地産地消」は、単なる流行ではない。輸送距離が短ければ、それだけ燃料の消費が抑えられ、新鮮なうちに食卓に届く。消費者にとっては鮮度の良い食材が手に入り、生産者にとっては中間の流通費を省いて適正な収入を得られる。さらに、地元の農家が経営を続けられれば、耕作放棄地の増加に歯止めがかかり、田畑が持つ水源の保全や景観の維持にもつながる。つまり、毎日の買い物で地元の野菜を一つ選ぶことが、地域の農業を支え、ひいては地域の環境や暮らしそのものを守ることになるのだ。もっとも、地産地消は万能ではなく、品目や季節によっては価格が割高になることもある。それでも、自分の消費が何につながっているのかを意識するだけで、私たちの日々の選択は少し変わるのではないだろうか。": [0.0, 62.36], "この野菜、ちょっと高いけど地元産なんだね。": [62.76, 4.075], "うん。地元の農家を応援することが、ひいては町の田んぼや景色を守ることになるんだって。": [67.235, 7.11], "そう考えると、毎日の買い物も大事だね。": [74.745, 4.03], "そうだね。三寒四温の季節だし、旬の菜の花でも買っていこうか。": [79.175, 5.97], "一人一人の節電が、ひいては地球温暖化の防止につながる。": [85.545, 5.145], "社員の健康を守ることは、ひいては会社の利益にもなる。": [91.09, 4.87], "読書は語彙を増やし、ひいては考える力を育てる。": [96.36, 4.585], "毎朝決まった時間に起きることは、生活のリズムを整え、ひいては仕事の効率を高めることにつながる。": [101.345, 8.7], "小さなミスの放置が、ひいては大事故を招く。": [110.445, 4.115], "雨が降り出し、さらには雷まで鳴り始めた。": [114.96, 4.12], "自然淘汰": [119.48, 1.385], "弱肉強食": [121.265, 1.785], "適者生存": [123.45, 1.49], "晴耕雨読": [125.34, 1.595], "一陽来復": [127.335, 1.535], "三寒四温": [129.27, 1.46], "花鳥風月": [131.13, 1.57], "風光明媚": [133.1, 1.38]}, "d201": {"ネット上の情報の真偽を見抜くのは、大人にとっても容易なことではない。もっともらしい見出しや専門家風の解説に、大量の「いいね」がついていれば、私たちはつい信じ込んでしまう。実際、ある調査では、偽のニュースを見せられた成人の半数以上が、それを事実だと判断したという。ましてや、生まれたときからスマートフォンが身近にあった子どもたちが、批判的な目を持たずに情報の海に飛び込めばどうなるか。誤った情報をそのまま信じ、時には自分も拡散する側に回ってしまう危険は言うまでもない。だからこそ、情報を疑い、出どころを確かめる力を、学校教育の早い段階から系統的に育てる必要がある。ただ「ネットは危ない」と禁止するだけでは、子どもたちを守ることにはならない。必要なのは、危険を避ける術ではなく、危険と向き合う術を教えることなのだ。": [0.0, 62.69], "この記事、専門家のコメントもあるし、本当っぽいよね。": [63.09, 5.115], "大人でもだまされるのに、ましてや子どもならすぐ信じちゃうよ。": [68.605, 4.76], "確かに。うちの子も、何でもすぐ友達に転送してるな。": [73.765, 5.205], "軽はずみに広めないように、出どころを確かめる習慣をつけさせないとね。": [79.37, 5.565], "専門家でさえ解けない問題だ。ましてや素人に分かるはずがない。": [85.335, 5.22], "大人でも疲れる道のりだ。ましてや小さな子どもにはつらいだろう。": [90.955, 5.165], "友人にも話せない。ましてや親になど、とても言えない。": [96.52, 4.755], "日本人の友人でさえ、この古文は難しいと言っていた。ましてや、留学して半年の私に読めるはずがない。": [101.675, 9.14], "母語でも難しい。ましてや外国語ではなおさらだ。": [111.215, 4.275], "雨が降るなら、なおさら早く出発しよう。": [115.89, 3.695], "軽挙妄動": [119.985, 1.545], "傍若無人": [121.93, 1.445], "厚顔無恥": [123.775, 1.385], "言語道断": [125.56, 1.365], "唯我独尊": [127.325, 1.465], "独断専行": [129.19, 1.53], "品行方正": [131.12, 1.565], "清廉潔白": [133.085, 1.625]}, "d202": {"念願の北海道旅行は、出発の朝から雲行きが怪しかった。空港に向かう電車が事故で止まり、予約していた便に乗り遅れたのだ。何とか午後の便に振り替えてもらったものの、到着した札幌は季節外れの大雪で、おまけに予約したはずのホテルには私の名前が見当たらない。フロント係と押し問答の末、ようやく見つかったのは駅から遠い古びた旅館だった。四面楚歌とはまさにこのことかと天を仰いだが、旅というのは分からないものである。その旅館の女将が出してくれた石狩鍋の、なんとうまかったことか。雪で足止めされた他の客たちとも打ち解け、夜更けまで語り合った。予定どおりに進んでいたら、決して出会えなかった人々と味である。人間万事塞翁が馬。思いどおりにならなかった旅ほど、後になって懐かしく思い出されるものだ。": [0.0, 57.235], "旅行、どうだった?": [57.635, 1.995], "最悪だったよ。飛行機に乗り遅れて、おまけにホテルの予約も入ってなかったんだ。": [60.03, 6.585], "八方塞がりだね。それでどうしたの?": [67.015, 3.375], "古い旅館に泊まったんだけど、それが最高でさ。まさに塞翁が馬だよ。": [70.79, 6.01], "この部屋は狭くて暗い。おまけに家賃も高い。": [77.2, 4.14], "道に迷い、おまけに雨まで降ってきた。": [81.74, 3.595], "彼女は頭がよくて親切で、おまけに料理も上手だ。": [85.735, 4.695], "今朝は寝坊して電車に乗り遅れた。おまけに、会社に着いてから大事な資料を家に忘れたことに気づき、前途多難な一日の始まりとなった。": [90.83, 11.1], "寝坊して、おまけに財布まで忘れた。": [102.33, 3.36], "本社は駅から近く、そのうえ設備も整っている。": [106.09, 4.52], "四面楚歌": [111.01, 1.445], "七転八倒": [112.855, 1.74], "八方塞がり": [114.995, 1.66], "波瀾万丈": [117.055, 1.515], "前途多難": [118.97, 1.255], "急転直下": [120.625, 1.58], "破顔一笑": [122.605, 1.445], "呉越同舟": [124.45, 1.425]}, "d204": {"高度経済成長期に一斉に造られた橋やトンネルが、今、老朽化の時期を迎えている。国の調査では、建設から五十年以上が経過する橋は、十年後には全体の六割に達する見込みだという。点検で補修が必要と判断されながら、予算や技術者の不足から手つかずのままになっている橋も少なくない。こうした状況で求められるのは、壊れてから直す「事後保全」から、壊れる前に手を打つ「予防保全」への転換である。初期の小さなひび割れの段階で補修すれば費用は抑えられるが、放置して損傷が進めば、架け替えに何倍もの費用がかかる。インフラの維持管理には、今こそ計画的な投資が必要だ。さもないと、将来世代は膨大な更新費用を背負わされ、最悪の場合、人命にかかわる事故が起きかねない。目に見えにくいインフラの危機に、社会全体でもっと関心を払うべきである。": [0.0, 64.255], "毎日少しずつでも歩くようにしてください。さもないと、筋力がどんどん落ちてしまいますよ。": [64.655, 7.35], "はい、分かってはいるんですが、つい……。": [72.405, 3.36], "一度落ちた筋力を取り戻すのは大変ですから、今のうちに始めましょう。": [76.165, 5.825], "分かりました。背水の陣で、明日から駅まで歩いてみます。": [82.39, 5.125], "早く出発しなさい。さもないと、最終電車に間に合わないよ。": [87.915, 5.685], "データはこまめに保存すること。さもないと、すべてを失いかねない。": [94.0, 5.695], "期限までに返却してください。さもないと、延滞料が発生します。": [100.095, 5.845], "試験の前日は早めに寝たほうがいい。さもないと、本番で頭が働かず、これまでの努力が水の泡になってしまう。": [106.34, 9.615], "薬は毎日飲むように。さもないと、症状が悪化する恐れがある。": [116.355, 5.87], "もう出よう。でないと、遅刻しちゃう。": [122.625, 3.36], "覆水盆に返らず": [126.385, 1.845], "臥薪嘗胆": [128.63, 1.435], "背水の陣": [130.465, 1.36], "漁夫の利": [132.225, 1.095], "五十歩百歩": [133.72, 1.46], "他山の石": [135.58, 1.37], "李下に冠を正さず": [137.35, 2.115], "百聞は一見に如かず": [139.865, 2.085]}, "d205": {"日本は世界有数の地震国である。国土の面積は世界の陸地のわずか〇・三パーセントにすぎないが、世界で起こる大きな地震の約二割がこの周辺で発生している。それゆえ、日本の建築の歴史は、揺れとの闘いの歴史でもあった。五重塔が数百年にわたって倒れずに立ち続けてきたのは、中心を貫く柱が揺れを和らげる仕組みを持つからだと言われる。この知恵は、現代の高層ビルの制震構造にも通じている。とはいえ、技術さえあれば安心というわけではない。どれほど頑丈な建物でも、家具が倒れてくれば中にいる人は危険にさらされるし、避難経路を知らなければ逃げ遅れる。地震と共に生きる宿命を負った国であるからこそ、建物の強さと一人一人の備えという両輪がそろって、はじめて命は守られるのである。": [0.0, 56.63], "先生、五重塔ってどうして地震で倒れないんですか。": [57.03, 4.615], "中心の柱が揺れを和らげるからだと言われているね。日本は地震が多い。それゆえ、こうした知恵が発達したんだよ。": [62.045, 9.375], "昔の人はすごいですね。": [71.82, 2.25], "ただ、いざというとき冷静沈着でいられるかどうかは、日頃の備え次第だよ。": [74.47, 6.415], "彼は誰に対しても誠実だった。それゆえ、多くの人に慕われた。": [81.285, 5.81], "この地方は雨が少ない。それゆえ、古くからため池が数多く造られてきた。": [87.495, 6.65], "人は不完全な存在だ。それゆえに、互いに支え合う必要がある。": [94.545, 5.73], "韓国の冬は寒さが厳しく、空気も乾燥している。それゆえ、床から部屋全体を暖めるオンドルという暖房が発達した。": [100.675, 10.375], "資源に乏しい国である。それゆえ、人材の育成に力を注いできた。": [111.45, 6.35], "電車が止まっていたんです。それで、遅れてしまいました。": [118.2, 4.84], "不撓不屈": [123.44, 1.285], "泰然自若": [125.125, 1.435], "冷静沈着": [126.96, 1.575], "危急存亡": [128.935, 1.52], "臨戦態勢": [130.855, 1.525], "百戦錬磨": [132.78, 1.545], "難攻不落": [134.725, 1.535], "質実剛健": [136.66, 1.55]}, "d206": {"プラスチックごみによる海洋汚染が深刻化している。年間数百万トンものプラスチックが海に流れ込み、魚や海鳥の体内からも見つかっている。レジ袋の有料化をはじめ、使い捨てプラスチックを減らす取り組みが各国で進められているのは当然のことだろう。かといって、プラスチックを社会から一掃すればよいという単純な話ではない。軽くて丈夫なプラスチック包装は、食品の鮮度を保ち、食品ロスを減らす役割も果たしている。代わりに紙やガラスを使えば、製造や輸送の過程でかえって多くのエネルギーを消費する場合もある。二律背反とも言えるこの難題に、唯一の正解はない。必要なのは「プラスチックは悪」という一面的な見方から脱し、用途ごとに環境への負荷を比較したうえで、使うべきところと減らすべきところを冷静に見極めることである。": [0.0, 58.86], "レジ袋なんて、もう全部紙袋にすればいいのに。": [59.26, 4.28], "うーん、かといって紙が環境にいいとは限らないらしいよ。": [63.94, 4.62], "えっ、そうなの?": [68.96, 1.775], "作るときにエネルギーをたくさん使うんだって。単純な二者択一で決められる問題じゃないね。": [71.135, 6.765], "今の仕事に不満はある。かといって、辞める勇気もない。": [78.3, 4.99], "甘いものは控えている。かといって、まったく食べないわけではない。": [83.69, 5.235], "外食は高くつく。かといって、毎日自炊する時間もない。": [89.325, 5.51], "今の部屋は駅から遠くて不便だ。かといって、駅前に引っ越せば家賃が倍になるので、二者択一に頭を悩ませている。": [95.235, 9.67], "彼の意見には反対だ。かといって、代案があるわけでもない。": [105.305, 5.22], "疲れているからといって、仕事を投げ出すわけにはいかない。": [110.925, 4.605], "二律背反": [115.93, 1.43], "二者択一": [117.76, 1.505], "取捨選択": [119.665, 1.645], "千載一遇": [121.71, 1.655], "一刀両断": [123.765, 1.4], "一網打尽": [125.565, 1.405], "一触即発": [127.37, 1.67], "一騎当千": [129.44, 1.355]}, "d207": {"本書の企画が持ち上がったのは、今から五年前のことである。当初は一年で刊行する予定だったが、取材先の事情で計画は二転三転し、途中で共著者の一人が病に倒れるという事態にも見舞われた。原稿を全面的に書き直したことも一度や二度ではない。正直に言えば、刊行をあきらめかけた時期もあった。ともあれ、こうして一冊の本の形にまとめることができたのは、取材に快く応じてくださった方々と、粘り強く励まし続けてくれた編集部のおかげである。回り道をした分、内容は当初の構想よりもはるかに厚みのあるものになったと自負している。もっとも、至らない点も多々あるだろう。読者の皆様からの率直なご批判を、次の仕事への糧とさせていただきたい。最後に、本書を手に取ってくださったすべての方に、心からの感謝を申し上げる。": [0.0, 59.885], "出版おめでとう。五年もかかったんだって?": [60.285, 3.705], "うん、計画が二転三転して、何度もあきらめかけたよ。": [64.39, 4.91], "ともあれ、形になってよかったね。特に最終章は圧巻だったよ。": [69.7, 5.875], "ありがとう。編集部が最後まで支えてくれたおかげだよ。": [75.975, 4.65], "いろいろあったが、ともあれ無事に帰国できてよかった。": [81.025, 4.06], "何はともあれ、まずは乾杯しましょう。": [85.485, 3.42], "結果はともあれ、最後まで全力を尽くしたことに意味がある。": [89.305, 4.89], "引っ越しの当日は雨が降り、荷物も予定より遅れて届いた。ともあれ、夜には新しい部屋で落ち着いて眠ることができた。": [94.595, 9.845], "細かい点はともあれ、計画の方向性は正しい。": [104.84, 4.515], "見た目はともかく、味は確かだ。": [109.755, 3.03], "二転三転": [113.185, 1.3], "起承転結": [114.885, 1.585], "画竜点睛": [116.87, 1.485], "推敲": [118.755, 1.29], "完璧": [120.445, 1.23], "圧巻": [122.075, 1.05], "白眉": [123.525, 1.13], "蛍雪の功": [125.055, 1.57]}, "d208": {"スウェーデンでは、父親の九割近くが育児休業を取得するという。両親に与えられる休業期間のうち一定の日数は父親だけが使える仕組みになっており、取らなければその分の権利が消える。この制度によって、男性が育児に参加することは特別なことではなく、ごく当たり前の光景になった。ひるがえって日本の現状はどうか。男性の育児休業取得率は上昇傾向にあるとはいえ、北欧諸国とは比較にならない水準にとどまり、取得期間も数日から数週間という短いものが多い。制度自体は整いつつあるのに、職場に迷惑をかけるという遠慮や、昇進への影響を懸念する声が根強いのだ。制度をいくら増やしても、意識が変わらなければ状況は変わらない。他国の成功例を参考にするなら、制度の形だけでなく、それを支える社会の空気にまで目を向ける必要があるだろう。": [0.0, 61.165], "スウェーデンじゃ、父親の九割近くが育休を取るんだって。": [61.565, 4.71], "すごいね。ひるがえってうちの会社なんて、取った男性はまだ二人だけだよ。": [66.675, 5.995], "制度はあっても、職場の雰囲気が旧態依然としてるからなあ。": [73.07, 5.04], "まず上の人が取ってくれれば、空気も変わると思うんだけど。": [78.51, 4.675], "他国は再生可能エネルギーの導入を急いでいる。ひるがえって、わが国の取り組みはどうだろうか。": [83.585, 7.545], "後輩の熱心な姿を見て、ひるがえって自分の怠けぶりを反省した。": [91.53, 5.57], "ひるがえって考えると、問題の原因は私たち自身にもあった。": [97.5, 5.23], "日本の電車では、多くの人が静かに本を読んでいる。ひるがえって自分を見ると、移動中はついスマートフォンばかり眺めている。": [103.13, 9.68], "海外の若者は政治に積極的に関わっている。ひるがえって日本の若者はどうか。": [113.21, 6.82], "都市部の人口は増えている。一方、地方では過疎化が進んでいる。": [120.43, 5.775], "内憂外患": [126.605, 1.415], "群雄割拠": [128.42, 1.54], "鶏口牛後": [130.36, 1.425], "先憂後楽": [132.185, 1.62], "旧態依然": [134.205, 1.3], "前途洋々": [135.905, 1.415], "日常茶飯": [137.72, 1.515], "異国情緒": [139.635, 1.38]}, "d209": {"父が亡くなって三年、故郷の実家は空き家のままになっている。私も兄も都会に家庭を持ち、今さら帰って住むつもりはない。古い木造家屋に買い手がつくとは思えず、維持するだけでも固定資産税や修繕費がかさむ。合理的に考えれば、早く取り壊して土地を処分すべきなのだろう。さりとて、いざ業者に連絡しようとすると、どうしても手が止まってしまう。柱に刻まれた背比べの傷、縁側で父と並んで見た夕焼け。あの家には、数字では測れない家族の時間が染み込んでいるのだ。全国で空き家が増え続け、防災や景観の面から社会問題になっていることは承知している。私のような煮え切らない持ち主が、その一因であることも。それでも、思い出の詰まった家を「処分すべき資産」と割り切れるようになるまで、もう少しだけ時間が欲しいと願ってしまうのである。": [0.0, 61.24], "実家、まだそのままなの?": [61.64, 2.58], "うん。維持費もかかるし、売ったほうがいいのは分かってるんだけど。": [64.62, 5.085], "さりとて、思い出のある家を手放すのはつらいよね。": [70.105, 4.28], "そうなんだ。売るとなったら、まさに断腸の思いだよ。": [74.785, 4.65], "行きたくはない。さりとて、断る理由も見つからない。": [79.835, 4.795], "彼の態度には腹が立つ。さりとて、正面から抗議するわけにもいかない。": [85.03, 6.375], "今の暮らしに不満はない。さりとて、満ち足りているとも言い難い。": [91.805, 5.495], "古いギターはもう何年も弾いていないので、売ってしまったほうがいい。さりとて、学生時代の思い出を考えると、手放す気にはなれない。": [97.7, 10.56], "都会の生活には疲れた。さりとて、田舎に帰る決心もつかない。": [108.66, 6.12], "お金はない。かといって、借金はしたくない。": [115.18, 4.2], "断腸の思い": [119.78, 1.48], "感慨無量": [121.66, 1.505], "進退両難": [123.565, 1.475], "千思万考": [125.44, 1.62], "沈思黙考": [127.46, 1.43], "隠忍自重": [129.29, 1.335], "明鏡止水": [131.025, 1.555], "一日千秋": [132.98, 1.59]}, "d211": {"【A】在宅勤務が定着して数年が経つ。通勤のストレスから解放され、育児や介護と仕事を両立できるようになった社員は多い。働き方がフレキシブルになったことで、かえってモチベーションが上がったという声も聞く。もちろん、対面でなければ得られない気づきもあるだろう。しかし、その一点だけを理由に全員に毎日の出社を求める方針には、疑問を抱かざるを得ない。\n【B】在宅勤務の利点は認める。だが、新人教育の現場では限界を感じざるを得ない。画面越しでは、先輩の電話応対を横で聞いて覚えるといった機会がない。若手が質問のハードルを高く感じ、一人で問題を抱え込んでしまう例も少なくない。チームのコンセンサスを形づくるうえでも、週に数日は顔を合わせる日を設けるべきだろう。": [0.0, 55.935], "来月から週3日出社になるんだって？": [56.335, 3.165], "うん、会社の方針だから従わざるを得ないよ。": [59.9, 3.88], "通勤、片道1時間半でしょ。モチベーション下がらない？": [64.18, 5.01], "正直ね。でも、後輩の面倒を見るには顔を合わせたほうがいいっていうジレンマもあってさ。": [69.59, 7.06], "部品の供給が止まり、工場は操業を一時停止せざるを得なかった。": [77.05, 5.445], "これだけ証拠がそろっていれば、彼の主張を認めざるを得ない。": [82.895, 4.82], "予算が足りない以上、計画の規模を縮小せざるを得ないだろう。": [88.115, 5.005], "終電を逃してしまい、高いと分かっていてもタクシーで帰らざるを得なかった。翌日の会議も延期せざるを得なくなった。": [93.52, 8.955], "大雨で道路が通れず、引き返さざるを得なかった。": [102.875, 4.06], "あまりにおかしくて、笑わずにはいられなかった。": [107.335, 3.74], "コンセンサス": [111.475, 1.42], "ジレンマ": [113.295, 1.165], "モチベーション": [114.86, 1.345], "ハードル": [116.605, 1.115], "フレキシブル": [118.12, 1.385], "ノルマ": [119.905, 1.07], "ワークライフバランス": [121.375, 1.655], "オフライン": [123.43, 1.095]}, "d212": {"【市立中央図書館　リニューアルオープンのお知らせ】\n改修工事のため休館していた中央図書館は、11月1日（土）に再開します。\n■開館時間　平日9:00〜20:00／土日祝9:00〜18:00\n■休館日　毎月第2月曜日（祝日の場合は翌日）、および館内メンテナンス日\n■新サービス\n・学習スペース（2階）：事前エントリー制。ウェブで前日まで予約可。1回3時間まで\n・電子書籍サービス：利用カードをお持ちの方は、自宅からもアクセス可能\n・資料の取り置き：カテゴリーを問わず1人10点まで\n※学習スペースの当日利用は、空きがある場合のみ受け付けます。\n館長より：新しいレイアウトの館内で皆様をお迎えできる日が、今から待ち遠しく思えてなりません。": [0.0, 59.29], "図書館、来月リニューアルオープンするんだって。": [59.69, 3.69], "学習スペースって予約制になるの？": [63.78, 3.03], "うん、前日までにウェブでエントリーするみたい。": [67.21, 3.57], "試験前は取り合いになりそうで、今から心配でならないよ。": [71.18, 4.775], "一人暮らしを始めてから、故郷の母のことが気になってならない。": [76.355, 5.17], "あの時もっと強く止めていればと、悔やまれてならない。": [81.925, 4.3], "彼の説明には、何か裏があるように思えてならない。": [86.625, 4.395], "最近、仕事の量に比べて評価が低いような気がしてならない。このままでいいのか、将来のことが心配でならない。": [91.42, 9.345], "合格発表の日が近づき、不安でならない。": [101.165, 3.86], "試験中に私語をしてはならない。": [105.425, 2.445], "リニューアル": [108.27, 1.185], "エントリー": [109.855, 1.165], "オプション": [111.42, 1.055], "カテゴリー": [112.875, 1.28], "レイアウト": [114.555, 1.235], "アクセス": [116.19, 1.23], "メンテナンス": [117.82, 1.37], "スペース": [119.59, 1.23]}, "d213": {"【A】小学生の息子にスマートフォンを持たせた。塾帰りの夜道を一人で歩かせるのが心配でたまらなかったからだ。位置情報を確認できるだけで、親の不安はずいぶん軽くなる。もちろんフィルタリングを設定し、使う時間も家族でルールを決めた。危険から遠ざけるより、早いうちに正しい使い方を身につけさせるほうが、結局はリテラシーを育てる近道ではないだろうか。\n【B】子どもにスマートフォンを与えることには慎重であるべきだと考える。ネット上のトラブルは大人の目の届かない所で起こる。フィルタリングをかけても、抜け道を探すのが子どもである。連絡手段が必要なら、通話機能だけの端末で十分だ。わが子が画面に夢中になり、外で遊ばなくなっていく姿を想像すると、残念に思えてならない。": [0.0, 54.75], "娘がスマホが欲しくてたまらないって、毎日言うのよ。": [55.15, 4.435], "クラスでも、もう持ってない子のほうが少ないらしいね。": [59.985, 4.125], "でも、ネットのトラブルに巻き込まれないか心配で。": [64.51, 4.05], "フィルタリングをかけて、使い方のルールを一緒に決めたらどうかな。": [68.96, 5.075], "合格の知らせを聞いて、うれしくてたまらなかった。": [74.435, 4.055], "冷房が壊れた部屋は、蒸し暑くてたまらない。": [78.89, 3.91], "試合に負けたのが悔しくてたまらず、夜も眠れなかった。": [83.2, 4.64], "久しぶりに会う友人との旅行が楽しみでたまらない。ただ、天気予報を見ると、当日は雨になるような気がしてならない。": [88.24, 9.335], "朝から歯が痛くてたまらない。": [97.975, 2.395], "彼が嘘をついているように思えてならない。": [100.77, 3.125], "リテラシー": [104.295, 1.29], "デバイス": [105.985, 1.17], "フィルタリング": [107.555, 1.245], "モラル": [109.2, 0.995], "リスク": [110.595, 1.045], "ガイドライン": [112.04, 1.21], "コミュニティ": [113.65, 1.19], "ツール": [115.24, 1.025]}, "d214": {"【第15回みなと町国際フェスティバルのご案内】\n日時：10月12日（日）10:00〜19:00（雨天決行）\n会場：みなと公園（各エリアの位置は会場マップをご覧ください）\n■ステージプログラム（中央エリア）\n11:00 和太鼓演奏／13:00 世界の民族舞踊／15:30 市民バンドコンサート／17:30 花火（荒天時は中止）\n■フードブース（東エリア）10:00〜18:00（売り切れ次第終了）\n■交通　駅西口から会場の正面ゲートまで、シャトルバスを20分間隔で運行（最終19:30発）。会場に駐車場はありません。\n※当日のボランティアスタッフを募集中です。詳細は実行委員会まで。\n実行委員長より：準備を重ねてきたスタッフ一同の思いは、きっと皆様に届くに相違ありません。": [0.0, 66.985], "今年のフェスティバル、駅からシャトルバスが出るらしいよ。": [67.385, 4.38], "よかった。去年は駐車場が満車で大変だったもんね。": [72.165, 4.445], "今年は会場に駐車場がないんだって。ボランティアのスタッフも増やすそうだよ。": [77.01, 5.845], "じゃあ、早めに行ってフードブースを回ろうか。": [83.255, 3.705], "現場に残された足跡から見て、犯人はこの家の事情に詳しい人物に相違ない。": [87.36, 6.815], "彼ほどの実力があれば、本番でも必ず結果を出すに相違ない。": [94.575, 5.42], "この筆跡は、祖父のものに相違ありません。": [100.395, 3.715], "窓ガラスが外側から割られていることから、侵入者は庭から入ったに相違ない。友達に言うなら「きっと庭から入ったにちがいないよ」くらいだろう。": [104.51, 11.72], "調査結果から判断して、この地層は一万年以上前のものに相違ない。": [116.63, 5.84], "電気がついているから、田中さんはもう帰ってきているにちがいない。": [122.87, 4.985], "プログラム": [128.255, 1.21], "ブース": [129.865, 1.05], "エリア": [131.315, 1.04], "ゲート": [132.755, 1.07], "スタッフ": [134.225, 1.135], "パンフレット": [135.76, 1.32], "ボランティア": [137.48, 1.265], "シャトルバス": [139.145, 1.36]}, "d215": {"【A】機械翻訳の精度は飛躍的に向上した。膨大なデータベースをもとに、アルゴリズムが文脈まで推測して訳文を出す。旅行や日常のやり取りであれば、もはや外国語を一から学ぶ必要は薄れつつあるのではないか。限られた時間は、自分の専門分野の知識を深めることに使うほうが合理的である。\n【B】機械翻訳が便利なのは確かだ。しかし、言葉の微妙なニュアンスや、相手との関係に応じた言い回しまでは任せきれない。そもそも外国語を学ぶとは、その言語を話す人々の考え方や文化に触れることにほかならない。訳文というアウトプットだけを手に入れても、学ぶプロセスで得られるはずの理解は自分の中に残らないのである。": [0.0, 50.01], "最近は翻訳アプリがあるから、英語の勉強ってもういらなくない？": [50.41, 5.07], "でも、アプリの訳ってニュアンスが変なときあるよ。": [55.88, 3.955], "まあね。インプットするデータ次第ってことか。": [60.235, 3.78], "それに、言葉を学ぶのはその国の人の考え方を知ることにほかならないって、先生も言ってたし。": [64.415, 8.08], "今回の成功は、社員一人一人の努力の結果にほかならない。": [72.895, 5.25], "彼が厳しく叱るのは、君に期待しているからにほかならない。": [78.545, 4.86], "歴史を学ぶことは、現在を理解することにほかならない。": [83.805, 4.74], "私が毎日日記を日本語で書くのは、学んだ表現をアウトプットしなければ身につかないと考えるからにほかならない。書くプロセスそのものが、最良の復習なのだ。": [88.945, 12.615], "この賞は、長年の地道な研究が認められた証にほかならない。": [101.96, 5.59], "私がしたことは、ほんの手伝いにすぎない。": [107.95, 3.77], "アルゴリズム": [112.12, 1.36], "データベース": [113.88, 1.385], "ニュアンス": [115.665, 1.1], "ナンセンス": [117.165, 1.115], "アウトプット": [118.68, 1.405], "インプット": [120.485, 1.235], "プロセス": [122.12, 1.235], "ロジック": [123.755, 1.145]}, "d216": {"今や、音楽はサブスクリプションで聴くものになったと言っても過言ではない。以下は、ある音楽配信サービスの料金プランである。\n■ライト：月額480円／広告あり／オフライン再生不可\n■スタンダード：月額980円／広告なし／ダウンロードは100曲まで\n■プレミアム：月額1,480円／広告なし／ダウンロード無制限／高音質配信\n■ファミリー：月額1,980円／プレミアムと同じ内容を、同居する家族最大5人で共有\n※学生は、スタンダードを月額580円で利用可能（学生証の登録が必要）。\n※年払いにすると、各プランとも2か月分が無料。\n※途中でアップグレードした場合、差額は日割りで計算されます。": [0.0, 56.1], "音楽、まだCD買ってるの？": [56.5, 2.885], "いや、去年からサブスクにしたよ。月額980円のプラン。": [59.785, 5.58], "学生なら安くなるの知ってた？学生証を登録すると580円だって。": [65.765, 6.205], "えっ、知らなかった。それならコストパフォーマンスは最強と言っても過言じゃないね。": [72.37, 6.3], "スマートフォンは現代人の生活を一変させたと言っても過言ではない。": [79.07, 5.29], "この試合の勝敗は、最後の一球で決まったと言っても過言ではない。": [84.76, 5.36], "彼女はこの分野の第一人者と言っても過言ではない。": [90.52, 4.055], "通勤時間に聴くポッドキャストは、私の一日のリズムを作っていると言っても過言ではない。無料のプランでも、コストパフォーマンスは十分だ。": [94.975, 10.775], "この発見は医学の歴史を変えたと言っても過言ではない。": [106.15, 4.27], "この店のラーメンは、町でいちばんと言ってもいい。": [110.82, 4.005], "サブスクリプション": [115.225, 1.635], "プラン": [117.26, 0.915], "コストパフォーマンス": [118.575, 1.805], "ユーザー": [120.78, 1.19], "アップグレード": [122.37, 1.455], "ダウンロード": [124.225, 1.295], "ストレージ": [125.92, 1.28], "プレミアム": [127.6, 1.21]}, "d218": {"【A】週休3日制を導入する企業が増えている。休日が増えれば社員は心身ともにリフレッシュでき、仕事のパフォーマンスも上がる。浮いた時間を学び直しや副業に充てる人もいるだろう。長く働くほど成果が出るという考え方は、もはや時代遅れと言わざるを得ない。\n【B】週休3日制の理念には賛成だが、現実は甘くない。もともと人手の足りない職場で休みを増やせば、残った社員にしわ寄せが行き、かえってストレスが増すだけだ。休日が増える分、給与を減らす仕組みを取る企業もある。業務量を見直さないまま制度だけを導入するのは、拙速と言わざるを得ない。": [0.0, 44.31], "来年度から、週休3日制を試験的に導入することになった。": [44.71, 5.37], "ありがたい話ですが、うちの部署はシフトが組めるかどうか…。": [50.48, 4.79], "確かに、今の人員では厳しいと言わざるを得ないな。": [55.67, 4.255], "業務の一部を外部に任せるなど、コストも含めて検討してみます。": [60.325, 5.345], "事故後の会社の対応は、あまりに遅かったと言わざるを得ない。": [66.07, 4.695], "準備期間がわずか一週間では、成功は難しいと言わざるを得ない。": [71.165, 5.47], "住民への説明が一度もなかったのは、行政の怠慢と言わざるを得ない。": [77.035, 5.66], "その駅は階段しかなく、ベビーカーや車いすの利用者への配慮が足りないと言わざるを得ない。利用者の声を聞いたうえで、早急にエレベーターを設置すべきだ。": [83.095, 11.69], "この計画は見通しが甘いと言わざるを得ない。": [95.185, 3.54], "この計画の成否が会社の将来を決めると言っても過言ではない。": [99.125, 4.905], "シフト": [104.43, 1.2], "ワークシェアリング": [106.03, 1.545], "リストラ": [107.975, 1.19], "コスト": [109.565, 1.115], "パフォーマンス": [111.08, 1.385], "ストレス": [112.865, 1.26], "リフレッシュ": [114.525, 1.245], "プライベート": [116.17, 1.345]}, "d219": {"【資源ごみの出し方が変わります（4月1日から）】\n■プラスチック製容器包装：毎週水曜日\n■ペットボトル：第1・第3金曜日（キャップとラベルは外して「プラスチック」の日へ）\n■缶・びん：第2・第4金曜日\n■スプレー缶・カセットボンベ：中身を使い切り、「缶・びん」の日に別の袋で\n■インクカートリッジ：集積所には出さず、市役所や家電店の回収箱へ\n※いずれも収集日の朝8時30分までに出してください。\n自治会より：最近、分別されていないごみが目立ち、回収されずに残される例も増えている。リサイクルが何のためにあるのかを、住民一人一人が改めて考えるべきではなかろうか。": [0.0, 52.02], "ペットボトルのキャップって、一緒に出しちゃだめなの？": [52.42, 3.935], "4月からはプラスチックの日に出すんだって。ラベルもはがしてね。": [56.755, 4.975], "面倒だなあ。でも、分別しないと回収してもらえないんでしょ。": [62.13, 5.225], "うん。リサイクルのためだと思えば、それくらいの手間はかけるべきなんじゃないかな。": [67.755, 6.135], "子どもの安全のためにも、通学路の点検を急ぐべきではなかろうか。": [74.29, 5.48], "制度を変える前に、まず現場の声を聞くべきではなかろうか。": [80.17, 4.85], "便利さばかりを追い求める生き方を、そろそろ見直すべきではなかろうか。": [85.42, 5.54], "駅前の駐輪場では、マナーを守らない利用者が後を絶たない。市は罰則を設ける前に、まず案内表示を分かりやすくするべきではなかろうか。": [91.36, 10.92], "高齢者の声をもっと政策に反映させるべきではなかろうか。": [102.68, 4.66], "他人の私生活をむやみに詮索するべきではない。": [107.74, 3.795], "リサイクル": [111.935, 1.32], "ラベル": [113.655, 1.015], "キャップ": [115.07, 1.05], "カートリッジ": [116.52, 1.29], "スプレー": [118.21, 1.2], "プラスチック": [119.81, 1.37], "マナー": [121.58, 1.065], "エコバッグ": [123.045, 1.135]}, "d220": {"【A】キャッシュレス決済の普及は、店にも客にも利点が大きい。レジでの会計時間が短くなり、釣り銭を用意する必要もない。ポイントが貯まるので買い物が楽しくなったという人もいる。現金の管理や輸送にかかる社会全体のコストを考えれば、現金は近い将来、ほとんど使われなくなるのではあるまいか。\n【B】キャッシュレス化の流れは今後も止まらないだろう。しかし、災害で停電や通信障害が起きれば、決済のインフラそのものが使えなくなる。スマートフォンの操作に不慣れな高齢者も少なくない。購入履歴が企業に集められることに、プライバシーの面から不安を抱く人もいる。すべてを電子化するのではなく、現金という選択肢も残しておくことが、誰も取り残さない社会のあり方なのではあるまいか。": [0.0, 54.63], "すみません、このカードにチャージしてあるんですが、使えますか。": [55.03, 5.115], "申し訳ありません。ただいま通信障害で、現金のみとなっております。": [60.545, 5.85], "そうですか。最近は現金を持ち歩かないので、困ったな。": [66.795, 5.195], "すぐ近くにATMがございますので、ご案内いたします。": [72.39, 4.845], "このままでは、地方の公共交通は維持できなくなるのではあるまいか。": [77.635, 5.4], "彼が急に会社を辞めたのは、何か深い事情があったからではあるまいか。": [83.435, 5.625], "子どもの読書離れは、大人の側にも責任があるのではあるまいか。": [89.46, 5.27], "スマートフォンで改札を通れるようになった今、紙の切符はやがて姿を消すのではあるまいか。実際、駅の券売機は年々減っている。": [95.13, 10.57], "この制度は、かえって格差を広げるのではあるまいか。": [106.1, 4.32], "この道、さっきも通ったんじゃないか。": [110.82, 3.425], "キャッシュレス": [114.645, 1.275], "インフラ": [116.32, 1.1], "ポイント": [117.82, 1.13], "セキュリティ": [119.35, 1.28], "プライバシー": [121.03, 1.33], "レジ": [122.76, 0.925], "チャージ": [124.085, 1.07], "タッチ": [125.555, 1.03]}, "d221": {"【運転見合わせのお知らせ】\n本日午前7時ごろ、沿線で発生した倒木の影響により、北山線は東町〜西浜間で運転を見合わせております。\n■運転再開見込み：午後2時ごろ\n■振替輸送：市営地下鉄、および中央バス（北山駅前〜西浜ターミナル）で実施中\n■東町より手前の区間は、ダイヤを大幅に減らして運転しています。\n最新の情報は、当社ウェブサイトおよび駅のアナウンスでご確認ください。\n――地元紙の記事より――\nこの区間では昨年から倒木によるトラブルが相次いでおり、通勤客はたびたびルートの変更を余儀なくされている。沿線住民からは、抜本的な対策を求める声が上がっている。": [0.0, 50.655], "北山線、また止まってるよ。倒木だって。": [51.055, 4.065], "えー、今週二回目じゃない。ラッシュの時間なのに。": [55.52, 4.4], "振替輸送でバスが出てるらしいから、ルートを変えるしかないね。": [60.32, 4.84], "沿線の人は、毎回遠回りを余儀なくされてるわけか。大変だね。": [65.56, 5.635], "工場の閉鎖により、多くの従業員が転職を余儀なくされている。": [71.595, 5.345], "豪雨の被害を受けた住民は、今も避難所での生活を余儀なくされている。": [77.34, 5.735], "原材料費の高騰で、多くの飲食店が値上げを余儀なくされている。": [83.475, 5.375], "記録的な猛暑の影響で、各地の学校が屋外での部活動の中止を余儀なくされている。熱中症対策として、活動時間を朝に移す学校も出てきた。": [89.25, 12.495], "選手はけがのため、引退を余儀なくされた。": [102.145, 3.75], "度重なるけがが、彼に引退を余儀なくさせた。": [106.295, 4.07], "ダイヤ": [110.765, 1.04], "ルート": [112.205, 1.065], "アナウンス": [113.67, 1.205], "ターミナル": [115.275, 1.21], "トラブル": [116.885, 1.105], "ラッシュ": [118.39, 1.01], "ピーク": [119.8, 1.025], "ウェブサイト": [121.225, 1.345]}, "d222": {"【A】これからの管理職に求められるのは、自ら先頭に立って部下を引っ張るリーダーシップではない。価値観や働き方の異なるメンバーの話に耳を傾け、それぞれのポテンシャルを引き出すマネジメントの力である。ダイバーシティが進む職場では、一人の判断よりも多様な意見をいかに生かすかが、チームの成果を左右するからだ。\n【B】部下の意見を聞くことはもちろん大切だ。だが、意見が割れたとき、最後に責任を持って決断するのは管理職の役目である。組織が向かう先をはっきりと示すビジョンがなければ、メンバーは迷うばかりだ。管理職には、多様性を尊重しつつも、必要な場面では自らイニシアチブを取ることが求められる。": [0.0, 50.0], "来月から、新しいプロジェクトのリーダーをお願いしたいんだけど。": [50.4, 4.89], "私でいいんでしょうか。まだ経験も浅いですし…。": [55.69, 4.025], "今回はいろんな部署のメンバーが集まるから、まとめる力が求められるんだ。君なら大丈夫だよ。": [60.115, 7.515], "ありがとうございます。キャリアのためにも挑戦してみます。": [68.03, 4.465], "医療の現場では、迅速かつ正確な判断が求められる。": [72.895, 4.87], "企業には、利益だけでなく社会への責任を果たすことが求められている。": [78.165, 5.695], "通訳には、語学力に加えて幅広い教養が求められる。": [84.26, 4.95], "観光ガイドには、語学力だけでなく、相手の文化を理解する力が求められる。また、急なトラブルにも冷静に対応できるリーダーシップを発揮することが求められる。": [89.61, 13.11], "この仕事には、高い集中力が求められる。": [103.12, 3.925], "この大会で、新監督の手腕が問われる。": [107.445, 3.895], "リーダーシップ": [111.74, 1.45], "ダイバーシティ": [113.59, 1.21], "マネジメント": [115.2, 1.435], "ポスト": [117.035, 1.08], "キャリア": [118.515, 1.075], "ビジョン": [119.99, 0.955], "イニシアチブ": [121.345, 1.42], "ポテンシャル": [123.165, 1.24]}, "d223": {"【夏季インターンシップ参加者募集】株式会社ミドリ企画\n本インターンシップでは、実際の商品企画に取り組んでいただきます。アイデアの斬新さだけでなく、それを形にする実行力が問われる5日間です。\n■コース\nAコース（企画職）：8月4日〜8日／定員10名\nBコース（営業職）：8月18日〜22日／定員20名\n■対象：2028年3月卒業予定の大学生・大学院生\n■応募方法：エントリーシートをウェブから提出（締切：6月30日）。Aコースはポートフォリオも併せて提出すること\n■その他：交通費支給（1日1,000円まで）。6月10日にオンライン説明会を実施（参加は任意）\n※各コースとも、初日の午前9時からオリエンテーションを行います。": [0.0, 60.53], "ミドリ企画のインターン、どっちのコースにする？": [60.93, 3.765], "企画職かな。でも、ポートフォリオが必要なんだよね。": [65.095, 4.65], "企画は発想力だけじゃなくて、形にする力が問われるらしいよ。": [70.145, 5.455], "じゃあ、去年作ったアプリの資料でアピールしてみようかな。": [76.0, 4.47], "今回の不祥事では、経営陣の責任が問われている。": [80.87, 4.495], "新監督の真価が問われるのは、むしろ来シーズンだ。": [85.765, 4.57], "情報があふれる時代だからこそ、それを見極める力が問われる。": [90.735, 5.12], "来週の面接では、専門的なスキルだけでなく、自分の考えを簡潔に伝える力が問われるだろう。経験を具体的にアピールできるよう準備しておきたい。": [96.255, 12.16], "この試験では、知識より応用力が問われる。": [108.815, 3.82], "この講座には、年齢を問わず誰でも参加できる。": [113.035, 4.19], "インターンシップ": [117.625, 1.465], "ポートフォリオ": [119.49, 1.415], "スキル": [121.305, 1.09], "ポジション": [122.795, 1.13], "フルタイム": [124.325, 1.245], "パートタイム": [125.97, 1.35], "アピール": [127.72, 1.07], "オリエンテーション": [129.19, 1.46]}, "d225": {"【A】知らない土地で店を選ぶとき、私はまずネットのレビューを確認する。多くの人の評価を集めたランキングは、失敗しないための頼りになる情報だ。もちろん好みは人それぞれだが、評価の高い店にはそれなりの理由があるものだ。限られた旅の時間を、運任せの店選びで無駄にしたくはない。\n【B】口コミの点数を信じすぎるのは危うい。そもそも書き込むのは、利用者のごく一部に過ぎない。中には店側が依頼した、宣伝まがいの投稿も紛れている。ランキングとは、ある時点での一部の人の印象を数字にしたものに過ぎないのだ。たまには自分の勘を信じて、知らない店の扉を開けてみるのも悪くない。": [0.0, 48.02], "この店、レビューで星4.5だって。行ってみない？": [48.42, 4.685], "うーん、レビューって一部の人の感想に過ぎないからなあ。": [53.505, 4.37], "でも、グルメサイトのランキングでも上位だよ。": [58.275, 3.725], "そうか。じゃあ、ものは試しで行ってみよう。": [62.4, 3.895], "私は自分の仕事をしたに過ぎません。お礼を言われるほどのことではありません。": [66.695, 5.765], "説明会の参加者は、わずか十人に過ぎなかった。": [72.86, 4.51], "それは単なるうわさに過ぎないから、気にしなくていい。": [77.77, 4.135], "高級ブランドを持つことがステータスだと考える人もいるが、それは作られたイメージに過ぎない。大切なのは、自分が本当に気に入ったものを長く使うことだ。": [82.305, 12.13], "これは計画の第一段階に過ぎない。": [94.835, 3.16], "そんな言い訳は、自分を守るための嘘でしかない。": [98.395, 4.11], "ランキング": [102.905, 1.265], "レビュー": [104.57, 1.015], "ブーム": [105.985, 0.99], "マーケティング": [107.375, 1.405], "ステータス": [109.18, 1.37], "イメージ": [110.95, 1.13], "インパクト": [112.48, 1.3], "バイアス": [114.18, 1.135]}, "d226": {"【さくら内科クリニック　診療のご案内】\n■診療時間\n月・火・木・金：9:00〜12:30／15:00〜18:30\n水：9:00〜12:30（午後は休診）\n土：9:00〜13:00　日・祝：休診\n■予約：ウェブまたは電話で受け付けます。予約のない方も診察しますが、お待ちいただく場合があります。\n■インフルエンザの予防接種：10月〜12月、平日の午後のみ（要予約）\n■リハビリ：3階のフロアで実施。初回はカウンセリングを行いますので、予約時間の30分前にお越しください。\n※初診の方は保険証をお持ちください。アレルギーのある方は受付でお申し出ください。\n院長より：軽い風邪くらいで、わざわざ病院に行くまでもあるまいと考える方も多いでしょう。気になる症状があれば、どうぞ気軽にご相談ください。": [0.0, 68.695], "熱はないんだけど、咳が止まらなくて。": [69.095, 3.505], "駅前のクリニック、土曜日は1時までやってるよ。": [73.0, 4.085], "わざわざ病院に行くまでもないかと思ってたんだけど。": [77.485, 3.85], "一週間も続いてるんでしょ。アレルギーかもしれないし、診てもらいなよ。": [81.735, 5.64], "この程度の雨なら、わざわざ傘を買うまでもあるまい。": [87.775, 4.275], "彼の実力は誰もが知っているのだから、改めて紹介するまでもあるまい。": [92.45, 5.82], "結果はすでに明らかで、再度調査するまでもあるまい。": [98.67, 4.52], "近所のコンビニに行くだけだから、鍵をかけるまでもあるまいと思って家を出た。ところが、帰ってみると猫が外に逃げ出していた。": [103.59, 9.74], "これくらいの傷なら、医者に見せるまでもあるまい。": [113.73, 3.91], "そんなことは、言うまでもない。": [118.04, 2.65], "クリニック": [121.09, 1.24], "リハビリ": [122.73, 1.165], "カルテ": [124.295, 1.105], "アレルギー": [125.8, 1.205], "ワクチン": [127.405, 1.135], "カウンセリング": [128.94, 1.39], "ケア": [130.73, 0.985], "フロア": [132.115, 1.06]}, "d227": {"【A】ネット上には、無料で楽しめるコンテンツがあふれている。しかし、その一つ一つの裏には、時間と技術を費やしたクリエーターがいる。作品のクオリティーに見合った報酬が支払われて然るべきだ。「趣味でやっているのだから」と無償での協力を当然のように求める依頼は、作り手の仕事を軽んじていると言わざるを得ない。\n【B】作品を無料で公開したことで多くの人の目に触れ、大きな仕事のオファーにつながった例も少なくない。駆け出しのフリーランスにとって、知名度は何よりの財産だ。もちろん、依頼された仕事には正当な報酬が支払われて然るべきだが、無料での公開や協力を一律に悪と決めつけるのは早計だろう。": [0.0, 48.875], "イラストの依頼が来たんだけど、ギャラはなしでって言われちゃって。": [49.275, 4.56], "え、それはひどいね。仕事なんだから、ちゃんと払われて然るべきだよ。": [54.235, 6.09], "「宣伝になるから」って言うのよ。": [60.725, 2.84], "フリーランスの足元を見てるだけじゃないか。断ったほうがいいよ。": [63.965, 4.94], "長年地域に尽くしてきた彼の功績は、もっと評価されて然るべきだ。": [69.305, 5.76], "被害者には、会社から十分な説明があって然るべきだろう。": [75.465, 5.01], "危険な作業には、それに見合った手当が支払われて然るべきだ。": [80.875, 5.015], "夜間も働く介護職員の負担を考えれば、給与はもっと引き上げられて然るべきだ。社会を支える仕事にふさわしい待遇が求められる。": [86.29, 10.52], "これほどの名作なら、もっと広く知られて然るべきだ。": [97.21, 4.37], "約束の時間は守るべきだ。": [101.98, 2.5], "クリエーター": [104.88, 1.37], "ギャラ": [106.65, 0.955], "コンテンツ": [108.005, 1.31], "ロイヤリティー": [109.715, 1.33], "フリーランス": [111.445, 1.26], "クオリティー": [113.105, 1.23], "オファー": [114.735, 1.06], "スポンサー": [116.195, 1.33]}, "d228": {"【フィットネスクラブ「アクティブ」会員規約（抜粋）】\n■会員種別と月会費\nレギュラー（全日利用可）：8,800円\nデイタイム（平日10:00〜17:00のみ）：5,500円\n■レッスン：予約制。開始24時間前まではキャンセル無料。それ以降のキャンセルおよび無断欠席は、1回につき500円のペナルティーとなります。\n■ロッカー：当日のみ利用可。閉館後も荷物が残っている場合は撤去します。\n■休会：1か月単位で可能（休会中は月額1,000円）。前月15日までに申請してください。\n■トレーナーによる個別指導：別料金（1回3,000円）\n※他の会員への迷惑行為など、規約への重大な違反があった場合は、会員資格の停止も免れませんので、ご注意ください。": [0.0, 60.97], "明日のヨガのレッスン、急に行けなくなっちゃった。": [61.37, 3.82], "今からキャンセルすると、ペナルティーがかかるんじゃない？": [65.59, 4.06], "うん、24時間前を過ぎてるから、500円取られるのは免れないね。": [70.05, 5.72], "でも、無断で休むよりはいいよ。インストラクターも準備があるしね。": [76.17, 5.36], "安全確認を怠った以上、運営側は責任を免れない。": [81.93, 4.955], "根拠のない発言を繰り返せば、軽率のそしりを免れないだろう。": [87.285, 5.46], "この計画は、税金の無駄遣いだという批判を免れない。": [93.145, 4.85], "商品の不具合を知りながら公表しなかったとすれば、その企業は社会的な批判を免れない。消費者の信頼を取り戻すには、長い時間がかかるだろう。": [98.395, 12.035], "データを改ざんしたとなれば、厳しい処分を免れない。": [110.83, 4.38], "資金不足で、研究の中断を余儀なくされた。": [115.61, 4.14], "トレーナー": [120.15, 1.24], "ロッカー": [121.79, 1.18], "ペナルティー": [123.37, 1.24], "メンバーシップ": [125.01, 1.355], "レッスン": [126.765, 1.025], "インストラクター": [128.19, 1.545], "キャンセル": [130.135, 1.135], "ウェア": [131.67, 0.95]}, "d229": {"【A】インバウンドの増加は、地方経済にとって大きな追い風だ。ホテルや飲食店が潤い、若者の働き口も生まれた。もちろん、混雑やごみの問題が生じていることは否めない。しかし、それは受け入れの仕組みを整えれば解決できる課題であり、観光客を減らす理由にはならない。\n【B】オーバーツーリズムの弊害は、もはや見過ごせない段階にある。生活道路にツアーバスが押し寄せ、住民が日常の買い物にも苦労している地域がある。観光が地域に利益をもたらしてきたことは否めないが、町のキャパシティーを超えた受け入れは、結局ローカルな暮らしそのものを壊してしまう。入域料の導入など、訪問者数を抑える策を急ぐべきだ。": [0.0, 49.905], "最近、駅前に観光客がすごく増えたよね。": [50.305, 4.165], "商店街は活気が出たけど、バスが混んで乗れないこともあるのよ。": [54.87, 5.205], "町のキャパシティーを超えてる感は否めないね。": [60.475, 3.38], "地元の人も観光客も気持ちよく過ごせる工夫が必要だと思う。": [64.255, 5.16], "新しいデザインは斬新だが、使いにくくなった感は否めない。": [69.815, 4.96], "準備不足が敗因の一つであったことは否めない。": [75.175, 3.815], "便利になった一方で、人と人との交流が減ったという面は否めない。": [79.39, 5.515], "この町は家賃が高く、生活費がかさむことは否めない。しかし、文化施設が多く、休日の楽しみには事欠かない。": [85.305, 10.685], "経験の浅さが、彼の弱点であることは否めない。": [96.39, 4.35], "健康が何より大切なことは言うまでもない。": [101.14, 3.51], "インバウンド": [105.05, 1.19], "オーバーツーリズム": [106.64, 1.54], "キャパシティー": [108.58, 1.31], "ツアー": [110.29, 1.06], "ガイド": [111.75, 1.055], "リゾート": [113.205, 1.2], "ローカル": [114.805, 1.16], "ホスピタリティ": [116.365, 1.425]}, "d230": {"【防災ガイド　家庭で備えておきたいもの】\n大地震などで電気・水道・ガスといったライフラインが止まれば、日常生活が大きく混乱することは想像に難くない。各家庭で次のものを備えておこう。\n■飲料水：1人1日3リットルを目安に、最低3日分（できれば1週間分）\n■食料：調理のいらないものを3日分。普段の食品を多めに買い、使った分を買い足す「ローリングストック」がおすすめ\n■携帯ラジオ・懐中電灯：予備のバッテリーや電池とともに\n■ヘルメット・軍手：家具の転倒やガラス片から身を守る\n■その他：常備薬、現金（小銭）、家族の連絡先を書いたメモ\n※避難場所は市のハザードマップで確認し、家族の集合場所も決めておくこと。": [0.0, 55.78], "防災グッズって、何から準備すればいいのかな。": [56.18, 4.005], "まずは水と食料だね。うちはローリングストックにしてるよ。": [60.585, 4.575], "普段の食べ物を多めに買っておくってやつ？": [65.56, 3.22], "そう。あと、スマホのバッテリーも忘れずにね。停電したら情報が入らなくなるから。": [69.18, 7.25], "突然の解雇通知に、社員たちが動揺したことは想像に難くない。": [76.83, 5.82], "一人で三人の子を育てた母の苦労は想像に難くない。": [83.05, 4.75], "この案が実現すれば、反対の声が上がることは想像に難くない。": [88.2, 5.54], "冬に大規模な停電が起きれば、暖房が使えずに体調を崩す人が出ることは想像に難くない。カイロや予備のバッテリーをストックしておくことが大切だ。": [94.14, 11.4], "大切な試合を前にした選手たちの緊張は想像に難くない。": [105.94, 4.895], "あんなに練習したんだから、彼は勝つに違いない。": [111.235, 4.1], "ハザードマップ": [115.735, 1.405], "シェルター": [117.54, 1.29], "ライフライン": [119.23, 1.215], "ストック": [120.845, 1.19], "ラジオ": [122.435, 1.08], "バッテリー": [123.915, 1.18], "ヘルメット": [125.495, 1.295], "マニュアル": [127.19, 1.1]}, "d232": {"【A】高校野球の監督を二十年務めてきて思うのは、勝つための秘訣は結局チームワークに尽きるということだ。突出した選手が一人いても、仲間を信頼して自分の役割を果たせないチームは、肝心な場面でもろい。誰かがスランプに陥ったとき、周りが支えられるかどうかが勝負を分ける。\n【B】チームワークが大切なのは確かだ。だが、それだけで勝てるほど勝負の世界は甘くない。最後に試合を決めるのは、苦しい場面でも普段どおりのプレーができる一人一人の技術と、メンタルの強さである。ライバルに負けたくないというハングリーな気持ちを持った選手が集まって、初めてチームは強くなるのだ。": [0.0, 45.95], "優勝おめでとうございます。今のお気持ちは？": [46.35, 3.89], "もう、うれしいの一言に尽きます。": [50.64, 3.09], "シーズンの中盤には、スランプもあったそうですね。": [54.13, 4.08], "はい。でも、コーチや仲間が支えてくれて、フォームを見直すことができました。": [58.61, 6.56], "今回の旅行の感想は、楽しかったの一言に尽きる。": [65.57, 4.705], "教え子の活躍を見られるのは、教師冥利に尽きる。": [70.675, 4.31], "料理の基本は、良い材料を選ぶことに尽きる。": [75.385, 3.91], "外国語が上達する秘訣は、毎日少しずつでも続けることに尽きる。どんなに優れた教材も、使わなければ意味がないからだ。": [79.695, 10.46], "この店の魅力は、店主の温かい人柄に尽きる。": [90.555, 4.425], "私の役目は、ほんの手伝いに過ぎない。": [95.38, 3.67], "チームワーク": [99.45, 1.4], "コーチ": [101.25, 1.065], "プレー": [102.715, 1.025], "スランプ": [104.14, 1.19], "ライバル": [105.73, 1.1], "ハングリー": [107.23, 1.12], "メンタル": [108.75, 1.12], "フォーム": [110.27, 1.03]}, "d233": {"【市民大学　秋期講座のご案内】\n①はじめてのプレゼンテーション：火曜19:00〜20:30／全6回／受講料6,000円／定員20名\n②ビジネス英語ディスカッション：木曜19:00〜20:30／全8回／受講料12,000円／中級レベル以上（事前テストあり）\n③地域の歴史を歩く：土曜10:00〜12:00／全4回／受講料3,000円／屋外での実施あり\n④データ分析入門ワークショップ：土曜14:00〜16:30／全5回／受講料8,000円／ノートパソコン持参\n※テキスト代は受講料に含まれます。市内在住・在勤の方は、受講料が2割引になります。\n※申込締切：9月20日。定員を超えた場合は抽選となります。\n事務局より：人前で話す力を基礎から鍛えたい方には、①の講座をおいてほかにないと自負しております。": [0.0, 73.43], "秋の市民大学、何か申し込む？": [73.83, 3.365], "プレゼンの講座にしようと思って。今度、会議で発表することになってさ。": [77.595, 6.17], "いいね。市内で働いてる人は2割引になるって。": [84.165, 4.43], "それは助かる。基礎から学ぶなら、あの講座をおいてほかにないって評判なんだ。": [88.995, 6.36], "この難しい交渉を任せられるのは、田中さんをおいてほかにいない。": [95.755, 5.385], "日本の伝統的な庭園を見るなら、京都をおいてほかにない。": [101.54, 4.72], "地域を立て直す機会があるとすれば、今をおいてほかにない。": [106.66, 4.665], "日本語の発音を基礎から直したいなら、駅前の語学教室の山田先生をおいてほかにいない。一人一人のレベルに合わせて、丁寧に指導してくれるからだ。": [111.725, 11.665], "この役を演じられる俳優は、彼をおいてほかにいない。": [123.79, 4.295], "終電を逃したから、歩いて帰るしかない。": [128.485, 3.685], "セミナー": [132.57, 1.285], "カリキュラム": [134.255, 1.295], "テキスト": [135.95, 1.23], "レベル": [137.58, 1.015], "ワークショップ": [138.995, 1.385], "ディスカッション": [140.78, 1.27], "プレゼンテーション": [142.45, 1.51], "アシスタント": [144.36, 1.425]}, "d234": {"【A】ファストファッションは、手頃な価格で流行の服を楽しめる仕組みをつくった。かつては一部の人のものだったおしゃれを、誰もが気軽に楽しめるようにしたという意味では、ファッションの民主化を実現したと言えなくもない。服を長く大切に着るかどうかは、結局は買う側の意識の問題だろう。\n【B】安い服を大量に作り、短いサイクルで捨てる仕組みは、環境に大きな負荷をかけている。売れ残った衣料が大量に処分されている現実もある。最近はサステナブルを掲げるアパレル企業も増えてきたが、宣伝の色合いが濃いものも少なくない。消費者もリユースや修理を取り入れ、服との付き合い方を見直すべきだ。": [0.0, 46.215], "このシャツ、千円だったの。安いでしょ。": [46.615, 3.885], "確かに。でも、ワンシーズンで着なくなるなら、もったいなくない？": [50.9, 5.395], "まあ、流行を気軽に楽しめるのは利点と言えなくもないでしょ。": [56.695, 4.86], "それはそうだけど、着なくなったらリユースに出すとかしようよ。": [61.955, 4.665], "見方を変えれば、今回の失敗は良い経験だったと言えなくもない。": [67.02, 5.28], "彼の意見にも一理あると言えなくもない。": [72.7, 3.07], "この品質でこの値段なら、まあ安いと言えなくもない。": [76.17, 4.33], "毎日同じ服を着るのは退屈だが、朝のコーディネートに悩まずに済むという点では合理的と言えなくもない。ただ、おしゃれを楽しむ機会が減るのは少し寂しい。": [80.9, 12.31], "少し派手だが、このデザインも個性的と言えなくもない。": [93.61, 4.44], "このデザインは、今年いちばんの傑作と言っても過言ではない。": [98.45, 4.875], "ファストファッション": [103.725, 1.32], "トレンド": [105.445, 1.135], "アパレル": [106.98, 1.09], "サステナブル": [108.47, 1.46], "ブランド": [110.33, 1.125], "リユース": [111.855, 1.175], "デザイン": [113.43, 1.03], "コーディネート": [114.86, 1.4]}, "d235": {"【賃貸物件情報】（駅からの徒歩時間は目安です）\nA：1K／25㎡／家賃6.8万円／駅徒歩3分／オートロック・フローリング／ペット不可\nB：1LDK／38㎡／家賃8.5万円／駅徒歩12分／広いバルコニー・クローゼット2か所／ペット相談可\nC：1K＋ロフト／22㎡／家賃5.9万円／駅徒歩7分／ユニットバス／2026年リフォーム済み／ペット不可\nD：2DK／45㎡／家賃7.9万円／駅徒歩20分／築35年／ペット可（小型犬・猫1匹まで）\n※家賃のほかに、管理費（各物件とも月5,000円）がかかります。\n担当者より：Dは広さの割に家賃が手頃ですが、駅からの距離を考えると、通勤に便利とは言い難いかもしれません。": [0.0, 63.36], "駅から近くて、収納の多い部屋を探しているんですが。": [63.76, 4.67], "でしたら、こちらはいかがでしょう。クローゼットが2か所ございます。": [68.83, 5.27], "徒歩12分ですか…。正直、近いとは言い難いですね。": [74.5, 4.95], "では、こちらのロフト付きのお部屋はいかがですか。駅から7分です。": [79.85, 5.45], "今の説明では、住民の理解を得られたとは言い難い。": [85.7, 4.535], "この店の料理は見た目こそ華やかだが、味は一流とは言い難い。": [90.635, 5.31], "両国の関係は、まだ安定しているとは言い難い状況だ。": [96.345, 4.875], "先週泊まったホテルは、インテリアこそおしゃれだったが、部屋が狭く、快適とは言い難かった。ただ、駅に近いのは便利だった。": [101.62, 10.535], "この対策で十分とは言い難い。": [112.555, 2.77], "値段が高いからといって、品質が良いとは限らない。": [115.725, 4.345], "リフォーム": [120.47, 1.155], "ロフト": [122.025, 1.09], "オートロック": [123.515, 1.225], "バルコニー": [125.14, 1.265], "フローリング": [126.805, 1.29], "クローゼット": [128.495, 1.38], "インテリア": [130.275, 1.22], "ユニットバス": [131.895, 1.36]}, "d236": {"【A】郊外の大型ショッピングモールには、食料品や衣料品は言うに及ばず、映画館や診療所までそろっていて、一か所で用事が済む。駐車場も広く、子ども連れや高齢者にとっても便利だ。シャッターの下りた商店街を嘆く声もあるが、住民の暮らしを実際に豊かにしているのは、むしろモールのほうではないか。\n【B】大型モールのテナントの多くは全国チェーンで、どこへ行っても似たような店が並ぶ。一方、商店街には店主の顔が見える店があり、常連客との何気ない会話が、一人暮らしの高齢者の見守りにもつながっている。品ぞろえではモールにかなわなくても、地域の結びつきを支える役割は言うに及ばず、町の個性を守るという点でも、商店街の価値は大きい。": [0.0, 53.015], "駅前の商店街、また一軒シャッターが下りてたよ。": [53.415, 4.355], "郊外にショッピングモールができてから、お客さんが減ったみたいね。": [58.17, 4.985], "でも、あのパン屋は週末は言うに及ばず、平日も行列ができてるよね。": [63.555, 6.095], "根強いリピーターがいるのね。": [70.05, 2.16], "この祭りには、地元の人は言うに及ばず、海外からも多くの観光客が訪れる。": [72.61, 7.0], "彼女は英語は言うに及ばず、フランス語やスペイン語も話せる。": [80.01, 4.775], "健康のためには、食事は言うに及ばず、睡眠にも気を配るべきだ。": [85.185, 5.9], "近所の古本屋は、文学書は言うに及ばず、珍しい写真集や古い地図までそろっている。店主と話したくて通うリピーターも多いそうだ。": [91.485, 10.715], "この曲は、若者は言うに及ばず、高齢者にも親しまれている。": [102.6, 5.54], "忙しくて、旅行はおろか、週末に休むことさえできない。": [108.54, 5.37], "ショッピングモール": [114.31, 1.54], "テナント": [116.25, 1.175], "チェーン": [117.825, 0.965], "シャッター": [119.19, 1.27], "ターゲット": [120.86, 1.245], "ニッチ": [122.505, 1.03], "リピーター": [123.935, 1.29], "ノスタルジー": [125.625, 1.355]}, "d237": {"【市立美術館　ご利用案内】\n■開館時間：9:30〜17:00（金曜日は20:00まで）※入館は閉館の30分前まで\n■休館日：月曜日（祝日の場合は翌平日）\n■観覧料（常設展／企画展「光の画家たち」）\n一般：500円／1,400円\n大学生：300円／1,000円\n高校生以下：無料／600円\nシニア（65歳以上）：250円／1,000円\n※企画展のチケットで、常設展もご覧いただけます。\n※20名以上の団体は2割引になります。\n※展示室内でのフラッシュ撮影はご遠慮ください。\n館長より：画集やレプリカでは味わえない本物の迫力こそ、人々が美術館に足を運ぶ理由にほかなるまい。": [0.0, 59.26], "金曜日なら夜8時まで開いてるんだって。仕事帰りに行けるね。": [59.66, 5.135], "企画展のチケットで、常設展も見られるらしいよ。": [65.195, 4.45], "お得だね。でも、入館は7時半までだから急がないと。": [70.045, 5.055], "そうだね。あと、フラッシュ撮影は禁止だから気をつけて。": [75.5, 4.99], "彼がこの賞を受けたのは、三十年に及ぶ地道な研究の成果にほかなるまい。": [80.89, 6.41], "若者が地方を離れるのは、魅力ある仕事が少ないからにほかなるまい。": [87.7, 5.72], "この沈黙は、彼なりの抗議にほかなるまい。": [93.82, 3.95], "若い世代の間で昔の喫茶店が人気なのは、デジタルに囲まれた日常から離れ、ゆったりした時間を求めているからにほかなるまい。古い物には、新しい物にはない温かみがある。": [98.17, 14.49], "この町が栄えたのは、港があったからにほかなるまい。": [113.06, 4.6], "この町が栄えたのは、港があったからにほかならない。": [118.06, 4.59], "ギャラリー": [123.05, 1.1], "コレクション": [124.55, 1.25], "アトリエ": [126.2, 1.145], "レプリカ": [127.745, 1.245], "フラッシュ": [129.39, 1.12], "チケット": [130.91, 1.295], "リーフレット": [132.605, 1.355], "シニア": [134.36, 1.15]}, "d239": {"【A】どんな分野でも、一流になるには才能が欠かせないと思う。同じ時間練習しても、センスのある人はコツをつかむのが圧倒的に速い。努力は誰にでもできるが、才能は努力で手に入れられるものではない。だからこそ、自分の向き不向きをなるべく早く見極めることが大切なのだ。\n【B】プロの世界で長く活躍している人に話を聞くと、誰もが地道なルーティンを何年も守り続けている。才能だけで勝てるのは最初のうちだけで、マンネリに陥らずに工夫を重ねられるかどうかが、やがて大きな差になる。そもそも才能の有無は、少しやってみたくらいで分かるものではない。結論を急がず、まずは続けてみることだ。": [0.0, 48.785], "ピアノを三か月やったけど、全然うまくならないんです。才能ないのかな。": [49.185, 6.075], "三か月で才能の有無なんて、分かるものではありませんよ。": [55.66, 4.8], "でも、同じ時期に始めた友達は、もうずっと先に進んでるんです。": [60.86, 5.935], "人と比べるものではありません。毎日のルーティンを守ることが大事です。": [67.195, 5.49], "目上の人に向かって、そんな口のきき方をするものではない。": [73.085, 4.86], "長年の習慣は、そう簡単に変えられるものではない。": [78.345, 4.41], "人の努力を笑うものではないよ。": [83.155, 2.69], "一度の失敗で自分には向いていないと決めつけるものではない。外国語の力は、一年や二年で身につくものではないのだから。": [86.245, 9.835], "食べ物を粗末にするものではない。": [96.48, 2.71], "小さなミスだから、そんなに落ち込むことはないよ。": [99.59, 4.165], "センス": [104.155, 1.13], "ノウハウ": [105.685, 1.125], "マンネリ": [107.21, 1.085], "ルーティン": [108.695, 1.065], "プロ": [110.16, 0.95], "アマチュア": [111.51, 1.235], "ストイック": [113.145, 1.26], "ベテラン": [114.805, 1.05]}, "d241": {"選挙が近づくと、候補者は街頭で「本日はお忙しいところ、足をお止めいただき、ありがとうございます」と深々と頭を下げる。だが、その丁寧な言葉の裏で、肝心の公約はどれほど語られているだろうか。ある候補者は「皆様がおっしゃることは、すべて承知しております」と繰り返したが、具体的な財源には一言も触れなかった。有権者の側も、礼儀正しい人物を「感じがいい」と評価しがちである。しかし、政治家に求められるのは私たちを敬う言葉遣いではなく、私たちの暮らしを左右する政策の中身だ。投票所へいらっしゃる前に、各党の公約を一度ご覧になってはいかがだろうか。敬語の美しさに目を奪われ、世論が中身を問わなくなれば、投票率がいくら上がっても、民主主義は空洞化するばかりである。": [0.0, 59.69], "部長、明日の説明会には社長もいらっしゃいますか。": [60.09, 4.455], "ああ、冒頭で一言おっしゃる予定だよ。": [64.945, 3.425], "承知しました。資料は事前に社長にご覧いただいたほうがよろしいでしょうか。": [68.77, 6.065], "うん、今日中にお渡ししておいて。社長は午後から外出なさるから。": [75.235, 5.695], "社長は毎朝、和食を召し上がるそうです。": [81.33, 3.78], "先方の部長は、この件をすでにご存じでした。": [85.51, 4.18], "明日は何時ごろこちらにお越しになりますか。": [90.09, 3.44], "来週の水曜日、A社の田中部長がお越しになります。工場の新しいラインをご覧になった後、会議室で昼食を召し上がる予定です。": [93.93, 10.855], "お客様が受付にいらっしゃいました。": [105.185, 2.845], "私が受付までお迎えに参ります。": [108.43, 3.105], "有権者": [111.935, 1.37], "投票率": [113.705, 1.215], "公約": [115.32, 1.185], "与党": [116.905, 1.11], "野党": [118.415, 1.11], "世論": [119.925, 0.845], "議席": [121.17, 1.135], "改選": [122.705, 1.105]}, "d242": {"個人情報の漏洩が発覚するたび、企業の幹部が記者会見で「関係者の皆様のもとへ、順次お詫びに伺います」と述べる光景は、もはや珍しくない。もちろん、誠意ある謝罪は欠かせない。だが、被害者が本当に知りたいのは、どのような脆弱性を突かれ、何が流出し、いつ復旧するのかという事実である。ある企業は「詳細は調査中のため、改めてご報告いたします」と繰り返すばかりで、侵入経路の説明は事件から三か月後だった。その間、利用者は自分のパスワードを変えるべきかどうかさえ判断できなかった。頭を下げる回数を増やすことと、信頼を取り戻すことは別物だ。平時から暗号化や認証の強化に投資し、事故が起きれば分かった範囲を速やかに公表する。そうした地道な姿勢こそが、幹部が何度「お詫びに参りました」と頭を下げるよりも、利用者の不安を和らげるはずだ。": [0.0, 65.79], "課長、システム障害の件で、明日A社へお詫びに伺うことになりました。": [66.19, 6.295], "そうか。先方の部長にはお目にかかれそうか。": [72.885, 4.055], "はい、十時にお時間を頂戴しました。報告書は私が持参いたします。": [77.34, 6.46], "わかった。私も同行すると、先方に申し伝えてくれ。": [84.2, 5.315], "承知いたしました。すぐにご連絡いたします。": [89.915, 3.91], "明日の午後、御社に伺ってもよろしいでしょうか。": [94.225, 4.085], "一度お目にかかって、ご挨拶したいと思っております。": [98.71, 4.255], "ご注文は確かに承りました。": [103.365, 2.88], "このたびはご迷惑をおかけし、申し訳ございません。明日、担当者と二人でお詫びに伺いたいのですが、部長にお目にかかることは可能でしょうか。": [106.645, 11.555], "明日、先生のお宅に伺います。": [118.6, 3.285], "来月から福岡支社へ参ります。": [122.285, 2.75], "脆弱性": [125.435, 1.33], "漏洩": [127.165, 1.105], "暗号化": [128.67, 1.195], "認証": [130.265, 1.155], "改竄": [131.82, 1.085], "復旧": [133.305, 1.16], "遮断": [134.865, 1.05], "侵入": [136.315, 1.195]}, "d243": {"病院で治療方針の説明を受けると、「では、副作用についてご説明させていただきます」「同意書にご署名をいただく形にさせていただいております」といった言い回しが続く。丁寧ではあるが、聞いているうちに、まるで決定事項を告げられているような気分になる患者も少なくないだろう。「させていただく」は本来、相手の許可や恩恵を受けて行う行為に使う言葉だ。ところが医療の現場では、それが患者の選択の余地を覆い隠す決まり文句になってはいないか。臨床研究や治験への参加を打診する場面ならなおさら、患者には断る自由があることを明確に伝えなければならない。言葉を丁寧にすることと、患者を対等な判断者として扱うことは同じではない。説明する側が問うべきは「失礼のない言い方か」ではなく、「この人は理解したうえで選べたか」なのである。": [0.0, 59.5], "本日の会議の進行は、私が務めさせていただきます。": [59.9, 5.07], "よろしくお願いします。資料はもう配付済みですか。": [65.37, 4.25], "はい。時間の都合上、説明は要点のみとさせていただきます。": [70.02, 5.675], "承知しました。質疑の時間はありますか。": [76.095, 3.75], "最後に十分ほど設けております。ご質問はその際にお願いいたします。": [80.245, 5.8], "恐縮ですが、本日は早めに失礼させていただきます。": [86.445, 4.615], "頂いた資料は、社内で検討させていただきます。": [91.46, 4.265], "では、私から簡単に自己紹介をさせていただきます。": [96.125, 4.665], "ただいまより定例会議を始めさせていただきます。本日は議題が多いため、各報告は五分以内とさせていただきます。": [101.19, 9.26], "体調不良のため、本日は欠席させていただきます。": [110.85, 4.585], "資料は明日までに送付いたします。": [115.835, 2.755], "診療": [118.99, 1.25], "処方": [120.64, 1.22], "副作用": [122.26, 1.365], "臨床": [124.025, 1.155], "治験": [125.58, 1.0], "感染症": [126.98, 1.275], "予防接種": [128.655, 1.25], "重症化": [130.305, 1.27]}, "d244": {"企業の統合報告書を読むと、「脱炭素社会の実現に向けて、全社一丸となって取り組んでまいります」という一文に、必ずと言っていいほど出会う。決意の表明自体を否定するつもりはない。しかし、この「まいります」には期限も数値もない。温室効果ガスの排出量をいつまでに何割減らすのか、再生可能エネルギーの比率をどう高めるのか。それが示されなければ、読者は言葉の誠実さを確かめようがない。実際、同じ決意を十年近く掲げながら、排出量がほとんど減っていない企業もある。異常気象が相次ぎ、生態系への影響が目に見える形で現れている今、求められているのは美しい決意表明ではなく、検証可能な約束だ。「努めてまいります」を「〇年までに〇割削減します」に置き換えられるかどうか。そこにこそ、企業の本気度が表れるのではないか。": [0.0, 62.85], "本日は、A社様との共同プロジェクトについてご報告いたします。": [63.25, 5.465], "進捗はいかがでしょうか。": [69.115, 2.24], "予定どおり進んでおります。今後も月に一度、進捗をご報告してまいります。": [71.755, 6.895], "心強いです。コストの面は大丈夫ですか。": [79.05, 3.98], "原材料費が上がっておりますが、引き続き削減に努めてまいります。": [83.43, 5.315], "今後とも品質の向上に努めてまいります。": [89.145, 3.515], "日ごとに暑くなってまいりましたが、いかがお過ごしでしょうか。": [93.06, 4.64], "では、銀行に寄ってから、そのまま取引先へ行ってまいります。": [98.1, 5.33], "受験票と写真付きの身分証、HBの鉛筆と消しゴム、腕時計は今夜のうちに鞄に入れておく。会場には三十分前に着くように家を出る。休憩時間には敬語のメモだけを見直す。落ち着いて、自分の力を出し切ってまいります。": [103.83, 18.56], "弊社はこの分野で三十年、研究を続けてまいりました。": [122.79, 4.855], "先生はこの分野で三十年、研究を続けていらっしゃいます。": [128.045, 5.025], "温室効果": [133.47, 1.475], "排出量": [135.345, 1.205], "脱炭素": [136.95, 1.195], "再生可能": [138.545, 1.51], "生態系": [140.455, 1.43], "絶滅危惧": [142.285, 1.445], "森林伐採": [144.13, 1.5], "異常気象": [146.03, 1.385]}, "d246": {"増税や公共料金の値上げが決まると、行政の告知は決まって「市民の皆様のご理解とご協力を、心よりお願い申し上げます」という一文で締めくくられる。丁重な言い回しではあるが、そこに至る経緯はほとんど書かれていない。審議会への諮問から答申まで、どのような議論があり、どんな代替案が退けられたのか。予算案の段階で、歳出の見直しはどこまで検討されたのか。それを知らされないまま協力だけを求められても、市民は納得のしようがない。「お願い申し上げる」という言葉は、本来、相手に負担をかけることへの恐縮の表れであるはずだ。ならば、その負担がなぜ必要なのかを丁寧に示すことこそ、言葉に見合った誠意というものだろう。施策への理解は、頭を下げて得るものではなく、根拠を示して得るものである。": [0.0, 58.355], "それでは開会にあたりまして、社長の高橋よりご挨拶申し上げます。": [58.755, 5.765], "皆様、本日はご多忙のところお越しいただき、心より御礼申し上げます。": [64.92, 6.6], "本年も変わらぬご支援を賜りますよう、お願い申し上げます。": [71.92, 4.925], "続きまして、新製品のご説明に移らせていただきます。": [77.245, 4.82], "日頃のご愛顧に、心より御礼申し上げます。": [82.465, 3.985], "ご迷惑をおかけしましたことを、深くお詫び申し上げます。": [86.85, 4.64], "詳細につきましては、後日改めてご案内申し上げます。": [91.89, 4.915], "本年も格別のお引き立てを賜り、厚く御礼申し上げます。年末年始の休業中はご不便をおかけいたしますが、何卒ご了承のほどお願い申し上げます。": [97.205, 12.42], "この件は、私から社長に申し上げておきます。": [110.025, 4.075], "はじめまして、営業部の田中と申します。": [114.5, 3.755], "行政": [118.655, 1.195], "施策": [120.25, 1.175], "是正": [121.825, 1.15], "答申": [123.375, 1.07], "諮問": [124.845, 1.05], "審議": [126.295, 1.11], "予算案": [127.805, 1.08], "歳出": [129.285, 1.225]}, "d247": {"人工知能の精度が上がり、ビジネス文書の作成を自動化する企業が増えている。「平素は格別のご高配を賜り、厚く御礼申し上げます」といった定型の挨拶なら、汎用の文章生成ツールでも瞬時に、しかも誤りなく書いてくれる。敬語に自信のない若手社員にとっては心強い味方だろう。私はこれを歓迎したい。決まり文句に頭を悩ませる時間が減れば、そのぶん中身を考える時間が増えるからだ。ただし、手紙の核となる部分まで機械に委ねてよいとは思わない。相手が何に困り、自分たちが何を約束できるのか。それは過去の文例をいくら学習しても導き出せない、当事者だけが知る事情である。「今後ともご指導を賜りますよう」と結ぶ前の数行にこそ、書き手は自分の言葉で向き合うべきだろう。形式は機械に、誠意は人に。その分担を誤らないことが肝心だ。": [0.0, 62.655], "先日はご多忙の中、弊社の展示会にご来場賜り、ありがとうございました。": [63.055, 6.835], "いえいえ、こちらこそ貴重な機会をいただきました。": [70.29, 4.055], "今後とも変わらぬご指導を賜りますよう、よろしくお願いいたします。": [74.745, 5.35], "こちらこそ、引き続きよろしくお願いします。": [80.495, 3.835], "平素は格別のご高配を賜り、厚く御礼申し上げます。": [84.73, 5.12], "皆様から賜りましたご意見は、今後の改善に生かしてまいります。": [90.25, 5.38], "本年も変わらぬご支援を賜りますよう、お願い申し上げます。": [96.03, 4.925], "このたびは弊社セミナーにご参加を賜り、誠にありがとうございました。今後とも変わらぬご愛顧を賜りますよう、よろしくお願い申し上げます。": [101.355, 11.1], "創立記念式典にご臨席を賜り、誠にありがとうございます。": [112.855, 5.425], "お見積もりをいただき、ありがとうございます。": [118.68, 3.535], "人工知能": [122.615, 1.465], "演算": [124.48, 1.02], "自動化": [125.9, 1.17], "汎用": [127.47, 1.185], "精度": [129.055, 1.14], "偏向": [130.595, 1.255], "検証": [132.25, 1.19], "透明性": [133.84, 1.28]}, "d248": {"介護の現場で長年働いてきた職員が表彰される式典を取材したことがある。壇上の女性は「このようなお褒めにあずかり、身に余る光栄です」と述べ、会場は温かい拍手に包まれた。だが式の後、彼女は小さな声で「表彰より、夜勤をもう一人増やしてほしい」と漏らした。高齢化が進み、要介護者や認知症の人は増え続けている。在宅医療を支える訪問介護の担い手は慢性的に不足し、一人当たりの負担増は限界に近い。社会は彼らを「尊い仕事」と称えるが、その言葉が賃金や人員配置に反映されなければ、感謝はむしろ現状を固定する役割を果たしかねない。褒め言葉の恩恵にあずかるだけでは、人は働き続けられないのである。私たちが示すべき敬意は、拍手ではなく、制度という形をとるべきだろう。": [0.0, 60.67], "では続きまして、営業部の鈴木さん、お願いいたします。": [61.07, 4.885], "ただいまご紹介にあずかりました、営業部の鈴木でございます。": [66.355, 4.945], "本日はこのような席にお招きにあずかり、大変光栄に存じます。": [71.7, 5.535], "鈴木さん、先ほどのご挨拶、とても良かったですよ。": [77.635, 4.95], "ありがとうございます。お褒めにあずかり、恐縮です。": [82.985, 4.535], "ただいまご紹介にあずかりました、山田でございます。": [87.92, 4.245], "社長からお褒めにあずかり、チーム一同大変励みになりました。": [92.565, 5.125], "大手企業だけが減税の恩恵にあずかるのは不公平だ。": [98.09, 4.25], "ただいまご紹介にあずかりました、企画部の金でございます。本日はこのような晴れの席にお招きにあずかり、誠に光栄に存じます。": [102.74, 10.745], "思いがけずお褒めにあずかり、恐縮しております。": [113.885, 3.915], "お客様のお荷物をフロントでお預かりします。": [118.2, 3.49], "介護": [122.09, 1.085], "在宅医療": [123.575, 1.4], "要介護": [125.375, 1.215], "認知症": [126.99, 1.195], "終末期": [128.585, 1.34], "延命": [130.325, 1.105], "担い手": [131.83, 1.18], "負担増": [133.41, 1.18]}, "d249": {"海洋に流れ出たプラスチックが微細な粒子となり、魚の体内から見つかったという報道が相次いでいる。これを受けて多くの自治体が分別ルールを細かくし、住民に一層の協力を仰いでいる。ある市では、ごみの種類が二十を超え、高齢の住民から「どこに出せばいいのか分からない」という声が上がった。市は専門家の判断を仰ぎつつ説明会を重ねているが、混乱は収まっていない。だが、問題の根はそもそも家庭の分別にあるのだろうか。焼却や埋め立てに回るごみの多くは、買った時点ですでに過剰に包装されている。再資源化の負担を住民の手間だけに押しつけるのは、蛇口を開けたまま床を拭くようなものだ。汚染を本気で減らしたいのであれば、行政が協力を仰ぐべき相手は、まず製品を作り、包む側の企業ではないか。": [0.0, 57.035], "部長、A社から、納期を一週間延ばしてほしいとの連絡がありました。": [57.435, 5.985], "そうか。それは私の一存では決められないな。": [63.82, 4.16], "では、本部長のご判断を仰いだほうがよろしいでしょうか。": [68.38, 4.565], "そうだね。経緯をまとめて、本部長に指示を仰いでくれ。": [73.345, 4.92], "承知しました。本日中にご報告いたします。": [78.665, 4.135], "判断に迷ったときは、必ず上司の指示を仰ぐようにしている。": [83.2, 5.03], "本件については、法務部の見解を仰いだうえで回答いたします。": [88.63, 5.14], "彼は入社以来、田中先輩を師と仰いできた。": [94.17, 4.05], "A社より納期延長のご依頼がございました。当社としての対応につきまして、部長のご判断を仰ぎたく、ご連絡いたしました。": [98.62, 9.895], "社長の最終判断を仰ぐことにした。": [108.915, 3.195], "部下に詳しい説明を求めた。": [112.51, 2.63], "廃棄物": [115.54, 1.19], "焼却": [117.13, 1.33], "埋め立て": [118.86, 1.235], "分別": [120.495, 1.15], "再資源化": [122.045, 1.41], "汚染": [123.855, 0.96], "海洋": [125.215, 1.17], "微細": [126.785, 1.05]}, "d250": {"首脳会談の後、記者から交渉の中身を問われた担当者が「詳細については存じておりません」と答える場面をよく目にする。外交に一定の秘密が必要なことは理解できる。手の内をすべて明かせば、相手国との交渉で国益を損ないかねないからだ。しかし、会談の当事者に近い人物が「存じません」を繰り返すのを聞くと、本当に知らないのか、言えないだけなのか、国民には区別がつかない。「お答えは差し控えたいと存じます」と正直に言うほうが、まだ誠実ではないだろうか。とりわけ、条約の締結や批准、あるいは他国への制裁といった重大な決定は、最終的に国民の暮らしに跳ね返ってくる。交渉の途中経過まで公開せよとは言わない。だが、合意に至った段階では、何を得て何を譲ったのかを、国民が理解できる言葉で説明する責任がある。": [0.0, 62.295], "失礼ですが、A社の木村社長をご存じでいらっしゃいますか。": [62.695, 4.85], "お名前は存じ上げておりますが、直接お目にかかったことはございません。": [67.945, 5.625], "そうでしたか。来週の交流会にいらっしゃるそうなので、ご紹介できればと存じまして。": [73.97, 6.91], "それはありがたいです。ぜひお願いしたく存じます。": [81.28, 4.07], "先生のご活躍は、かねてより存じ上げております。": [85.75, 4.33], "その件につきましては、私は存じておりません。": [90.48, 4.35], "近いうちに、改めてご挨拶に伺いたいと存じます。": [95.23, 4.615], "先生のお名前とご研究は、以前からよく存じ上げておりました。本日直接お話を伺えて、大変光栄に存じます。": [100.245, 10.095], "御社の社長のことは、よく存じ上げております。": [110.74, 3.97], "会議の日程は存じております。": [115.11, 2.555], "外交": [118.065, 1.22], "首脳": [119.685, 1.15], "会談": [121.235, 1.06], "締結": [122.695, 1.21], "批准": [124.305, 0.98], "制裁": [125.685, 1.225], "交渉": [127.31, 1.215], "国益": [128.925, 1.24]}, "d251": {"行政手続きの電子化が急速に進んでいる。役所のホームページには「各種申請は、オンライン窓口をご利用いただけます」「お手持ちの端末からご申請いただくと、待ち時間なくお手続きが完了します」といった案内が並ぶ。個人情報を一元化し、利便性を高める方向性そのものに異論はない。だが、その文面が前提としているのは、スマートフォンを使いこなし、画面の指示を読み解ける住民だけではないか。高齢者や障害のある人、通信環境が整わない地域の住民にとって、普及率の数字の陰で取り残される不安は小さくない。デジタル格差は個人の努力不足ではなく、社会の基盤の問題である。「ご利用いただけます」と案内するだけで足りるはずがない。対面の窓口を残し、使い方を一緒に確かめる人を置くこと。それを怠ったまま進む電子化は、効率と引き換えに、行政の公平性を手放すことになりかねない。": [0.0, 65.79], "恐れ入りますが、こちらの申込書にご記入いただけますか。": [66.19, 4.94], "はい。住所は今の住所でいいですか。": [71.53, 3.39], "はい。それから、ご本人確認のため、身分証明書をご提示いただけますでしょうか。": [75.32, 7.37], "運転免許証でも大丈夫ですか。": [83.09, 2.835], "はい、結構です。ご協力いただき、ありがとうございます。": [86.325, 5.515], "お手数ですが、内容をご確認いただけますでしょうか。": [92.24, 4.42], "会員の方は、こちらの割引をご利用いただけます。": [97.06, 4.31], "担当者が参りますので、少々お待ちいただけますか。": [101.77, 4.53], "お申し込みは、専用フォームからご入力いただけます。送信前に、内容をよくご確認いただきますようお願いいたします。なお、会員の方は優先枠をご利用いただけます。": [106.7, 13.905], "このカードは、全国の店舗でご利用いただけます。": [121.005, 4.21], "（×）このカードは、全国の店舗でご利用できます。": [125.615, 4.935], "電子化": [130.95, 1.045], "個人情報": [132.395, 1.465], "利便性": [134.26, 1.185], "一元化": [135.845, 1.36], "普及率": [137.605, 1.14], "格差": [139.145, 1.2], "端末": [140.745, 1.155], "基盤": [142.3, 0.97]}, "d253": {"ある地方都市の病院で、救急外来を支える勤務医が三人しかいないと聞いた。夜間に救急車が重なれば、搬送先が決まらず、患者は車内で何十分も待つことになる。病床が逼迫するたびに、市長は「先生方の献身的なご尽力を、大変心強く、またありがたく存じます」と感謝を述べる。その言葉に偽りはないだろう。だが、医師の偏在を個人の使命感で埋め合わせる仕組みは、遅かれ早かれ破綻する。過重労働で一人が倒れれば、地域医療そのものが立ち行かなくなるからだ。必要なのは、周辺の病院と役割を分担し、救急を拠点病院に集約するといった、痛みを伴う再編である。住民にとって近くの病院が減るのは寂しいことに違いない。それでも、感謝の言葉を重ねるより、医師が無理なく働き続けられる体制を整えることこそ、行政の務めではないだろうか。": [0.0, 64.215], "このたびは、弊社の新製品発表会にお越しいただき、誠にありがとうございます。": [64.615, 6.945], "こちらこそ、お招きいただき光栄に存じます。": [71.96, 3.98], "後ほど、ご感想をお聞かせいただければ幸いに存じます。": [76.34, 4.75], "ええ、ぜひ。実物を拝見するのを楽しみにしておりました。": [81.49, 5.155], "このような賞をいただき、大変光栄に存じます。": [87.045, 4.135], "ご参加いただけないとのこと、誠に残念に存じます。": [91.58, 4.635], "温かいお言葉をいただき、ありがたく存じます。": [96.615, 4.105], "このたびは温かいお祝いのお言葉をいただき、大変ありがたく存じます。今後もご指導いただければ幸いに存じます。": [101.12, 9.125], "お目にかかれて、うれしく存じます。": [110.645, 3.085], "来週中にはお届けできるかと存じます。": [114.13, 3.3], "偏在": [117.83, 1.155], "勤務医": [119.385, 1.01], "過重労働": [120.795, 1.365], "救急": [122.56, 1.17], "搬送": [124.13, 1.19], "病床": [125.72, 1.175], "地域医療": [127.295, 1.295], "逼迫": [128.99, 1.23]}, "d254": {"猛暑のたびに、電力会社や政府は「不要な照明の消灯など、節電にご協力願います」と呼びかける。電力需給が厳しい日に国民一人一人が少しずつ電気を控えることには、確かに一定の効果がある。しかし、毎年同じ呼びかけが繰り返されている現状は、むしろ問題が先送りされてきたことの証ではないか。再生可能エネルギーによる発電は天候に左右されるため、余った電力をためる蓄電設備や、地域間で電気を融通し合う送電網の整備が欠かせない。化石燃料に頼る古い発電所を使い続け、足りない分を節電で補うやり方は、いつまでも続けられるものではない。原子力をどう位置づけるかという難しい議論も、避けて通ることはできない。「ご協力願います」という丁寧な言葉で国民の我慢に期待する前に、供給の仕組みそのものを変える道筋を示すべきである。": [0.0, 62.635], "恐れ入りますが、会場内での撮影はご遠慮願います。": [63.035, 4.67], "あ、すみません。資料の写真もだめですか。": [68.105, 4.14], "申し訳ございません。資料は後日データでお送りいたしますので、それまでお待ち願えますか。": [72.645, 7.41], "わかりました。じゃあ、名刺をお渡ししておきます。": [80.455, 4.265], "ありがとうございます。それでは、お席へお戻り願います。": [85.12, 4.96], "館内での喫煙はご遠慮願います。": [90.48, 2.825], "恐れ入りますが、受付までお越し願えますでしょうか。": [93.705, 4.56], "担当者が戻るまで、こちらでお待ち願います。": [98.665, 3.965], "開始五分前までにご着席願います。講演中の録音・撮影はご遠慮願います。": [103.03, 7.265], "会場内での飲食はご遠慮願います。": [110.695, 3.05], "どうぞこちらにお掛けください。": [114.145, 2.38], "原子力": [116.925, 1.25], "発電": [118.575, 1.13], "電力需給": [120.105, 1.39], "供給": [121.895, 1.185], "蓄電": [123.48, 1.085], "送電網": [124.965, 1.31], "化石燃料": [126.675, 1.44], "節電": [128.515, 1.195]}, "d255": {"法案や条例の改正にあたって、行政が国民から意見を募るパブリックコメントという制度がある。募集の文書には「皆様のご意見を広く拝聴し、今後の検討に生かしてまいります」と記されている。ところが実際には、意見の募集期間が終わってわずか数日で原案どおり閣議決定され、そのまま国会で可決されることも珍しくない。数千件の意見をそれほどの短期間で拝読し、検討できるとは考えにくい。寄せられた意見への回答も「ご意見として承ります」と一行で済まされることが多い。これでは「拝聴」は形だけで、結論ありきの手続きと受け取られても仕方がない。立法の過程に国民の声を取り入れるという制度本来の目的を果たすには、どの意見を採用し、どの意見をなぜ退けたのかを具体的に示す必要がある。聞く姿勢は、言葉ではなく結果で示されるべきものだ。": [0.0, 64.005], "先日お送りした企画書は、もうご覧いただけましたでしょうか。": [64.405, 4.915], "はい、拝見しました。とても分かりやすかったです。": [69.72, 4.425], "ありがとうございます。部長のご意見も、ぜひ拝聴できればと思うのですが。": [74.545, 6.24], "では、来週の会議でお時間を取りますね。": [81.185, 3.635], "恐縮です。それまでに、御社の過去の事例資料を拝借してもよろしいでしょうか。": [85.22, 6.675], "お送りいただいた資料、確かに拝受いたしました。": [92.295, 4.13], "先生のご著書を拝読し、大変感銘を受けました。": [96.825, 4.58], "本日は貴重なお話を拝聴でき、光栄でした。": [101.805, 4.445], "ご提案書を拝受いたしました。早速拝読いたしましたところ、大変興味深い内容でございました。": [106.65, 7.885], "お手紙、ありがたく拝見しました。": [114.935, 3.135], "お手元の資料をご覧ください。": [118.47, 2.455], "法案": [121.325, 1.02], "可決": [122.745, 1.17], "否決": [124.315, 1.1], "採決": [125.815, 1.315], "施行": [127.53, 1.155], "改正": [129.085, 1.215], "条例": [130.7, 1.165], "立法": [132.265, 1.18]}, "d256": {"災害が起きるたびに、SNS上には根拠のない偽情報が瞬く間に拡散する。事業者は「真偽の不確かな情報の発信・共有はお控えくださいますよう、お願い申し上げます」と注意を呼びかけるが、その効果は限られている。そもそも、刺激的な投稿ほど多くの人の目に触れるよう設計されているのは、ほかならぬ事業者の仕組みである。匿名の利用者が誹謗中傷を書き込んでも、削除されるまでには何日もかかることがある。もちろん、国家が投稿を厳しく規制すれば言論の自由が脅かされるという懸念はもっともだ。だからといって、利用者の良識に訴えるだけでは問題は解決しない。表示の優先順位を決める仕組みを公開し、被害の申し立てには迅速に対応する。事業者が自らの責任を果たしてこそ、「ご注意くださいますよう」という言葉にも重みが生まれるのではないか。": [0.0, 61.84], "部長、取引先への案内状、この文面でよろしいでしょうか。": [62.24, 5.49], "どれどれ。「ご確認ください」で終わっているね。": [68.13, 4.155], "取引先宛てだから、「ご確認くださいますよう、お願い申し上げます」にしたほうがいい。": [72.685, 7.16], "承知しました。返信の期限も書き添えたほうがいいでしょうか。": [80.245, 4.895], "そうだね。「十日までにご返信くださいますよう」と入れておいて。": [85.54, 5.275], "資料を添付いたしましたので、ご査収くださいますようお願い申し上げます。": [91.215, 5.605], "寒さ厳しき折、どうぞご自愛くださいますよう。": [97.22, 4.185], "ご不明な点は、担当までお問い合わせくださいますようお願いいたします。": [101.805, 5.32], "会議資料を添付いたしましたので、事前にご一読くださいますようお願い申し上げます。また、ご出欠を十日までにご返信くださいますよう、併せてお願い申し上げます。": [107.525, 13.14], "ご出席くださいますよう、お願い申し上げます。": [121.065, 3.915], "ご出席いただきますよう、お願い申し上げます。": [125.38, 3.965], "偽情報": [129.745, 1.325], "拡散": [131.47, 1.16], "匿名": [133.03, 1.23], "誹謗中傷": [134.66, 1.43], "削除": [136.49, 1.26], "規制": [138.15, 1.09], "言論": [139.64, 1.035], "発信": [141.075, 1.06]}, "d257": {"感染症の流行が収束すると、社会は驚くほど早くそれを忘れていく。流行の最中には、隔離や検疫、外出の自粛が当然のように求められ、多くの人が仕事や学びの機会を失った。ところが、収束が宣言された後に出された行政の文書は、「長期にわたり多大なるご不便をおかけしました段、深くお詫び申し上げます」という一文で締めくくられ、それ以上の総括はなされなかった。どの措置が蔓延の防止に効果的で、どの措置が過剰だったのか。免疫や抗体に関する当時の知見は、どこまで正確だったのか。こうした検証を欠いたまま次の流行を迎えれば、私たちは同じ混乱を繰り返すことになる。謝罪の言葉は、それだけで終わるべきものではない。公衆衛生の名のもとに人々に負担を強いた以上、その是非を記録し、次の備えに生かすことこそが、本当の意味での責任の取り方であろう。": [0.0, 64.935], "部長、先方へのお詫び状、こちらの文面でいかがでしょうか。": [65.335, 5.395], "「納品が遅れましたことをお詫びします」か。少し軽いね。": [71.13, 5.085], "「納品が大幅に遅延いたしました段、深くお詫び申し上げます」としたほうがいい。": [76.615, 6.4], "承知しました。「の段」は、改まった書面で使う表現ですよね。": [83.415, 6.055], "そう。口頭なら「遅れまして、申し訳ございません」で十分だよ。": [89.87, 6.5], "返信が遅くなりました段、何卒ご容赦ください。": [96.77, 4.395], "貴社ますますご清栄の段、お喜び申し上げます。": [101.565, 4.31], "ご無礼の段、平にご容赦願います。": [106.275, 3.28], "このたびは弊社の手配の不備により、商品のお届けが遅延いたしました段、深くお詫び申し上げます。今後はこのようなことがないよう、確認体制を見直してまいります。": [109.955, 13.05], "ご迷惑をおかけしました段、深くお詫び申し上げます。": [123.405, 4.395], "ご迷惑をおかけしましたこと、深くお詫び申し上げます。": [128.2, 4.53], "公衆衛生": [133.13, 1.49], "隔離": [135.02, 1.11], "検疫": [136.53, 1.16], "蔓延": [138.09, 1.0], "免疫": [139.49, 1.125], "抗体": [141.015, 1.145], "流行": [142.56, 1.215], "収束": [144.175, 1.285]}, "d258": {"温暖化をめぐる議論は、これまで主に温室効果ガスをいかに減らすかという緩和策を中心に進められてきた。もちろん、それは今後も欠かせない。しかし、すでに豪雨や干ばつ、海面上昇は現実の脅威となっている。排出をどれほど減らしても、今後数十年の気温上昇はある程度避けられないと、多くの研究者が指摘している。だとすれば、変化に備える適応策にも同じだけの力を注ぐべきではないか。ある沿岸の町の首長は、記者会見で「住民の命を守るため、全力で防災に取り組む所存です」と語った。だが、その町の堤防のかさ上げ計画は、予算不足を理由に十年以上先送りされている。決意を語ることは、予算をつけることの代わりにはならない。減災のための投資は、被害が起きた後の復旧費用に比べれば、はるかに安くつくはずだ。": [0.0, 61.44], "それでは、新任の田中支店長よりご挨拶をお願いいたします。": [61.84, 5.22], "田中でございます。このたび大阪支店長を拝命いたしました。": [67.46, 5.165], "微力ではございますが、地域のお客様のお役に立てるよう、精一杯努める所存です。": [73.025, 7.205], "支店長、力強いご挨拶でしたね。": [80.63, 3.665], "ありがとう。言ったからには、結果で示すつもりだよ。": [84.695, 4.59], "今後も誠心誠意、業務に励む所存です。": [89.685, 3.955], "二度とこのような事態を起こさない所存でございます。": [94.04, 3.765], "ご期待に添えるよう、最善を尽くす所存です。": [98.205, 3.88], "本日付で企画部に配属になりました金と申します。一日も早く戦力になれるよう、積極的に学んでいく所存です。どうぞよろしくお願いいたします。": [102.485, 12.365], "新しい部署でも全力を尽くす所存です。": [115.25, 3.41], "週末は家でゆっくり休むつもりです。": [119.06, 3.12], "温暖化": [122.58, 1.16], "海面上昇": [124.14, 1.555], "干ばつ": [126.095, 1.2], "豪雨": [127.695, 0.97], "防災": [129.065, 1.12], "減災": [130.585, 1.105], "適応策": [132.09, 1.27], "緩和策": [133.76, 1.21]}, "d260": {"過疎に悩む自治体では、学校や病院の統廃合が避けられない課題となっている。財政難の中、限られた交付金で全ての施設を維持することは、もはや難しい。ある町で小学校の統合が決まった際、町長は住民説明会で「児童数の減少と財政状況を踏まえ、苦渋の決断として統合を決定した次第です」と述べた。説明そのものに不合理な点はない。だが、住民の多くが反発したのは、結論に対してではなく、その順序に対してだった。決めてから「次第です」と経緯を語るのでは、住民は事後報告の聞き手でしかない。地方自治の本旨は、住民が自らの地域の行く末を自ら選ぶことにあるはずだ。統合の是非が分かれる問題であれば、決定の前に複数の案と費用を示し、場合によっては住民投票に諮る道もあっただろう。痛みを伴う決断ほど、住民と共に下すべきなのである。": [0.0, 65.605], "突然お電話して申し訳ございません。A社の山田と申します。": [66.005, 5.1], "いつもお世話になっております。どのようなご用件でしょうか。": [71.505, 4.575], "実は、ご注文の部品の入荷が遅れておりまして、納期について急ぎご相談したく、お電話を差し上げた次第です。": [76.48, 9.14], "そうでしたか。どのくらい遅れそうですか。": [86.02, 3.425], "一週間ほどの見込みです。ご迷惑をおかけし、申し訳ございません。": [89.845, 5.99], "一度直接ご説明したく、本日伺った次第です。": [96.235, 4.8], "以上のような理由で、今回は辞退させていただいた次第です。": [101.435, 4.88], "資料に誤りがございましたので、訂正版をお送りした次第です。": [106.715, 5.075], "先日ご依頼いただいたお見積もりにつきまして、一部仕様の確認が必要となり、ご連絡を差し上げた次第です。ご回答をいただき次第、正式な見積書をお送りいたします。": [112.19, 13.935], "至急ご確認いただきたく、ご連絡した次第です。": [126.525, 4.205], "確認が取れ次第、ご連絡いたします。": [131.13, 3.525], "地方自治": [135.055, 1.2], "自治体": [136.655, 1.14], "首長": [138.195, 1.2], "財政難": [139.795, 1.305], "過疎": [141.5, 1.085], "交付金": [142.985, 1.065], "合併": [144.45, 1.185], "住民投票": [146.035, 1.55]}, "d261": {"私たちがウェブ上で何を閲覧し、どこで何を買ったか。そうした履歴は日々収集され、広告の配信や商品の推薦に使われている。利用者は登録時に「同意する」のボタンを押しているのだから問題はない、というのが多くの企業の言い分だ。しかし、長大な規約をすべて読んだうえで同意している人がどれほどいるだろうか。ある利用者が、自分についてどのような情報が保有されているのかを企業に問い合わせたところ、「社内規定により、詳細についてはお答えいたしかねます」という回答が返ってきたという。丁寧な断りではあるが、自分の情報の行方を本人が知ることができないのは、どう考えても筋が通らない。匿名化しているから安全だという説明も、複数のデータを組み合わせれば個人が特定され得る以上、十分ではない。開示を求められたら応じる。それは企業の厚意ではなく、利用者の権利として保障されるべきものだ。": [0.0, 64.09], "すみません、この商品、来週の月曜までに届けてもらえますか。": [64.49, 5.705], "申し訳ございません。在庫を確認いたしましたが、月曜日のお届けはお約束いたしかねます。": [70.595, 7.44], "そうですか。じゃあ、一番早くていつになりますか。": [78.435, 4.47], "水曜日でしたら、確実にお届けできます。": [83.305, 3.8], "わかりました。それでお願いします。": [87.505, 2.935], "恐れ入りますが、個人情報に関するお問い合わせにはお答えいたしかねます。": [90.84, 5.74], "その件につきましては、私ではわかりかねますので、担当者に確認いたします。": [96.98, 6.91], "誠に申し訳ございませんが、ご返品はお受けいたしかねます。": [104.29, 4.995], "誠に申し訳ございませんが、本日中の発送はお約束いたしかねます。明日の午前中でしたら確実に発送できますが、いかがでしょうか。": [109.685, 11.275], "当日のキャンセルには対応いたしかねます。": [121.36, 3.14], "当日のキャンセルはできません。": [124.9, 2.34], "閲覧履歴": [127.64, 1.355], "収集": [129.395, 1.22], "同意": [131.015, 0.95], "匿名化": [132.365, 1.28], "追跡": [134.045, 1.24], "流出": [135.685, 1.135], "保護法": [137.22, 1.11], "開示": [138.73, 1.04]}, "d262": {"高齢化に伴い、医療費は年々膨らみ続けている。保険料を払う現役世代の負担は重く、財源の確保が急務であることは言うまでもない。そこで、窓口での自己負担の割合を一律に引き上げる案が検討されている。だが、この案は慎重に考えるべきだ。負担が増えれば、とりわけ所得の低い人々が、体調の異変を感じても受診を先延ばしにしかねない。病気が見過ごされ、重症化してから医療機関にかかれば、治療はかえって高額になる。抑制するつもりの医療費が、結果的に増えるという皮肉な事態も起こりかねないのだ。医療保険制度を持続可能なものにするには、負担を求めること自体は避けられないだろう。ただし、それは年齢で一律に線を引くのではなく、所得や資産といった負担能力に応じた形であるべきだ。給付と負担の釣り合いは、数字だけでなく、人の行動まで見通して設計されなければならない。": [0.0, 64.545], "この見積もり、今日中に先方に送るつもり？": [64.945, 3.85], "はい。ただ、まだ金額の最終確認ができておりませんで……。": [69.195, 5.32], "確認しないで送ったら、後でトラブルになりかねないよ。": [74.915, 4.43], "そうですね。部長にご確認いただいてからお送りします。": [79.745, 4.585], "うん。先方には、明日の午前中にお送りすると伝えておいて。": [84.73, 5.33], "このまま放置すれば、大きな事故につながりかねない。": [90.46, 4.26], "不用意な発言は、会社の信用を損ないかねません。": [95.12, 4.46], "彼なら締め切りを忘れかねないから、念のため連絡しておこう。": [99.98, 4.99], "納期を一週間縮めると、品質の確認が不十分になりかねません。お客様には「誠に恐縮ですが、ご希望の納期ではお引き受けいたしかねます」とお伝えしましょう。": [105.37, 13.425], "その対応では、顧客の不満を招きかねない。": [119.195, 3.915], "そのご要望は、弊社では承りかねます。": [123.51, 3.98], "医療費": [127.89, 0.995], "保険料": [129.285, 1.24], "自己負担": [130.925, 1.145], "給付": [132.47, 1.025], "財源": [133.895, 1.075], "持続可能": [135.37, 1.385], "高額": [137.155, 1.195], "抑制": [138.75, 1.255]}, "d263": {"公園の池のほとりに「恐れ入りますが、飼育している生き物を池に放さないでください」という看板が立っている。この控えめな一文の背景には、深刻な問題がある。かつてペットとして輸入された外来種が野外で繁殖し、在来種を食べたり生息地を奪ったりして、地域の生態系を大きく変えてしまった例は数多い。その結果、多くの自治体が多額の費用をかけて駆除を続けている。駆除の現場は、生き物の命を奪うという重い仕事でもある。だが考えてみれば、外来種自身に罪はない。彼らを持ち込み、飽きたからと放したのは人間だ。生物多様性の保全というと、絶滅しかけた固有種を守る取り組みに目が向きがちだが、それと同じくらい重要なのは、問題を新たに生まない仕組みである。看板で「恐れ入りますが」とお願いするだけでは足りない。輸入や販売の段階での規制と、最後まで責任を持って飼うという教育こそが求められている。": [0.0, 67.37], "恐れ入りますが、営業部の佐藤様はいらっしゃいますか。": [67.77, 4.51], "申し訳ございません。佐藤はただいま席を外しております。": [72.68, 4.805], "そうですか。恐れ入りますが、お戻りは何時ごろになりますか。": [77.885, 5.21], "三時ごろの予定です。よろしければ、折り返しお電話を差し上げましょうか。": [83.495, 6.03], "恐れ入ります。では、お願いいたします。": [89.925, 3.68], "恐れ入りますが、もう一度お名前をお伺いできますか。": [94.005, 4.445], "恐れ入りますが、こちらにご署名をお願いいたします。": [98.85, 4.36], "わざわざお越しいただき、恐れ入ります。": [103.61, 3.37], "恐れ入りますが、山田様がお戻りになりましたら、A社の金から電話があったとお伝えいただけますでしょうか。また、恐れ入りますが、本日中に折り返しお電話をいただけると助かります。": [107.38, 14.39], "恐れ入りますが、少々お待ちいただけますか。": [122.17, 3.995], "すみませんが、ちょっと待ってもらえる？": [126.565, 3.065], "生物多様性": [130.03, 1.735], "外来種": [132.165, 1.145], "在来種": [133.71, 1.17], "保全": [135.28, 1.0], "乱獲": [136.68, 1.235], "生息地": [138.315, 1.29], "固有種": [140.005, 1.09], "駆除": [141.495, 1.015]}, "d264": {"ある自治体が若い世代向けに実施したアンケートに、「差し支えなければ、お子さんを持つ予定がない理由をお聞かせください」という設問があり、議論を呼んだ。丁寧な前置きがあるとはいえ、この問い自体に、子どもを持つことを当然視する視線を感じた人が少なくなかったのだろう。少子化と人口減少が社会保障の土台を揺るがしていることは確かだ。出生率の回復を目標に掲げる政策の意図も理解できる。だが、子どもを持つかどうかは個人の人生の選択であり、行政が理由を尋ねて改めさせる対象ではない。政策が問うべきは「なぜ産まないのか」ではなく、「産みたい人が産めないのはなぜか」である。待機児童の解消、男性も取りやすい育児休業、長時間労働の是正。子育て支援の財政出動は、個人の選択に介入するためではなく、選択の幅を広げるためにこそ使われるべきだ。": [0.0, 62.855], "本日はお時間をいただき、ありがとうございます。差し支えなければ、お名刺を頂戴できますか。": [63.255, 7.975], "あ、失礼しました。こちらです。": [71.63, 3.215], "ありがとうございます。差し支えなければ、今回のご予算の規模を伺ってもよろしいでしょうか。": [75.245, 7.44], "そうですね……まだ社内で調整中なので、おおよそでもよろしければ。": [83.085, 5.71], "もちろんです。差し支えのない範囲で結構です。": [89.195, 4.115], "差し支えなければ、ご連絡先を教えていただけますか。": [93.71, 4.59], "差し支えのない範囲で、ご事情をお聞かせください。": [98.7, 4.26], "書類は後日のご提出でも差し支えございません。": [103.36, 3.9], "差し支えなければ、今回のご予算の規模をお聞かせいただけますか。また、差し支えのない範囲で、最終的なご決定の時期も伺えれば幸いです。": [107.66, 12.0], "差し支えなければ、ご年齢を伺えますか。": [120.06, 3.77], "よろしければ、お茶をどうぞ。": [124.23, 2.52], "少子化": [127.15, 1.285], "出生率": [128.835, 1.31], "子育て支援": [130.545, 1.335], "待機児童": [132.28, 1.27], "育児休業": [133.95, 1.385], "人口減少": [135.735, 1.53], "社会保障": [137.665, 1.49], "財政出動": [139.555, 1.54]}, "d265": {"「誠に勝手ながら、旧システムの保守サービスは、来年三月をもって終了させていただきたく存じます」。取引先のベンダーからこんな通知が届き、慌てて基幹システムの刷新に乗り出す企業は少なくない。丁重な文面ではあるが、事実上の最後通告である。多くの企業はここで、新しいシステムへの移行を同じベンダーに一任する。互換性の問題も運用の手順も、専門家に任せておけば安心だというわけだ。だが、私はこれこそが刷新が失敗する最大の原因だと考えている。システムとは業務の写し鏡である。紙と判子を前提に組み立てられた手順をそのまま新しい仕組みに載せ替えても、業務効率は少しも上がらない。導入の前に、どの業務が本当に必要なのかを、現場を知る社員自身が問い直さなければならない。システムを入れ替えることと、仕事のやり方を変えることは、似て非なるものなのだ。": [0.0, 63.435], "部長、来週の役員会議で、私からも新システムについてご説明させていただきたく存じます。": [63.835, 8.07], "いいよ。どのくらい時間が必要かな。": [72.305, 3.24], "十分ほど頂戴できればと思います。あと、事前に資料にお目通しいただきたいのですが。": [75.945, 6.965], "わかった。明日までに送っておいて。": [83.31, 3.065], "ありがとうございます。それと、当日は情報システム部の山口さんにも同席していただきたく存じます。": [86.775, 8.345], "来週の打ち合わせを、木曜日に変更させていただきたく存じます。": [95.52, 5.345], "誠に勝手ながら、八月十三日から十六日まで休業させていただきたく存じます。": [101.265, 7.17], "本件につきましては、社内で再度検討させていただきたく存じます。": [108.835, 5.725], "誠に恐縮ですが、社内の都合により、十五日のお打ち合わせを翌週に延期させていただきたく存じます。直前のお願いとなり、大変申し訳ございません。": [114.96, 12.91], "納品日を一日延期させていただきたく存じます。": [128.27, 3.86], "納品日を一日延期させていただきます。": [132.53, 3.185], "遠隔": [136.115, 1.19], "業務効率": [137.705, 1.445], "導入": [139.55, 1.08], "刷新": [141.03, 1.125], "移行": [142.555, 1.1], "互換性": [144.055, 1.22], "運用": [145.675, 1.105], "保守": [147.18, 1.03]}, "d267": {"自治体から届く健診の案内は、たいてい「つきましては、期間内のご受診のほど、何卒よろしくお願い申し上げます」という結びの言葉で終わる。礼儀正しい文面だが、毎年これを受け取っても、受診しない人は受診しない。生活習慣病の多くは自覚症状がないまま進行し、罹患に気づいた時には治療が難しくなっていることもある。早期発見が予後を大きく左右することは、多くの人が知識としては知っているはずだ。それでも受診率が伸びないのは、案内の言葉が足りないからではなく、「平日の昼間に休めない」「結果を聞くのが怖い」といった個々の事情に届いていないからではないか。実際、夜間や休日に健診を受けられるようにした地域や、保健師が電話で一人一人に声をかけた地域では、受診者が目に見えて増えたという。啓発の文書を丁寧に整えることより、受けられない理由を一つずつ取り除くことが先決である。": [0.0, 65.61], "課長、取引先へのメールの結びは、どう書けばいいでしょうか。": [66.01, 5.475], "見積もりの依頼なら、「ご検討のほど、何卒よろしくお願い申し上げます」でいいんじゃないかな。": [71.885, 7.53], "なるほど。急ぎの連絡のときはどうすればいいでしょうか。": [79.815, 4.51], "「取り急ぎご連絡まで」と書くこともあるけど、目上の相手には「まずは取り急ぎご連絡申し上げます」のほうが丁寧だね。": [84.725, 9.945], "わかりました。ありがとうございます。": [95.07, 2.945], "ご多忙のところ恐縮ですが、ご検討のほど何卒よろしくお願い申し上げます。": [98.415, 6.21], "まずは取り急ぎ、資料送付のご連絡を申し上げます。": [105.025, 4.47], "まずは略儀ながら、メールにて御礼申し上げます。": [109.895, 3.965], "お見積書を添付いたしましたので、ご確認のほどよろしくお願いいたします。ご検討いただけますよう、何卒よろしくお願い申し上げます。": [114.26, 10.68], "明日の会議室が変更になりました。取り急ぎご連絡まで。": [125.34, 4.97], "明日の会議室が変更となりました。まずは取り急ぎご連絡申し上げます。": [130.71, 5.895], "健診": [137.005, 1.08], "早期発見": [138.485, 1.4], "生活習慣病": [140.285, 1.855], "罹患": [142.54, 1.02], "疾患": [143.96, 1.18], "予後": [145.54, 0.99], "受診率": [146.93, 1.21], "啓発": [148.54, 1.21]}, "d268": {"政治家の記者会見を見ていると、「総理がおっしゃられたように」「ご覧になられた方も多いと思いますが」といった言い回しをよく耳にする。いずれも、尊敬語にさらに「られる」を重ねた二重敬語であり、規範的には誤りとされる。インターネット上では、こうした誤用をあげつらう投稿も少なくない。だが私は、政治家の敬語の誤りに目くじらを立てることに、あまり意味があるとは思わない。敬語が多少過剰であっても、意味は十分に伝わるからだ。問題にすべきは言葉遣いの正しさではなく、その丁寧な言葉で何が語られ、何が語られていないかである。献金や業界との癒着が疑われた際に、「誠に遺憾に存じます」「真摯に受け止めさせていただきます」と繰り返すばかりで、肝心の説明責任を果たさない。そうした姿勢こそが政治不信を深め、民意と代議制の距離を広げているのではないだろうか。": [0.0, 63.62], "課長、先方の部長がお見えになられました。": [64.02, 3.92], "「お見えになりました」でいいよ。「お見えになられる」は二重敬語だから。": [68.34, 5.805], "あ、失礼しました。それから、部長が、先に資料をご覧になりたいとおっしゃっています。": [74.545, 7.535], "わかった。すぐにお持ちして。私もすぐに伺うと伝えておいて。": [82.48, 5.57], "部長は明日の会議にご出席になるそうです。": [88.45, 3.545], "お客様がお帰りになりましたので、会議室を片付けます。": [92.395, 4.77], "弊社の社長が、そのように申しておりました。": [97.565, 3.835], "社長がお帰りになりました。受付でお尋ねください。弊社の部長が拝見いたしました。": [101.8, 7.28], "先生がおっしゃったとおり、結果は良好でした。": [109.48, 3.905], "（×）先生がおっしゃられたとおり、結果は良好でした。": [113.785, 4.98], "政治不信": [119.165, 1.36], "民意": [120.925, 0.95], "代議制": [122.275, 1.165], "説明責任": [123.84, 1.58], "癒着": [125.82, 1.155], "汚職": [127.375, 1.08], "献金": [128.855, 1.145], "罷免": [130.4, 0.975]}, "d269": {"自動運転バスの実証実験が始まった町で、住民説明会に参加した。市の担当者は「実験期間中は、職員が車内で皆様のご意見を伺ってまいります」「ご高齢の方も安心してご乗車いただけます」と繰り返し、渋滞の緩和や大気汚染の監視など、技術がもたらす恩恵を次々に挙げた。しかし、質疑応答で一人の女性が「運転手さんと話すのが、私にとっては唯一の外出の楽しみなんです」と述べると、会場は静まり返った。技術の評価は、運行の正確さや事故の少なさといった数値だけでは測れない。バスは移動手段であると同時に、地域の人と人とをつなぐ場でもあったのだ。環境負荷の少ない循環型の町づくりを目指すなら、なおのこと、暮らしの中で失われるものにも目を向けるべきだろう。「ご意見を伺ってまいります」という言葉が、数値に表れない声を拾い上げる約束として果たされることを願いたい。": [0.0, 66.355], "もしもし、B社の松本です。佐々木部長はいらっしゃいますか。": [66.755, 5.42], "いつもお世話になっております。佐々木はただいま会議中でございます。": [72.575, 5.295], "そうですか。では、明日の午前中に、こちらから改めてお電話いたします。": [78.27, 6.415], "恐れ入ります。佐々木が戻りましたら、松本様からお電話があったと申し伝えます。": [85.085, 6.97], "よろしくお願いします。": [92.455, 1.945], "資料は明日、私どもからお送りします。": [94.8, 3.805], "資料は明日、先方の担当者がお送りになるそうです。": [99.005, 4.6], "会議の内容を録音させていただけますか。": [104.005, 3.32], "佐々木部長へ。B社の松本様からお電話があり、明日の午前中に改めてお電話くださるとのことです。": [107.725, 8.325], "この書類にサインしていただけますか。": [116.45, 2.8], "この書類をコピーさせていただけますか。": [119.65, 3.035], "環境負荷": [123.085, 1.35], "循環型": [124.835, 1.34], "大気": [126.575, 1.04], "水質": [128.015, 1.21], "監視": [129.625, 1.065], "実証実験": [131.09, 1.37], "自動運転": [132.86, 1.275], "渋滞": [134.535, 1.15]}, "d271": {"「早くしてってば」「大丈夫だってば」。日常会話でよく耳にする「ってば」は、同じことを何度も言っているのに相手が動かない、あるいは信じてくれないときのいら立ちを表す。聴解試験でも、この表現はしばしば問題を解く鍵になる。話し手が「ってば」と語気を強めて繰り返したなら、それはあらかじめ伝えておいたはずの要点であり、相手に最も実行してほしい内容だと考えてよい。逆に、会話の前半で話題に上った作業が「後でいい」と後回しにされることも少なくない。言葉の端々に表れる感情の揺れに気を配ることこそ、正確な聞き取りへの近道なのである。": [0.0, 46.11], "田中さん、会議の資料、まだ？もう十時過ぎてるよ。": [46.51, 5.14], "わかってるって。今、グラフを直してるところ。": [52.05, 4.155], "グラフは後でいいってば。先に部長にデータだけ送ってって、さっきから言ってるでしょ。": [56.605, 6.645], "えっ、データだけでいいの？じゃ、すぐ送る。グラフはそのあと仕上げるよ。": [63.65, 6.315], "うん。会議室の予約は私がやっとくから。": [70.365, 3.845], "もう怒ってないってば。何回言わせるの。": [74.61, 3.355], "ねえ、早く起きてってば。遅刻するよ。": [78.365, 3.775], "うちの兄ってば、また私のケーキを勝手に食べたの。": [82.54, 4.52], "もう出発の時間だってば。あらかじめ準備しておいてって言ったでしょ。": [87.46, 5.245], "大丈夫だってば。心配しないで。": [93.105, 3.125], "弟ったら、また鍵をなくしたのよ。": [96.63, 3.285], "あらかじめ": [100.315, 1.365], "ことごとく": [102.08, 1.39], "おのずと": [103.87, 1.19], "かねて": [105.46, 1.0], "いたって": [106.86, 1.04], "しきりに": [108.3, 1.19], "とっさに": [109.89, 1.005], "まるっきり": [111.295, 1.225]}, "d272": {"「あれ、何て名前だったっけ」。年齢を重ねると、こうした独り言がおのずと増えるものだ。しかし、言葉が出てこないこと自体をそれほど悲観する必要はないと、ある脳科学者は言う。記憶はなくなったのではなく、取り出すのに少し時間がかかっているにすぎないというのだ。実際、「っけ」と口にしたあと、ひたすら思い出そうと粘るより、いったん別のことを考えたほうが、あっけないほど簡単に答えが浮かぶことも多い。聴解の問題でも、「〜だっけ」は話し手の記憶があいまいだという合図である。その直後に相手が訂正や新しい情報を加えることが多いので、最後まで気を抜かずに聞きたい。": [0.0, 45.935], "ねえ、社会学のレポートの締め切り、いつだっけ？": [46.335, 4.63], "来週の金曜じゃなかったっけ。あ、待って、先生が変更するって言ってたな。": [51.365, 6.67], "え、そうだっけ？早くなったの？": [58.435, 3.24], "いや、逆。先生が学会に出るから、一週間延ばすって。だから再来週の金曜。": [62.075, 7.815], "よかった。じゃあ、その分ひたすら文献を読めるね。": [70.29, 4.56], "すみません、お名前、何とおっしゃいましたっけ。": [75.25, 4.15], "明日の集合って、九時だったっけ、十時だったっけ。": [79.8, 4.56], "子どものころは、この川でよく泳いだっけなあ。": [84.76, 3.865], "次の会議って、三階の会議室だったっけ。時間は二時でしたっけ。てきぱき準備しないとね。": [89.025, 7.88], "あの店、月曜は休みだったっけ。": [97.305, 3.32], "明日は晴れるかな。": [101.025, 1.665], "ひたすら": [103.09, 1.245], "あっけない": [104.735, 1.21], "ありきたり": [106.345, 1.255], "ささやか": [108.0, 1.29], "うっとうしい": [109.69, 1.315], "おっくう": [111.405, 1.105], "すべ": [112.91, 1.07], "てきぱき": [114.38, 1.24]}, "d274": {"送別の贈り物選びは、意外に頭を悩ませるものだ。高価な品を贈れば相手に気を遣わせるし、ありきたりの品では印象に残らない。最近はかさばらず、相手が自分で好きな物を選べるカタログギフトが人気だという。一方で、「品物よりも手書きのメッセージのほうが心に残るんじゃないか」という声も根強い。実際、退職者を対象にしたある調査では、最も記憶に残った贈り物として、同僚の寄せ書きを挙げた人が半数近くに上った。結局のところ、贈り物の価値を決めるのは値段ではなく、相手のことを思って選んだかどうかなのだろう。選択を店員の勧めにゆだねるだけでは、気持ちは伝わりにくい。": [0.0, 48.265], "部長の送別会のプレゼント、このペンでいいかな。": [48.665, 4.285], "うーん、ペンはもう何本も持ってるんじゃない？毎年もらうって言ってたし。": [53.35, 5.47], "そっか。じゃあ、このカタログギフトは？好きな物を選べるし。": [59.22, 5.465], "それなら喜ばれるんじゃない？ただ、みんなのメッセージカードは別に用意したほうがいいよ。": [65.085, 6.685], "わかった。じゃ、カードを置いてるか、まず店員さんに聞いてみる。": [72.17, 5.28], "この服、ちょっと派手すぎるんじゃない？": [77.85, 3.055], "山田さんなら、もう帰ったんじゃないかな。": [81.305, 3.385], "危ないから、そこで遊ぶんじゃない。": [85.09, 3.025], "花束はかさばるんじゃない？電車で帰るなら、小さいお菓子のほうがいいんじゃない？": [88.515, 6.285], "それ、田中さんの傘なんじゃない？": [95.2, 3.05], "人の物に勝手に触るんじゃない。": [98.65, 2.73], "ぼやく": [101.78, 1.065], "うろたえる": [103.245, 1.205], "かさばる": [104.85, 1.21], "もくろむ": [106.46, 1.17], "ゆだねる": [108.03, 1.15], "けなす": [109.58, 1.135], "ばてる": [111.115, 1.015], "ねだる": [112.53, 1.01]}, "d275": {"仕事にゆとりがないと感じる人は多い。だが、予定と予定の間に生まれるつかの間の空き時間を、私たちはどれほど意識しているだろうか。ある企業では、会議が予定より早く終わったり、来客が遅れたりしたときに取りかかる「すき間仕事」をあらかじめリストにしておくよう社員に勧めている。書類の見直しやメールの整理など、十分ほどで済む作業を書き出しておけば、空いた時間に迷わず手をつけられる。導入した部署では残業時間が月平均で二割近く減り、効果は歴然としていたという。「せっかく時間ができたことだし」と、小さな作業を一つ片づける。その積み重ねが、仕事全体をはかどらせるのだ。": [0.0, 47.945], "山田さん、取引先との打ち合わせ、三時からだったね。": [48.345, 4.975], "はい。ただ、先方から少し遅れるかもしれないと連絡がありまして。": [53.72, 5.95], "そうか。せっかく時間ができたことだし、先に見積書を見直しておいてくれるかな。金額の欄に一か所ミスがあった気がするんだ。": [60.07, 10.255], "わかりました。打ち合わせ用の資料のコピーはどうしましょう。": [70.725, 4.5], "それは先方の人数がはっきりしてからでいいよ。": [75.625, 3.705], "雨もやんだことだし、少し散歩しようか。": [79.73, 3.865], "みんなそろったことだし、そろそろ始めましょう。": [83.995, 3.97], "もう遅いことだし、続きは明日にしよう。": [88.365, 3.575], "今日は仕事がはかどったことだし、たまには早く帰りませんか。": [92.34, 5.04], "天気もいいことだし、外で食べようよ。": [97.78, 3.485], "雪が降ったから、電車が遅れた。": [101.665, 3.005], "よみがえる": [105.07, 1.265], "つかの間": [106.735, 1.24], "ゆとり": [108.375, 1.05], "いきさつ": [109.825, 1.205], "しくじる": [111.43, 1.2], "はかどる": [113.03, 1.21], "一律": [114.64, 1.17], "歴然": [116.21, 1.13]}, "d276": {"「そんなの、できるわけないじゃん」。若者の会話でよく聞かれるこの言い回しは、「〜わけがないじゃないか」がくだけた形である。相手の提案や期待を真っ向から打ち消すため、使い方を誤ると冷たい印象を与えかねない。ただし、聴解問題では、話し手が何かを否定したあとに、その本当の理由を説明する場面が少なくない。「先生が許してくれるわけない」と言った人が、実は先生の性格ではなく、自分の側に後ろめたい事情を抱えている、といった具合だ。否定の言葉そのものより、その後に続く理由に耳を傾けることが、正解を選ぶ鍵となる。話し手の意図を読み取る力が試されるのである。": [0.0, 47.445], "発表の準備、間に合いそう？先生に延期をお願いしてみたら？": [47.845, 5.43], "無理無理。延ばしてもらえるわけないじゃん。": [53.675, 3.195], "でも、去年、風邪をひいた人には一週間待ってくれたって聞いたよ。": [57.27, 5.435], "それは病気だったからでしょ。僕の場合、ただ準備をさぼってただけだし、正直に言ったら怒られるよ。": [63.105, 8.225], "まあね。じゃ、今夜から手分けしてスライドを作ろう。": [71.73, 4.455], "あの人がそんな約束、覚えてるわけないじゃん。": [76.585, 3.88], "こんなに安いのに、品質がいいわけないよ。": [80.865, 3.675], "この程度の作業なら、わけないよ。三十分で終わる。": [84.94, 4.705], "一日で終わるわけないじゃん。手続きがすごく煩雑なんだから。": [90.045, 4.89], "あいつが謝るわけないじゃん。": [95.335, 2.09], "鍵はかけたから、開いているはずがない。": [97.825, 3.51], "互角": [101.735, 1.15], "安堵": [103.285, 1.0], "意図": [104.685, 0.95], "抜群": [106.035, 1.09], "煩雑": [107.525, 1.215], "簡素": [109.14, 1.12], "手分け": [110.66, 1.125], "打診": [112.185, 0.995]}, "d277": {"「一晩で五十ページなんて、訳せっこない」。誰もがそう思うような依頼が、職場では不意に舞い込んでくることがある。そんなとき、頭ごなしに断るのも、無理をして引き受けるのも得策ではない。ある翻訳会社の担当者は、まず相手が本当に必要としている部分を確かめることが大切だと語る。期限までに全部が必要なケースは意外に少なく、会議で使う数ページさえあれば十分という場合も多いからだ。優先順位を示して交渉すれば、依頼主も落胆することなく、仕事の質も保てる。「できっこない」と嘆く前に、何ができるかを考える。その姿勢こそが信頼につながるのだろう。": [0.0, 46.265], "この翻訳、明日の朝までに全部終わらせてほしいって。": [46.665, 4.565], "えっ、五十ページも？一晩でなんて、できっこないよ。": [51.63, 4.885], "だよね。でも、先方の会議が明日の午後なんだって。": [56.915, 4.715], "だったら、会議で使う最初の十ページだけ先に仕上げて、残りは週末までにしてもらえないか交渉してみたら？": [62.03, 8.615], "そうだね。じゃ、先方に連絡する前に、まず課長に相談してみるよ。": [71.045, 6.47], "こんな難しい問題、子どもに解けっこないよ。": [77.915, 4.02], "今から走っても、終電には間に合いっこない。": [82.335, 3.86], "あの頑固な父が、私の気持ちなんかわかりっこない。": [86.595, 4.555], "一か月で十キロなんて、やせっこないよ。念願のマラソン大会まで、少しずつ減らしたら？": [91.55, 7.585], "一人でこの量なんて、運べっこないよ。": [99.535, 3.415], "あの店のランチが、そんなに高いわけがない。": [103.35, 3.82], "念願": [107.57, 1.05], "落胆": [109.02, 1.11], "憤慨": [110.53, 1.14], "仰天": [112.07, 1.07], "交錯": [113.54, 1.225], "推移": [115.165, 1.04], "頑な": [116.605, 1.32], "克明": [118.325, 1.265]}, "d278": {"なかなか寝つけない、夜中に何度も目が覚める。睡眠の悩みを抱える人は少なくないが、すぐに薬に頼るのは考えものだと専門家は口をそろえる。不眠の原因は生活習慣に潜んでいることが多く、まずはそれを見直すのが先決だというのだ。中でも見落とされがちなのが、寝る直前のスマートフォンである。画面の光は脳を昼間だと錯覚させ、眠りを妨げる。ある医師は患者に「一週間だけ、寝室にスマホを持ち込まないようにしてみたらどうですか」と勧めるそうだ。綿密な検査より先に、漠然とした習慣を一つ変えてみる。案外それだけで、眠りの質は大きく変わるのかもしれない。": [0.0, 46.93], "検査の結果ですが、特に異常はありませんでしたよ。": [47.33, 4.295], "そうですか。でも、最近どうも寝つきが悪くて。": [52.025, 4.44], "寝る前にスマホを見ていませんか。まずは寝る一時間前から画面を見ないようにしてみたらどうでしょう。": [56.865, 7.19], "はあ…。薬はいただけないんでしょうか。": [64.455, 3.215], "薬は二週間ほど様子を見てからにしましょう。それでも眠れなければ、また来てください。": [68.07, 7.205], "そんなに疲れているなら、少し休んだらどう？": [75.675, 4.025], "わからないなら、先生に直接聞いてみたら？": [80.1, 3.91], "文句ばかり言っていないで、少しは自分でやったらどうなの。": [84.41, 4.67], "一人で全部やるなんて無謀だよ。先輩に少し手伝ってもらったらどう？": [89.48, 5.585], "そんなに気になるなら、本人に聞いてみたらどう？": [95.465, 4.0], "駅までは、このバスに乗ればいいですよ。": [99.865, 3.34], "綿密": [103.605, 1.155], "寛大": [105.16, 1.13], "無償": [106.69, 1.12], "無謀": [108.21, 1.07], "不審": [109.68, 0.98], "不意に": [111.06, 0.92], "未然に": [112.38, 1.02], "漠然": [113.8, 1.115]}, "d279": {"新しい物流拠点の候補地を、資料と写真だけで決めてしまう企業は意外に多い。ところが、いざ稼働してみると、周辺の道路が朝夕に渋滞したり、思ったより騒音への苦情が多かったりと、案の定問題が噴き出すことがある。昼間は閑散としている場所でも、時間帯によって表情はまったく異なるのだ。ある物流会社の幹部は「現地に足を運ばないことには、何もわからない」と断言する。同社では候補地を決める前に、必ず担当者が朝・昼・夜の三回現地を訪れ、周辺をくまなく歩くことにしている。手間はかかるが、後から計画を根こそぎ見直す事態に比べれば、さほど大きな負担ではない。": [0.0, 49.155], "部長、新しい倉庫の候補地の資料、お送りしておきました。": [49.555, 5.485], "ああ、見たよ。でも写真だけじゃねえ。実際に現地を見ないことには決められないな。": [55.44, 6.88], "では、来週、視察に行かれますか。": [62.72, 3.665], "そうしよう。その前に、地元の不動産会社に、周辺の道路の交通量を問い合わせておいてくれる？": [66.785, 8.23], "承知しました。すぐに連絡します。": [75.415, 3.245], "実際に食べてみないことには、おいしいかどうかわからない。": [79.06, 4.495], "社長の許可が出ないことには、この計画は進められません。": [83.955, 5.015], "体が丈夫でないことには、この仕事は続かないよ。": [89.37, 4.45], "過去のデータをくまなく調べないことには、正確な予算は出せません。": [94.22, 5.49], "本人に会わないことには、採用は決められない。": [100.11, 3.91], "雨が降らなければ、明日は海に行こう。": [104.42, 3.36], "閑散": [108.18, 1.08], "案の定": [109.66, 1.225], "根こそぎ": [111.285, 1.265], "さほど": [112.95, 1.22], "いっそ": [114.57, 1.045], "てっきり": [116.015, 1.125], "くまなく": [117.54, 1.095], "ことによると": [119.035, 1.4]}, "d281": {"買った服のサイズが合わず、店に交換を頼みに行ったら、レシートがないと受け付けられないと断られた。そんな経験を持つ人は少なくないだろう。多くの店では、レシートは購入日や支払い方法を確かめる唯一の手がかりであり、トラブルを防ぐためにも極力提示を求めるようにしている。一方で、最近はアプリの会員番号やカードの利用履歴から購入記録を確認できる店も増えてきた。とはいえ、すべての店が対応しているわけではない。依然として紙のレシートが頼りという店も多いのだ。返品や交換の可能性が少しでもある買い物なら、レシートはしばらく取っておかないと、と心がけておきたい。": [0.0, 45.8], "すみません、先週ここで買ったシャツ、サイズが合わなくて交換したいんですが。": [46.2, 6.395], "かしこまりました。レシートはお持ちでしょうか。": [52.995, 3.67], "あ、家に置いてきちゃって…。カードで払ったんですけど。": [57.065, 4.45], "申し訳ございません。当店では、交換にはレシートがないと…。カードの控えでは確認ができないんです。": [61.915, 8.14], "そうですか。じゃ、取りに帰らないと。閉店は何時ですか。": [70.455, 5.305], "八時でございます。": [76.16, 1.735], "もうこんな時間だ。そろそろ帰らないと。": [78.295, 3.515], "早く申し込まないと、いい席がなくなるよ。": [82.21, 3.725], "明日は試験だから、ちゃんと復習しとかないと。": [86.335, 3.915], "今日中に報告書を出さないと。それから、残業は極力減らさないとね。": [90.65, 6.16], "会議の資料、今日中にまとめないと。": [97.21, 3.375], "やばい、もう出なきゃ。": [100.985, 2.095], "とりわけ": [103.48, 1.225], "じかに": [105.105, 1.095], "一挙に": [106.6, 1.035], "極力": [108.035, 1.255], "断然": [109.69, 1.05], "ろくに": [111.14, 1.09], "依然として": [112.63, 1.435], "かろうじて": [114.465, 1.29]}, "d282": {"電車の遅延や急な体調不良など、遅刻にはやむを得ない事情もある。しかし、職場で問題になるのは、遅れたこと自体より、その知らせ方であることが多い。ある調査によれば、同僚の遅刻で最も不快に感じた点として「連絡がなかったこと」を挙げた人が七割を超えた。遅れるにしても、一言あれば周囲は予定を組み替えられる。ところが、連絡があやふやだったり、そっけない一行だけだったりすると、残された人はどう動けばいいかわからず、すかさず代わりの対応をとることもできない。ささいなことのようでも、事情を早めに、つぶさに伝える習慣が、職場の信頼を支えているのである。": [0.0, 46.985], "佐藤さん、また遅刻だって。電車が止まってたらしいよ。": [47.385, 4.875], "電車なら仕方ないけど、遅れるにしても、連絡ぐらいはしてほしいよね。": [52.66, 5.73], "確かに。今朝は一緒にお客さんのところへ行く予定だったんでしょ？": [58.79, 5.06], "そう。結局、私一人で先方におわびの電話をしたんだから。": [64.25, 5.685], "それにしても、毎回何の連絡もないのは困るね。": [70.335, 4.355], "忙しいにしても、返事ぐらいはすぐにしてほしい。": [75.09, 4.13], "冗談にしても、言っていいことと悪いことがある。": [79.62, 3.935], "賛成するにしても反対するにしても、理由を説明してください。": [83.955, 5.24], "忙しかったにしても、あやふやな返事じゃなくて、来られるかどうかはっきり言ってほしかったな。": [89.595, 6.92], "事情があったにしても、無断欠勤はよくない。": [96.915, 3.83], "たとえ宝くじが当たったとしても、仕事は辞めない。": [101.145, 4.245], "あいにく": [105.79, 1.15], "おびただしい": [107.34, 1.415], "まちまち": [109.155, 1.225], "つぶさに": [110.78, 1.245], "すかさず": [112.425, 1.295], "あやふや": [114.12, 1.22], "ぎこちない": [115.74, 1.22], "そっけない": [117.36, 1.33]}, "d283": {"もし一年間だけ海外で学べるとしたら、どこを選ぶだろうか。多くの学生は、まず都市の知名度や物価を思い浮かべる。だが、留学経験者に話を聞くと、選択の決め手はおおむね別のところにあるようだ。最も多かったのは「大学同士の協定があり、取った単位がそのまま卒業に認められるかどうか」だった。単位が認められなければ、帰国後に卒業が遅れ、就職活動にも影響が出かねない。華やかな街での生活はさぞ魅力的だろうが、現実的な条件を軽く見ると、計画はたやすく崩れてしまう。憧れだけでなく、制度の仕組みを確かめてから行き先を決める。それが後悔しない留学の第一歩なのだ。": [0.0, 49.495], "もし来年留学するとしたら、どこにする？": [49.895, 3.665], "うーん、前はロンドンって思ってたけど、今はメルボルンかな。": [53.96, 4.91], "え、どうして？物価が安いから？": [59.27, 3.285], "ううん、物価はさほど変わらないの。うちの大学の協定校があって、単位をそのまま認めてもらえるからなんだ。": [62.955, 8.595], "なるほど、それは大きいね。": [71.95, 2.565], "もし宝くじが当たったとしたら、何に使う？": [74.915, 3.77], "その話が本当だとしたら、計画を見直す必要がある。": [79.085, 4.94], "仮に明日出発するとしたら、今日中に準備を終えないといけない。": [84.425, 5.06], "もし一か月休めるとしたら、ひとまず実家に帰って、のんびり過ごしたいです。最近忙しくて、ずっと帰れていないので。": [89.885, 9.935], "もし犯人が彼だとしたら、動機は何だろう。": [100.22, 3.785], "京都に行くなら、秋がいいですよ。": [104.405, 2.905], "たやすい": [107.71, 1.165], "もろい": [109.275, 0.995], "しぶとい": [110.67, 1.24], "ずさん": [112.31, 1.04], "まばら": [113.75, 1.07], "ひとまず": [115.22, 1.17], "おおむね": [116.79, 1.165], "さぞ": [118.355, 1.085]}, "d284": {"「残業を減らそう」とか言って、上司本人が毎晩遅くまで席を立たない。そんな職場では、部下はなかなか先に帰ろうとは言い出せないものだ。働き方の見直しが叫ばれて久しいが、制度を整えても現場の空気が変わらなければ、効果は心もとない。ある会社では、若手社員が各部署の退社時刻を記録したデータを経営会議に提出したことがきっかけで、管理職が率先して定時に帰るようになったという。感情的な不満をぶつけるのではなく、客観的な数字という手がかりを示したことが、上層部を動かしたのだ。若い世代の目覚ましい行動力は、組織にとって頼もしい存在と言えるだろう。": [0.0, 46.63], "部長、「残業は減らそう」とか言って、自分は毎日遅くまでいるよね。": [47.03, 6.28], "そうなんだよ。だから、こっちも先に帰りにくいんだよね。": [53.71, 4.95], "ねえ、今度の会議で、定時に会議室の電気を消すルールを提案してみない？": [59.06, 6.275], "いいね。でも、いきなり言っても通らないと思うな。まず、ほかの課の残業時間を調べてみようよ。": [65.735, 8.16], "そうだね。数字がないと、説得力がないもんね。": [74.295, 4.6], "弟は「明日から早起きする」とか言って、結局昼まで寝ていた。": [79.295, 6.12], "彼、忙しいとか言って、いつも飲み会には来るんだよね。": [85.815, 5.075], "来年こそ社長になるぞ、とか言っちゃって。": [91.29, 3.61], "兄は「貯金する」とか言って、毎月新しい服を買ってるんだよ。将来が心もとないな。": [95.3, 8.235], "「すぐ戻る」とか言って、もう二時間も帰ってこない。": [103.935, 4.54], "彼は「すぐ戻る」と言って出かけた。": [108.875, 3.685], "けだるい": [112.96, 1.13], "心もとない": [114.49, 1.58], "やましい": [116.47, 1.21], "紛らわしい": [118.08, 1.385], "目覚ましい": [119.865, 1.325], "頼もしい": [121.59, 1.295], "興ざめ": [123.285, 1.18], "手がかり": [124.865, 1.185]}, "d285": {"会社の研修や行事が急に取りやめになるのは珍しいことではない。講師の体調不良や悪天候など、事情はさまざまだ。問題は、その知らせがどう伝わるかである。正式な通知が出る前に「中止なんだって」という話だけが先に広まり、肝心の代わりの日程や申込期限が見落とされることがあるのだ。ある企業では、こうした混乱を防ぐため、行事を見合わせる場合は担当者が必ず全員にメールを送り、変更点を三行以内にまとめて示すことにした。うわさを取り次ぐだけの伝言では、手続きの締め切りまで正確に伝わるとは限らない。情報の出どころを確かめる手立てを持つことが大切だ。": [0.0, 46.36], "ねえ、明日の研修、中止なんだって。講師の先生が急に入院されたらしいよ。": [46.76, 7.21], "えっ、そうなの？じゃ、明日は普通に仕事か。": [54.37, 4.505], "うん。で、その代わりに来週オンラインでやるんだって。申し込みは今日の五時までだって。": [59.275, 6.875], "今日の五時？だって、そんな連絡、来てないよ。": [66.55, 4.72], "さっき人事部からメールが来てたよ。リンクもそこに載ってる。": [71.67, 4.735], "あ、ほんとだ。じゃ、忘れないうちに今すぐ申し込んじゃおう。": [76.805, 5.28], "田中さん、来月結婚するんだって。": [82.485, 3.345], "「どうして宿題やってないの？」「だって、難しかったんだもん。」": [86.23, 4.755], "こんな簡単なこと、子どもだってできるよ。": [91.385, 3.595], "今週の飲み会、取りやめになったんだって。お店に予約のキャンセルの電話をしとかなきゃ。": [95.38, 6.885], "あの店、来月閉店するんだって。": [102.665, 3.27], "天気予報によると、明日は雪が降るそうだ。": [106.335, 3.775], "手際": [110.51, 1.06], "手立て": [111.97, 1.08], "見合わせる": [113.45, 1.1], "取り次ぐ": [114.95, 1.175], "取りやめる": [116.525, 1.23], "立て替える": [118.155, 1.295], "持ち越す": [119.85, 1.26], "繰り越す": [121.51, 1.28]}, "d286": {"人気の店が突然閉店すると聞くと、多くの人はまず経営不振を思い浮かべる。だが、近年は売り上げが好調なまま店を閉める例も珍しくないという。理由は後継者の不在や建物の老朽化、そして店主自身の新たな挑戦などさまざまだ。ある洋菓子店の店主は「繁盛しているうちに休むなんてもったいない、と何度も言われた」と苦笑する。それでも、技術を磨き直したいという思いを打ち切ることはできなかったそうだ。常連客の反応はまちまちだったが、最後は多くの人が快く送り出してくれたという。店をたたむ理由は、外から見えるものと食い違っていることも多いのである。": [0.0, 45.445], "聞いた？駅前のあのパン屋さん、来月で閉店するんだって。": [45.845, 5.06], "うそ。あんなに人気があるのに、閉めちゃうなんて。": [51.305, 4.215], "売り上げは好調なんだけど、店長さんがフランスでもう一度修業したいんだって。": [55.92, 5.835], "へえ。繁盛してるのに、また一から修業なんて、すごい向上心だね。": [62.155, 6.53], "二年後には戻ってきて、また店を開くつもりらしいよ。": [69.085, 4.455], "こんなところで先生に会うなんて、びっくりした。": [73.94, 3.805], "約束を三回も破るなんて、ひどすぎる。": [78.145, 3.795], "私なんて、まだまだ勉強が足りません。": [82.34, 3.555], "新人の木村さんが自分から幹事を申し出るなんて、驚いたよ。すごくやる気があるんだね。": [86.295, 7.315], "彼が試験に落ちるなんて、信じられない。": [94.01, 3.55], "あの名選手が引退するとは、誰も予想しなかった。": [97.96, 4.37], "打ち切る": [102.73, 1.13], "食い違う": [104.26, 1.235], "見落とす": [105.895, 1.215], "思い詰める": [107.51, 1.355], "申し出る": [109.265, 1.22], "歩み寄る": [110.885, 1.24], "心がける": [112.525, 1.505], "割り込む": [114.43, 1.205]}, "d288": {"スマートフォンが一台あれば予定も記録も管理できる時代に、紙の手帳の売れ行きが堅調だという。ある文具メーカーの調査で、驚いたことには、二十代の利用率が四十代を上回っていた。理由を尋ねると、「手で書くと頭が整理される」「画面の通知に割り込まれず、自分の考えに集中できる」といった声が目立った。デジタルの便利さを否定するわけではない。ただ、何でも効率を優先するあまり、考える時間そのものをおろそかにしてはいないか。紙の上でペンを走らせる数分間は、忙しい若者にとって、自分と向き合うささやかな休息なのかもしれない。道具へのこだわりは、生き方へのこだわりでもあるのだ。": [0.0, 47.8], "今回の調査で、一番意外だったことは何ですか。": [48.2, 4.435], "そうですね。驚いたことには、若い人ほど紙の手帳を使っていたんです。": [53.035, 6.285], "へえ、スマートフォンではなく、ですか。": [59.72, 3.575], "ええ。値段が安いからとか、デザインがかわいいからという答えもありましたが、一番多かったのは、書くと頭が整理されるから、という理由でした。": [63.695, 11.475], "なるほど。考えるための道具なんですね。": [75.57, 3.575], "驚いたことには、彼はたった一か月で日本語を話せるようになった。": [79.545, 5.57], "残念なことに、その店は先月閉店してしまった。": [85.515, 4.555], "うれしいことには、応募者が予想の二倍も集まった。": [90.47, 4.33], "驚いたことには、新人の彼が一人で三つのプロジェクトをこなしていたんです。しかも、どれも期限前に終わらせていました。": [95.2, 9.505], "ありがたいことに、近所の人が手伝ってくれた。": [105.105, 3.99], "読んだことは読んだが、内容はよく覚えていない。": [109.495, 3.91], "煮詰まる": [113.805, 1.16], "張り合う": [115.365, 1.095], "ためらう": [116.86, 1.115], "こだわる": [118.375, 1.135], "くつろぐ": [119.91, 1.135], "しのぐ": [121.445, 1.11], "こなす": [122.955, 1.135], "さえぎる": [124.49, 1.18]}, "d289": {"天候が売り上げにもたらす影響は、想像以上に大きい。あるスーパーでは、気温が三十度を超えた日に、温かい総菜の売り上げが平均の六割まで落ち込んだ。一方で、冷たい麺類や酢の物は倍近く売れたという。店長は「暑さのせいか、お客様が手に取る商品ががらりと変わる」と話す。もちろん、売り上げが減った原因を天気だけに求めるのは危うい。値上げや近隣の競合店など、ほかの要因がそれとなく影響していることもあるからだ。そこで同店では、値段を据え置いた商品の動きも比べ、原因を一つずつ確かめている。数字の背後にある客の気持ちを読み取る努力が、商売を支えているのだ。": [0.0, 48.015], "店長、先月はお弁当の売り上げがずいぶん落ちましたね。": [48.415, 4.765], "うん。暑さのせいか、温かいおかずの弁当が売れなくなったみたいなんだ。": [53.58, 5.765], "値上げの影響じゃないんですか。先月から三十円上げましたよね。": [59.745, 5.06], "いや、値上げしていない弁当も同じくらい落ちてるからね。それは関係ないと思うよ。": [65.205, 6.465], "なるほど。じゃ、夏の間は冷たい麺類を増やしてみましょうか。": [72.07, 5.395], "寝不足のせいか、今日は頭がぼんやりしている。": [77.865, 3.82], "年のせいか、最近疲れが取れにくくなった。": [82.085, 3.88], "気温が高かったせいか、今年は桜が早く咲いた。": [86.365, 4.49], "運動を始めたせいか、最近よく眠れるようになりました。小さな習慣が大きな変化をもたらすんですね。": [91.255, 8.375], "風邪のせいか、食欲がない。": [100.03, 2.82], "君が遅れたせいで、電車に乗り遅れたじゃないか。": [103.25, 4.08], "つかさどる": [107.73, 1.325], "そそる": [109.455, 1.165], "とがめる": [111.02, 1.135], "はばむ": [112.555, 1.065], "ほのめかす": [114.02, 1.445], "まかなう": [115.865, 1.18], "むせる": [117.445, 1.065], "もたらす": [118.91, 1.22]}, "d290": {"家電量販店で売り場を歩いていると、「軽いわりに画面が大きい」「値段のわりに性能がいい」といった宣伝文句があふれている。だが、こうした言葉を鵜呑みにすると、自分の使い方に合わない製品を選んでしまいかねない。長所の裏には、たいてい何らかの短所が隠れているからだ。例えば、軽さを優先したパソコンは電池の容量が小さいことが多く、外出先で長時間使う人には向かない。ある販売員は「まずお客様の使い方を伺うよう心がけている」と話す。売り手の言葉にあざむかれないためには、自分にとって何が一番大切かをわきまえておくことが欠かせないのである。": [0.0, 44.665], "このノートパソコン、軽いわりに画面が大きいですね。": [45.065, 4.265], "はい。ただ、電池の持ちが少し短めなんです。四時間ほどでしょうか。": [49.73, 6.39], "うーん、外で一日中使うことが多いんですよ。": [56.52, 4.115], "でしたら、こちらはいかがでしょう。少し重いですが、電池は十二時間持ちます。": [61.035, 6.665], "じゃ、そっちにします。あと、持ち運び用のケースも一緒に見せてもらえますか。": [68.1, 6.72], "このレストランは、値段のわりにおいしい。": [75.22, 3.345], "彼はよく勉強しているわりには、成績が上がらない。": [78.965, 4.395], "祖父は年のわりに若く見える。": [83.76, 2.6], "先輩がおごってくれた店、駅から遠いわりにお客さんがいっぱいでした。料理が本当においしかったです。": [86.76, 7.94], "この服は、値段のわりに生地がしっかりしている。": [95.1, 3.86], "初めてにしては、上手に焼けたね。": [99.36, 3.15], "わきまえる": [102.91, 1.265], "あざむく": [104.575, 1.22], "いたわる": [106.195, 1.09], "うつむく": [107.685, 1.2], "おごる": [109.285, 1.005], "かばう": [110.69, 1.04], "くじける": [112.13, 1.18], "こじれる": [113.71, 1.155]}, "d291": {"新人が「わかりました」と即答するたびに、かえって不安になる。そんな悩みを抱える先輩社員は多い。理解していないくせに返事だけはいい、と陰で言われる新人も、実は戸惑っているのだ。ある研修会社の調査では、新入社員の六割以上が「質問すると仕事ができないと思われそうで、ためらう」と答えている。職場になじむまでの間、彼らは自分の無知を悟られまいと粘ってしまう。そこで同社が勧めるのは、疑問をその場で書き留め、決まった時間にまとめて聞く仕組みだ。質問を個人の勇気に頼るのではなく、ルールにしてしまえば、尋ねる側も答える側も気が楽になる。": [0.0, 46.91], "新人の木村くん、よくわかってないくせに、何でも「わかりました」って言うんだよね。": [47.31, 7.265], "ああ、それで昨日の発注、数を間違えたんだ。": [54.975, 4.515], "そう。でも、強く言うと萎縮しちゃいそうで、どう言えばいいかな。": [59.89, 5.525], "わからないことはその場でメモしておいて、夕方にまとめて聞いてもらうようにしたら？": [65.815, 6.03], "なるほど。それなら本人も聞きやすいかもね。": [72.245, 3.78], "弟は自分では何もしないくせに、文句ばかり言う。": [76.425, 4.345], "彼は知っているくせに、何も教えてくれなかった。": [81.17, 4.04], "子どものくせに、生意気なことを言うんじゃない。": [85.61, 3.59], "兄は料理ができないくせに、母の味付けにいつも文句を言うんです。母も戸惑っているので、今度一緒に作らせてみようと思います。": [89.6, 10.095], "お金がないくせに、また高い服を買ってきた。": [100.095, 3.91], "一生懸命練習したのに、試合に負けてしまった。": [104.405, 4.31], "悟る": [109.115, 1.13], "廃れる": [110.645, 1.16], "そびえる": [112.205, 1.2], "たじろぐ": [113.805, 1.14], "募る": [115.345, 1.045], "戸惑う": [116.79, 1.125], "なじむ": [118.315, 1.055], "粘る": [119.77, 1.02]}, "d292": {"「子どもっぽい」「忘れっぽい」のように性質や傾向を表す「っぽい」は、若者の間で用法がさらに広がっている。「今日、課長休みっぽいよ」「この店、もう閉まってるっぽい」といった具合に、はっきりしない状況を推量する言い方として定着しつつあるのだ。断定を避けて柔らかく伝えられる便利さがある一方で、根拠がぼやけたまま情報が広まり、職場でもめる原因になることもある。ある会社員は「『っぽい』と聞いたら、必ず予定表で確かめる」という。曖昧な言葉をそのまま事実とみなさないこと。それが、言葉の変化とうまく付き合うための知恵なのかもしれない。": [0.0, 46.605], "課長、まだ来てない？この書類、今日中にはんこをもらわないといけないんだけど。": [47.005, 6.675], "今日は休みっぽいよ。予定表が一日空いてたから。": [54.08, 4.37], "困ったな。経理に五時までに出さないといけないんだ。": [58.85, 4.1], "だったら、副課長に代わりに押してもらえるか聞いてみたら？急ぎのときはそれでいいって、前に課長が言ってたよ。": [63.35, 8.725], "そうなんだ。じゃ、すぐ聞いてくるよ。": [72.475, 3.47], "彼は年齢のわりに、話し方が子どもっぽい。": [76.345, 3.9], "最近、忘れっぽくなって困っている。": [80.645, 3.39], "あの店、今日は閉まってるっぽいね。電気が消えてる。": [84.435, 4.57], "駅前の道、今日は工事で混んでるっぽいよ。よけて裏の道から行ったほうがいいかも。": [89.405, 6.77], "このスーツは、ちょっと安っぽく見える。": [96.575, 3.33], "今日の彼女は、彼女らしい明るい笑顔だった。": [100.305, 3.85], "ばらす": [104.555, 1.085], "ぼやける": [106.04, 1.175], "みなす": [107.615, 1.115], "もめる": [109.13, 1.025], "ゆがむ": [110.555, 1.065], "よける": [112.02, 1.095], "有数": [113.515, 1.155], "屈指": [115.07, 1.045]}, "d293": {"「その件はお受けいたしかねます」。ホテルや役所の窓口で耳にするこの言葉は、相手を正面から拒むのではなく、事情があってできないのだという含みを持たせた、日本語らしい断り方である。ある老舗ホテルの支配人は、断る場面ほど言葉を吟味する必要があると話す。単に「できません」と言えば角が立つが、「かねます」と言ったうえで代わりの提案を添えれば、客の不満はかなり相殺されるという。満室のためにチェックアウトの延長には応じられなくても、荷物を預かることはできる。客の要望を熟知し、できることを示す姿勢が、断りの言葉を思いやりに変えるのだ。": [0.0, 44.765], "すみません、チェックアウトを午後三時まで延ばしていただけませんか。": [45.165, 5.075], "申し訳ございません。本日は満室でございまして、次のお客様のお部屋の準備がございますので、三時まではお受けいたしかねます。": [50.64, 10.365], "そうですか…。じゃあ、荷物だけ預かってもらえますか。": [61.405, 4.51], "はい、それでしたら承ります。フロントでお預かりいたします。": [66.315, 5.41], "よかった。じゃ、部屋から荷物を持ってきます。": [72.125, 4.01], "申し訳ありませんが、そのご質問にはお答えいたしかねます。": [76.535, 4.865], "担当者が不在のため、詳しいことはわかりかねます。": [81.8, 4.44], "その意見には、残念ながら賛成しかねる。": [86.64, 3.75], "申し訳ございませんが、明日までの納品はお約束いたしかねます。品質の面で懸念がございますので、金曜日でいかがでしょうか。": [90.79, 10.25], "当店では、返品はお受けしかねます。": [101.44, 3.28], "そんな運転をしていたら、事故を起こしかねない。": [105.12, 3.7], "匹敵": [109.22, 1.21], "回顧": [110.83, 1.145], "懸念": [112.375, 0.98], "誇張": [113.755, 1.155], "皮肉": [115.31, 1.09], "吟味": [116.8, 0.985], "熟知": [118.185, 1.08], "相殺": [119.665, 1.225]}, "d295": {"職場で同僚に何かを頼むとき、どんな言い方を選ぶかで相手の受け取り方は大きく変わる。「コピーして」と言い切るより、「コピーしてもらえる？」と尋ねる形にしたほうが、相手に断る余地を残すぶん柔らかく響く。さらに丁寧にしたいなら「〜てもらえないかな」と否定の形にするとよい。ただし、言い方が丁寧でも、頼む内容があいまいでは意味がない。ある業務改善の専門家は、依頼の際には「何を、いつまでに、どの順番で」を必ず添えるよう勧めている。複数の作業を頼むときに順番を示さないと、相手が着手する順序を誤り、結局やり直しになってしまうことが多いからだ。": [0.0, 47.49], "ごめん、今ちょっと手が離せなくて。この資料、二十部コピーしてもらえる？": [47.89, 6.305], "いいよ。両面でいい？": [54.595, 2.085], "うん。あ、その前に、三ページ目の表、数字が古いままなんだ。最新のに差し替えてからにしてもらえないかな。": [57.08, 9.49], "わかった。最新の数字って、共有フォルダに入ってるやつ？": [66.97, 5.075], "そう、それ。助かる。ホチキス止めは私があとでやるから。": [72.445, 5.895], "悪いけど、この荷物、ちょっと持ってもらえる？": [78.74, 4.11], "すみません、もう少しゆっくり話してもらえますか。": [83.25, 4.1], "明日の会議、私の代わりに出てもらえないかな。": [87.75, 4.17], "悪いけど、先に見積もりを確認してもらえる？それが済んだら、新しい企画書に着手してもらえないかな。": [92.32, 8.665], "ちょっと窓を開けてもらえる？": [101.385, 2.075], "ちょっと窓を開けてくれる？": [103.86, 1.99], "一環": [106.25, 1.05], "発足": [107.7, 1.18], "頓挫": [109.28, 1.07], "着手": [110.75, 1.175], "披露": [112.325, 1.06], "譲歩": [113.785, 1.1], "蓄積": [115.285, 1.29], "撤回": [116.975, 1.125]}, "d296": {"「また傘、電車に忘れてきちゃった」。駅の忘れ物の中で、圧倒的に多いのが傘だという。ある鉄道会社では、雨の日には一日に数百本もの傘が届けられるが、持ち主が引き取りに来るのは二割程度にとどまる。安い傘なら、わざわざ取りに行くより新しく買ったほうが早い、と考える人が多いのだろう。だが、思い入れのある品であれば、まず降りた駅の窓口に申し出るのが鉄則だ。電車が終点に着いてしまう前に連絡が取れれば、車内で見つかる可能性が高いからである。忘れ物の扱いはここ数年で一変し、今ではインターネットで問い合わせができる会社も増えている。": [0.0, 45.32], "どうしよう、さっきの電車に傘、忘れてきちゃった。": [45.72, 4.665], "え、あの高いやつ？忘れ物センターに電話してみたら？": [50.785, 4.865], "でも、番号がわからないし…。": [56.05, 2.605], "だったら、駅の窓口で聞くのが一番早いよ。電車が終点まで行っちゃう前なら、途中の駅で探してもらえるかもしれないし。": [59.055, 9.625], "そっか。じゃ、すぐ窓口に行ってくる。": [69.08, 3.765], "おいしかったから、ケーキを全部食べちゃった。": [73.245, 3.535], "昨日は疲れて、ソファで寝ちゃったんだ。": [77.18, 3.36], "面白くて、一晩で全部読んじゃった。": [80.94, 3.43], "昨日の打ち合わせ、うっかり忘れちゃったんです。今日、先方に釈明のメールを送らないと。": [84.77, 7.555], "お皿、割っちゃった。ごめんね。": [92.725, 2.975], "ここでたばこを吸っちゃだめだよ。": [96.1, 2.44], "保留": [98.94, 1.02], "是正": [100.36, 1.15], "刷新": [101.91, 1.125], "釈明": [103.435, 1.34], "脱帽": [105.175, 1.2], "怠慢": [106.775, 1.04], "傍観": [108.215, 1.09], "一変": [109.705, 1.05]}, "d297": {"ゼミや会議の資料を事前に配るかどうかで、議論の質は大きく変わる。当日その場で初めて資料を目にした参加者は、内容を追うのに精一杯で、意見を述べる余裕がない。一方、前もって読んでおいた人は、疑問点を整理したうえで議論に臨めるため、話し合いが盛況になりやすい。ある大学教員は、学生に「発表資料は前日までに全員に送っといて」と必ず伝えるという。資料の該当箇所に目を通しておくだけでも、発言の数は目に見えて増えるそうだ。準備の手間を惜しまない姿勢が、議論の成果に大きく寄与するのである。こうした取り組みは学生の間でも好評だという。": [0.0, 45.58], "明日のゼミの発表、資料はもうできてる？": [45.98, 3.77], "はい、ほぼできました。あとは図を一つ入れるだけです。": [50.15, 4.645], "図はなくてもいいから、今日中にみんなに送っといて。事前に読んどいてもらいたいからね。": [55.195, 6.48], "わかりました。参考文献のリストもつけておいたほうがいいですか。": [62.075, 5.24], "それは明日、紙で配ればいいよ。まずは資料ね。": [67.715, 4.505], "会議室は私が予約しとくね。": [72.62, 2.875], "寒いから、窓は閉めといて。": [75.895, 2.755], "明日までにこの本、読んどいてね。": [79.05, 2.99], "今夜のうちに切符を買っとくね。それから、ガイドブックの該当ページも読んどくよ。": [82.44, 6.72], "パーティーの前に、飲み物を冷やしとくね。": [89.56, 3.355], "冷蔵庫に飲み物が冷やしてあるよ。": [93.315, 2.775], "好評": [96.49, 1.205], "盛況": [98.095, 1.305], "寄与": [99.8, 0.995], "該当": [101.195, 1.18], "不振": [102.775, 0.98], "未練": [104.155, 0.94], "気配": [105.495, 1.09], "しっくり": [106.985, 1.235]}, "d298": {"上司からプレゼンの資料に厳しい指摘を受けると、誰しも落ち込むものだ。しかし、本番が迫っているなら、くよくよしている場合ではない。ある研修講師は、指摘を受けたらまず「何を言われたか」を三つ以内に書き出すよう勧める。感情に流されて全部をやり直そうとすると、時間ばかりかかって肝心の点がおろそかになりがちだからだ。多くの場合、指摘の核心は構成や結論の位置といった骨組みにあり、色やデザインはかすかな印象の差にすぎない。優先順位を見極めて骨組みから直す。この手順を身につけた人は、シビアな場面でも冷静に対応できるという。": [0.0, 44.39], "はあ、プレゼンの資料、また部長にだめ出しされちゃった。": [44.79, 4.725], "落ち込んでる場合じゃないよ。本番は明後日でしょ。": [49.915, 3.89], "そうなんだけど、どこから直せばいいか…。色使いも地味だって言われたし。": [54.205, 5.8], "部長、結論が最後にあるからわかりにくいって言ってたよね。まずは構成を入れ替えたら？色は最後でいいよ。": [60.405, 8.52], "確かに。じゃ、まず結論を最初のページに持ってくるよ。": [69.325, 4.875], "笑ってる場合じゃないよ。早く片付けないと。": [74.6, 3.745], "試験は来週なのに、ゲームをしている場合ではない。": [78.745, 4.08], "迷ってる場合じゃない。今すぐ申し込もう。": [83.225, 3.615], "悩んでる場合じゃないよ。締め切りは明日なんだから、細かい部分をおろそかにしないように、まず全体を見直そう。": [87.24, 8.655], "寝てる場合じゃない。もう出発の時間だよ。": [96.295, 3.72], "仕事が忙しくて、旅行どころじゃない。": [100.415, 3.555], "うやむや": [104.37, 1.185], "おろそか": [105.955, 1.29], "かすか": [107.645, 1.035], "ひそか": [109.08, 1.17], "ルーズ": [110.65, 1.02], "シビア": [112.07, 1.155], "デマ": [113.625, 0.96], "ノウハウ": [114.985, 1.125]}, "d299": {"家業を持つ家庭では、帰省が「休み」にならないことも少なくない。実家の店の繁忙期や改装工事が重なると、旅行どころではなく、家族総出で手伝うことになるからだ。ある調査では、自営業の家庭で育った二十代の約四割が「長期休暇を実家の手伝いに充てたことがある」と答えた。最近は家業を継がない若者が増えるなか、こうした手伝いを通じて店の経営やお客との接し方といったノウハウを学び、後に自分の起業に生かす例もあるという。ニーズの変化をつかむ力や、ノルマのない仕事を自分で回す経験は、会社勤めだけではなかなか得られないものなのかもしれない。": [0.0, 45.805], "来月の温泉旅行、行けそう？": [46.205, 3.025], "それがさ、旅行どころじゃないんだ。実家の店を手伝うことになって。": [49.63, 5.64], "え、お父さん、具合でも悪いの？": [55.67, 3.21], "いや、父は元気なんだけど、店の改装工事が長引いちゃって、再開の準備が間に合わないんだって。": [59.28, 8.33], "そっか。じゃ、旅行はまた今度にしよう。": [68.01, 3.885], "試験の前日で、テレビを見るどころじゃない。": [72.295, 3.715], "引っ越しの準備で忙しくて、花見どころじゃなかった。": [76.41, 4.44], "熱が高くて、仕事どころではありません。": [81.25, 3.71], "今月はノルマが厳しくて、趣味のテニスどころじゃないんです。週末も営業の準備をしています。": [85.36, 7.605], "頭が痛くて、勉強どころじゃない。": [93.365, 3.255], "彼は謝るどころか、逆に怒り出した。": [97.02, 3.555], "ニーズ": [100.975, 1.02], "ノルマ": [102.395, 1.07], "メカニズム": [103.865, 1.335], "ブランク": [105.6, 1.14], "コンスタント": [107.14, 1.38], "プライオリティ": [108.92, 1.27], "タイムリー": [110.59, 1.19], "クレーム": [112.18, 1.12]}, "d302": {"新しく駅前に開店した書店の話題で、地域の掲示板はこのところ持ちきりだ。開店初日、シャッターが上がるや否や、待ち構えていた客が一斉に店内へ流れ込んだという。店長によれば、ある年配の男性は入店するなり、迷わず郷土史の棚へ向かい、十冊近くを抱えてレジに並んだそうだ。ネット書店の普及に押され、町の本屋が次々と姿を消すなか、この店は地元の出版社と提携し、品揃えで独自性を打ち出した。こうした取り組みが業界の閉塞感の打開につながるのか、同業者も注目している。": [0.0, 41.155], "今日は、子どもの「食べ物の好き嫌い」についてお話しします。": [41.555, 5.575], "うちの息子なんて、昨日も食卓のピーマンを見るなり、顔をしかめて席を立ってしまいました。": [47.53, 7.2], "でも、自分で育てた野菜は別なんですね。ベランダでトマトを収穫するや否や、その場でかじっていました。": [55.13, 8.63], "無理に食べさせるより、育てる過程に関わらせるほうが、ずっと効果があるようです。": [64.16, 6.58], "父は帰宅するなり、ソファに倒れ込んで眠ってしまった。": [71.14, 4.59], "彼女は電話を切るなり、わっと泣き出した。": [76.13, 3.445], "部長は会議室に入ってくるなり、資料を机にたたきつけた。": [79.975, 5.08], "弟は合格通知を受け取るなり、部屋を飛び出していった。母は私の顔を見るなり、何かあったのかと尋ねた。": [85.455, 9.0], "彼は私の顔を見るなり、黙って部屋を出ていった。": [94.855, 4.255], "試合終了の笛が鳴るや否や、観客がグラウンドになだれ込んだ。": [99.51, 5.125], "打開": [105.035, 1.06], "発足": [106.495, 1.18], "拍車": [108.075, 1.2], "措置": [109.675, 1.055], "踏襲": [111.13, 1.125], "一環": [112.655, 1.05], "合致": [114.105, 1.035], "是正": [115.54, 1.15]}, "d303": {"三連休の最終日とあって、空港の到着ロビーは土産袋を提げた家族連れでごった返していた。今年は航空各社が運賃の値下げに踏み切ったこともあり、利用者は前年を大きく上回ったという。中でも人気を集めたのは、地方空港と結ぶ新路線だ。地元の観光協会の担当者は「長年かけて根回しを重ねてきただけあって、手応えを感じている」と話す。一方で、急増した旅行者への対応が追いつかず、手荷物の受け取りに一時間近く待たされた人もいた。路線の拡大と受け入れ態勢の整備をどう両立させるかが、今後の課題となりそうだ。": [0.0, 43.82], "さすが、プロの料理人だけあって、包丁さばきが違うね。": [44.22, 5.22], "ええ、十年も修業したんですって。": [49.84, 3.065], "今日は駅前、すごい人だね。": [53.305, 2.9], "人気グループのライブがあるとあって、朝から行列ができてるみたい。": [56.605, 5.195], "人気作家のサイン会とあって、書店の前には長い列ができた。": [62.2, 5.16], "久しぶりの晴天とあって、公園は家族連れでにぎわっている。": [67.76, 4.89], "年に一度の祭りとあって、町じゅうが活気に満ちていた。": [73.05, 4.57], "初雪の週末とあって、スキー場は若者でにぎわった。ベテランの講師だけあって、教え方がとても分かりやすかった。": [78.02, 9.325], "初の海外公演とあって、メンバーは緊張した面持ちだった。": [87.745, 5.07], "元選手だけあって、彼のフォームは今でも美しい。": [93.215, 4.36], "頓挫": [97.975, 1.07], "抜粋": [99.445, 1.065], "網羅": [100.91, 1.04], "配属": [102.35, 1.21], "名残": [103.96, 1.015], "兆し": [105.375, 1.14], "根回し": [106.915, 1.22], "手分け": [108.535, 1.125]}, "d304": {"深刻な不況にあって、多くの企業が人員削減に踏み切るなか、ある老舗の部品メーカーは雇用の存続を最優先に掲げた。社長は「苦しい時期にあってこそ、社員の技術が会社の財産になる」と語り、役員報酬を削って給与の財源を捻出したという。もっとも、決して楽な道ではなかった。主力製品の受注は激減し、閑静な住宅街の一角にある工場には、機械の音がまばらに響くだけの日もあった。それでも社員の間では、その恩を事業で還元しようという機運が高まった。のちに同社の若手が開発した斬新な小型部品は、医療機器の分野において高い評価を得ることになる。": [0.0, 47.665], "来月の説明会の会場だけど、本社の大会議室と駅前のホールの二つが候補なんだ。": [48.065, 7.38], "参加者が百人を超えるなら、ホールのほうが円滑に進められると思います。": [55.845, 5.87], "でも、この厳しい予算状況にあっては、無料で使える本社がいいんじゃないでしょうか。": [62.115, 6.715], "申し込みは、今のところ六十人ほどですね。": [69.23, 3.89], "それなら、説明会は本社において開催することにしよう。": [73.52, 4.965], "情報があふれる現代にあって、正しい情報を見極める力が求められている。": [78.885, 6.095], "彼は病床にあっても、最後まで研究のことを気にかけていた。": [85.38, 5.14], "指導者という立場にあって、そのような発言は軽率と言わざるを得ない。": [90.92, 5.555], "物資の乏しい戦後にあっても、祖母は笑顔を絶やさなかった。説明会は三階の会議室において行います。": [96.875, 8.56], "戦時下にあって、人々は互いに助け合って暮らした。": [105.835, 4.52], "入学式は本校の体育館において行われます。": [110.755, 3.92], "進呈": [115.075, 1.29], "還元": [116.765, 1.085], "存続": [118.25, 1.29], "誇張": [119.94, 1.155], "歴然": [121.495, 1.13], "斬新": [123.025, 1.075], "閑静": [124.5, 1.19], "円滑": [126.09, 1.18]}, "d305": {"十二月ともなると、商店街の空気は一変する。普段は閑散としている通りにも歳末の買い物客が押し寄せ、各店は人手の確保に追われる。ある老舗の和菓子店では、正月用の注文が例年の倍近くに達し、店主は伝票の処理だけでも煩雑を極めると苦笑する。注文の内訳を見ると、近年は遠方の客からの通信販売が増えているという。一方で、配送料の値上がりが利益を圧迫しているのも事実だ。もし来年さらに値上げとなると、送料の一部を客に負担してもらうことも検討せざるを得ない、と店主は話す。": [0.0, 42.01], "皆さん、社会人も三年目ともなると、仕事の進め方が自分なりに固まってきますよね。": [42.41, 7.64], "それ自体は悪いことではありません。ただ、やり方が固まると、新しい方法を試す機会が減ってしまうんです。": [50.45, 8.95], "そこで私が勧めているのが、月に一度、あえて普段と違う手順で仕事をしてみることです。": [59.8, 7.645], "効率は一時的に落ちるかもしれませんが、思わぬ発見があるものですよ。": [67.845, 5.835], "大臣ともなると、発言の一つ一つが注目される。": [74.08, 4.55], "夜十時ともなると、この辺りは人通りがほとんどなくなる。": [79.03, 4.815], "子どもも中学生ともなれば、親の言うことを素直には聞かない。": [84.245, 4.99], "課長ともなると、自分の仕事だけでなく部下の育成も任される。年末ともなれば、どの店も夜遅くまで営業している。": [89.635, 9.73], "横綱ともなると、負けが許されない重圧がある。": [99.765, 4.245], "会議が延期となると、資料を作り直さなければならない。": [104.41, 4.51], "煩雑": [109.32, 1.215], "克明": [110.935, 1.265], "頑丈": [112.6, 1.175], "一律": [114.175, 1.17], "内訳": [115.745, 1.25], "発散": [117.395, 1.06], "補填": [118.855, 1.015], "復旧": [120.27, 1.16]}, "d306": {"路線バスの廃止が相次ぐ山間部では、病院への通院はおろか、日用品の買い物さえままならない高齢者が少なくない。ある村では、住民が手分けして車を出し合う仕組みを作ったが、担い手の高齢化で長続きしなかった。そこで村は、予約制の乗り合いタクシーを導入した。運行経費の不足分は村の財源で賄っている。ところが、利用者は当初の見込みを下回った。電話での予約が面倒だという声が多く、便利になるどころか、かえって外出を控える人もいたという。村は現在、集会所に端末を置き、職員が予約を代行する方法を試している。": [0.0, 43.985], "新しく来た部長、パソコンはおろか、携帯電話もほとんど使わないらしいよ。": [44.385, 6.41], "えっ、じゃあ、資料はどうやってお渡しすればいいのかな。": [51.195, 4.62], "この薬を飲んでから、少しは楽になった?": [56.215, 3.9], "楽になるどころか、かえって頭痛がひどくなったよ。": [60.515, 4.095], "彼は海外旅行はおろか、国内の飛行機にも乗ったことがない。": [65.01, 5.115], "事故の後、走ることはおろか、歩くことさえできなかった。": [70.525, 5.115], "入社したばかりの頃は、敬語はおろか、電話の取り方すら分からなかった。": [76.04, 6.04], "来日したばかりの頃は、会話はおろか、あいさつもろくにできなかった。節約のつもりが、お金がたまるどころか、かえって出費が増えた。": [82.48, 11.215], "漢字はおろか、ひらがなもまだ書けない。": [94.095, 3.395], "雨は止むどころか、ますます激しくなった。": [97.89, 3.63], "損なう": [101.92, 1.28], "賄う": [103.6, 1.18], "携わる": [105.18, 1.28], "培う": [106.86, 1.255], "紛れる": [108.515, 1.125], "滞る": [110.04, 1.255], "免れる": [111.695, 1.285], "諮る": [113.38, 1.11]}, "d307": {"市立図書館の分館は、今月末日をもって閉館することになった。建物の老朽化に加え、耐震診断によって大規模な改修が必要だと判明したためだ。市は利用者に対し、書面をもって閉館の経緯を説明するとともに、貸出中の資料は本館で返却できるよう手配した。地域の読書会からは存続を求める声も上がったが、改修費用が数億円に上ることから、市は建て替えを見合わせ、移動図書館車の運行で対応する方針を固めた。長年通い続けてきた住民の一人は「寂しいが、子どもの頃の思い出は消えない」と名残を惜しんでいた。": [0.0, 44.13], "来週の工場見学ツアーだけど、参加の申し込みはメールと電話、どちらで受け付けようか。": [44.53, 7.31], "記録が残りますから、申し込みはメールをもって受け付けるのがいいと思います。": [52.24, 5.62], "ただ、年配のお客様も多いですから、電話もあったほうが親切じゃないでしょうか。": [58.26, 6.54], "確かに。じゃあ両方で受け付けて、締め切りは金曜日の正午をもって、ということにしよう。": [65.2, 7.47], "本日の営業は午後八時をもって終了いたします。": [73.07, 3.96], "合否の結果は、後日書面をもってお知らせします。": [77.43, 4.13], "彼女は持ち前の粘り強さをもって、難しい交渉をまとめ上げた。": [81.96, 5.465], "当サークルは、三月末日をもって活動を終了いたします。詳しい経緯は、メールをもってご報告いたします。長い間ありがとうございました。": [87.825, 11.7], "これをもちまして、本日の式典を終了いたします。": [99.925, 4.355], "台風によって、多くの便が欠航した。": [104.68, 3.5], "見合わせる": [108.58, 1.1], "取り止める": [110.08, 1.23], "仕切る": [111.71, 1.1], "見計らう": [113.21, 1.325], "打ち明ける": [114.935, 1.26], "立て替える": [116.595, 1.295], "突き止める": [118.29, 1.31], "持て余す": [120.0, 1.325]}, "d309": {"公開中のドキュメンタリー映画が、静かな反響を呼んでいる。戦後間もない頃、焼け野原に小さな診療所を開いた一人の医師の生涯を、残された日記と家族の証言から丹念に描いた作品だ。華やかな演出はなく、映像はむしろ淡々としている。それでも、物資の乏しい中で患者に向き合い続けた医師の姿は、観る者の心を揺さぶらずにはおかない。上映後、しばらく席を立てずにいる観客も多いという。監督は「彼の足跡の手掛かりを求めて各地を訪ね歩くうちに、記録に残さずにはいられなくなった」と語る。興行の先行きを危ぶむ声もあったが、口コミで上映館は着実に増えている。": [0.0, 48.205], "今日ご紹介するのは、ある小さな町の合唱団を追った映画です。": [48.605, 5.25], "メンバーの多くは楽譜も読めない素人で、最初は声もそろいません。": [54.255, 5.445], "それが、練習を重ねるうちに、少しずつ一つの声になっていく。その過程は、観る人を励まさずにはおかないでしょう。": [60.1, 9.935], "私自身、最後の場面では、涙を流さずにはいられませんでした。": [70.435, 5.86], "彼の誠実な人柄は、周囲の人を引きつけずにはおかない。": [76.695, 4.98], "この不正は、いずれ世間の批判を招かずにはおかないだろう。": [82.075, 4.79], "今度こそ、事件の真相を明らかにせずにはおかない。": [87.265, 4.465], "その小説の結末は、読者に家族の意味を考えさせずにはおかない。私も読み終えた後、母に電話せずにはいられなかった。": [92.13, 10.355], "彼女の歌声は、聴く者の心を打たずにはおかない。": [102.885, 4.335], "あまりにおかしくて、笑わずにはいられなかった。": [107.62, 3.74], "心当たり": [111.76, 1.42], "腕前": [113.58, 1.085], "手際": [115.065, 1.06], "手掛かり": [116.525, 1.185], "目途": [118.11, 0.96], "枠組み": [119.47, 1.195], "見通し": [121.065, 1.195], "先行き": [122.66, 1.33]}, "d310": {"過疎化の進む島に、都市部から移住してきた若者たちがいる。彼らは島の伝統的な塩づくりを次の世代に引き継ぐべく、使われなくなった作業小屋を借りて小さな製塩所を立ち上げた。作業は決して楽ではない。海水を煮詰める工程は丸一日かかり、火加減の細やかな調整が欠かせない。それでも、島の高齢者から製法を学ぶうちに、和やかな交流が生まれたという。販路を広げるために、彼らはインターネット販売にも速やかに乗り出した。ささやかな事業だが、島の名を全国に知らしめる一助となりつつある。": [0.0, 40.945], "新しいプロジェクト、期限に間に合わせるべく、全員で休日出勤することになったよ。": [41.345, 6.875], "えっ、また?先月もそうだったじゃない。": [48.62, 3.74], "来週の会議の資料って、何のために作るんでしたっけ。": [52.76, 4.59], "取引先に新しい料金体系を説明するためですよ。": [57.75, 4.82], "彼は医師になるべく、毎晩遅くまで勉強を続けた。": [62.97, 4.51], "会社は経営を立て直すべく、不採算部門の売却を決めた。": [67.88, 5.11], "被災地の現状を伝えるべく、記者たちは現地へ向かった。": [73.39, 4.805], "N1に合格すべく、毎朝一時間早く起きて聴解の練習をしている。試験に受かるために、毎朝早起きしてるんだ。": [78.595, 9.675], "事故の原因を究明すべく、調査委員会が設置された。": [88.67, 4.685], "大雪のために、電車が大幅に遅れた。": [93.755, 3.56], "おおらか": [97.715, 1.09], "しなやか": [99.205, 1.345], "ささやか": [100.95, 1.29], "速やか": [102.64, 1.345], "健やか": [104.385, 1.33], "緩やか": [106.115, 1.265], "細やか": [107.78, 1.295], "和やか": [109.475, 1.265]}, "d311": {"健康のために十分な睡眠が欠かせないことは、言うまでもない。だが、その「十分」がどれくらいかとなると、答えは人によって異なる。ある調査では、成人の多くが自分に必要な睡眠時間を把握していないことが分かった。研究者は、休日に目覚まし時計を使わず、自然に目が覚めるまで眠ってみることを勧める。予め就寝時刻を一定にしておけば、数日で自分に合った長さが見えてくるという。わざわざ専門の機関で検査を受けるには及ばない。まずは自分の体の声に耳を傾けることが、何よりの近道だ。": [0.0, 41.905], "課長、明日の取引先訪問ですが、資料を印刷して持っていきましょうか。": [42.305, 6.36], "先方には昨日データで送ってあるから、わざわざ印刷するまでもないよ。": [49.065, 5.525], "でも、先方の部長は紙の資料がお好きだと聞きました。念のため、一部だけでも。": [54.99, 7.115], "そうか。じゃあ、部長の分だけ用意してくれる?": [62.505, 4.21], "わかりました。私が準備しておきます。": [67.115, 3.43], "この程度のけがなら、病院に行くまでもない。": [70.945, 3.65], "結果は、改めて確認するまでもなく明らかだった。": [74.995, 4.44], "彼が優秀であることは、言うまでもない。": [79.835, 3.42], "ただの寝不足だから、病院に行くまでもないよ。電話で十分ですから、わざわざ謝りに来ていただくには及びません。": [83.655, 8.83], "駅はすぐそこだから、タクシーを呼ぶまでもない。": [92.885, 3.935], "簡単な手続きですので、わざわざお越しいただくには及びません。": [97.22, 5.085], "一向に": [102.705, 1.2], "到底": [104.305, 1.165], "辛うじて": [105.87, 1.29], "極力": [107.56, 1.255], "案の定": [109.215, 1.225], "予め": [110.84, 1.365], "努めて": [112.605, 1.115], "未だに": [114.12, 1.135]}, "d312": {"観光地での迷惑行為が、再び問題になっている。立ち入り禁止の柵を越えて撮影する、私有地に無断で車を止めるなど、危険極まりない行為が後を絶たない。ある町では、張り紙による注意だけでは効果がないとして、壊された柵の撤去と再設置を繰り返し、その費用もかさんでいる。町は観光協会に巡回業務の委託を検討しているが、人手の確保は容易ではない。一方、町の取り組みを紹介した地元の高校生の動画が全国大会で表彰され、代表の生徒は「光栄の至りです」と喜びを語った。住民と訪問者の双方が気持ちよく過ごせる仕組みづくりが求められている。": [0.0, 46.975], "本日は、このような賞をいただき、光栄の至りです。": [47.375, 4.795], "正直に申しますと、十年前の私は、取材相手に対して無礼極まりない態度をとる記者でした。": [52.57, 7.985], "ある方に厳しく叱られて、ようやく人の話を聞くことの大切さに気づいたんです。": [60.955, 6.595], "今回の受賞は、その方の言葉があってこそだと思っています。": [67.95, 5.145], "夜中に大声で騒ぐなんて、迷惑極まりない。": [73.495, 4.09], "雨の夜に無灯火で自転車に乗るのは、危険極まりない。": [77.985, 4.6], "彼の発言は、被害者に対して失礼極まりないものだった。": [82.985, 4.88], "このような場でお話しできるとは、恐縮の至りです。学生時代の私は、遅刻ばかりする非常識極まりない人間でした。": [88.265, 10.03], "連絡もなく約束を破るとは、非常識極まりない。": [98.695, 4.57], "皆様からこのような温かい言葉をいただき、感激の至りです。": [103.665, 5.38], "割愛": [109.445, 1.145], "手配": [110.99, 1.055], "交付": [112.445, 1.04], "撤去": [113.885, 1.07], "督促": [115.355, 1.245], "返還": [117.0, 1.145], "照会": [118.545, 1.26], "委託": [120.205, 1.075]}, "d313": {"新入社員の頃、私は先輩から「君ごときに何がわかる」と言われたことがある。気掛かりな案件について意見を述べた直後のことだった。当時は自分の軽率な発言を悔やんで落ち込んだが、今思えば、先輩は私の意見を無造作に退けたわけではなかった。その後、彼は私の指摘をもとに綿密な調査を行い、取引先の不正を突き止めたのだ。後日、寡黙な先輩は珍しく、「あの一言がなければ、夢のごとき好条件に飛びついていた」と打ち明けてくれた。言葉の裏にある意図を読む大切さを、私は痛切に感じた。": [0.0, 43.415], "部長、私ごときがこんな大きな仕事を任されて、よろしいんでしょうか。": [43.815, 6.25], "何を言ってるんだ。君だから頼んだんだよ。": [50.465, 3.485], "この部屋、まるでホテルのような広さですね。": [54.35, 3.73], "ええ。でも家賃のほうも、ホテル並みなんですよ。": [58.48, 4.275], "彼は風のごとく走り去っていった。": [63.155, 2.85], "私ごときの意見が採用されるとは、思ってもみませんでした。": [66.405, 5.075], "光陰矢のごとしと言うが、本当に月日が経つのは早い。": [71.88, 4.635], "私ごときがこんな賞をいただいていいのでしょうか。発表が終わると、拍手が波のごとく会場に広がった。": [76.915, 8.15], "あんな失敗ごときで、落ち込むことはないよ。": [85.465, 3.735], "子どものような笑顔で、彼は話し始めた。": [89.6, 3.705], "気掛かり": [93.705, 1.205], "有望": [95.31, 1.175], "寛大": [96.885, 1.13], "無造作": [98.415, 1.255], "綿密": [100.07, 1.155], "軽率": [101.625, 1.215], "寡黙": [103.24, 1.115], "痛切": [104.755, 1.23]}, "d314": {"三月に入り、日差しが少しずつ春めいてきた。とはいえ、朝晩の冷え込みはまだ厳しく、庭の梅もようやくほころび始めたところだ。この季節になると、私は祖父の言葉を思い出す。厳しい冬を耐えた木ほど、春に見事な花を咲かせる。祖父は説教めいたことを嫌う人だったが、この話だけは何度も繰り返した。商売が衰え、店の存続が揺らいだときも、祖父は「花は必ず咲く」と言って笑っていた。当時の私には、その言葉が単なる慰めに聞こえた。しかし、今ならわかる。あれは、苦境の中でも希望を秘めて生きるという覚悟だったのだと。": [0.0, 46.2], "来週のイベントのポスター、二つ案があるんですけど、どう思いますか。": [46.6, 5.59], "Ａ案は、ちょっと子どもっぽい感じがするなあ。": [52.59, 3.79], "Ｂ案のほうは、色合いが春めいていて、季節に合っていると思うよ。": [56.78, 5.475], "ただ、Ｂ案は文字が小さくて、少し読みにくいんですよね。": [62.655, 5.17], "じゃあ、Ｂ案を使って、文字だけ大きくしよう。": [68.225, 4.27], "木々の芽が膨らみ、山もすっかり春めいてきた。": [72.895, 4.045], "彼は冗談めかして言ったが、目は笑っていなかった。": [77.34, 4.1], "彼女の謎めいた微笑みが、ずっと気になっている。": [81.84, 4.105], "朝の風が秋めいてきて、長袖が欲しくなった。弟は飽きっぽくて、習い事が長続きしない。": [86.345, 8.11], "上司の皮肉めいた一言に、場の空気が凍りついた。": [94.855, 4.495], "年のせいか、最近忘れっぽくなった。": [99.75, 3.525], "秘める": [103.675, 1.025], "裂ける": [105.1, 1.175], "廃れる": [106.675, 1.16], "和らぐ": [108.235, 1.145], "揺らぐ": [109.78, 1.04], "衰える": [111.22, 1.185], "潤う": [112.805, 1.06], "遂げる": [114.265, 1.005]}, "d316": {"休日の朝、地域の有志が集まり、河川敷の清掃活動が行われた。参加者たちは泥まみれになりながら、川岸に流れ着いたごみを拾い集めた。驚いたことに、回収されたごみの大半はプラスチック製品だった。ペットボトルの数は二時間で千本を超え、河川敷は一時、ごみ袋だらけになったという。主催者によれば、清掃活動が地域に定着するにつれ、ポイ捨ては確実に減ってきた。それでも、上流から流れてくるごみは後を絶たない。主催者は「ごみを出さない意識を流域全体に浸透させたい」と話し、近隣の自治体に連携を呼びかけている。": [0.0, 45.825], "先週末、初めて田植えの体験に参加してきました。": [46.225, 4.645], "田んぼに入ると足がずぶずぶ沈んで、あっという間に全身泥まみれです。": [51.27, 5.53], "腰は痛くなるし、手は小さな傷だらけになるし、本当に大変でした。": [57.2, 6.195], "でも、毎日食べているお米がこんなに手間をかけて作られているんだと実感できて、いい経験になりました。": [63.795, 8.105], "子どもたちは泥まみれになって、グラウンドを走り回っていた。": [72.3, 4.695], "真夏の工事現場で、作業員たちは汗まみれで働いていた。": [77.395, 5.125], "彼は事業に失敗し、借金まみれの生活を送っている。": [82.92, 5.05], "部屋の大掃除をしたら、服がほこりまみれになった。初めて書いた日本語の作文は、間違いだらけだった。": [88.37, 8.305], "倉庫から出てきた古い箱は、ほこりまみれだった。": [97.075, 4.18], "彼の報告書は誤字だらけで、読むのに苦労した。": [101.655, 4.17], "浸透": [106.225, 1.29], "定着": [107.915, 1.21], "継承": [109.525, 1.215], "蓄積": [111.14, 1.29], "循環": [112.83, 1.14], "遮断": [114.37, 1.05], "散策": [115.82, 1.265], "介入": [117.485, 1.12]}, "d317": {"周囲の心配をよそに、七十歳を過ぎてから大学に入学した女性がいる。若い学生に交じって講義を受けることに、初めは引け目を感じたという。しかし、彼女は弱音を吐かなかった。足のけがをものともせず、片道一時間半の道のりを毎日通い続けたのだ。周りに気兼ねすることなく質問する彼女の姿に、若い学生たちも刺激を受けた。卒業論文のテーマは、生まれ育った漁村に伝わる祭りの記録である。「見栄を張らずに、知りたいことを知りたいと言えばいい。それだけのことです」と、彼女は穏やかに笑った。": [0.0, 41.785], "お父さん、ゆうべも家族の心配をよそに、遅くまで飲んでたんでしょう。": [42.185, 5.775], "まあね。でも、ちゃんと終電で帰ってきたよ。": [48.36, 4.215], "あの選手、けがをものともせず、最後まで走り切ったね。": [52.975, 5.105], "うん。ゴールした瞬間、思わず拍手しちゃった。": [58.48, 4.11], "親の反対をよそに、彼は大学を辞めて店を開いた。": [62.99, 4.665], "住民の不安をよそに、工事は予定どおり進められた。": [68.055, 4.46], "周囲の期待をよそに、彼女はあっさりと引退を表明した。": [72.915, 4.705], "兄は家族の心配をよそに、一人で世界一周の旅に出た。友人は骨折をものともせず、松葉杖で試験会場に現れた。": [78.02, 10.29], "医者の忠告をよそに、彼はたばこを吸い続けている。": [88.71, 4.435], "選手たちは激しい雨をものともせず、全力でプレーした。": [93.545, 4.735], "引け目": [98.68, 1.12], "弱音": [100.2, 1.085], "気兼ね": [101.685, 1.095], "見栄": [103.18, 0.95], "意地": [104.53, 0.905], "未練": [105.835, 0.94], "執着": [107.175, 1.305], "心得": [108.88, 1.255]}, "d318": {"先日、知人の店が閉店した。原因は資金繰りの悪化だったという。あと一年持ちこたえれば客足も戻ったかもしれないものを、と彼は悔しそうに語った。彼の店は地元の食材にこだわった料理で、評判も決して悪くなかった。ただ、彼は人に頼ることを極端に嫌った。早めに専門家に相談していれば、打つ手はいくらでもあったものを、一人で抱え込んでしまったのだ。誇りを持って仕事に取り組むことは大切だ。しかし、助けを求めるのを怠れば、その誇りも単なる意地になりかねない。頼るべきときには素直に頼ろう。彼の話を聞きながら、私はそう心がけることにした。": [0.0, 46.295], "昨日の飲み会、山田さん来なかったね。": [46.695, 3.56], "来られないなら、連絡くれればよかったものを。料理が一人分余っちゃった。": [50.655, 5.74], "確かに。でも、急な残業だったらしいよ。": [56.795, 4.05], "ああ、それは私が急ぎの仕事を頼んだんだ。申し訳ない。次回は私がおごるから。": [61.245, 7.545], "えっ、本当ですか。じゃあ、次は山田さんも一緒に行きましょう。": [69.19, 5.585], "一言謝ればすむものを、彼は最後まで意地を張った。": [75.175, 4.555], "もっと早く病院に行けば治ったものを、我慢しすぎてしまった。": [80.13, 4.82], "黙っていればいいものを、余計なことを言って彼女を怒らせた。": [85.35, 4.685], "前の晩に準備しておけば慌てずにすんだものを、つい後回しにしてしまった。困っていたなら、相談してくれればよかったものを。": [90.435, 9.815], "知らせてくれれば、手伝ったものを。": [100.65, 3.065], "一生懸命練習したのに、試合に負けてしまった。": [104.115, 4.31], "改まる": [108.825, 1.24], "収まる": [110.465, 1.13], "際立つ": [111.995, 1.175], "心がける": [113.57, 1.505], "差し支える": [115.475, 1.535], "取り組む": [117.41, 1.19], "怠る": [119.0, 1.18], "誇る": [120.58, 1.11]}, "d319": {"昼は会社員として働くかたわら、夜は小説を書き続けてきた男性が、今年、文学賞を受賞した。執筆にあてられるのは、帰宅後の二時間と週末だけ。通勤電車の中では、つり革につかまりながらスマートフォンに構想を書き留めた。原稿の出来はまちまちで、ぎこちない文章に自分でも嫌気がさすことがあったという。それでも、ひたむきに書き続けた。選考委員は「働く現場を知る作者ならではの描写が光る」と評価した。男性は「二足のわらじは煩わしいと思われがちだが、会社員としての日々が、むしろ創作を支えてくれた」と話す。": [0.0, 45.005], "私は、市役所に勤めるかたわら、週末は地元の子どもたちにサッカーを教えています。": [45.405, 7.445], "始めた頃は、仕事と両立できるか心細かったんですが、気づけば十年になりました。": [53.25, 7.405], "子どもたちは、ボールを追いかけながら、お互いに声をかけ合うことを自然に覚えていきます。": [61.055, 6.7], "勝ち負けより、仲間と力を合わせる喜びを知ってほしい。それが私の一番の願いです。": [68.155, 7.455], "彼女は大学で教えるかたわら、翻訳の仕事もしている。": [76.01, 4.93], "父は農業のかたわら、地域の消防団員として活動してきた。": [81.34, 5.485], "祖母は家事のかたわら、俳句を詠むのを楽しみにしていた。": [87.225, 4.615], "私は会社で働くかたわら、日本語能力試験の勉強を続けている。毎朝、コーヒーを飲みながら単語を復習している。": [92.24, 9.95], "兄は会社勤めのかたわら、週末はカフェを経営している。": [102.59, 4.885], "彼女は鼻歌を歌いながら、洗濯物を干していた。": [107.875, 4.355], "ひたむき": [112.63, 1.205], "まちまち": [114.235, 1.225], "ぎこちない": [115.86, 1.22], "紛らわしい": [117.48, 1.385], "煩わしい": [119.265, 1.4], "好ましい": [121.065, 1.33], "望ましい": [122.795, 1.325], "心細い": [124.52, 1.49]}, "d320": {"近所の公園に、一匹の野良猫がすみついている。毎朝七時になると、決まってベンチの下に姿を現す。ある年配の男性がやって来て袋を開けるが早いか、猫は一目散に駆け寄っていく。男性は十年以上、雨の日も欠かさずえさをやり続けてきたという。ただ、最近は公園の管理事務所から注意を受けることもある。ふん害を訴える住民の声が、この一帯で一挙に高まったからだ。男性が立ち去ったとたん、猫を追い払おうとする人もいる。動物を愛する気持ちと、地域の生活環境。どちらか一方を一概に否定することはできず、事務所も対応に苦慮している。": [0.0, 45.095], "うちの子、家に帰ってくるが早いか、ゲームを始めるのよ。": [45.495, 5.065], "うちもだよ。宿題なんて後回しさ。": [50.96, 3.38], "さっき、玄関のドアを開けたとたん、雨が降り出してさ。": [54.74, 4.77], "あら、それで傘を取りに戻ったの?": [59.91, 3.12], "彼は席に着くが早いか、弁当を食べ始めた。": [63.43, 4.27], "子どもたちはチャイムが鳴るが早いか、校庭へ飛び出していった。": [68.1, 4.75], "店のシャッターが開くが早いか、客が一斉に駆け込んだ。": [73.25, 4.62], "うちの犬は、私が散歩用のリードを手に取るが早いか、玄関に走っていく。駅に着いたとたん、財布を忘れたことに気づいた。": [78.27, 10.615], "彼女は電話を切るが早いか、上着をつかんで家を飛び出した。": [89.285, 4.71], "立ち上がったとたん、めまいがした。": [94.395, 2.695], "一変": [97.49, 1.05], "一新": [98.94, 1.005], "一掃": [100.345, 1.115], "一括": [101.86, 1.165], "一斉": [103.425, 1.115], "一帯": [104.94, 1.085], "一概に": [106.425, 1.235], "一挙": [108.06, 1.05]}, "d321": {"精密機械の部品を作るある町工場では、千分の一ミリの誤差たりとも許されない。工場長によれば、製品の品質は機械の性能だけでは決まらない。素材の温度や湿度のわずかな変化を見逃さない職人の感覚が、精巧な部品を生み出すのだという。この工場では、作業の手順をあえて簡素にし、職人が自分の手で確かめる工程を残している。若手の育成にも時間を惜しまない。厳密な検査を通らなかった部品は、一つも出荷しない。その誠実な姿勢が評価され、海外の医療機器メーカーからも注文が相次いでいる。": [0.0, 41.77], "新製品の発表まで、あと一週間だ。一日たりとも無駄にはできないぞ。": [42.17, 6.36], "はい。ただ、パンフレットがまだ一枚も届いていないんです。": [48.93, 4.78], "さっき印刷会社に確認したら、明日の午前中には届くそうです。": [54.11, 5.425], "そうか。じゃあ、届いたらすぐに内容をチェックしてくれ。": [59.935, 4.84], "試験まであとわずかだ。一日たりとも休んではいられない。": [65.175, 4.805], "会議の内容は、一言たりとも外部に漏らしてはならない。": [70.38, 4.7], "彼は入院中も、一瞬たりとも仕事のことを忘れなかった。": [75.48, 4.99], "本番まで、一日たりとも勉強を休まないつもりだ。聴解の問題は、一問たりとも聞き逃したくない。": [80.87, 8.67], "今月は一円たりとも無駄遣いしないと決めた。": [89.94, 3.775], "財布の中には百円も残っていなかった。": [94.115, 3.295], "厳密": [97.81, 1.16], "精巧": [99.37, 1.305], "緻密": [101.075, 1.12], "簡素": [102.595, 1.12], "質素": [104.115, 1.175], "素朴": [105.69, 1.175], "誠実": [107.265, 1.23], "柔軟": [108.895, 1.07]}, "d323": {"旅先で何を食べるかは、旅の満足度を大きく左右する。全国どこでも同じ味を手頃な値段で楽しめるチェーン店も便利だが、せっかくなら、その土地ならではの料理を味わいたいものだ。例えば、ある港町の食堂では、朝に水揚げされたばかりの魚を使った定食が名物で、店の人の手厚いもてなしも評判だ。手軽な観光ガイドには載っていない店ほど、意外な発見がある。店主との何気ない会話から、その町らしい暮らしぶりが見えてくることもある。手近な情報だけに頼らず、地元の人に尋ねてみる。それが、旅を豊かにする一番の近道かもしれない。": [0.0, 44.6], "今回のツアーでは、有名な観光地にはあえて行きません。": [45.0, 4.645], "その代わり、地元の農家に泊まって、この地域ならではの郷土料理を一緒に作ります。": [50.045, 6.935], "夜は、農家の皆さんといろりを囲んで、昔話を聞く時間もあります。": [57.38, 6.195], "その土地らしい暮らしを、肌で感じていただける旅になると思います。": [63.975, 5.465], "手作りならではの温かみが、この器の魅力だ。": [69.84, 4.22], "雪国ならではの冬の祭りを、一度見てみたい。": [74.46, 4.1], "このきめ細かいサービスは、老舗旅館ならではだ。": [78.96, 4.285], "私の故郷には、港町ならではの新鮮な刺身を出す店がたくさんある。夏になると、海辺の町らしいにぎやかな祭りが開かれる。": [83.645, 10.87], "職人ならではの技が、細部にまで光っている。": [94.915, 4.135], "今日は春らしい、穏やかな一日だった。": [99.45, 3.595], "手薄": [103.445, 1.055], "手頃": [104.9, 1.06], "手厚い": [106.36, 1.14], "手軽": [107.9, 1.005], "手近": [109.305, 1.06], "手順": [110.765, 0.96], "手口": [112.125, 1.065], "手腕": [113.59, 1.025]}, "d324": {"近年、インターネット上には真偽の定かでない健康情報があふれている。ある調査では、回答者の半数以上が、ネットで見た情報をもとに自己流で対処した経験があると答えた。中には、症状に該当しない薬を飲み続けて体調を崩した例もある。専門家は、信頼するに足る情報かどうかを見極めるには、まず発信者が誰なのかを確認すべきだと指摘する。また、一つの情報だけに頼らず、複数の情報源を比べることも重要だ。こうした地道な確認作業を続ける姿勢こそ、情報があふれる時代において評価に値するものだと言えるだろう。": [0.0, 43.36], "今度の新人、大きな仕事を任せるに足る人物だと思う?": [43.76, 5.075], "ええ。まだ若いですが、責任感は十分にありますよ。": [49.235, 4.975], "話題のあの映画、見る価値あった?": [54.61, 3.005], "うーん、評判のわりには、わざわざ映画館で見るに値するとは思えなかったな。": [58.015, 6.2], "彼は、どんな秘密も打ち明けられる信頼するに足る人物だ。": [64.615, 4.91], "審査員を納得させるに足る作品は、まだ見当たらない。": [69.925, 4.54], "そんな取るに足りないことで悩むのは、もうやめよう。": [74.865, 4.075], "この小説は、何度読み返しても一読に値する名作だ。彼女は、どんな仕事も安心して任せるに足る同僚だ。": [79.34, 9.565], "これは十分に信頼するに足るデータだ。": [89.305, 3.135], "彼の勇気ある行動は、称賛に値する。": [92.84, 3.895], "該当": [97.135, 1.18], "適用": [98.715, 1.215], "適応": [100.33, 1.175], "応募": [101.905, 1.05], "応対": [103.355, 1.11], "対処": [104.865, 1.11], "処置": [106.375, 1.065], "処分": [107.84, 1.06]}, "d325": {"SNS上で、特定の人物を中傷する書き込みが問題になっている。中には読むにたえない言葉が並び、標的にされた人が心身の不調を訴える例も少なくない。匿名だから何を書いても構わないという気軽さが、言葉の暴力を生むのだろう。こうした中、ある俳優が自身の経験を語った動画が注目を集めた。彼は誹謗中傷に苦しんだ日々を淡々と振り返り、最後に「支えてくれたファンの皆さんには、感謝の念にたえません」と深々と頭を下げた。その気丈な姿に、多くの人が胸を打たれたという。": [0.0, 40.705], "それでは、今年度で退任される田中先生から一言いただきます。": [41.105, 5.54], "皆さん、長い間本当にありがとうございました。感謝の念にたえません。": [47.045, 5.97], "先生、僕が最初に出した論文、ひどかったですよね。": [53.415, 5.08], "ええ、正直、読むにたえないものでした。でも、そこからよく成長しましたね。": [58.895, 7.19], "先生、これからもぜひ研究室に遊びに来てくださいね。": [66.485, 4.97], "事故現場の様子は、見るにたえないものだった。": [71.855, 3.705], "皆様の温かいご支援に、感謝の念にたえません。": [75.96, 4.32], "彼の演説は他人の悪口ばかりで、聞くにたえなかった。": [80.68, 4.64], "在職中は大変お世話になり、感謝の念にたえません。ネット上の心ない書き込みは、とても読むにたえないものだった。": [85.72, 9.165], "酔った客同士の言い争いは、聞くにたえなかった。": [95.285, 4.05], "恩師の訃報に接し、悲しみにたえない。": [99.735, 3.6], "気休め": [103.735, 1.265], "気配": [105.4, 1.09], "気質": [106.89, 1.06], "気まぐれ": [108.35, 1.205], "気長": [109.955, 1.095], "気丈": [111.45, 1.09], "気品": [112.94, 0.97], "気迫": [114.31, 1.095]}, "d326": {"毎日運動しないまでも、せめて週に二、三回は体を動かしたい。そう考える人は多いが、実際に続けられる人は少ない。理由としてはもっぱら忙しさが挙げられるが、専門家によれば、問題は時間よりも目標の立て方にある。最初から高い目標を掲げると、達成できない日が続き、おのずと意欲が失われていくのだ。そこで勧められるのが、エレベーターではなく階段を使う、一駅分歩くといった、生活の中に無理なく組み込める小さな習慣である。劇的な効果は得られないにしても、続けることで体は確実に変わっていくという。かねてから運動不足を気にしていた私も、これなら続けられそうだ。": [0.0, 48.5], "新入社員の皆さんに、一つお願いがあります。": [48.9, 4.075], "毎日完璧な報告書を書けとは言いません。ただ、完璧とは言わないまでも、要点だけは必ず押さえてください。": [53.375, 9.25], "それから、自分で解決できないにしても、困ったことがあれば早めに相談すること。": [63.025, 7.0], "一人で抱え込むのが、一番よくないんです。": [70.425, 3.655], "全額とは言わないまでも、せめて半分は返してほしい。": [74.48, 4.545], "毎日とは言わないまでも、週に一度は親に電話しなさい。": [79.425, 4.67], "優勝はできないまでも、決勝までは進みたい。": [84.495, 4.03], "ネイティブ並みとは言わないまでも、せめて仕事の会議で困らない程度には話したい。疲れて勉強できないにしても、単語だけは毎日見るようにしている。": [88.925, 11.155], "プロ並みとは言わないまでも、人前で弾ける程度にはなりたい。": [100.48, 4.66], "参加しないにしても、返事だけはしてください。": [105.54, 4.01], "ことごとく": [109.95, 1.39], "もっぱら": [111.74, 1.18], "おのずと": [113.32, 1.19], "かねて": [114.91, 1.0], "とっさに": [116.31, 1.005], "いたって": [117.715, 1.04], "くまなく": [119.155, 1.095], "ひたすら": [120.65, 1.245]}, "d327": {"春とはいえ、山の上はまだ冬の寒さだ。週末、友人と三人で、初心者向けとされる山に登った。登山道は整備されていて見晴らしもよく、途中までは順調だった。ところが、山頂付近で急に霧が立ち込め、道を見失いかけた。ベテランの登山家といえども、天候の急変を完全に予測することはできないという。私たちは見当をつけて来た道を引き返し、無事に下山できたが、自分たちの準備の甘さを思い知った。地図の見落としが一つでもあれば、事故につながりかねない。次の登山では、事前の計画をより入念に立てるつもりだ。": [0.0, 44.245], "新しいプロジェクト、うまくいってる?": [44.645, 3.085], "順調とはいえ、まだ油断はできないよ。": [48.13, 3.435], "社長でも、この規則は守らなきゃいけないんですか。": [51.965, 4.305], "ええ。社長といえども、例外は認められません。": [56.67, 4.37], "冗談とはいえ、言っていいことと悪いことがある。": [61.44, 4.005], "円安が進んでいるとはいえ、海外旅行の人気は根強い。": [65.845, 4.87], "夏休みとはいえ、宿題が多くて遊ぶ暇がない。": [71.115, 4.38], "十月とはいえ、昼間はまだ半袖で過ごせるほど暑い。ベテランの通訳者といえども、準備なしで専門的な会議に臨むことはない。": [75.895, 10.72], "仕事とはいえ、毎晩遅くまで残業するのはつらい。": [87.015, 4.43], "子どもといえども、自分の行動には責任を持つべきだ。": [91.845, 4.47], "見込み": [96.715, 1.1], "見落とし": [98.215, 1.215], "見当": [99.83, 1.215], "見栄え": [101.445, 1.07], "見晴らし": [102.915, 1.245], "見返り": [104.56, 1.155], "見極め": [106.115, 1.23], "見本": [107.745, 1.0]}, "d328": {"新規事業の採算が合うかどうかを判断するのは難しい。事前に試算を重ねても、市場の反応は予測どおりにはいかないからだ。ある中小企業の社長は、かつて大きな誤算を経験した。海外向けの新商品を開発したものの、為替の変動で利益が想定を大きく下回ったのだ。社長は「理由がどうであれ、見通しの甘さは経営者の責任だ」と振り返る。その後、同社は計画の段階で、楽観的にせよ悲観的にせよ、複数のシナリオを立てることを徹底した。損失の清算には三年を要したが、この経験が今の堅実な経営の土台になっているという。": [0.0, 45.22], "来月の社員旅行、行き先は温泉と海、どっちがいいと思う?": [45.62, 5.515], "行き先はどこであれ、移動時間は短いほうがいいな。": [51.535, 4.285], "温泉にしろ海にしろ、予算は一人二万円以内で頼むよ。": [56.22, 4.905], "海のほうは、バスで四時間もかかるんですよね。温泉なら一時間半です。": [61.525, 5.995], "それなら、近いほうで決まりだね。": [67.92, 2.98], "理由がどうであれ、暴力は許されない。": [71.3, 3.43], "誰であれ、ルールを破れば処分の対象となる。": [75.13, 3.855], "晴天であれ雨天であれ、試合は予定どおり行われる。": [79.385, 4.465], "役職が何であれ、会議には時間どおりに集まること。買うにしろ買わないにしろ、早めに決めたほうがいいよ。": [84.25, 8.67], "大人であれ子どもであれ、入場料は同じだ。": [93.32, 3.755], "行くにしろ行かないにしろ、明日までに返事をください。": [97.475, 4.245], "誤算": [102.12, 1.015], "打算": [103.535, 0.995], "採算": [104.93, 1.17], "概算": [106.5, 1.085], "精算": [107.985, 1.17], "試算": [109.555, 1.055], "換算": [111.01, 1.08], "清算": [112.49, 1.17]}, "d331": {"先月、ある自治体が子育て支援の申請をオンライン化した。受付開始が告知されるや否や、アクセスが殺到し、システムはわずか数分で停止してしまった。担当者によれば、事前の負荷試験では、想定の三倍の利用にも耐えられるはずだったという。ところが実際には、「申請期間は数日しかない」という誤った情報が広まり、住民が一斉に手続きを急いだのである。期間は本来一か月以上あったにもかかわらず、だ。この一件は、技術的な準備だけでは不十分であり、情報をどう伝えるかが利用者の行動を大きく左右することを示している。自治体は今後、告知の段階で期間や手順を丁寧に説明する方針だという。": [0.0, 49.825], "ねえ、市の申請サイト、もう使えるようになった？": [50.225, 4.555], "それがさ、公開されるや否やアクセスが殺到して、止まっちゃったらしいよ。": [55.18, 6.05], "えっ、締め切りまでまだ一か月もあるのに？": [61.63, 3.51], "うん、数日で締め切られるって噂が広まったんだって。告知の仕方がまずかったみたい。": [65.54, 6.925], "新製品の発売が発表されるや否や、その会社の株価は急上昇した。": [72.865, 6.215], "父は玄関のドアを開けるや否や、「夕飯はまだか」と大声を出した。": [79.48, 5.67], "その歌手が舞台に姿を現すや、会場は大歓声に包まれた。": [85.55, 5.58], "人気グループの公演日程が発表されるや否や、チケットの申し込みが殺到した。わずか五分で全席が売り切れ、ファンたちは一斉に落胆の声を上げた。": [91.53, 11.81], "彼は席に着くや否や、分厚い資料を広げた。": [103.74, 4.135], "資料が届き次第、皆様にお送りします。": [108.275, 3.84], "殺到": [112.515, 1.26], "告知": [114.175, 1.115], "負荷": [115.69, 1.04], "想定": [117.13, 1.265], "一斉": [118.795, 1.115], "左右": [120.31, 1.095], "落胆": [121.805, 1.11], "周知": [123.315, 1.125]}, "d332": {"ある地方の小さなパン店が、駅前への出店を皮切りに、わずか三年で県内に十店舗を構えるまでになった。成功の理由として、よく商品の質の高さが挙げられる。だが私は、それ以上に、店主が地域の声に耳を傾け続けてきた点に注目したい。新しい店を出すたびに周辺の住民に好みを尋ね、店ごとに品揃えを変えてきたというのだ。規模を拡大すると、効率を優先するあまり画一化に走りがちである。しかし、地域に根ざした商売とは、むしろ店の数が増えるほど、一つ一つの土地に寄り添うことではないだろうか。拡大と個別性は、必ずしも相反するものではないのである。": [0.0, 47.545], "あのパン屋、また新しい店を出すらしいね。": [47.945, 4.025], "うん、駅前の店を皮切りに、あっという間に十店舗だって。": [52.37, 5.03], "でも、どの店も同じ商品じゃないんだよね。": [57.8, 3.725], "そうそう。土地ごとに品揃えを変えてるんだって。画一化しないのがいいところよね。": [61.925, 6.575], "そのバンドは、大阪公演を皮切りに、全国二十都市を回るツアーを開始した。": [68.9, 6.665], "一人の社員の告発を皮切りに、同様の不正が次々と明るみに出た。": [75.965, 5.93], "この技術は、医療分野での採用を皮切りとして、さまざまな産業に広がっていった。": [82.295, 6.995], "その古着店は、学生街への出店を皮切りに、都内各地に店舗を広げていった。どの店も地域に根ざした雰囲気づくりを大切にしているそうだ。": [89.69, 11.385], "札幌での発売を皮切りに、新商品は全国で販売された。": [101.475, 5.535], "この店には、ケーキをはじめ、さまざまな洋菓子が並んでいる。": [107.41, 5.375], "出店": [113.185, 1.16], "構える": [114.745, 1.14], "画一化": [116.285, 1.275], "根ざす": [117.96, 1.135], "寄り添う": [119.495, 1.19], "相反する": [121.085, 1.175], "品揃え": [122.66, 1.385], "趨勢": [124.445, 1.265]}, "d333": {"A　老朽化の進む市民会館を、今年度末をもって閉館するという市の決定は妥当だと考える。耐震補強には多額の費用がかかり、利用者も年々減っている。採算の取れない施設をいつまでも維持すれば、他の行政サービスにしわ寄せが及ぶ。惜しむ声があるのは理解できるが、限られた財源をどう配分するかという観点から判断すべきだ。\nB　閉館の判断はいささか性急ではないか。確かに建物は古く、費用の問題は無視できない。しかし、市民会館は地域の文化活動の拠点であり、利用者数だけで価値を測るのは一面的だ。少なくとも、代わりの活動場所を確保するまで、存続の道を探ってもよいはずである。": [0.0, 50.07], "市民会館は、三月末をもって閉館となります。皆様、長い間ありがとうございました。": [50.47, 8.16], "本当に閉まっちゃうんですね。子どもの頃から発表会はいつもここだったのに。": [59.03, 5.925], "建物の老朽化を考えると、仕方ないのかもしれませんね。": [65.355, 4.97], "でも、代わりの場所が決まる前に閉めるのは、いささか急すぎる気がします。": [70.725, 5.93], "当店は、九月三十日をもちまして閉店させていただきます。": [77.055, 5.105], "合否の結果は、後日書面をもってお知らせします。": [82.56, 4.13], "彼の実力をもってすれば、この程度の課題は一日で片づくだろう。": [87.09, 5.615], "駅前の映画館は、今月末をもって六十年の歴史に幕を下ろすことになりました。存続を求める署名も集まりましたが、閉館を惜しむ声に応えることはできませんでした。": [93.105, 13.57], "以上をもちまして、本日の説明会を終了いたします。": [107.075, 4.725], "この寺は、八世紀に一人の僧によって建てられた。": [112.2, 4.29], "老朽化": [116.89, 1.24], "存続": [118.53, 1.29], "性急": [120.22, 1.25], "採算": [121.87, 1.17], "惜しむ": [123.44, 1.04], "いささか": [124.88, 1.315], "妥当": [126.595, 1.075], "拠点": [128.07, 1.015]}, "d334": {"市立動物園が開園以来初めて夜間営業を行うとあって、初日は開門前から長い行列ができた。昼間はじっとしている動物たちが、夜になると活発に動き回る姿を見られるのが目当てだという。園側は来場者を一晩二千人と見込んでいたが、実際にはその倍近くが詰めかけ、急きょ臨時の駐車場を設けた。家族連れに交じって、仕事帰りの会社員の姿も目立った。一方で、照明や人の声が動物に負担をかけるのではないかと心配する意見もある。園では、動物の様子を毎晩確認し、問題があれば営業時間を短縮することも検討するとしている。": [0.0, 44.455], "昨日、動物園の夜間営業に行ってきたよ。": [44.855, 3.885], "初めての試みとあって、すごい人だったでしょう？": [49.14, 4.19], "うん、入るまで一時間待ち。でも、夜のライオンはさすがに迫力があったよ。": [53.73, 6.54], "へえ、物珍しさもあるし、しばらくは盛況が続きそうだね。": [60.67, 5.62], "年に一度の大売り出しとあって、店の前には早朝から人が並んでいた。": [66.69, 5.605], "人気俳優が来るとあって、小さな町の商店街は異例の賑わいを見せた。": [72.695, 5.845], "連休最終日とあって、高速道路の上り線は朝から渋滞が続いている。": [78.94, 6.06], "人気作家が十年ぶりにサイン会を開くとあって、書店には朝から大勢のファンが詰めかけた。整理券は開店直後になくなり、会は終始盛況だった。": [85.4, 11.83], "初の夜間公開とあって、会場は大勢の人で賑わった。": [97.63, 4.98], "十年も海外に住んでいただけあって、彼の英語は実に自然だ。": [103.01, 5.18], "目当て": [108.59, 1.065], "見込む": [110.055, 1.1], "詰めかける": [111.555, 1.415], "臨時": [113.37, 1.005], "盛況": [114.775, 1.305], "物珍しい": [116.48, 1.54], "異例": [118.42, 1.04], "賑わう": [119.86, 1.125]}, "d335": {"「お忙しいところをお越しいただき、ありがとうございます」。式典の冒頭で耳にするこの一言を、決まり文句として聞き流す人は多いだろう。だが本来これは、相手が自分の都合を後回しにして来てくれたことへの、敬意と感謝の表明である。近年、メールの書き出しに同じ文言を機械的に貼り付ける風潮が見られるが、それでは言葉は形骸化するばかりだ。定型の挨拶は、気持ちを伝える手間を省くための道具ではない。むしろ、限られた字数で相手を労うために先人が磨いてきた知恵である。決まった言い回しだからこそ、その意味を一度立ち止まって考え、心を込めて使いたいものだ。": [0.0, 46.01], "本日はお休みのところをお集まりいただき、ありがとうございます。": [46.41, 5.165], "いえいえ。部長こそ、ご多忙のところを準備していただいて。": [51.975, 5.015], "本来なら先月開くところを、ここまで延びてしまって申し訳ありません。": [57.39, 5.76], "いや、皆さんの都合を優先した結果だから、気にしないで。": [63.55, 5.15], "危ないところを、通りかかった人に助けてもらった。": [69.1, 4.265], "本来なら厳しく処分するところを、今回は反省文の提出だけで済ませた。": [73.765, 6.15], "お休みのところを突然お電話してしまい、失礼いたしました。": [80.315, 4.99], "ご多忙のところを貴重なお時間を割いていただき、誠にありがとうございました。準備に尽力してくださった皆様を、改めて労いたいと存じます。": [85.705, 11.525], "寝ているところを起こされて、彼は機嫌が悪かった。": [97.63, 4.185], "出かけようとしているところへ、友人が訪ねてきた。": [102.215, 4.15], "形骸化": [106.765, 1.26], "風潮": [108.425, 1.215], "冒頭": [110.04, 1.16], "聞き流す": [111.6, 1.35], "労う": [113.35, 1.125], "敬意": [114.875, 0.99], "言い回し": [116.265, 1.29], "多忙": [117.955, 1.06]}, "d337": {"A　定期健診を受けていれば、もっと早く病気の兆候に気づけたものを──。そう悔やむ患者の声を、医師として何度も聞いてきた。症状が出てからでは手遅れになる病気は少なくない。忙しさを理由に健診を怠るのは、自分の健康を軽視しているに等しい。\nB　健診の重要性は否定しない。ただ、数値が基準内だったからといって、すっかり安心してしまう人が多いのも事実だ。健診の結果を過信して体の異変を見過ごしては、本末転倒である。日々の体調の変化に注意を払うことこそ、病気を未然に防ぐ第一歩だろう。": [0.0, 41.265], "もう少し早くいらしていれば、薬だけで済んだものを、と思うと残念です。": [41.665, 6.055], "そうですか……。去年から時々胸が痛むことはあったんですが、つい見過ごしてしまって。": [48.12, 6.78], "幸い、手遅れではありません。ただ、今後は年に一度の健診を怠らないでください。": [55.3, 7.35], "はい、これからは体の小さな変化も軽く考えないようにします。": [63.05, 5.65], "一言相談してくれれば手伝ったものを、彼は一人で抱え込んでしまった。": [69.1, 5.77], "素直に謝れば済むものを、意地を張るから話がこじれるのだ。": [75.27, 5.025], "あと五分早く家を出ていれば、最終電車に間に合ったものを。": [80.695, 4.905], "体がだるいと感じた時点で受診していれば、一日休むだけで済んだものを、無理をして働き続けたせいで一週間も寝込んでしまった。小さな兆候を軽視してはいけないと痛感した。": [86.0, 13.815], "早く打ち明けてくれれば、力になれたものを。": [100.215, 3.845], "雨が降っているのに、彼は傘も持たずに出かけた。": [104.46, 4.245], "受診": [109.105, 1.04], "兆候": [110.545, 1.27], "見過ごす": [112.215, 1.255], "軽視": [113.87, 1.09], "過信": [115.36, 1.045], "未然": [116.805, 0.975], "怠る": [118.18, 1.18], "手遅れ": [119.76, 1.205]}, "d338": {"駅前の老舗書店が、シャッターを下ろしたまま一か月が過ぎた。ついに閉店かと思いきや、先週、カフェを併設した新しい店として再出発した。近年はネット通販の普及で客足が遠のき、経営は苦しかったという。打開策として三代目の店主が選んだのは、書店を本を「買う場所」から「過ごす場所」へと変えることだった。店内には長居できる椅子が並び、扱う本も地元の作家や郷土史を中心に絞り込んだ。改装後は若い客の姿が増え、売り上げも少しずつ回復しているそうだ。店主は「居心地のよさが、結果的に本との出会いを生むんです」と話す。": [0.0, 46.725], "駅前の本屋さん、閉店したのかと思いきや、カフェ付きの店になってたよ。": [47.125, 6.145], "ああ、一か月くらい改装してたらしいね。": [53.67, 3.58], "最近は客足が遠のいてたみたいだから、心配してたんだ。": [57.65, 4.955], "今は居心地がいいって評判で、若い人もよく来てるらしいよ。": [63.005, 5.105], "今年の冬は暖かいと思いきや、二月に入って記録的な大雪に見舞われた。": [68.51, 6.335], "簡単な試験かと思いきや、最後の問題で手も足も出なかった。": [75.245, 5.315], "彼のことだから遅れてくると思いきや、誰よりも早く会場に着いていた。": [80.96, 5.68], "雨で客足が遠のくかと思いきや、その日のイベント会場は大勢の家族連れで賑わった。予想外の展開に、主催者もうれしい悲鳴を上げていた。": [87.04, 11.455], "てっきり反対されると思いきや、両親はあっさり留学を認めてくれた。": [98.895, 5.595], "空が暗くなったかと思ったら、急に激しい雨が降り出した。": [104.89, 4.88], "老舗": [110.17, 1.25], "併設": [111.82, 1.215], "改装": [113.435, 1.215], "客足": [115.05, 1.255], "遠のく": [116.705, 1.145], "打開": [118.25, 1.06], "居心地": [119.71, 1.245], "絞り込む": [121.355, 1.405]}, "d339": {"蛇口をひねれば、いつでもきれいな水が出る。その便利さに慣れきった私たちは、水が有限の資源であることをつい忘れてしまう。昨年の夏、記録的な渇水に見舞われたある島では、住民が一滴たりとも無駄にすまいと、風呂の残り湯を洗濯や庭の水やりに回したという。ダムの水が枯渇寸前になって初めて、人々は日々の浪費を自覚したのである。しかし、こうした意識が非常時だけのものであってはならない。水の恩恵を当たり前と思わず、普段から使い方を見直すことこそが、将来の危機に対する最大の備えになるはずだ。": [0.0, 42.085], "今年の夏も、また水不足になるかもしれないって。": [42.485, 4.475], "去年は大変だったよね。一滴たりとも無駄にできないって、お風呂の残り湯まで使ったし。": [47.36, 7.055], "でも、雨が降ったらすぐ元の生活に戻っちゃったよね。": [54.815, 4.66], "確かに。喉元過ぎれば熱さを忘れる、ってやつだな。": [59.875, 5.03], "本番まで、一秒たりとも気を抜くわけにはいかない。": [65.305, 4.295], "会社の機密情報は、一行たりとも外部に漏らしてはならない。": [70.0, 5.1], "彼は入院中も、一日たりとも日記を欠かさなかった。": [75.5, 4.72], "試験本番まであと一か月しかない。時間を浪費していると自覚してからは、一日たりとも単語の復習を休まないことにしている。": [80.62, 9.97], "試験まであと一週間、一日たりとも無駄にはできない。": [90.99, 4.575], "この教室の生徒は、一人として宿題を忘れなかった。": [95.965, 4.665], "渇水": [101.03, 1.115], "有限": [102.545, 1.065], "枯渇": [104.01, 1.17], "浪費": [105.58, 1.015], "恩恵": [106.995, 1.175], "賄う": [108.57, 1.18], "自覚": [110.15, 1.145], "備蓄": [111.695, 1.035]}, "d340": {"A　在宅勤務の導入から三年がたった。毎日とは言わないまでも、週に二、三日は自宅で働ける今の制度は、育児や介護との両立に欠かせない。通勤の煩わしさから解放され、仕事の裁量が増えたと感じる社員も多い。せっかく定着した柔軟な働き方を、後退させるべきではない。\nB　在宅勤務の利点は認める。ただ、出社の機会が減ったことで、部署を越えた意思疎通が希薄になったという弊害も無視できない。完全に元に戻せとは言わないまでも、対面の場を意図的に設けるなど、出社との併用のあり方を見直す時期に来ているのではないか。": [0.0, 44.705], "来月から、在宅勤務の日数を見直すことになったよ。": [45.105, 4.615], "えっ、全員毎日出社に戻るんですか。": [50.12, 3.465], "いや、毎日とは言わないまでも、週に二日は顔を出してほしいという方針らしい。": [53.985, 6.705], "それなら、子育てとの両立もなんとかできそうです。": [61.09, 4.355], "優勝は望めないまでも、せめて予選は突破したい。": [65.845, 4.32], "完璧とは言えないまでも、新人にしては上出来の報告書だ。": [70.565, 5.005], "毎日ではないまでも、できるだけ自炊するよう心がけている。": [75.97, 4.935], "毎日とは言わないまでも、週に一度は部署を越えて顔を合わせる場を設けるべきだと思う。オンラインだけでは、どうしても意思疎通が希薄になりがちだからだ。": [81.305, 11.27], "毎日とは言わないまでも、週に一度は電話してほしい。": [92.975, 4.445], "その程度のことなら、わざわざ先生に聞くまでもない。": [97.82, 4.445], "柔軟": [102.665, 1.07], "両立": [104.135, 1.14], "煩わしい": [105.675, 1.4], "弊害": [107.475, 1.125], "疎通": [109.0, 1.165], "裁量": [110.565, 1.225], "併用": [112.19, 1.17], "希薄": [113.76, 1.095]}, "d341": {"八十歳を超えた今も、被災地で炊き出しを続ける男性がいる。三十年前、自らも地震で家を失った経験から、「困っている人に温かい食事を届けたい」と志したのだという。以来、大きな災害が起きるたびに仲間と駆けつけ、多い日には五百食を用意する。決して体が丈夫なわけではない。それでも、早朝から黙々と野菜を刻むその姿に、取材した記者は感動を禁じ得なかったと記している。男性は「自分がしてもらったことを返しているだけです」と淡々と語る。こうした惜しみない献身が、復興の現場を陰で支えているのである。": [0.0, 44.91], "被災地で炊き出しを続ける男性の映像、ご覧いただきました。": [45.31, 5.085], "八十歳を超えてなお、毎日あれだけの量を用意されているとは。感動を禁じ得ませんね。": [50.795, 7.185], "三十年前の、ご自身の被災経験がきっかけだそうです。": [58.38, 4.89], "受けた恩を返したいという思いが、原動力になっているんでしょうね。": [63.67, 4.975], "被害の大きさを伝える映像に、驚きを禁じ得なかった。": [69.045, 4.705], "弱い立場の人を狙った詐欺の手口には、憤りを禁じ得ない。": [74.15, 5.16], "大けがから復帰して再び表彰台に立った選手の姿に、涙を禁じ得なかった。": [79.71, 6.63], "自らも家を失いながら、他の被災者のために炊き出しに携わる人々の姿に、感動を禁じ得なかった。私も何か力になれることはないかと考えている。": [86.74, 12.785], "被災者の苦しみを思うと、同情を禁じ得ない。": [99.925, 4.005], "あまりに面白い話で、笑わずにはいられなかった。": [104.33, 4.3], "被災": [109.03, 1.035], "炊き出し": [110.465, 1.26], "復興": [112.125, 1.215], "献身": [113.74, 1.08], "黙々と": [115.22, 1.39], "携わる": [117.01, 1.28], "志す": [118.69, 1.44], "惜しみない": [120.53, 1.14]}, "d342": {"SNSには、真偽の定かでない情報があふれている。もっともらしい数字や専門用語が並んでいると、つい信頼するに足る情報だと思い込んでしまうが、出典が示されていないものも少なくない。とりわけ災害時には、善意から発信された誤情報が瞬く間に拡散し、混乱を招くことがある。大切なのは、情報を鵜呑みにせず、誰が何を根拠に言っているのかを吟味する習慣だ。一つの情報源に偏らず、複数の裏付けを確かめれば、信憑性はある程度見極められる。情報の受け手である私たち一人一人にも、発信者と同じだけの責任があるのではないだろうか。": [0.0, 45.11], "この記事、新しいお茶で病気が治るって書いてあるけど、本当かな。": [45.51, 5.875], "出典が書いてないね。信頼するに足る情報とは言えないんじゃない？": [51.785, 5.19], "でも、もうたくさんの人が拡散してるよ。": [57.375, 3.62], "広まってることと正しいことは別だよ。鵜呑みにしないほうがいい。": [61.395, 5.005], "彼女のこれまでの実績は、十分に信頼するに足るものだ。": [66.8, 4.89], "人に胸を張って語るに足る経験など、私にはまだ何もない。": [72.09, 5.27], "他人から見れば取るに足らない悩みでも、本人にとっては深刻なのだ。": [77.76, 5.42], "出典がはっきりしていて、複数の専門家の裏付けがある情報なら、信頼するに足ると判断している。そうでないものは鵜呑みにせず、時間をかけて吟味するようにしている。": [83.58, 13.155], "彼は部下から信頼されるに足るリーダーだ。": [97.135, 3.305], "この新人の提案は、十分に検討に値する。": [100.84, 4.235], "吟味": [105.475, 0.985], "鵜呑み": [106.86, 1.025], "出典": [108.285, 1.16], "偏る": [109.845, 1.165], "見極める": [111.41, 1.275], "裏付け": [113.085, 1.23], "信憑性": [114.715, 1.38], "拡散": [116.495, 1.16]}, "d344": {"A　スマートフォンを操作しながら自転車に乗る人を、毎日のように見かける。歩行者のすぐ脇を高速で走り抜ける光景は、危険極まりない。注意や啓発だけでは効果が薄いことは明らかで、罰則を設けて厳しく取り締まるべきだ。違反が横行している現状を野放しにしていては、重大な事故が起きるのは時間の問題である。\nB　無謀な運転が許されないのは当然だ。しかし、罰則の強化だけで問題が解決するとは思えない。自転車が安心して走れる道が整っていないため、やむを得ず歩道を走る人も多いからだ。取り締まりを徹底する前に、まず安全に走れる道路環境を整えることこそが、本当の抑止につながるのではないか。": [0.0, 49.4], "さっき、スマホを見ながら自転車に乗ってる人にぶつかりそうになったの。": [49.8, 5.495], "えっ、大丈夫だった？ああいう運転は危険極まりないよね。": [55.695, 4.815], "最近、本当に多いよね。もっと厳しく取り締まってほしいな。": [60.91, 5.365], "罰則はあるけど、徹底されてないみたいだね。": [66.675, 3.75], "何の連絡もなく約束を破るとは、失礼極まりない。": [70.825, 4.835], "夜間にライトもつけずに山道を走るのは、危険極まりない行為だ。": [76.06, 5.465], "会議は同じ議論の繰り返しで、退屈極まりなかった。": [81.925, 4.665], "歩道を猛スピードで走り抜ける自転車は、歩行者にとって危険極まりない。罰則を設けて取り締まるだけでなく、交通ルールの教育も徹底すべきだと思う。": [86.99, 12.045], "人の話を最後まで聞かずに遮るのは、無礼極まりない。": [99.435, 4.92], "このような賞をいただき、光栄の至りでございます。": [104.755, 4.17], "罰則": [109.325, 1.13], "取り締まる": [110.855, 1.25], "横行": [112.505, 1.205], "抑止": [114.11, 1.13], "徹底": [115.64, 1.16], "啓発": [117.2, 1.21], "無謀": [118.81, 1.07], "野放し": [120.28, 1.23]}, "d345": {"北陸のある町では、四百年以上前から漆器づくりが続いている。湿度の高いこの土地の風土が、漆をゆっくり乾かすのに適していたからだという。木を削って器の形を作り、漆を何十回も塗り重ねては研ぐ。その工程は百を超え、一つの椀が仕上がるまでに半年以上かかることも珍しくない。手間を惜しまないからこそ生まれる深い艶と素朴な温かみは、まさに職人の手仕事ならではのものだ。しかし近年は担い手の高齢化が進み、技術の継承が危ぶまれている。町では若手職人を育てる研修制度を設け、長い時間をかけて培われてきた技を次の世代へつなごうとしている。": [0.0, 47.775], "このお椀、持ってみると軽くて、なんだか温かみがありますね。": [48.175, 5.27], "ありがとうございます。百以上の工程を経て、職人が一つずつ仕上げております。": [53.845, 6.755], "この深い艶は、手仕事ならではですね。": [61.0, 3.585], "ええ。ただ、最近は担い手が減ってしまって、技術の継承が課題なんです。": [64.985, 6.695], "朝市で味わう取れたての魚は、港町ならではの楽しみだ。": [72.08, 5.23], "子どもならではの自由な発想に、大人たちは驚かされた。": [77.71, 4.83], "この柔らかな手触りは、手織りならではだ。": [82.94, 3.515], "私の故郷には、古い木造の家が並ぶ素朴な町並みが今も残っている。地元の人ならではの温かいもてなしと静かな趣が、訪れる人を惹きつけている。": [86.855, 13.035], "雪国ならではの冬祭りを、ぜひ一度見てみたい。": [100.29, 4.255], "今日は春らしい穏やかな天気だ。": [104.945, 2.69], "漆器": [108.035, 1.125], "継承": [109.56, 1.215], "風土": [111.175, 1.06], "趣": [112.635, 1.205], "担い手": [114.24, 1.18], "培う": [115.82, 1.255], "工程": [117.475, 1.2], "素朴": [119.075, 1.175]}, "d346": {"最近の若者は長編小説はおろか、短い記事さえ最後まで読めない──。そんな嘆きをよく耳にする。確かに、スマートフォンで断片的な情報を次々と眺める習慣が、注意力を散漫にしている面はあるだろう。だが、それを若者の根気のなさだけのせいにするのは公平ではない。一つの文章に没頭するには、通知に邪魔されない時間と場所が要る。そうした環境を奪ってきたのは、むしろ大人が作った社会の仕組みではなかったか。読む力は一朝一夕には身につかない素養である。一概に若者を責めるより、じっくり読める時間をどう取り戻すかを、社会全体で考えるべきだ。": [0.0, 45.81], "最近の学生は長い文章を読まなくなったって、先生が嘆いてたよ。": [46.21, 5.765], "正直、僕も小説はおろか、ニュース記事も途中でやめちゃうことがあるな。": [52.375, 6.14], "スマホの通知が多すぎるんだよね。集中なんてできないもん。": [58.915, 4.81], "そうそう。読むときだけでも通知を切ってみようかな。": [64.125, 4.365], "足を骨折してしまい、走ることはおろか、一人で歩くこともできない。": [68.89, 5.995], "祖母は海外はおろか、隣の県にさえほとんど行ったことがない。": [75.285, 5.135], "その村には、かつて電話はおろか、電気すら通っていなかった。": [80.82, 5.25], "留学したばかりの頃は、新聞はおろか、駅の案内表示さえ読めなかった。それでも根気よく辞書を引き続けたおかげで、今では長い記事にも没頭できるようになった。": [86.47, 13.13], "彼は漢字はおろか、ひらがなもまだ書けない。": [100.0, 3.79], "薬を飲んだが、熱は下がるどころか、かえって上がってしまった。": [104.19, 5.235], "嘆く": [109.825, 1.09], "断片的": [111.315, 1.32], "散漫": [113.035, 1.14], "没頭": [114.575, 1.145], "根気": [116.12, 1.09], "一概に": [117.61, 1.235], "素養": [119.245, 1.15], "一朝一夕": [120.795, 1.445]}, "d347": {"A　生徒の個人情報を無断で持ち帰り、紛失した教員がいた。教育者にあるまじき行為であり、厳しい処分は免れない。今回の不祥事で、学校への信頼は大きく失墜した。同様の事態の再発を防ぐには、懲戒の基準を明確にし、厳罰で臨む姿勢を示すことが不可欠だ。\nB　行為そのものが許されないのは言うまでもない。だが、自宅に持ち帰らなければ仕事が終わらないほど業務が多かったのなら、それは個人の倫理だけの問題ではない。一人を戒めて幕引きをすれば、組織の抱える問題が隠蔽されかねない。再発を防ぐには、教員の働き方そのものを見直す必要がある。": [0.0, 46.45], "ニュース見た？例の会社の社長、検査データの書き換えを指示してたらしいよ。": [46.85, 6.215], "経営者にあるまじき行為ね。真面目に働いてる社員がかわいそう。": [53.465, 5.185], "一度失った信頼を取り戻すには、相当時間がかかるだろうな。": [59.05, 5.435], "処分するだけじゃなくて、再発を防ぐ仕組みを作らないとね。": [64.885, 4.985], "患者の秘密を他人に漏らすなど、医師にあるまじき行為だ。": [70.27, 4.56], "審判に暴言を吐くとは、スポーツ選手にあるまじき態度である。": [75.23, 4.945], "弱い立場の者を踏みにじるなど、人として許すまじき振る舞いだ。": [80.575, 5.145], "試合中に相手選手を侮辱するのは、プロの選手にあるまじき行為だ。一度失墜した信頼は簡単には取り戻せないことを、肝に銘じてほしい。": [86.12, 11.22], "賄賂を受け取るなど、公務員にあるまじき行為だ。": [97.74, 3.82], "疲れているときは、無理に運転するべきではない。": [101.96, 3.95], "不祥事": [106.31, 1.145], "懲戒": [107.855, 1.215], "厳罰": [109.47, 1.17], "失墜": [111.04, 1.25], "隠蔽": [112.69, 1.135], "再発": [114.225, 1.275], "倫理": [115.9, 0.98], "戒める": [117.28, 1.275]}, "d348": {"高校サッカー選手権の決勝は、最後まで張り詰めた展開となった。前半に二点を奪われ、劣勢に立たされた地元校だったが、選手たちは決して諦めなかった。後半、粘り強い守備から一点を返すと、スタンドは割れんばかりの歓声に包まれた。そして終了間際、主将の放ったシュートがゴールに吸い込まれ、試合は延長戦へともつれ込んだ。結局、PK戦の末に敗れ、悲願の初優勝には届かなかった。それでも観客は、涙を流しながら選手たちの健闘を讃え、いつまでも拍手を送り続けた。試合後、監督は「この一年で一番いい試合だった」と胸を張った。": [0.0, 47.035], "昨日の決勝、見た？最後まで固唾をのんで見ちゃったよ。": [47.435, 5.075], "見た見た。同点ゴールのとき、スタジアムが割れんばかりの歓声だったね。": [52.91, 5.85], "PK戦で負けちゃったけど、劣勢から本当によく粘ったよ。": [59.16, 5.005], "うん、悲願の初優勝は来年に持ち越しだね。": [64.565, 3.935], "合格の知らせを聞いて、母は泣き出さんばかりに喜んだ。": [68.9, 4.855], "会場は、溢れんばかりの観客で埋め尽くされていた。": [74.155, 4.415], "彼は「お前のせいだ」と言わんばかりの目で、私をにらんだ。": [78.97, 5.52], "十年ぶりに再会した友人は、私の顔を見るなり、飛びつかんばかりに駆け寄ってきた。マラソンを完走した私の健闘を、彼は何度も讃えてくれた。": [84.89, 12.23], "スタジアムは割れんばかりの拍手に包まれた。": [97.52, 3.515], "相手が弱ったのを見て、ここぞとばかりに彼は攻め込んだ。": [101.435, 4.675], "喝采": [106.51, 1.115], "劣勢": [108.025, 1.135], "粘る": [109.56, 1.02], "健闘": [110.98, 1.215], "張り詰める": [112.595, 1.285], "讃える": [114.28, 1.115], "悲願": [115.795, 0.97], "固唾": [117.165, 1.105]}, "d349": {"親の介護を一人で担う人が増えている。仕事を続けながら、夜中にも何度も起きて世話をする日々が、心身をどれほど疲弊させるかは想像にかたくない。にもかかわらず、多くの人は周囲に窮状を打ち明けられず、問題を抱え込んでしまう。「家族のことは家族で」という意識や、弱音を吐くことへのためらいがあるからだろう。だが、介護する人が倒れてしまえば、介護される人も行き場を失う。周囲が相手の事情を察して声をかけ、公的な支援につなぐことが必要だ。介護を個人の問題として孤立させない社会こそ、私たちが目指すべき姿ではないだろうか。": [0.0, 44.06], "田中さん、お母さんの介護で毎晩何度も起きてるんだって。": [44.46, 4.585], "それは大変だ。疲れがたまっているのは想像にかたくないね。": [49.445, 4.925], "でも、職場では何も言わないで、一人で抱え込んでるみたい。": [54.77, 5.2], "今度、それとなく声をかけてみようか。会社にも介護休暇の制度があるし。": [60.37, 6.32], "突然職を失った彼の不安は、想像にかたくない。": [67.09, 4.67], "長年連れ添った妻を亡くした父の悲しみは、察するにかたくない。": [72.16, 5.555], "このまま物価の上昇が続けば、家計がさらに苦しくなることは想像にかたくない。": [78.115, 6.65], "海外で一人暮らしを始めた妹が、慣れない環境でどれほど孤立感を抱えているかは想像にかたくない。何でも打ち明けられるよう、週に一度は電話で話を聞くつもりだ。": [85.165, 13.27], "一人で三人の子を育てる苦労は、想像にかたくない。": [98.835, 4.765], "あの温厚な彼が人を殴ったとは、にわかには信じがたい。": [104.0, 4.81], "介護": [109.21, 1.085], "疲弊": [110.695, 1.145], "孤立": [112.24, 1.08], "担う": [113.72, 1.015], "察する": [115.135, 1.18], "抱え込む": [116.715, 1.38], "打ち明ける": [118.495, 1.26], "窮状": [120.155, 1.175]}, "d351": {"A　過疎化に歯止めをかけるべく、多くの自治体が移住者に補助金を出している。住宅の取得や引っ越しにかかる費用を補助すれば、都会の若い世帯が地方での暮らしを選ぶ後押しになる。実際、補助制度を始めてから移住者が倍増した町もある。まずは人を呼び込むことが先決だ。\nB　補助金で一時的に人が増えても、仕事がなければ定着はしない。補助の期間が終わると同時に都会へ戻ってしまう例も少なくないと聞く。本当に必要なのは、企業の誘致や地元産業の育成によって、その土地で暮らし続けられる基盤を作ることだ。持続的な地域づくりは、補助金頼みでは実現しない。": [0.0, 45.91], "うちの町も、移住者に補助金を出し始めたらしいね。": [46.31, 4.44], "人口の減少に歯止めをかけるべく、いろいろ工夫してるみたい。": [51.15, 4.895], "でも、仕事がないと結局定着しないんじゃないかな。": [56.445, 4.52], "そうなの。だから今、企業の誘致にも力を入れてるんだって。": [61.365, 5.265], "彼は医者になるべく、毎日夜遅くまで勉強を続けた。": [67.03, 4.835], "新たな市場を開拓すべく、同社は東南アジアに支社を設けた。": [72.265, 5.27], "被災者の声を直接聞くべく、知事は自ら現地に足を運んだ。": [77.935, 5.63], "日本の企業で働くという目標を実現すべく、毎朝一時間、ビジネス日本語の勉強を続けている。習慣として定着させることで、学習を持続できるようになった。": [83.965, 13.875], "真相を明らかにすべく、警察は捜査を続けている。": [98.24, 4.68], "健康のために、毎朝野菜ジュースを飲んでください。": [103.32, 4.275], "歯止め": [107.995, 1.11], "過疎": [109.505, 1.085], "移住": [110.99, 1.015], "誘致": [112.405, 1.06], "補助": [113.865, 1.015], "定着": [115.28, 1.21], "持続": [116.89, 1.13], "先決": [118.42, 1.325]}, "d352": {"先月公開されたドキュメンタリー映画が、静かな反響を呼んでいる。地方の小さな病院で、終末期の患者と向き合う看護師たちの一年を追った作品だ。カメラは、患者の最期の日々や家族の葛藤を、過度な脚色を加えることなく克明に映し出す。生々しい場面も少なくないが、そこに漂うのは悲しみだけではない。患者の何気ない一言に看護師たちが笑い合う姿は、温かな余韻を残す。迫真の映像は、観る者に「自分ならどう生き、どう最期を迎えたいか」を考えさせずにはおかない。上映が終わっても、しばらく席を立てずにいる観客が多かったという。": [0.0, 45.415], "昨日、話題のドキュメンタリー映画を観てきたんだ。": [45.815, 3.91], "病院の看護師さんたちを追ったやつ？どうだった？": [50.125, 3.9], "患者さんの最期まで克明に描かれていて、生き方を考えさせずにはおかない作品だったよ。": [54.425, 7.135], "重そうだけど、観てみたいな。": [61.96, 2.675], "意外と笑える場面もあって、温かい余韻が残ったよ。": [65.035, 4.52], "この小説の意外な結末は、読者を驚かせずにはおかないだろう。": [69.955, 5.49], "彼の力強い演説は、聴衆の心を揺さぶらずにはおかなかった。": [75.845, 5.56], "今度こそ事件の真相を突き止めずにはおかない、と記者は誓った。": [81.805, 5.4], "主人公が家族との葛藤を乗り越えていく姿は、観る者の心を揺さぶらずにはおかない。見終わった後も、私はしばらく余韻に浸っていた。": [87.605, 10.965], "戦争の悲惨さを伝えるこの写真は、見る人に平和の尊さを考えさせずにはおかない。": [98.97, 6.95], "あまりに悲しい結末に、私は泣かずにはいられなかった。": [106.32, 4.9], "描写": [111.62, 1.105], "余韻": [113.125, 0.93], "揺さぶる": [114.455, 1.195], "克明": [116.05, 1.265], "葛藤": [117.715, 1.195], "生々しい": [119.31, 1.43], "迫真": [121.14, 1.16], "脚色": [122.7, 1.28]}, "d353": {"ここ数年、すぐに役立つ成果を求める風向きが、研究の世界にも強まっている。予算は実用化に近い分野に偏り、何に役立つか分からない基礎研究は後回しにされがちだ。だが歴史を振り返れば、社会を大きく変えた発見の多くは、目先の利益とは無縁の地道な探究から生まれている。短期的な見返りばかりを求めれば、若い研究者は失敗を恐れて萎縮し、挑戦的なテーマを避けるようになるだろう。基礎研究が結実するまでには長い年月がかかる。だからこそ、社会全体がその価値を理解し、支え続ける必要がある。若い研究者が自由に模索できる環境が整うことを、私は願ってやまない。": [0.0, 49.505], "それでは、今年度で退任される山田教授から、一言お願いいたします。": [49.905, 6.11], "四十年間、地道に研究を続けてこられたのは、皆さんの支えがあったからです。": [56.415, 6.855], "若い皆さんが目先の成果にとらわれず、自由に挑戦し続けることを願ってやみません。": [63.67, 6.74], "先生、長い間、本当にありがとうございました。": [70.81, 4.85], "皆様のご健康とご多幸を、心より祈ってやみません。": [76.06, 4.79], "彼は生涯、故郷の山々を愛してやまなかった。": [81.25, 4.245], "私が敬愛してやまない恩師が、今年で教壇を去られる。": [85.895, 4.83], "私が敬愛してやまない祖父は、八十歳を過ぎた今も、毎朝地道に畑仕事を続けている。いつまでも元気でいてくれることを、心から願ってやまない。": [91.125, 12.795], "卒業生の皆さんの今後のご活躍を、期待してやみません。": [104.32, 5.135], "試験の結果が気になってならない。": [109.855, 2.78], "地道": [113.035, 1.11], "萎縮": [114.545, 0.995], "模索": [115.94, 1.13], "敬愛": [117.47, 1.075], "目先": [118.945, 1.13], "見返り": [120.475, 1.155], "結実": [122.03, 1.235], "偏重": [123.665, 1.245]}, "d354": {"A　市の新庁舎の建設は、着工前から見通しの甘さが指摘されていた。案の定、地盤の問題で工事は難航し、工期は二年以上延びた。資材価格の上昇も重なって、ついには当初の見積もりの倍近くまで費用が膨らむしまつだ。杜撰な計画を立てた責任は、厳しく問われるべきである。\nB　計画に甘さがあったことは否定できない。とはいえ、大規模な工事に想定外の事態は付き物で、すべてを事前に見通すのは難しい。問題は、途中で立ち止まる仕組みがなかった点にある。費用が一定の額を超えたら、撤退も含めて計画を見直す。そうしたルールがあれば、事業が頓挫しかけるほどの混乱は防げたはずだ。": [0.0, 50.11], "市役所の新しい庁舎、まだ完成しないの？": [50.51, 4.17], "工事が難航して、工期が二年も延びたんだって。": [55.08, 4.085], "費用も、当初の見積もりの倍近くに膨らんでるらしいね。": [59.565, 4.765], "おまけに、追加の予算まで組むしまつよ。ずさんな計画だったとしか言えないわね。": [64.73, 6.565], "弟は毎晩ゲームに夢中で、ついには学校まで休むしまつだ。": [71.695, 5.375], "彼は何度注意しても遅刻を繰り返し、とうとう大事な商談にまで遅れてくるしまつだった。": [77.47, 6.84], "さんざん迷って買った傘を、その日のうちに電車に置き忘れるしまつだ。": [84.71, 5.58], "同僚は締め切りを何度も延ばしたうえに、最後には資料をなくしたと言い出すしまつだ。杜撰な仕事ぶりのせいで、プロジェクトはすっかり難航してしまった。": [90.69, 11.105], "彼は借金を重ね、ついには家族にまで嘘をつくしまつだ。": [102.195, 5.145], "さんざん悩んだあげく、彼は留学をあきらめた。": [107.74, 4.015], "工期": [112.155, 1.075], "膨らむ": [113.63, 1.135], "見積もり": [115.165, 1.165], "杜撰": [116.73, 1.04], "頓挫": [118.17, 1.07], "着工": [119.64, 1.245], "難航": [121.285, 1.22], "撤退": [122.905, 1.105]}, "d355": {"祖父が亡くなって一年がたつ。先日、遺品を整理していると、押し入れの奥から古い日記帳が何冊も出てきた。そこには、戦後間もない頃、家族を養うために各地を転々とした日々が、几帳面な字でつづられていた。生前の祖父は、昔のことをほとんど語らなかった。私もいつか聞こうと思いながら、忙しさにかまけて、結局聞かずじまいになってしまった。それが今でも心残りだ。それでも、日記を一ページずつ紐解くうちに、私の知らなかった若き日の祖父の面影が少しずつ浮かび上がってきた。今は祖父を偲びつつ、日記を手がかりに、祖父が暮らした町を訪ねてみたいと思っている。": [0.0, 47.96], "おじいちゃんの遺品を整理してたら、古い日記が出てきたの。": [48.36, 4.475], "へえ、どんなことが書いてあった？": [53.235, 2.79], "戦後すぐの頃の苦労が細かく書いてあって。生前に直接聞いておけばよかったんだけど、結局聞かずじまいで。": [56.425, 8.965], "そうか……。でも、日記が残っていて本当によかったね。": [65.79, 4.825], "せっかく京都まで行ったのに、雨のせいで金閣寺は見ずじまいだった。": [71.015, 5.425], "買ったまま一度も着ずじまいの服が、クローゼットにたくさんある。": [76.84, 4.87], "彼女が突然会社を辞めた理由は、とうとう分からずじまいだった。": [82.11, 5.17], "卒業前にお世話になった先生にお礼を言おうと思っていたのに、タイミングを逃して言えずじまいだった。それが今でも心残りなので、今年は手紙を書くつもりだ。": [87.68, 12.1], "忙しくて、借りた本は結局読まずじまいだった。": [100.18, 4.305], "彼は電気もつけないまま、部屋で考え込んでいた。": [104.885, 4.175], "遺品": [109.46, 0.95], "面影": [110.81, 1.265], "生前": [112.475, 1.15], "心残り": [114.025, 1.495], "手がかり": [115.92, 1.185], "紐解く": [117.505, 1.235], "偲ぶ": [119.14, 1.11], "悔やむ": [120.65, 1.035]}, "d356": {"同じ職場で同じ仕事をしているのに、雇用形態が違うというだけで、賃金に大きな格差がある。こうした状況は、長年当然のように受け入れられてきた。しかし、仕事の内容と責任が同じであれば、それに見合う報酬が支払われてしかるべきだ。非正規で働く人の中には、一家の家計を支えている人も少なくない。待遇の差は、本人の努力だけでは埋められない生活の差につながっている。近年、格差を是正するための法律が整えられたが、実態はまだ追いついていない。制度を形だけのものにしないためには、企業任せにせず、社会全体で抜本的な見直しを進めることが求められている。": [0.0, 47.71], "派遣の佐藤さん、私たちと同じ仕事をしてるのに、ボーナスが出ないんだって。": [48.11, 6.26], "それはおかしいよ。責任も同じなんだから、同じ待遇を受けてしかるべきだ。": [54.77, 6.275], "法律もできたけど、実態はなかなか変わらないみたい。": [61.445, 4.435], "会社任せにしないで、組合からも声を上げていこうよ。": [66.28, 4.62], "長年の功績を考えれば、彼はもっと評価されてしかるべきだ。": [71.3, 5.275], "これほどの被害を出したのだから、会社は公式に謝罪してしかるべきだろう。": [76.975, 5.615], "住民の意見は、計画の段階で聞かれてしかるべきだった。": [82.99, 4.835], "保育士や介護職員は社会を支える大切な仕事をしているのだから、それに見合う報酬を受け取ってしかるべきだ。待遇の格差を是正することが急務だと思う。": [88.225, 12.03], "これだけ成果を上げたのだから、彼女は昇進してしかるべきだ。": [100.655, 4.935], "約束の時間は守るべきだ。": [105.99, 2.5], "待遇": [108.89, 1.09], "報酬": [110.38, 1.16], "格差": [111.94, 1.2], "是正": [113.54, 1.15], "雇用": [115.09, 1.085], "見合う": [116.575, 0.97], "抜本的": [117.945, 1.32], "実態": [119.665, 1.135]}, "d358": {"A（食品メーカー社長）　原材料の高騰が続き、当社も主力商品の値上げを余儀なくされた。これまでは経費を削って価格を据え置いてきたが、もはや企業努力で吸収できる範囲を超えている。このままでは品質の維持も難しい。苦渋の決断だったが、どうかご理解いただきたい。\nB（消費者）　値上げの事情は分からなくもない。ただ、ここ一年で日用品が軒並み割高になり、家計は圧迫される一方だ。価格に転嫁するだけでなく、包装を簡素にしたり、手頃な商品を残したりと、消費者の負担を抑える工夫をもっと示してほしい。": [0.0, 44.105], "またお菓子が値上がりしてるね。": [44.505, 2.255], "原材料の高騰で、メーカーも値上げを余儀なくされてるらしいよ。": [47.16, 5.01], "量も前より減ってる気がするんだけど。": [52.57, 2.965], "価格を据え置く代わりに、中身を減らすところも多いんだって。": [55.935, 4.61], "大雨の影響で、決勝戦は翌日への延期を余儀なくされた。": [60.945, 5.04], "業績の悪化により、同社は国内工場の閉鎖を余儀なくされた。": [66.385, 5.39], "突然の病が、彼に現役引退を余儀なくさせた。": [72.175, 4.465], "台風で飛行機が欠航し、私たちは現地でもう一泊することを余儀なくされた。急いで探したホテルは割高で、旅行の予算が大きく圧迫されてしまった。": [77.04, 12.435], "部品の不足で、工場は一週間の操業停止を余儀なくされた。": [89.875, 5.29], "これだけ証拠がそろえば、彼も罪を認めざるを得ないだろう。": [95.565, 4.75], "高騰": [100.715, 1.2], "転嫁": [102.315, 1.125], "据え置く": [103.84, 1.185], "圧迫": [105.425, 1.175], "苦渋": [107.0, 1.035], "吸収": [108.435, 1.145], "軒並み": [109.98, 1.19], "割高": [111.57, 1.245]}, "d359": {"本番の試験会場で実力を発揮できる人と、そうでない人がいる。その差はどこから生まれるのだろうか。ある受験指導の専門家は、「本番で頼りになるのは、日々の積み重ねにほかならない」と言う。直前になって新しい問題集に手を出すより、これまで解いてきた問題を見直すほうが、自信を支える糧になるというのだ。また、模試で良い点を取るとつい慢心しがちだが、それこそが最大の敵だとも指摘する。逆に、思うような結果が出なかったときこそ、粘り強く弱点に向き合う好機だという。平常心で試験に臨むためにも、最後の一か月は、これまでの学習の集大成と位置づけたい。": [0.0, 47.055], "試験まであと一か月だね。新しい問題集、もう一冊買おうかな。": [47.455, 5.87], "先生は、今まで解いた問題を見直すほうがいいって言ってたよ。": [53.725, 5.02], "そっか。本番で頼りになるのは、これまでの積み重ねにほかならないってことだね。": [59.145, 6.59], "うん。平常心で臨めるように、最後まで一緒に頑張ろう。": [66.135, 5.085], "この賞をいただけたのは、支えてくれた家族のおかげにほかならない。": [71.62, 5.365], "彼が部下を厳しく叱るのは、その成長を願っているからにほかならない。": [77.385, 5.705], "失敗とは、成功に至るまでの一つの過程にほかならない。": [83.49, 5.135], "一年間、毎日欠かさず日本語を勉強してこられたのは、同じ目標を持つ仲間がいたからにほかならない。本番では平常心を保ち、この一年の集大成を見せたい。": [89.025, 13.525], "この成功は、チーム全員の努力の結果にほかならない。": [102.95, 4.695], "それは根拠のない噂にすぎない。": [108.045, 2.745], "積み重ね": [111.19, 1.48], "粘り強い": [113.07, 1.36], "慢心": [114.83, 1.045], "糧": [116.275, 1.015], "臨む": [117.69, 1.06], "平常心": [119.15, 1.18], "集大成": [120.73, 1.49], "好機": [122.62, 1.075]}, "d361": {"N1の本番で最も多くの受験者を苦しめるのは、問題の難しさよりも時間である。言語知識と読解を合わせて110分という時間は一見十分に思えるが、長文に差しかかる頃には残りわずかになっていることが少なくない。そこで勧めたいのが、事前に配分を決めておくことだ。たとえば文字・語彙と文法は合わせて25分程度で切り上げ、残りを読解に回す。迷った問題には印をつけていったん先へ進み、最後に戻ればよい。もちろん全問をじっくり解けるに越したことはないが、一問に固執して後半に手が回らなくなっては元も子もない。また、言語知識・読解・聴解の各区分には19点の基準点があり、総合で100点を超えても一つでも下回れば不合格になる。満点を狙うより、どの区分でも確実に点を取ることを優先しよう。約55分の聴解は途中で止められないので、休憩時間に頭を休めておくことも立派な戦略である。": [0.0, 67.675], "本番の時間配分、もう決めた？": [68.075, 3.055], "うん。文法までは25分で終わらせて、読解に時間を残すつもり。": [71.53, 5.69], "見直しの時間も取れるに越したことはないけど、なかなか難しいよね。": [77.62, 5.5], "だから、迷ったら印をつけて、とりあえず先に進むことにしたの。": [83.52, 5.915], "なるほど。一問に時間をかけすぎるのが一番危ないもんね。": [89.835, 4.79], "試験会場には早めに着くに越したことはない。": [95.025, 3.805], "体調管理に気をつけるに越したことはないが、神経質になりすぎるのも考えものだ。": [99.23, 6.665], "費用は安いに越したことはないが、安全性を犠牲にしてはならない。": [106.295, 5.295], "見直しの時間を十分に取れるに越したことはないが、私は文字・語彙と文法を25分で終わらせ、残りを読解に充てるつもりだ。迷った問題は印をつけて後回しにする。": [111.99, 13.86], "睡眠は十分にとるに越したことはない。": [126.25, 3.24], "疲れた日は、早く寝るに限る。": [129.89, 2.97], "配分": [133.26, 1.07], "固執": [134.73, 1.1], "見極める": [136.23, 1.275], "割り切る": [137.905, 1.18], "基準点": [139.485, 1.12], "切り上げる": [141.005, 1.2], "着手": [142.605, 1.175], "焦燥": [144.18, 1.29]}, "d362": {"聴解の試験でメモを取るべきかどうかは、人によって意見が分かれる。書くことに気を取られて肝心な部分を聞き漏らしてしまっては、本末転倒だからだ。しかし、課題理解やポイント理解のように質問が先に流れる問題では、要点を書き留めておくと判断の手がかりになる。コツは、文字で書こうとしないことだ。人物は「男」「女」の一字で、賛成は○、反対は×、増減は矢印で表すというように、自分なりの記号をあらかじめ決めておく。数字や曜日、そして「でも」「ただ」といった逆接の後に続く内容は特に問われやすいので、逐一ではなく、そこだけを拾えばよい。一方、即時応答では書いている暇などない。耳だけで勝負するに限る。メモはそれ自体が目的ではなく、あくまで記憶を補う道具だということを忘れないでほしい。": [0.0, 61.38], "聴解のメモって、どうやって取ってる？": [61.78, 3.235], "全部書こうとすると聞き漏らすから、記号だけにしてるよ。": [65.415, 4.455], "記号？たとえば？": [70.27, 1.995], "賛成なら丸、反対ならバツ。「でも」の後は特に注意して書き留めるんだ。": [72.665, 6.82], "なるほど。迷ったら、短く書くに限るってことね。": [79.885, 4.71], "疲れたときは、何も考えずに寝るに限る。": [84.995, 3.91], "暑い夏の日には、冷たいそばに限る。": [89.305, 3.545], "面倒なことに巻き込まれたくなければ、余計なことは言わないに限る。": [93.25, 5.31], "数字は算用数字で、賛成は○、反対は×と決めておく。迷ったときは、とにかく短く書くに限る。": [98.96, 9.435], "聴解のメモは、記号で済ませるに限る。": [108.795, 3.66], "急いでいる日に限って、電車が遅れる。": [112.855, 3.435], "書き留める": [116.69, 1.315], "聞き漏らす": [118.405, 1.34], "略記": [120.145, 1.015], "要旨": [121.56, 1.085], "手がかり": [123.045, 1.185], "逐一": [124.63, 1.175], "把握": [126.205, 1.075], "本末転倒": [127.68, 1.66]}, "d363": {"試験前日にすべきことは、新しい知識を詰め込むことではなく、これまでの総点検である。まず持ち物を確かめよう。受験票、HBの鉛筆と消しゴム、そして時計としてしか使えない腕時計。会場までの経路と所要時間も前もって調べておけば、当日慌てずに済む。学習面では、自分で作った間違いノートをざっと見返す程度にとどめたい。一年かけて積み上げてきたものが、一晩で消えてしまうことはない。むしろ大切なのは、十分な睡眠をとり、平常心で本番に臨むことだ。当日、見たことのない言葉が出てきても動揺する必要はない。前後の文脈から推測し、それでも分からなければ印をつけて次へ進むまでだ。やるだけのことはやってきた。あとは、積み重ねてきた力を出し切るまでのことである。": [0.0, 57.46], "明日はいよいよ本番だね。持ち物、全部確認した？": [57.86, 4.85], "うん、受験票も鉛筆も腕時計も、かばんに入れたよ。": [63.11, 4.615], "会場までの道は？": [68.125, 1.855], "先週一度行ってみたから大丈夫。あとは早く寝るだけ。": [70.38, 4.87], "そうそう。ここまで来たら、やってきたことを出し切るまでだよ。": [75.65, 5.15], "今年がだめなら、来年また挑戦するまでだ。": [81.2, 3.99], "終電を逃したら、駅から歩いて帰るまでだ。": [85.59, 3.835], "深い意味はありません。思ったことを言ったまでです。": [89.825, 3.845], "受験票、鉛筆、消しゴム、腕時計はすべてかばんに入れた。あとは早めに寝て、明日は全力を尽くすまでだ。": [94.07, 9.74], "電車が止まったら、タクシーで行くまでだ。": [104.21, 3.34], "これほど簡単な問題なら、説明するまでもない。": [107.95, 4.305], "点検": [112.655, 1.11], "万全": [114.165, 1.05], "携行": [115.615, 1.24], "抜かり": [117.255, 1.075], "心構え": [118.73, 1.5], "平常心": [120.63, 1.18], "仕上げ": [122.21, 1.145], "臨む": [123.755, 1.06]}, "final": {"山田さん、来週の説明会の準備なんだけど、資料の印刷はもう頼んである？": [0.0, 6.62], "はい、昨日印刷会社に発注しました。": [7.02, 3.655], "そう。じゃあ、会場の予約は？": [11.075, 3.345], "それも先週済ませてあります。あ、ただ、参加者の名簿がまだ最終版になっていなくて。": [14.82, 7.615], "名簿は申込みの締め切りが明日だから、それが過ぎてからでいいよ。それより、当日のアンケート用紙、まだ作ってないよね。名簿より先に、そっちをお願い。": [22.835, 12.785], "分かりました。すぐ取りかかります。": [36.02, 2.965], "すみません、図書館のカードを作りたいんですが。": [39.385, 3.935], "はい。こちらの申込書にご記入のうえ、ご住所の確認できるものをお出しください。": [43.72, 6.735], "運転免許証でいいですか。": [50.855, 2.245], "ええ、結構です。ただ、免許証のご住所が今のお住まいと違う場合は、公共料金の領収書など、現住所の分かるものも必要になります。": [53.5, 11.95], "あ、先月引っ越したばかりで、まだ住所変更してないんです。領収書も家に置いてきちゃって……。": [65.85, 7.7], "でしたら、本日は申込書だけお書きいただいて、次回それをお持ちいただければ、その場でお作りします。": [73.95, 8.37], "新しいカフェ、どうだった？": [82.72, 2.51], "うーん、コーヒーはおいしかったし、値段も思ってたより手ごろだったんだけどね。": [85.63, 5.785], "じゃあ、何が気に入らなかったの？": [91.815, 2.805], "席と席の間が狭くて、隣の人の話が全部聞こえちゃうの。あれじゃ落ち着いて本も読めないよ。": [95.02, 7.94], "そうか。店員さんの感じはどうだった？": [103.36, 3.33], "それは丁寧でよかったよ。": [107.09, 2.18], "部長、例の新商品の発売、延期になったそうですね。やはり工場の生産が間に合わなかったんですか。": [109.67, 8.78], "いや、生産は予定どおりなんだ。問題はパッケージでね。表示の一部に、法律上確認が必要な点が見つかって。": [118.85, 9.78], "そうだったんですか。てっきり、競合他社の発売日に合わせたのかと思っていました。": [129.03, 6.55], "それも検討はしたけど、結局は関係なかったよ。": [135.98, 4.495], "この書類、明日までに仕上げてもらえると助かるんだけど。": [140.875, 4.565], "せっかくお越しいただいたのに、あいにく社長は外出しておりまして。": [145.84, 5.205], "田中さんったら、また会議の資料を忘れてきたんだって。": [151.445, 4.565]}};
